const TEXT_LINE_HEIGHT_SCALE: f32 = 1.2;
// ECMA-376 Part 1 §20.1.7.1 DrawingML text-body schema defaults.
const DRAWINGML_DEFAULT_HORIZONTAL_TEXT_BODY_INSET_EMU: i64 = 91_440;
const DRAWINGML_DEFAULT_VERTICAL_TEXT_BODY_INSET_EMU: i64 = 45_720;
// LibreOffice chart2 `AreaChart.cxx` passes a fixed 100 mm100 offset to
// `createDataLabel` after moving a top label above the marker.
const CARTESIAN_DATA_LABEL_OFFSET_PT: f32 = 72.0 / 25.4;
// Office-generated chart data-label text bodies use a 38,100 EMU horizontal
// inset (3pt).  The inset remains observable when c:txPr is omitted because
// the label shape itself is generated by the host application.
const AUTOMATIC_DATA_LABEL_HORIZONTAL_INSET_PT: f32 = 3.0;
// Word's auto-fitted chart axis-title frame retains 3 pt at each end of the
// text direction. An Office COM font-size matrix (8/10/12 pt) reports title
// heights equal to measured text advances plus 6 pt in every case.
const WORD_CHART_AXIS_TITLE_END_INSET_PT: f32 = 3.0;
// LibreOffice raises the corresponding 3-D bar/column offset to 260 mm100,
// but Microsoft Office fixed output retains the ordinary 100 mm100 clearance
// after transforming the complete 3-D anchor. Keeping the LO value here puts
// every outside label exactly 1.6 mm too far from its marker.
const BAR_3D_DATA_LABEL_OFFSET_PT: f32 = 72.0 / 25.4;
// LibreOffice chart2/source/view/charttypes/BubbleChart.cxx sizes the largest
// bubble to one quarter of the smaller final plot extent. ECMA-376
// §21.2.2.21 then applies c:bubbleScale as 0..=300% of that default size.
const MAXIMUM_BUBBLE_DIAMETER_RATIO: f32 = 0.25;
// Word's legacy chart fixed-output pipeline quantizes data-marker edges to
// 1/600 inch. Axis strokes retain their higher-precision automatic-layout
// coordinates, so this grid belongs to series geometry rather than PlotRect.
const WORD_FIXED_CHART_DATA_EDGE_GRID_PT: f32 = 72.0 / 600.0;
// Word keeps the data-table name/key column anchored to the chart's fixed
// output frame. Controlled 8/10/12 pt table-font and ShowLegendKey matrices
// retain these positions while only the measured name width grows.
const WORD_DATA_TABLE_OUTER_LEFT_INSET_PT: f32 = 17.0;
const WORD_DATA_TABLE_NAME_NO_KEY_INSET_PT: f32 = 1.9;
const WORD_DATA_TABLE_KEY_LEADING_INSET_PT: f32 = 3.2;
const WORD_DATA_TABLE_KEY_WIDTH_PT: f32 = 19.2;
const WORD_DATA_TABLE_KEY_GAP_PT: f32 = 2.0;
// Word keeps a fixed-size line sample in a data-table chart's side legend.
// COM font-size controls retain a 10 pt right margin and an 11 pt gap from
// PlotArea.InsideRight to Legend.Left; the PDF gives the sample and text insets.
const WORD_DATA_TABLE_LINE_LEGEND_KEY_WIDTH_PT: f32 = 19.2;
const WORD_DATA_TABLE_LINE_LEGEND_KEY_GAP_PT: f32 = 2.12;
const WORD_DATA_TABLE_LINE_LEGEND_LEFT_PADDING_PT: f32 = 4.64;
const WORD_DATA_TABLE_LINE_LEGEND_RIGHT_PADDING_PT: f32 = 4.04;
const WORD_DATA_TABLE_LINE_LEGEND_FRAME_RIGHT_INSET_PT: f32 = 6.0;
const WORD_DATA_TABLE_LINE_LEGEND_PLOT_GAP_PT: f32 = 11.0;
const WORD_DATA_TABLE_LINE_LEGEND_HEADER_PADDING_PT: f32 = 3.17;
const WORD_DATA_TABLE_LINE_LEGEND_PLOT_TOP_INSET_PT: f32 = 0.48;
// Office's untitled Word percent-stacked bars keep their right-side legend
// frame 10 pt from ChartArea.Right and its plot a further 22.18 pt away.
// The chart frame in our page model includes ChartArea's 4 pt left inset.
const WORD_PERCENT_BAR_LEGEND_FRAME_RIGHT_INSET_PT: f32 = 6.0;
const WORD_PERCENT_BAR_LEGEND_PLOT_GAP_PT: f32 = 22.18;
const WORD_PERCENT_BAR_LEGEND_KEY_GAP_PT: f32 = 2.47;
const WORD_PERCENT_BAR_LEGEND_RIGHT_PADDING_PT: f32 = 4.0;
const WORD_PERCENT_BAR_CATEGORY_LABEL_GAP_EM: f32 = 0.95;
// Word's automatic titled single-line/no-legend plot keeps fixed viewport
// edges as chart width/height vary. Value/category/title font probes isolate
// the three font-relative bands from those outer device margins.
const WORD_TITLED_SINGLE_LINE_TICK_LEFT_PT: f32 = 6.5;
const WORD_TITLED_SINGLE_LINE_TICK_GAP_EM: f32 = 0.928;
const WORD_TITLED_SINGLE_LINE_RIGHT_INSET_PT: f32 = 11.0;
const WORD_TITLED_SINGLE_LINE_TOP_INSET_PT: f32 = 0.48;
const WORD_TITLED_SINGLE_LINE_BOTTOM_INSET_PT: f32 = 6.5;
const WORD_TITLED_SINGLE_LINE_CATEGORY_BOTTOM_EM: f32 = 1.855;

// `c:bubble3D` is an intrinsic chart-marker surface, not shorthand for an
// authored `a:sp3d`. Controlled Word fixed-output probes keep this exact
// neutral scene when the series scene/material/bevel and the theme's third
// effect scene are replaced. Keep one immutable typed value for every host
// and marker rather than cloning package theme state into each chart model.
static OFFICE_BUBBLE_3D_SCENE: LazyLock<a::Scene3DType> = LazyLock::new(|| a::Scene3DType {
  camera: Box::new(a::Camera {
    preset: a::PresetCameraValues::OrthographicFront,
    rotation: Some(a::Rotation {
      latitude: 0,
      longitude: 0,
      revolution: 0,
    }),
    ..a::Camera::default()
  }),
  light_rig: Box::new(a::LightRig {
    rig: a::LightRigValues::ThreePoints,
    direction: a::LightRigDirectionValues::Top,
    rotation: None,
  }),
  ..a::Scene3DType::default()
});
// Word's automatic numeric-axis labels reserve a nominal three-em horizontal
// pitch even when the current strings are narrower. Controlled fixed-output
// probes retain this pitch when c:txPr/a:bodyPr insets are changed, so it is a
// generated-axis policy rather than an authored text-body inset. The vertical
// extent remains the measured line box.
const WORD_NUMERIC_AXIS_MINIMUM_HORIZONTAL_PITCH_EM: f32 = 3.0;
// Complex category axes reserve an independent band for every parent level.
// LibreOffice VCartesianAxis::doStaggeringOfLabels accumulates the measured
// label extent plus the axis-to-text distance rather than overlaying the
// levels. The different physical orientations use different clearances
// because a vertical-axis parent label is rotated by 90 degrees.
const MULTILEVEL_HORIZONTAL_LEVEL_GAP_EM: f32 = 0.63;
const MULTILEVEL_VERTICAL_LEVEL_GAP_EM: f32 = 1.05;
// A complex category axis on the physical Y axis keeps additional end
// clearance inside the automatic plot. The immutable Word fixed output for
// the three-level horizontal-bar control is four fifths of a label line box
// shorter than the structurally matching ordinary horizontal-bar profile,
// split one fifth at the top and three fifths at the bottom. Expressing the
// measured difference in line boxes keeps it independent of chart-frame size
// and hierarchy depth.
const MULTILEVEL_VERTICAL_PLOT_TOP_INSET_LINES: f32 = 0.2;
const MULTILEVEL_VERTICAL_PLOT_BOTTOM_INSET_LINES: f32 = 0.6;

