struct WordDataTableLayout {
  outer_left: f32,
  series_column_width: f32,
  header_height: f32,
  body_row_height: f32,
  key_width: f32,
  key_height: f32,
}

impl WordDataTableLayout {
  fn height(self, series_count: usize) -> f32 {
    self.header_height + self.body_row_height * series_count as f32
  }
}

