#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ChartLayoutProfile {
  PowerPoint,
  Word,
  Excel,
}

fn radial_host_defaults(profile: ChartLayoutProfile) -> profiles::RadialHostDefaults {
  match profile {
    ChartLayoutProfile::PowerPoint => profiles::POWERPOINT_RADIAL_DEFAULTS,
    ChartLayoutProfile::Word => profiles::WORD_RADIAL_DEFAULTS,
    ChartLayoutProfile::Excel => profiles::EXCEL_RADIAL_DEFAULTS,
  }
}

fn maximum_auto_main_increment_count(
  profile: ChartLayoutProfile,
  available_axis_length_pt: f32,
  label_shape_extent_pt: f32,
) -> usize {
  // LibreOffice VCartesianAxis::estimateMaximumAutoMainIncrementCount divides
  // the final center-to-center label line by the maximum recorded label shape
  // extent. The first and
  // last generated shapes each occupy half an extent at the ends of the full
  // axis line, so their centers are one complete extent closer together.
  // LibreOffice clamps this budget to at least two intervals. Word fixed
  // output permits a single interval on a physically tiny numeric axis; the
  // caller-selected maximum must survive into the scale calculation for that
  // 0..5/5 state. Bubble marker bounds expand the numeric data domain after
  // this pass; they are not part of the label extent.
  let label_shape_extent_pt = label_shape_extent_pt.max(1.0);
  let minimum = match profile {
    ChartLayoutProfile::Word => 1.0,
    ChartLayoutProfile::PowerPoint | ChartLayoutProfile::Excel => 2.0,
  };
  ((available_axis_length_pt - label_shape_extent_pt).max(0.0) / label_shape_extent_pt)
    .floor()
    .clamp(minimum, 10.0) as usize
}

fn cartesian_value_axis_increment_budget(
  layout_profile: ChartLayoutProfile,
  radar_only: bool,
  horizontal_bar_only: bool,
  word_untitled_side_horizontal_bar: bool,
  physical_budget: usize,
) -> usize {
  if layout_profile == ChartLayoutProfile::PowerPoint && radar_only {
    5
  } else if (radar_only && layout_profile == ChartLayoutProfile::Excel)
    || (layout_profile == ChartLayoutProfile::PowerPoint && horizontal_bar_only)
  {
    physical_budget.min(5)
  } else if layout_profile == ChartLayoutProfile::Word
    && horizontal_bar_only
    && word_untitled_side_horizontal_bar
  {
    physical_budget.min(6)
  } else {
    physical_budget
  }
}

fn suppress_duplicate_formatted_tick_budget(
  physical_budget: usize,
  tick_labels: &[(f64, String)],
) -> usize {
  // LibreOffice VCartesianAxis::estimateMaximumAutoMainIncrementCount also
  // protects against a number format collapsing adjacent numeric ticks to the
  // same visible string (tdf#48041).  The longest equal-label run determines
  // how far the scale must be thinned; date axes have their own time-unit
  // estimator and do not enter this helper.
  let mut longest_run = 1_usize;
  let mut current_run = 0_usize;
  let mut previous = None::<&str>;
  for (_, label) in tick_labels {
    if previous == Some(label.as_str()) {
      current_run += 1;
    } else {
      current_run = 1;
      previous = Some(label);
    }
    longest_run = longest_run.max(current_run);
  }
  if longest_run <= 1 {
    return physical_budget;
  }
  physical_budget
    .min(tick_labels.len() / longest_run)
    .clamp(physical_budget.clamp(1, 2), 10)
}

fn numeric_axis_label_shape_width(
  profile: ChartLayoutProfile,
  measured_width: f32,
  font_size_pt: f32,
) -> f32 {
  if profile == ChartLayoutProfile::Word {
    measured_width.max(font_size_pt * WORD_NUMERIC_AXIS_MINIMUM_HORIZONTAL_PITCH_EM)
  } else {
    measured_width
  }
}

fn maximum_tick_label_axis_pitch(
  tick_labels: &[(f64, String)],
  style: &TextStyle,
  profile: ChartLayoutProfile,
  rotation_degrees: f32,
  horizontal_axis: bool,
  metrics: &mut TextMetrics,
) -> f32 {
  // LibreOffice VCartesianAxis records the bounds of the generated label
  // shapes and divides the final axis length by that complete extent. Office
  // Word additionally gives generated numeric labels a nominal horizontal
  // pitch. This is independent of authored c:txPr/a:bodyPr insets and applies
  // before rotation projects the shape onto the physical axis.
  let (sin, cos) = rotation_degrees.to_radians().sin_cos();
  let sin = sin.abs();
  let cos = cos.abs();
  tick_labels
    .iter()
    .map(|(_, label)| {
      let measured_width = metrics.measure_text(label, style);
      let width = numeric_axis_label_shape_width(profile, measured_width, style.font_size_pt);
      // Axis labels are laid out in the same 1.2-em line boxes that are later
      // emitted to the page. Font ink/face metrics can be substantially
      // shorter (notably Calibri digits), and using them here admits labels
      // that the generated text shapes cannot actually fit.
      let height = metrics
        .inline_text_box_height_for_text(label, style)
        .max(line_height(style));
      if horizontal_axis {
        width * cos + height * sin
      } else {
        width * sin + height * cos
      }
    })
    .fold(0.0_f32, f32::max)
    .max(line_height(style))
}

fn word_automatic_titled_bottom_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::Word
    && chart.legend_position == Some(ChartLegendPosition::Bottom)
    && !chart.legend_overlay
    && chart.legend_layout.is_none()
    && chart.title.is_some()
    && !chart.title_overlay
    && chart.plot_layout.is_none()
    && chart.view_3d.is_none()
}

fn word_uses_hidden_vertical_value_band(
  layout_profile: ChartLayoutProfile,
  value_tick_labels_visible: bool,
  horizontal_bar_only: bool,
) -> bool {
  layout_profile == ChartLayoutProfile::Word && !value_tick_labels_visible && !horizontal_bar_only
}

fn word_titled_bottom_band_height(
  has_word_titled_bottom_layout: bool,
  horizontal_bar_only: bool,
  frame_height_pt: f32,
) -> f32 {
  if has_word_titled_bottom_layout && !horizontal_bar_only {
    profiles::WORD_TITLED_BOTTOM_DEVICE_BAND_HEIGHT_PT
  } else {
    frame_height_pt
  }
}

fn east_asian_title_script(title: &str, style: &TextStyle) -> Option<TextScript> {
  script_direction_runs(title, FontSize(style.font_size_pt), style.small_caps)
    .into_iter()
    .map(|run| run.script)
    .find(|script| {
      matches!(
        script,
        TextScript::Han | TextScript::Hiragana | TextScript::Katakana | TextScript::Hangul
      )
    })
}

fn word_chart_title_ink_box_excess(metrics: TextVerticalMetrics, font_size_pt: f32) -> f32 {
  // Word reserves the same 15% side leading above and below the physical
  // East Asian ink-box excess as it does for WordprocessingML CJK line boxes.
  // Malgun Gothic's 4.621pt excess at 14pt therefore occupies 6.007pt in the
  // chart plot band, matching the Office/SDK difference to MS Mincho controls.
  (metrics.ink_height_pt() - font_size_pt).max(0.0)
    * (1.0 + 2.0 * WORDPROCESSINGML_CJK_SIDE_LEADING_RATIO)
}

