pub(crate) fn solid_chart_shape_style(
  fill_color: Option<RgbColor>,
  stroke: Option<(RgbColor, f32)>,
) -> crate::common::ShapeStyle<'static> {
  crate::common::ShapeStyle {
    fill: fill_color.map_or(crate::common::ShapeStyleValue::Unspecified, |color| {
      crate::common::ShapeStyleValue::Paint(crate::common::Fill::Solid(common_rgb(color, 1.0)))
    }),
    stroke: stroke.map_or(
      crate::common::ShapeStyleValue::Unspecified,
      |(color, width_pt)| {
        crate::common::ShapeStyleValue::Paint(crate::common::Stroke {
          width: crate::common::Pt(width_pt),
          color: common_rgb(color, 1.0),
          ..Default::default()
        })
      },
    ),
  }
}

pub(crate) fn normalize_chart_marker_shape_style(
  marker: Option<&c::Marker>,
  mut style: crate::common::ShapeStyle<'static>,
  automatic_stroke: Option<&crate::common::ShapeStyleValue<crate::common::Stroke<'static>>>,
) -> crate::common::ShapeStyle<'static> {
  let Some(outline) = marker
    .and_then(|marker| marker.chart_shape_properties.as_deref())
    .and_then(|properties| properties.outline.as_deref())
  else {
    return style;
  };
  if matches!(
    outline.outline_choice1.as_ref(),
    Some(a::OutlineChoice::NoFill(_))
  ) {
    style.stroke = crate::common::ShapeStyleValue::NoPaint;
    return style;
  }

  if let Some(crate::common::ShapeStyleValue::Paint(automatic)) = automatic_stroke {
    let mut merged = automatic.clone();
    if let crate::common::ShapeStyleValue::Paint(direct) = &style.stroke
      && outline.outline_choice1.is_some()
    {
      merged.color = direct.color;
      merged.pattern.clone_from(&direct.pattern);
      merged.gradient.clone_from(&direct.gradient);
    }
    if let Some(width) = outline.width {
      merged.width = crate::common::Pt(crate::units::emu_to_points(i64::from(width)));
    }
    crate::common::drawingml_stroke::apply_outline_style_over_inherited(&mut merged, outline);
    style.stroke = crate::common::ShapeStyleValue::Paint(merged);
  } else if outline.width.is_none()
    && let crate::common::ShapeStyleValue::Paint(stroke) = &mut style.stroke
  {
    // Keep the Office recovery for malformed/theme-less packages.
    stroke.width = crate::common::Pt(0.5);
  }
  style
}

fn excel_derived_single_series_side_title_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::Excel
    && !style.has_explicit_title
    && matches!(chart.title.as_ref(), Some(ChartTitleText::Explicit(_)))
    && chart.series.len() == 1
    && matches!(
      chart.legend_position,
      Some(ChartLegendPosition::Left | ChartLegendPosition::Right | ChartLegendPosition::TopRight)
    )
    && !chart.legend_overlay
    && chart.plot_layout.is_none()
}

fn powerpoint_derived_single_series_title_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::PowerPoint
    && !style.has_explicit_title
    && chart.has_automatic_title_marker
    && matches!(
      (chart.title.as_ref(), chart.series.as_slice()),
      (Some(ChartTitleText::Explicit(title)), [series])
        if series.has_nonempty_explicit_name && title == &series.name
    )
}

fn excel_explicit_single_series_side_title_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::Excel
    && style.has_explicit_title
    && matches!(chart.title.as_ref(), Some(ChartTitleText::Explicit(_)))
    && chart.series.len() == 1
    && matches!(
      chart.legend_position,
      Some(ChartLegendPosition::Left | ChartLegendPosition::Right | ChartLegendPosition::TopRight)
    )
    && !chart.legend_overlay
    && chart.plot_layout.is_none()
    && (chart.gap_width_percent - 219.0).abs() < f64::EPSILON
    && (chart.overlap_percent + 27.0).abs() < f64::EPSILON
}

fn excel_legacy_default_single_series_side_title_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::Excel
    && style.has_explicit_title
    && style.title_top_adjustment_ratio.abs() > f32::EPSILON
    && matches!(chart.title.as_ref(), Some(ChartTitleText::Explicit(_)))
    && chart.series.len() == 1
    && matches!(
      chart.legend_position,
      Some(ChartLegendPosition::Left | ChartLegendPosition::Right | ChartLegendPosition::TopRight)
    )
    && !chart.legend_overlay
    && chart.plot_layout.is_none()
}

fn excel_vary_colors_data_table_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::Excel
    && chart.data_table.is_some()
    && chart.vary_colors_by_point
    && chart.series.len() == 1
    && matches!(
      chart.legend_position,
      Some(ChartLegendPosition::Left | ChartLegendPosition::Right | ChartLegendPosition::TopRight)
    )
    && !chart.legend_overlay
    && chart.title.is_none()
    && chart.plot_layout.is_none()
}

fn excel_explicit_bottom_column_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::Excel
    && style.has_explicit_title
    && !chart.title_overlay
    && matches!(chart.title.as_ref(), Some(ChartTitleText::Explicit(_)))
    && chart.legend_position == Some(ChartLegendPosition::Bottom)
    && !chart.legend_overlay
    && chart.series.len() == 2
    && chart
      .series
      .iter()
      .all(|series| series.kind == ChartSeriesKind::Column)
    && (chart.gap_width_percent - 219.0).abs() < f64::EPSILON
    && (chart.overlap_percent + 27.0).abs() < f64::EPSILON
    && chart.plot_layout.is_none()
}

fn excel_untitled_bottom_column_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::Excel
    && chart.legend_position == Some(ChartLegendPosition::Bottom)
    && !chart.legend_overlay
    && chart.title.is_none()
    && !chart.has_automatic_title_marker
    && !chart.has_explicit_categories
    && chart.series.len() == 2
    && chart
      .series
      .iter()
      .all(|series| series.kind == ChartSeriesKind::Column)
}

fn excel_untitled_bottom_line_no_marker_layout(
  chart: &ClusteredColumnChart<'_>,
  style: &ClusteredColumnStyle,
) -> bool {
  style.layout_profile == ChartLayoutProfile::Excel
    && chart.legend_position == Some(ChartLegendPosition::Bottom)
    && !chart.legend_overlay
    && chart.title.is_none()
    && chart.series.len() == 2
    && chart.series.iter().all(|series| {
      series.kind == ChartSeriesKind::Line
        && series.marker.is_some_and(|marker| {
          marker
            .symbol
            .as_ref()
            .is_some_and(|symbol| symbol.val == c::MarkerStyleValues::None)
        })
    })
    && chart.plot_layout.is_none()
}

pub(crate) fn lower_clustered_column_chart(
  frame: ChartFrame,
  chart: &ClusteredColumnChart<'_>,
  automatic_title: &str,
  style: &ClusteredColumnStyle,
) -> Vec<PageItem> {
  if frame.width_pt <= 0.0 || frame.height_pt <= 0.0 || chart.series.is_empty() {
    return Vec::new();
  }

  let category_count = chart
    .series
    .iter()
    .map(|series| series.values.len())
    .chain(std::iter::once(chart.categories.len()))
    .max()
    .unwrap_or(0);
  if category_count == 0 {
    return Vec::new();
  }
  // LibreOffice ChartView performs an initial ten-increment autoscale before
  // maximum label extents and the final inner plot rectangle are known.
  // A second, size-dependent pass is performed after the plot is laid out.
  let axis_scales =
    cartesian_axis_scales(chart, style.layout_profile, category_count, 10, 10, None);
  let Some(scale) = axis_scales.first().map(|axes| axes.y) else {
    return Vec::new();
  };
  if scale.maximum <= scale.minimum {
    return Vec::new();
  }
  let percent_stacked = axis_set_is_percent_stacked(chart, 0);

  let mut metrics = TextMetrics::new();
  let title_text = match chart.title.as_ref() {
    Some(ChartTitleText::Explicit(title)) => Some(title.as_str()),
    Some(ChartTitleText::Automatic) => Some(automatic_title),
    None => None,
  };
  let has_layout_title = title_text.is_some() && !chart.title_overlay;
  let has_layout_explicit_title = has_layout_title && style.has_explicit_title;
  let has_powerpoint_derived_single_series_title =
    powerpoint_derived_single_series_title_layout(chart, style);
  let title_line_height = line_height(&style.title);
  let title_reservation_height = title_text.map_or(title_line_height, |title| {
    let rotation_radians = (style.title.rotation_deg + chart.title_rotation_deg).to_radians();
    if rotation_radians.abs() <= f32::EPSILON {
      title_line_height
    } else {
      let title_width = metrics.measure_text(title, &style.title);
      title_width * rotation_radians.sin().abs() + title_line_height * rotation_radians.cos().abs()
    }
  });
  let chartsheet_category_layout = excel_chartsheet_automatic_category_layout(chart, style);
  let category_label_line_height = line_height(&style.category_label);
  let value_label_line_height = line_height(&style.value_label);
  let label_line_height = category_label_line_height
    .max(value_label_line_height)
    .max(line_height(&style.label));
  let legend_line_height = line_height(&style.legend);
  let radar_only = chart
    .series
    .iter()
    .all(|series| series.kind == ChartSeriesKind::Radar);
  let horizontal_bar_only = chart
    .series
    .iter()
    .all(|series| series.kind == ChartSeriesKind::Bar);
  let has_word_titled_single_line_no_legend = word_titled_single_line_no_legend(chart, style);
  let scatter_only = chart.series.iter().all(|series| {
    matches!(
      series.kind,
      ChartSeriesKind::Scatter | ChartSeriesKind::Bubble
    )
  });
  let category_hierarchy = hierarchical_cartesian_category_axis(chart, radar_only, scatter_only);
  let has_multicomponent_data_labels = chart.series.iter().any(|series| {
    series
      .data_labels
      .iter()
      .any(|label| label.text_components.len() > 1)
  });
  let has_indexed_scatter_automatic_layout = style.layout_profile == ChartLayoutProfile::Excel
    && scatter_only
    && title_text.is_none()
    && scatter_uses_index_x_values(chart)
    && (has_multicomponent_data_labels || chart.has_automatic_title_marker);
  let has_legacy_indexed_scatter_layout = style.layout_profile == ChartLayoutProfile::Excel
    && scatter_only
    && title_text.is_none()
    && !chart.has_automatic_title_marker
    && scatter_uses_index_x_values(chart)
    && !has_multicomponent_data_labels
    && chart.plot_layout.is_none();
  let has_titled_indexed_scatter_layout = style.layout_profile == ChartLayoutProfile::Excel
    && scatter_only
    && !chart.title_overlay
    && matches!(chart.title.as_ref(), Some(ChartTitleText::Automatic))
    && scatter_uses_index_x_values(chart);
  let has_explicit_title_indexed_scatter_layout = style.layout_profile == ChartLayoutProfile::Excel
    && scatter_only
    && !chart.title_overlay
    && style.has_explicit_title
    && matches!(chart.title.as_ref(), Some(ChartTitleText::Explicit(_)))
    && chart.legend_position.is_none()
    && scatter_uses_index_x_values(chart)
    && chart.plot_layout.is_none();
  let has_legacy_single_series_title_layout = style.layout_profile == ChartLayoutProfile::Excel
    && !style.has_explicit_title
    && matches!(chart.title.as_ref(), Some(ChartTitleText::Explicit(_)))
    && chart.series.len() == 1
    && chart.legend_position.is_none();
  let has_modern_single_series_title_layout =
    has_legacy_single_series_title_layout && style.modern_excel_profile;
  let has_legacy_styleless_single_series_device_layout = has_legacy_single_series_title_layout
    && !style.modern_excel_profile
    && chart.plot_layout.is_none();
  let legacy_styleless_device_adjustment = if has_legacy_styleless_single_series_device_layout {
    profiles::EXCEL_LEGACY_STYLELESS_SINGLE_SERIES_DEVICE
  } else {
    profiles::CartesianDeviceAdjustment::default()
  };
  let has_modern_single_series_scatter_title_layout =
    has_modern_single_series_title_layout && scatter_only;
  let modern_single_series_title_adjustment = if has_modern_single_series_title_layout {
    if scatter_only {
      profiles::EXCEL_MODERN_SINGLE_SERIES_SCATTER_TITLE
    } else {
      profiles::EXCEL_MODERN_SINGLE_SERIES_TITLE
    }
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let has_derived_single_series_side_title_layout =
    excel_derived_single_series_side_title_layout(chart, style);
  let has_explicit_single_series_side_title_layout =
    excel_explicit_single_series_side_title_layout(chart, style);
  let has_legacy_default_single_series_side_title_layout =
    excel_legacy_default_single_series_side_title_layout(chart, style);
  let legacy_default_single_series_adjustment =
    if has_legacy_default_single_series_side_title_layout {
      profiles::EXCEL_LEGACY_DEFAULT_SINGLE_SERIES_SIDE_TITLE
    } else {
      profiles::CartesianLayoutAdjustment::default()
    };
  let has_automatic_untitled_layout = chart.has_automatic_title_marker
    || (chart.title_overlay && matches!(chart.title.as_ref(), Some(ChartTitleText::Automatic)))
    || has_indexed_scatter_automatic_layout;
  let value_axis_visible = chart.value_axis.is_none_or(value_axis_is_visible);
  let horizontal_value_tick_labels_visible = horizontal_bar_only
    && value_axis_visible
    && chart.value_axis.is_none_or(|axis| {
      axis
        .tick_label_position
        .as_ref()
        .is_none_or(|position| position.val != Some(c::TickLabelPositionValues::None))
    });
  let primary_value_axis_on_right = chart.value_axis.is_some_and(value_axis_is_on_right);
  let value_tick_labels_visible = value_axis_visible
    && !radar_only
    && !horizontal_bar_only
    && chart.value_axis.is_none_or(|axis| {
      axis
        .tick_label_position
        .as_ref()
        .is_none_or(|position| position.val != Some(c::TickLabelPositionValues::None))
    });
  let value_gridlines_visible = value_axis_visible
    && !radar_only
    && !horizontal_bar_only
    && chart
      .value_axis
      .is_none_or(|axis| axis.major_gridlines.is_some());
  let category_axis_visible = chart
    .category_axis
    .map(category_axis_is_visible)
    .or_else(|| chart.date_axis.map(date_axis_is_visible))
    .unwrap_or(true);
  let category_tick_labels_visible = chart.data_table.is_none()
    && !radar_only
    && !horizontal_bar_only
    && category_axis_visible
    && chart
      .category_axis
      .map(|axis| {
        axis
          .tick_label_position
          .as_ref()
          .is_none_or(|position| position.val != Some(c::TickLabelPositionValues::None))
          && category_axis_text_rotation_is_supported(
            axis.text_properties.as_deref(),
            category_count,
          )
      })
      .or_else(|| {
        chart.date_axis.map(|axis| {
          axis
            .tick_label_position
            .as_ref()
            .is_none_or(|position| position.val != Some(c::TickLabelPositionValues::None))
            && category_axis_text_rotation_is_supported(
              axis.text_properties.as_deref(),
              category_count,
            )
        })
      })
      .unwrap_or(true);
  let (date_ticks, date_axis_increment_budget) =
    if category_tick_labels_visible && chart.date_axis.is_some() {
      let preliminary_ticks = date_axis_ticks(chart).unwrap_or_default();
      let budget = estimated_date_axis_maximum_auto_main_increment_count(
        style.layout_profile,
        chart,
        frame.width_pt,
        &preliminary_ticks,
        &style.category_label,
        &mut metrics,
      );
      (
        date_axis_ticks_with_maximum_auto_increment_count(chart, budget),
        budget,
      )
    } else {
      (None, 500)
    };
  let category_label_texts: Vec<String> = if category_tick_labels_visible {
    if let Some(ticks) = date_ticks.as_ref() {
      ticks.iter().map(|tick| tick.text.clone()).collect()
    } else if let Some(hierarchy) = category_hierarchy {
      hierarchy.expanded_level(0)
    } else {
      chart.categories.clone()
    }
  } else {
    Vec::new()
  };
  let category_axis_text_properties = chart
    .category_axis
    .and_then(|axis| axis.text_properties.as_deref())
    .or_else(|| {
      chart
        .date_axis
        .and_then(|axis| axis.text_properties.as_deref())
    });
  let unwrapped_category_label_maximum_width = category_label_texts
    .iter()
    .map(|label| metrics.measure_text(label, &style.category_label))
    .fold(0.0f32, f32::max);
  let category_label_rotation = category_axis_text_rotation_degrees_for_layout(
    style.layout_profile,
    category_axis_text_properties,
    frame.width_pt,
    category_label_texts.len(),
    unwrapped_category_label_maximum_width,
    style.category_label.font_size_pt,
  );
  let category_label_lines: Vec<Vec<String>> = if category_label_rotation.abs() > f32::EPSILON {
    // A rotated chart label owns one text line. Wrapping it against the
    // unrotated category slot before applying the transform turns
    // `Sep 2013` into two independently rotated objects and under-reserves
    // the category band. Excel and PowerPoint retain the complete line and
    // let its rotated extent determine the automatic plot reservation.
    category_label_texts
      .into_iter()
      .map(|label| vec![label])
      .collect()
  } else {
    let slot_width = frame.width_pt / category_count as f32 * 0.9;
    category_label_texts
      .iter()
      .map(|label| wrap_chart_label(label, slot_width, &style.category_label, &mut metrics))
      .collect()
  };
  let category_label_line_count =
    category_label_lines.iter().map(Vec::len).max().unwrap_or(1) as f32;
  let category_label_unrotated_height = category_label_line_height * category_label_line_count;
  let category_label_maximum_width = category_label_lines
    .iter()
    .flatten()
    .map(|line| metrics.measure_text(line, &style.category_label))
    .fold(0.0f32, f32::max);
  let category_leaf_label_height = if category_label_rotation.abs() <= f32::EPSILON {
    category_label_unrotated_height
  } else {
    let rotation = category_label_rotation.to_radians();
    category_label_maximum_width * rotation.sin().abs()
      + category_label_unrotated_height * rotation.cos().abs()
  };
  let hierarchical_category_level_layouts = if category_tick_labels_visible
    && !horizontal_bar_only
    && let Some(hierarchy) = category_hierarchy
  {
    horizontal_category_level_layouts(
      hierarchy,
      frame.width_pt,
      &style.category_label,
      &mut metrics,
    )
  } else {
    Vec::new()
  };
  let vertical_category_level_layouts =
    if horizontal_bar_only && let Some(hierarchy) = category_hierarchy {
      vertical_category_level_layouts(
        hierarchy,
        frame.height_pt,
        &style.category_label,
        &mut metrics,
      )
    } else {
      Vec::new()
    };
  let category_label_height = category_leaf_label_height
    + hierarchical_category_level_layouts
      .iter()
      .map(|level| level.band_height)
      .sum::<f32>();
  let legend_position = chart.legend_position;
  // ECMA-376 Part 1 §21.2.2.132 allows other chart elements to overlap an
  // overlay legend. LibreOffice's VLegend::changePosition mirrors that
  // contract by subtracting a legend from the remaining plot space only when
  // Overlay is false. Keep that ownership decision shared by every automatic
  // plot band instead of letting legendPos alone reserve one side.
  let has_layout_reserving_legend = legend_position.is_some() && !chart.legend_overlay;
  let has_bottom_legend =
    has_layout_reserving_legend && legend_position == Some(ChartLegendPosition::Bottom);
  let has_untitled_bottom_column_layout = excel_untitled_bottom_column_layout(chart, style);
  let has_untitled_bottom_line_no_marker_layout =
    excel_untitled_bottom_line_no_marker_layout(chart, style);
  let has_explicit_bottom_column_layout = excel_explicit_bottom_column_layout(chart, style);
  let has_explicit_powerpoint_title =
    style.layout_profile == ChartLayoutProfile::PowerPoint && has_layout_explicit_title;
  let has_powerpoint_generated_title_bottom_layout = style.layout_profile
    == ChartLayoutProfile::PowerPoint
    && has_bottom_legend
    && has_layout_title
    && !style.has_explicit_title
    && matches!(chart.title.as_ref(), Some(ChartTitleText::Automatic))
    && !chart.title_layout_container_present
    && chart.plot_layout.is_none();
  let has_powerpoint_generated_title_no_legend_layout = style.layout_profile
    == ChartLayoutProfile::PowerPoint
    && legend_position.is_none()
    && has_layout_title
    && has_powerpoint_derived_single_series_title
    && !chart.title_layout_container_present
    && chart.plot_layout.is_none()
    && chart.view_3d.is_none()
    && !radar_only
    && !horizontal_bar_only
    && !scatter_only;
  let has_top_legend =
    has_layout_reserving_legend && legend_position == Some(ChartLegendPosition::Top);
  let has_side_legend = has_layout_reserving_legend
    && matches!(
      legend_position,
      Some(ChartLegendPosition::Left | ChartLegendPosition::Right | ChartLegendPosition::TopRight)
    );
  let has_excel_explicit_title_side_legend_layout = style.layout_profile
    == ChartLayoutProfile::Excel
    && has_side_legend
    && has_layout_explicit_title
    && chart.plot_layout.is_none();
  let has_excel_explicit_date_line_top_right_overlay_layout = style.layout_profile
    == ChartLayoutProfile::Excel
    && legend_position == Some(ChartLegendPosition::TopRight)
    && chart.legend_overlay
    && has_layout_title
    && chart.plot_layout.is_none()
    && chart.date_axis.is_some()
    && chart.category_axis_title.is_some()
    && chart.value_axis_title.is_some()
    && chart.series.len() >= 2
    && chart
      .series
      .iter()
      .all(|series| series.kind == ChartSeriesKind::Line);
  let has_excel_title_only_layout = style.layout_profile == ChartLayoutProfile::Excel
    && legend_position.is_none()
    && has_layout_explicit_title
    && chart.plot_layout.is_none()
    && !has_explicit_title_indexed_scatter_layout;
  let has_unshifted_side_line_layout = style.layout_profile == ChartLayoutProfile::Excel
    && has_side_legend
    && !has_layout_title
    && !chart.category_axis_shifted
    && chart.plot_layout.is_none()
    && chart
      .series
      .iter()
      .all(|series| matches!(series.kind, ChartSeriesKind::Line | ChartSeriesKind::Stock));
  let has_independent_axis_text_layout = style.layout_profile == ChartLayoutProfile::Excel
    && has_side_legend
    && !has_layout_title
    && chart.has_automatic_title_marker
    && chart.plot_layout.is_none()
    && chart
      .category_axis
      .is_some_and(|axis| axis.text_properties.is_some())
    && chart
      .value_axis
      .is_some_and(|axis| axis.text_properties.is_some());
  let has_shifted_category_empty_side_legend_layout = style.layout_profile
    == ChartLayoutProfile::Excel
    && has_side_legend
    && !has_layout_title
    && chart.title.is_none()
    && !chart.has_automatic_title_marker
    && chart.has_explicit_categories
    && chart.category_axis_shifted
    && chart.plot_layout.is_none()
    && chart.series.len() == 1
    && chart.series[0].kind == ChartSeriesKind::Column
    && !chart.series[0].has_explicit_name
    && (chart.gap_width_percent - 100.0).abs() < f64::EPSILON
    && chart.overlap_percent.abs() < f64::EPSILON;
  let host_defaults = match style.layout_profile {
    ChartLayoutProfile::PowerPoint => profiles::POWERPOINT_CARTESIAN_DEFAULTS,
    ChartLayoutProfile::Word => profiles::WORD_CARTESIAN_DEFAULTS,
    ChartLayoutProfile::Excel => profiles::EXCEL_CARTESIAN_DEFAULTS,
  };
  let host_side_legend_bands = match style.layout_profile {
    ChartLayoutProfile::PowerPoint => profiles::POWERPOINT_SIDE_LEGEND_BANDS,
    ChartLayoutProfile::Word if has_layout_explicit_title => {
      profiles::WORD_EXPLICIT_TITLE_SIDE_LEGEND_BANDS
    }
    ChartLayoutProfile::Word => profiles::WORD_SIDE_LEGEND_BANDS,
    ChartLayoutProfile::Excel => profiles::EXCEL_SIDE_LEGEND_BANDS,
  };
  // Word's automatic cartesian layout places a side-legend plot band lower
  // than the corresponding PowerPoint chart-space layout. The ratio is
  // stable across the three Office title-fill fixtures, which share no
  // c:manualLayout but differ in title-area fill.
  let word_side_adjustment = if style.layout_profile == ChartLayoutProfile::Word
    && has_side_legend
    && has_layout_explicit_title
    && chart.plot_layout.is_none()
  {
    profiles::WORD_EXPLICIT_TITLE_SIDE_LEGEND
  } else if style.layout_profile == ChartLayoutProfile::Word
    && has_side_legend
    && !has_layout_title
    && chart.plot_layout.is_none()
  {
    profiles::WORD_UNTITLED_SIDE_LEGEND
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let word_no_legend_adjustment = if style.layout_profile == ChartLayoutProfile::Word
    && !has_layout_reserving_legend
    && !has_layout_title
    && chart.plot_layout.is_none()
  {
    if horizontal_bar_only {
      profiles::WORD_UNTITLED_HORIZONTAL_BAR_NO_LEGEND
    } else {
      profiles::WORD_UNTITLED_NO_LEGEND
    }
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let word_horizontal_multilevel_adjustment = if style.layout_profile == ChartLayoutProfile::Word
    && category_hierarchy.is_some()
    && !horizontal_bar_only
    && chart.plot_layout.is_none()
    && chart.view_3d.is_none()
  {
    profiles::WORD_AUTOMATIC_HORIZONTAL_MULTILEVEL_CATEGORY_AXIS
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let has_word_titled_bottom_layout = word_automatic_titled_bottom_layout(chart, style);
  let word_titled_bottom_adjustment = if has_word_titled_bottom_layout {
    if horizontal_bar_only {
      profiles::WORD_TITLED_BOTTOM_HORIZONTAL_BAR
    } else {
      profiles::WORD_TITLED_BOTTOM_LEGEND
    }
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let has_word_titled_bottom_device_bands = has_word_titled_bottom_layout && !horizontal_bar_only;
  let automatic_band_height_pt = word_titled_bottom_band_height(
    has_word_titled_bottom_layout,
    horizontal_bar_only,
    frame.height_pt,
  );
  let powerpoint_derived_title_adjustment =
    if has_powerpoint_derived_single_series_title && has_side_legend && chart.plot_layout.is_none()
    {
      if horizontal_bar_only {
        profiles::POWERPOINT_DERIVED_SERIES_TITLE_HORIZONTAL_BAR
      } else if radar_only {
        profiles::CartesianLayoutAdjustment::default()
      } else {
        profiles::POWERPOINT_DERIVED_SERIES_TITLE_SIDE_LEGEND
      }
    } else {
      profiles::CartesianLayoutAdjustment::default()
    };
  let powerpoint_generated_title_bottom_adjustment = if has_powerpoint_generated_title_bottom_layout
  {
    profiles::POWERPOINT_GENERATED_TITLE_BOTTOM_LEGEND
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let powerpoint_generated_title_no_legend_adjustment =
    if has_powerpoint_generated_title_no_legend_layout {
      profiles::POWERPOINT_GENERATED_TITLE_NO_LEGEND
    } else {
      profiles::CartesianLayoutAdjustment::default()
    };
  let excel_side_adjustment = if has_excel_explicit_title_side_legend_layout {
    profiles::EXCEL_EXPLICIT_TITLE_SIDE_LEGEND
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let excel_explicit_date_line_top_right_overlay_adjustment =
    if has_excel_explicit_date_line_top_right_overlay_layout {
      profiles::EXCEL_EXPLICIT_DATE_LINE_TOP_RIGHT_OVERLAY
    } else {
      profiles::CartesianLayoutAdjustment::default()
    };
  let excel_untitled_side_adjustment = if style.layout_profile == ChartLayoutProfile::Excel
    && has_side_legend
    && !has_layout_title
    && has_automatic_untitled_layout
    && chart.plot_layout.is_none()
  {
    if chart.title_overlay && matches!(chart.title.as_ref(), Some(ChartTitleText::Automatic)) {
      profiles::EXCEL_LEGACY_EMPTY_OVERLAY_SIDE_LEGEND
    } else if chart.title.is_none() && chart.has_explicit_categories {
      profiles::EXCEL_UNTITLED_EXPLICIT_CATEGORY_SIDE_LEGEND
    } else {
      profiles::EXCEL_AUTOMATIC_UNTITLED_SIDE_LEGEND
    }
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let has_excel_vary_colors_data_table_layout = excel_vary_colors_data_table_layout(chart, style);
  let excel_vary_colors_data_table_adjustment = if has_excel_vary_colors_data_table_layout {
    profiles::EXCEL_VARY_COLORS_DATA_TABLE
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  // Excel's automatic cartesian layout uses a separate title reservation when
  // no legend is authored. Office fixed-output evidence keeps both the plot
  // and category-label bands lower than the side-legend profile.
  let excel_title_only_adjustment = if has_explicit_title_indexed_scatter_layout {
    profiles::EXCEL_EXPLICIT_TITLE_INDEXED_SCATTER
  } else if has_excel_title_only_layout {
    profiles::EXCEL_TITLE_ONLY
  } else {
    profiles::CartesianLayoutAdjustment::default()
  };
  let word_data_table_layout = chart.data_table.and_then(|table| {
    (style.layout_profile == ChartLayoutProfile::Word
      && !horizontal_bar_only
      && chart.view_3d.is_none()
      && chart.plot_layout.is_none())
    .then(|| measure_word_data_table_layout(frame, chart, table, style, &mut metrics))
  });
  let data_table_height = word_data_table_layout.map_or_else(
    || {
      chart.data_table.map_or(0.0, |_| {
        label_line_height * (chart.series.len() as f32 + 1.0) + label_line_height * 0.45
      })
    },
    |layout| layout.height(chart.series.len()),
  );

  // Office's automatic chart layout reserves semantic bands around the plot:
  // title, value labels, category labels, and legend. The distances scale with
  // chart height, while actual label widths determine the left plot inset.
  let title_top = frame.y_pt
    + automatic_band_height_pt
      * if style.layout_profile == ChartLayoutProfile::Excel
        && chart.title_overlay
        && matches!(chart.title.as_ref(), Some(ChartTitleText::Automatic))
      {
        profiles::EXCEL_LEGACY_EMPTY_OVERLAY_TITLE_TOP_RATIO
      } else if has_titled_indexed_scatter_layout {
        profiles::EXCEL_TITLED_INDEXED_SCATTER_TITLE_TOP_RATIO
      } else if has_legacy_single_series_title_layout {
        profiles::EXCEL_LEGACY_SINGLE_SERIES_TITLE_TOP_RATIO
      } else {
        host_defaults.title_top_ratio
      }
    + frame.height_pt * style.title_top_adjustment_ratio
    + if has_derived_single_series_side_title_layout {
      frame.height_pt * profiles::EXCEL_DERIVED_SINGLE_SERIES_SIDE_TITLE.title_top_ratio
    } else if has_explicit_single_series_side_title_layout {
      frame.height_pt * profiles::EXCEL_EXPLICIT_SINGLE_SERIES_SIDE_TITLE.title_top_ratio
    } else if has_explicit_bottom_column_layout {
      frame.height_pt * profiles::EXCEL_EXPLICIT_BOTTOM_COLUMN.title_top_ratio
    } else {
      0.0
    }
    + frame.height_pt * powerpoint_generated_title_bottom_adjustment.title_top_ratio;
  let mut title_top =
    title_top + frame.height_pt * powerpoint_generated_title_no_legend_adjustment.title_top_ratio;
  title_top += legacy_styleless_device_adjustment.title_top_pt * style.stroke_scale;
  let legend_bottom_margin = style.legend.font_size_pt * 0.81;
  let legend_top = frame.y_pt + frame.height_pt - legend_bottom_margin - legend_line_height;
  let category_bottom_ratio = host_defaults.category_bottom_ratio;
  let mut category_top = if chart.data_table.is_some() {
    frame.y_pt + frame.height_pt
      - data_table_height
      - if has_bottom_legend {
        legend_line_height + automatic_band_height_pt * profiles::DATA_TABLE_BOTTOM_LEGEND_GAP_RATIO
      } else if word_data_table_layout.is_some() {
        // Word leaves a fixed chart-area inset below the complete data table.
        5.0 * style.stroke_scale
      } else {
        automatic_band_height_pt * category_bottom_ratio
      }
  } else if !category_tick_labels_visible {
    frame.y_pt + frame.height_pt - automatic_band_height_pt * category_bottom_ratio
  } else if has_bottom_legend {
    legend_top
      - category_label_height
      - automatic_band_height_pt
        * if has_explicit_powerpoint_title {
          profiles::POWERPOINT_TITLED_BOTTOM_LEGEND_CATEGORY_GAP_RATIO
        } else {
          profiles::DEFAULT_BOTTOM_LEGEND_CATEGORY_GAP_RATIO
        }
  } else {
    frame.y_pt + frame.height_pt
      - category_label_height
      - automatic_band_height_pt * category_bottom_ratio
  } + frame.height_pt * word_side_adjustment.category_top_ratio
    + frame.height_pt * word_no_legend_adjustment.category_top_ratio
    + frame.height_pt * word_horizontal_multilevel_adjustment.category_top_ratio
    + automatic_band_height_pt * word_titled_bottom_adjustment.category_top_ratio
    + frame.height_pt * powerpoint_derived_title_adjustment.category_top_ratio
    + frame.height_pt * powerpoint_generated_title_bottom_adjustment.category_top_ratio
    + frame.height_pt * powerpoint_generated_title_no_legend_adjustment.category_top_ratio
    + frame.height_pt * excel_side_adjustment.category_top_ratio
    + frame.height_pt * excel_explicit_date_line_top_right_overlay_adjustment.category_top_ratio
    + frame.height_pt * excel_title_only_adjustment.category_top_ratio
    + frame.height_pt * excel_untitled_side_adjustment.category_top_ratio
    + frame.height_pt * excel_vary_colors_data_table_adjustment.category_top_ratio
    + frame.height_pt * legacy_default_single_series_adjustment.category_top_ratio;
  if !horizontal_bar_only && chart.category_axis_title.is_some() && chart.data_table.is_none() {
    // Office's automatic bottom stack reserves the category-axis title before
    // sizing the final plot. A bottom legend also needs the two inter-band
    // gaps around that title; without a legend the title line and its normal
    // leading still move the category labels and plot upward together.
    category_top -= line_height(&style.label) * if has_bottom_legend { 2.25 } else { 1.1 };
  }
  if has_independent_axis_text_layout {
    // Excel's automatic plot reservation is slightly tighter when both axes
    // carry independent text bodies. Keep that authored-axis profile separate
    // from the ordinary untitled side-legend layout.
    category_top += frame.height_pt * profiles::EXCEL_INDEPENDENT_AXIS_TEXT.category_top_ratio;
  } else if has_titled_indexed_scatter_layout {
    // Excel 2013's automatic-title scatter layout reserves a shallower plot
    // above the bottom legend than the legacy untitled scatter profile.
    category_top += frame.height_pt * profiles::EXCEL_TITLED_INDEXED_SCATTER.category_top_ratio;
  } else if has_legacy_indexed_scatter_layout {
    // Pre-2013 string-valued scatter caches use indexed x positions, but keep
    // the ordinary single-component label and legend bands.
    category_top += frame.height_pt * profiles::EXCEL_LEGACY_INDEXED_SCATTER.category_top_ratio;
  }
  category_top += frame.height_pt * modern_single_series_title_adjustment.category_top_ratio;
  if has_unshifted_side_line_layout {
    // `crossBetween="midCat"` puts the first and last line markers on the
    // plot edges. Excel's automatic side-legend layout reserves a slightly
    // lower category band for that on-marker axis profile.
    category_top += frame.height_pt * profiles::EXCEL_UNSHIFTED_SIDE_LINE.category_top_ratio;
  }
  if has_legacy_single_series_title_layout {
    category_top += frame.height_pt * profiles::EXCEL_LEGACY_SINGLE_SERIES_TITLE.category_top_ratio;
  } else if has_untitled_bottom_column_layout {
    // Modern Excel's missing autoTitleDeleted marker keeps the chart
    // untitled and reserves a compact bottom category/legend band.
    category_top += frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_COLUMN.category_top_ratio;
  } else if has_derived_single_series_side_title_layout {
    category_top +=
      frame.height_pt * profiles::EXCEL_DERIVED_SINGLE_SERIES_SIDE_TITLE.category_top_ratio;
  } else if has_explicit_single_series_side_title_layout {
    category_top +=
      frame.height_pt * profiles::EXCEL_EXPLICIT_SINGLE_SERIES_SIDE_TITLE.category_top_ratio;
  } else if has_untitled_bottom_line_no_marker_layout {
    category_top +=
      frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_LINE_NO_MARKER.category_top_ratio;
  } else if has_explicit_bottom_column_layout {
    category_top += frame.height_pt * profiles::EXCEL_EXPLICIT_BOTTOM_COLUMN.category_top_ratio;
  }
  let untitled_plot_top_ratio = if has_side_legend {
    host_defaults.untitled_side_plot_top_ratio
  } else {
    host_defaults.untitled_no_side_plot_top_ratio
  };
  let mut plot_top = if has_layout_title {
    title_top + title_reservation_height + label_line_height * 0.9
  } else {
    frame.y_pt + frame.height_pt * untitled_plot_top_ratio
  } + frame.height_pt * word_side_adjustment.plot_top_ratio
    + frame.height_pt * word_no_legend_adjustment.plot_top_ratio
    + frame.height_pt * word_horizontal_multilevel_adjustment.plot_top_ratio
    + automatic_band_height_pt * word_titled_bottom_adjustment.plot_top_ratio
    + frame.height_pt * powerpoint_derived_title_adjustment.plot_top_ratio
    + frame.height_pt * powerpoint_generated_title_bottom_adjustment.plot_top_ratio
    + frame.height_pt * powerpoint_generated_title_no_legend_adjustment.plot_top_ratio
    + frame.height_pt * excel_side_adjustment.plot_top_ratio
    + frame.height_pt * excel_explicit_date_line_top_right_overlay_adjustment.plot_top_ratio
    + frame.height_pt * excel_title_only_adjustment.plot_top_ratio
    + frame.height_pt * excel_untitled_side_adjustment.plot_top_ratio
    + frame.height_pt * excel_vary_colors_data_table_adjustment.plot_top_ratio
    + frame.height_pt * legacy_default_single_series_adjustment.plot_top_ratio;
  if has_word_titled_bottom_layout
    && let Some(title) = title_text
    && let Some(script) = east_asian_title_script(title, &style.title)
  {
    let metrics = metrics.vertical_metrics_for_script(&style.title, script);
    plot_top += automatic_band_height_pt
      * profiles::WORD_BOTTOM_LEGEND_EAST_ASIAN_TITLE_EXTRA_RATIO
      + word_chart_title_ink_box_excess(metrics, style.title.font_size_pt);
  }
  if has_independent_axis_text_layout {
    plot_top += frame.height_pt * profiles::EXCEL_INDEPENDENT_AXIS_TEXT.plot_top_ratio;
  } else if has_legacy_indexed_scatter_layout {
    plot_top += frame.height_pt * profiles::EXCEL_LEGACY_INDEXED_SCATTER.plot_top_ratio;
  }
  plot_top += frame.height_pt * modern_single_series_title_adjustment.plot_top_ratio;
  if has_titled_indexed_scatter_layout {
    plot_top += frame.height_pt * profiles::EXCEL_TITLED_INDEXED_SCATTER.plot_top_ratio;
  } else if has_legacy_single_series_title_layout {
    plot_top += frame.height_pt * profiles::EXCEL_LEGACY_SINGLE_SERIES_TITLE.plot_top_ratio;
  } else if has_untitled_bottom_column_layout {
    plot_top += frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_COLUMN.plot_top_ratio;
  } else if has_derived_single_series_side_title_layout {
    // title_top already carries the derived-title displacement; only the
    // residual plot reservation is added here.
    plot_top += frame.height_pt * profiles::EXCEL_DERIVED_SINGLE_SERIES_SIDE_TITLE.plot_top_ratio;
  } else if has_explicit_single_series_side_title_layout {
    // The title displacement above is part of the automatic plot
    // reservation; retain only the remaining Office plot-band offset.
    plot_top += frame.height_pt * profiles::EXCEL_EXPLICIT_SINGLE_SERIES_SIDE_TITLE.plot_top_ratio;
  } else if has_untitled_bottom_line_no_marker_layout {
    plot_top += frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_LINE_NO_MARKER.plot_top_ratio;
  } else if has_explicit_bottom_column_layout {
    // title_top carries most of the authored-title displacement.
    plot_top += frame.height_pt * profiles::EXCEL_EXPLICIT_BOTTOM_COLUMN.plot_top_ratio;
  }
  if has_top_legend {
    plot_top += legend_line_height
      + frame.height_pt
        * if style.layout_profile == ChartLayoutProfile::Word {
          profiles::WORD_TOP_LEGEND_GAP_RATIO
        } else {
          profiles::DEFAULT_TOP_LEGEND_GAP_RATIO
        };
  }
  if chart.view_3d.is_some() && has_bottom_legend {
    // VDiagram preserves the projected scene aspect ratio inside the
    // axis/legend rectangle. With a bottom legend that fit leaves one value
    // label em above the scene; without it the 3-D back wall intrudes into an
    // overlay title even though the title itself does not resize the plot.
    plot_top += style.value_label.font_size_pt;
  }
  let side_category_gap_ratio = match style.layout_profile {
    ChartLayoutProfile::Excel
      if has_side_legend && !has_layout_title && has_automatic_untitled_layout =>
    {
      profiles::EXCEL_AUTOMATIC_UNTITLED_SIDE_CATEGORY_GAP_RATIO
    }
    ChartLayoutProfile::Excel if has_derived_single_series_side_title_layout => {
      profiles::EXCEL_DERIVED_TITLE_SIDE_CATEGORY_GAP_RATIO
    }
    ChartLayoutProfile::Excel
      if has_explicit_single_series_side_title_layout
        || has_legacy_default_single_series_side_title_layout =>
    {
      profiles::EXCEL_EXPLICIT_TITLE_SIDE_CATEGORY_GAP_RATIO
    }
    ChartLayoutProfile::PowerPoint | ChartLayoutProfile::Word | ChartLayoutProfile::Excel => {
      host_side_legend_bands.category_gap_ratio
    }
  };
  let category_plot_gap_ratio =
    if style.layout_profile == ChartLayoutProfile::Word && category_label_line_count > 1.0 {
      profiles::WORD_MULTILINE_CATEGORY_PLOT_GAP_RATIO
    } else if style.layout_profile == ChartLayoutProfile::Excel
      && legend_position.is_none()
      && has_layout_explicit_title
      && chart.plot_layout.is_none()
    {
      profiles::EXCEL_TITLE_ONLY_CATEGORY_PLOT_GAP_RATIO
    } else if (style.layout_profile == ChartLayoutProfile::Excel
      && legend_position.is_none()
      && has_legacy_single_series_title_layout
      && chart.plot_layout.is_none())
      || has_untitled_bottom_column_layout
    {
      profiles::EXCEL_LEGACY_TITLE_CATEGORY_PLOT_GAP_RATIO
    } else if has_untitled_bottom_line_no_marker_layout || has_explicit_bottom_column_layout {
      profiles::EXCEL_BOTTOM_CATEGORY_PLOT_GAP_RATIO
    } else {
      profiles::DEFAULT_CATEGORY_PLOT_GAP_RATIO
    };
  let mut plot_bottom = category_top
    - if word_data_table_layout.is_some() {
      // The first data-table gridline is also the bottom edge of the plot.
      0.0
    } else {
      automatic_band_height_pt
        * if has_side_legend {
          side_category_gap_ratio
        } else if has_bottom_legend && has_explicit_powerpoint_title {
          profiles::POWERPOINT_TITLED_BOTTOM_PLOT_GAP_RATIO
        } else {
          category_plot_gap_ratio
        }
    };
  plot_bottom += frame.height_pt
    * (word_side_adjustment.plot_bottom_ratio
      + word_no_legend_adjustment.plot_bottom_ratio
      + word_horizontal_multilevel_adjustment.plot_bottom_ratio
      + powerpoint_derived_title_adjustment.plot_bottom_ratio
      + powerpoint_generated_title_bottom_adjustment.plot_bottom_ratio)
    + automatic_band_height_pt * word_titled_bottom_adjustment.plot_bottom_ratio;
  plot_bottom +=
    frame.height_pt * powerpoint_generated_title_no_legend_adjustment.plot_bottom_ratio;
  plot_bottom += frame.height_pt * excel_vary_colors_data_table_adjustment.plot_bottom_ratio;
  plot_bottom +=
    frame.height_pt * excel_explicit_date_line_top_right_overlay_adjustment.plot_bottom_ratio;
  plot_bottom += frame.height_pt * modern_single_series_title_adjustment.plot_bottom_ratio;
  plot_bottom += frame.height_pt * legacy_default_single_series_adjustment.plot_bottom_ratio;
  if has_titled_indexed_scatter_layout {
    plot_bottom += frame.height_pt * profiles::EXCEL_TITLED_INDEXED_SCATTER.plot_bottom_ratio;
  } else if has_indexed_scatter_automatic_layout {
    // Excel's untitled scatter profile reserves a wider four-sided axis
    // band than the generic cartesian profile. This is visible when string
    // x-values are imported as indexed positions: Office's fixed output for
    // ser_labels.xlsx places the plot at
    // (0.1078, 0.0579)-(0.9573, 0.8721) of the chart frame. Keep the
    // adjustment relative to the frame so worksheet print scaling and
    // horizontal page clipping continue to apply normally.
    category_top += frame.height_pt * profiles::EXCEL_AUTOMATIC_INDEXED_SCATTER.category_top_ratio;
    plot_top += frame.height_pt * profiles::EXCEL_AUTOMATIC_INDEXED_SCATTER.plot_top_ratio;
    plot_bottom += frame.height_pt * profiles::EXCEL_AUTOMATIC_INDEXED_SCATTER.plot_bottom_ratio;
  }
  if has_unshifted_side_line_layout {
    plot_top += frame.height_pt * profiles::EXCEL_UNSHIFTED_SIDE_LINE.plot_top_ratio;
    plot_bottom += frame.height_pt * profiles::EXCEL_UNSHIFTED_SIDE_LINE.plot_bottom_ratio;
  }
  if horizontal_bar_only && category_hierarchy.is_some() {
    plot_top += category_label_line_height * MULTILEVEL_VERTICAL_PLOT_TOP_INSET_LINES;
    plot_bottom -= category_label_line_height * MULTILEVEL_VERTICAL_PLOT_BOTTOM_INSET_LINES;
  }
  if word_data_table_layout.is_some() {
    // Generic untitled Word charts add a separate category/plot clearance.
    // A data table replaces that clearance: its header starts exactly at the
    // plot's bottom gridline (also observed in the Office PDF vector paths).
    plot_bottom = category_top;
  }
  if plot_bottom <= plot_top {
    return Vec::new();
  }

  let value_number_format =
    vertical_axis_number_format_code(chart, 0).or(percent_stacked.then_some("0%"));
  let value_display_unit = chart.value_axis.map_or(1.0, value_axis_display_unit);
  let tick_labels = scale_tick_labels(
    scale.minimum,
    scale.maximum,
    scale.major_unit,
    value_number_format,
    scale.logarithmic_base,
    value_display_unit,
  );
  let word_parallel_layout_base = style.layout_profile == ChartLayoutProfile::Word
    && chart.plot_layout.is_none()
    && category_hierarchy.is_none()
    && chart.axis_sets.len() == 1
    && matches!(
      chart.legend_position,
      None
        | Some(ChartLegendPosition::Bottom | ChartLegendPosition::Top | ChartLegendPosition::Right)
    )
    && chart.view_3d.is_some_and(|view| view.right_angle_axes)
    && chart.series.iter().all(|series| {
      series.is_3d
        && matches!(
          series.grouping,
          ChartSeriesGrouping::Clustered
            | ChartSeriesGrouping::Stacked
            | ChartSeriesGrouping::PercentStacked
        )
    });
  let word_parallel_column_layout = word_parallel_layout_base
    && chart
      .series
      .iter()
      .all(|series| series.kind == ChartSeriesKind::Column);
  let word_parallel_bar_layout = word_parallel_layout_base
    && horizontal_bar_only
    && chart
      .series
      .iter()
      .all(|series| series.grouping == ChartSeriesGrouping::Clustered);
  let word_parallel_layout = word_parallel_column_layout || word_parallel_bar_layout;
  // Office's numeric label reservation also measures the two inner samples
  // min + major and max - major, even on a logarithmic axis where these are
  // not painted ticks. Conditional-number-format COM controls identify these
  // exact values independently of the visible labels and series magnitudes.
  let mut measured_tick_labels = tick_labels.clone();
  if word_parallel_column_layout && let Some(native_major_unit) = scale.logarithmic_base {
    // The model's logarithmic major_unit is an exponent step; Office's
    // MajorUnit API reports the base itself (2/5/10 native controls).
    for value in [
      scale.minimum + native_major_unit,
      scale.maximum - native_major_unit,
    ] {
      measured_tick_labels.push((
        value,
        crate::render::chart::format_chart_number(value / value_display_unit, value_number_format),
      ));
    }
  }
  let maximum_tick_width = if value_tick_labels_visible {
    measured_tick_labels
      .iter()
      .map(|(_, label)| {
        if word_parallel_column_layout {
          word_chart_tick_label_width(label, &style.value_label, &mut metrics)
        } else {
          metrics.measure_text(label, &style.value_label)
        }
      })
      .fold(0.0_f32, f32::max)
  } else {
    0.0
  };
  let secondary_value_tick_sets = axis_scales
    .iter()
    .enumerate()
    .skip(1)
    .filter_map(|(axis_set_index, axes)| {
      let axis = axis_set_value_axis(chart, axis_set_index)?;
      if !value_axis_is_visible(axis)
        || axis
          .tick_label_position
          .as_ref()
          .is_some_and(|position| position.val == Some(c::TickLabelPositionValues::None))
        || radar_only
        || horizontal_bar_only
      {
        return None;
      }
      let format_code = vertical_axis_number_format_code(chart, axis_set_index)
        .or_else(|| axis_set_is_percent_stacked(chart, axis_set_index).then_some("0%"));
      let labels = scale_tick_labels(
        axes.y.minimum,
        axes.y.maximum,
        axes.y.major_unit,
        format_code,
        axes.y.logarithmic_base,
        value_axis_display_unit(axis),
      );
      let width = labels
        .iter()
        .map(|(_, label)| metrics.measure_text(label, &style.value_label))
        .fold(0.0_f32, f32::max);
      Some((
        axis_set_index,
        axis,
        axes.y,
        labels,
        width,
        value_axis_is_on_right(axis),
      ))
    })
    .collect::<Vec<_>>();
  let word_combination_layout = word_automatic_combination_layout(chart, style);
  let word_manual_bottom_layout = word_manual_bottom_cartesian_layout(chart, style);
  let secondary_axis_tick_gap = if word_combination_layout || word_manual_bottom_layout {
    metrics
      .vertical_metrics_for_text("0", &style.value_label)
      .line_height_pt()
      * profiles::WORD_HORIZONTAL_BAR_AXIS_BAND_LINE_HEIGHTS
      * 0.5
  } else {
    frame.height_pt * profiles::DEFAULT_TICK_GAP_RATIO
  };
  let secondary_left_value_axis_band_width = secondary_value_tick_sets
    .iter()
    .filter(|(_, _, _, _, _, on_right)| !on_right)
    .map(|(_, _, _, _, width, _)| *width + secondary_axis_tick_gap)
    .sum::<f32>();
  let secondary_right_value_axis_band_width = secondary_value_tick_sets
    .iter()
    .filter(|(_, _, _, _, _, on_right)| *on_right)
    .map(|(_, _, _, _, width, _)| *width + secondary_axis_tick_gap)
    .sum::<f32>();
  let side_legend_width = if has_side_legend {
    vertical_legend_width(chart, style, scale, &mut metrics)
  } else {
    0.0
  };
  let word_fixed_line_legend_frame_width =
    word_fixed_line_legend_frame_width(chart, style, scale, &mut metrics);
  let word_marker_legend_frame_width =
    word_marker_legend_frame_width(chart, style, scale, &mut metrics);
  let word_scatter_layout = word_automatic_scatter_layout(chart, style);
  let word_scatter_value_line = metrics
    .vertical_metrics_for_text("0", &style.value_label)
    .line_height_pt();
  let word_scatter_value_line = if word_parallel_layout {
    word_chart_layout_metric(word_scatter_value_line)
  } else {
    word_scatter_value_line
  };
  let word_scatter_category_line = metrics
    .vertical_metrics_for_text("0", &style.category_label)
    .line_height_pt();
  let word_scatter_category_line = if word_parallel_layout {
    word_chart_layout_metric(word_scatter_category_line)
  } else {
    word_scatter_category_line
  };
  // Bubble sizing precedes tick-label reservation. Native width/height,
  // title, data-range and 10–300% scale controls use this outer allocation;
  // shrinking the final inside plot must not shrink the bubble a second time.
  let bubble_reference_extent = word_scatter_layout.then(|| {
    let legend_band = if has_side_legend {
      word_fixed_line_legend_frame_width
        .or(word_marker_legend_frame_width)
        .unwrap_or(side_legend_width)
        + 6.0 * style.stroke_scale
    } else {
      0.0
    };
    (frame.width_pt - 10.0 * style.stroke_scale - legend_band)
      .min(
        frame.height_pt
          - 10.0 * style.stroke_scale
          - word_scatter_title_band(chart, style, &mut metrics),
      )
      .max(0.0)
  });
  let word_scatter_endpoint_width = if word_scatter_layout {
    axis_scales
      .first()
      .and_then(|axes| axes.x)
      .map_or(0.0, |scale| {
        scatter_axis_endpoint_width(chart, scale, &style.category_label, &mut metrics)
      })
  } else {
    0.0
  };
  let side_plot_outer_margin = frame.height_pt * profiles::CARTESIAN_SIDE_PLOT_OUTER_MARGIN_RATIO;
  let side_legend_outer_margin = if style.chartsheet {
    2.0 * style.stroke_scale
  } else {
    frame.height_pt
      * match style.layout_profile {
        ChartLayoutProfile::Excel
          if !has_layout_title
            && has_automatic_untitled_layout
            && (chart.has_explicit_categories
              || (chart.title_overlay
                && matches!(chart.title.as_ref(), Some(ChartTitleText::Automatic)))
              || has_indexed_scatter_automatic_layout) =>
        {
          profiles::EXCEL_AUTOMATIC_UNTITLED_SIDE_LEGEND_OUTER_MARGIN_RATIO
        }
        ChartLayoutProfile::Excel if has_derived_single_series_side_title_layout => {
          profiles::EXCEL_DERIVED_TITLE_SIDE_LEGEND_OUTER_MARGIN_RATIO
        }
        ChartLayoutProfile::PowerPoint | ChartLayoutProfile::Word | ChartLayoutProfile::Excel => {
          host_side_legend_bands.legend_outer_margin_ratio
        }
      }
  };
  let side_plot_gap = frame.height_pt
    * match style.layout_profile {
      ChartLayoutProfile::Excel
        if has_side_legend
          && !has_layout_title
          && has_automatic_untitled_layout
          && (chart.cached_category_count == 2
            || chart.has_explicit_categories
            || (chart.title_overlay
              && matches!(chart.title.as_ref(), Some(ChartTitleText::Automatic)))) =>
      {
        profiles::EXCEL_AUTOMATIC_UNTITLED_COMPACT_SIDE_PLOT_GAP_RATIO
      }
      ChartLayoutProfile::Excel
        if has_side_legend && !has_layout_title && has_automatic_untitled_layout =>
      {
        profiles::EXCEL_AUTOMATIC_UNTITLED_WIDE_SIDE_PLOT_GAP_RATIO
      }
      ChartLayoutProfile::Excel if has_unshifted_side_line_layout => {
        profiles::EXCEL_UNSHIFTED_LINE_SIDE_PLOT_GAP_RATIO
      }
      ChartLayoutProfile::PowerPoint | ChartLayoutProfile::Word | ChartLayoutProfile::Excel => {
        host_side_legend_bands.plot_gap_ratio
      }
    }
    + if has_legacy_default_single_series_side_title_layout {
      // The compact automatic label (`Series1` / `系列1`) does not donate its
      // removed word-space to the plot; Excel retains that half-em as part of
      // the side legend reservation.
      style.legend.font_size_pt * profiles::EXCEL_LEGACY_DEFAULT_SINGLE_SERIES_LEGEND_RESERVATION_EM
    } else {
      0.0
    };
  let tick_left_ratio = if has_titled_indexed_scatter_layout {
    profiles::EXCEL_TITLED_INDEXED_SCATTER_TICK_LEFT_RATIO
  } else if has_legacy_single_series_title_layout {
    profiles::EXCEL_LEGACY_SINGLE_SERIES_TICK_LEFT_RATIO
  } else if has_untitled_bottom_column_layout {
    profiles::EXCEL_UNTITLED_BOTTOM_COLUMN_TICK_LEFT_RATIO
  } else if word_uses_hidden_vertical_value_band(
    style.layout_profile,
    value_tick_labels_visible,
    horizontal_bar_only,
  ) {
    profiles::WORD_HIDDEN_VALUE_TICK_LEFT_RATIO
  } else if has_side_legend {
    match style.layout_profile {
      ChartLayoutProfile::Excel if !has_layout_title && has_automatic_untitled_layout => {
        profiles::EXCEL_AUTOMATIC_UNTITLED_SIDE_TICK_LEFT_RATIO
      }
      ChartLayoutProfile::PowerPoint | ChartLayoutProfile::Word | ChartLayoutProfile::Excel => {
        host_side_legend_bands.tick_left_ratio
      }
    }
  } else {
    if has_explicit_title_indexed_scatter_layout {
      profiles::DEFAULT_TICK_LEFT_RATIO
    } else if style.layout_profile == ChartLayoutProfile::Excel
      && legend_position.is_none()
      && has_layout_explicit_title
      && chart.plot_layout.is_none()
    {
      profiles::EXCEL_TITLE_ONLY_TICK_LEFT_RATIO
    } else if has_bottom_legend && has_explicit_powerpoint_title {
      profiles::POWERPOINT_TITLED_BOTTOM_TICK_LEFT_RATIO
    } else {
      profiles::DEFAULT_TICK_LEFT_RATIO
    }
  };
  let primary_value_axis_title_band_width =
    if !horizontal_bar_only && chart.value_axis_title.is_some() {
      line_height(&style.label) * 2.0
    } else {
      0.0
    };
  let tick_left = frame.x_pt
    + automatic_band_height_pt * tick_left_ratio
    + if primary_value_axis_on_right {
      0.0
    } else {
      primary_value_axis_title_band_width
    }
    + if has_derived_single_series_side_title_layout {
      frame.height_pt * profiles::EXCEL_DERIVED_SINGLE_SERIES_SIDE_TITLE.tick_left_ratio
    } else if has_explicit_single_series_side_title_layout {
      frame.height_pt * profiles::EXCEL_EXPLICIT_SINGLE_SERIES_SIDE_TITLE.tick_left_ratio
    } else if has_untitled_bottom_line_no_marker_layout {
      frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_LINE_NO_MARKER.tick_left_ratio
    } else if has_explicit_bottom_column_layout {
      frame.height_pt * profiles::EXCEL_EXPLICIT_BOTTOM_COLUMN.tick_left_ratio
    } else {
      0.0
    }
    + if has_side_legend && legend_position == Some(ChartLegendPosition::Left) {
      side_legend_width + side_plot_outer_margin + side_plot_gap
    } else {
      0.0
    };
  let mut tick_left = tick_left
    + automatic_band_height_pt * word_titled_bottom_adjustment.tick_left_ratio
    + frame.height_pt * word_horizontal_multilevel_adjustment.tick_left_ratio
    + frame.height_pt * powerpoint_derived_title_adjustment.tick_left_ratio
    + frame.height_pt * powerpoint_generated_title_no_legend_adjustment.tick_left_ratio
    + if has_indexed_scatter_automatic_layout {
      frame.height_pt * profiles::EXCEL_AUTOMATIC_INDEXED_SCATTER.tick_left_ratio
    } else if has_legacy_indexed_scatter_layout {
      frame.height_pt * profiles::EXCEL_LEGACY_INDEXED_SCATTER.tick_left_ratio
    } else {
      0.0
    }
    + frame.height_pt * excel_vary_colors_data_table_adjustment.tick_left_ratio;
  tick_left +=
    frame.height_pt * excel_explicit_date_line_top_right_overlay_adjustment.tick_left_ratio;
  if has_word_titled_single_line_no_legend {
    tick_left = frame.x_pt + WORD_TITLED_SINGLE_LINE_TICK_LEFT_PT * style.stroke_scale;
  }
  let tick_gap = if word_parallel_column_layout && value_tick_labels_visible {
    // Native 8/10/14pt and independent label-content/offset controls reserve
    // 0.76 natural lines at the default tick-label offset. This differs from
    // the generic horizontal-bar band and includes the label's own padding.
    word_scatter_value_line * 0.76
  } else if (word_scatter_layout || word_combination_layout || word_manual_bottom_layout)
    && value_tick_labels_visible
  {
    word_scatter_value_line * profiles::WORD_HORIZONTAL_BAR_AXIS_BAND_LINE_HEIGHTS * 0.5
  } else if has_word_titled_single_line_no_legend && value_tick_labels_visible {
    style.value_label.font_size_pt * WORD_TITLED_SINGLE_LINE_TICK_GAP_EM
  } else if chartsheet_category_layout && value_tick_labels_visible {
    metrics
      .vertical_metrics_for_text("0", &style.value_label)
      .line_height_pt()
      * (profiles::EXCEL_CHARTSHEET_AXIS_BAND_LINE_HEIGHTS * 0.5)
  } else if value_tick_labels_visible {
    automatic_band_height_pt
      * if has_side_legend {
        if has_shifted_category_empty_side_legend_layout {
          profiles::EXCEL_SHIFTED_CATEGORY_EMPTY_SIDE_LEGEND_TICK_GAP_RATIO
        } else if has_unshifted_side_line_layout {
          profiles::EXCEL_UNSHIFTED_LINE_SIDE_TICK_GAP_RATIO
        } else {
          host_side_legend_bands.tick_gap_ratio
        }
      } else {
        if has_modern_single_series_scatter_title_layout
          && chart
            .plot_layout
            .is_some_and(|layout| layout.targets_inner_plot)
        {
          profiles::EXCEL_MANUAL_INNER_SCATTER_TICK_GAP_RATIO
        } else if has_bottom_legend && has_explicit_powerpoint_title {
          profiles::POWERPOINT_TITLED_BOTTOM_TICK_GAP_RATIO
        } else {
          profiles::DEFAULT_TICK_GAP_RATIO
        }
      }
  } else {
    0.0
  };
  let primary_value_axis_band_width = maximum_tick_width + tick_gap;
  let left_value_axis_band_width = secondary_left_value_axis_band_width
    + if primary_value_axis_on_right {
      0.0
    } else {
      primary_value_axis_band_width
    };
  let right_value_axis_band_width = secondary_right_value_axis_band_width
    + if primary_value_axis_on_right {
      primary_value_axis_band_width
    } else {
      0.0
    };
  let mut plot_left = tick_left + left_value_axis_band_width;
  let mut plot_right = frame.x_pt + frame.width_pt
    - if has_side_legend {
      side_legend_width + side_plot_outer_margin + side_plot_gap
    } else {
      automatic_band_height_pt
        * if has_bottom_legend && has_explicit_powerpoint_title {
          profiles::POWERPOINT_TITLED_BOTTOM_RIGHT_MARGIN_RATIO
        } else if word_uses_hidden_vertical_value_band(
          style.layout_profile,
          value_tick_labels_visible,
          horizontal_bar_only,
        ) {
          profiles::WORD_HIDDEN_VALUE_RIGHT_MARGIN_RATIO
        } else {
          profiles::DEFAULT_RIGHT_MARGIN_RATIO
        }
    }
    - right_value_axis_band_width
    - if primary_value_axis_on_right {
      primary_value_axis_title_band_width
    } else {
      0.0
    };
  plot_left += frame.height_pt
    * (word_side_adjustment.plot_left_ratio
      + word_no_legend_adjustment.plot_left_ratio
      + word_horizontal_multilevel_adjustment.plot_left_ratio
      + powerpoint_derived_title_adjustment.plot_left_ratio
      + powerpoint_generated_title_no_legend_adjustment.plot_left_ratio
      + legacy_default_single_series_adjustment.plot_left_ratio)
    + automatic_band_height_pt * word_titled_bottom_adjustment.plot_left_ratio;
  plot_right += frame.height_pt
    * (word_side_adjustment.plot_right_ratio
      + word_no_legend_adjustment.plot_right_ratio
      + word_horizontal_multilevel_adjustment.plot_right_ratio
      + powerpoint_derived_title_adjustment.plot_right_ratio
      + powerpoint_generated_title_no_legend_adjustment.plot_right_ratio
      + legacy_default_single_series_adjustment.plot_right_ratio)
    + automatic_band_height_pt * word_titled_bottom_adjustment.plot_right_ratio;
  if style.layout_profile == ChartLayoutProfile::Excel
    && has_side_legend
    && has_layout_explicit_title
    && chart.plot_layout.is_none()
  {
    plot_left += frame.height_pt * excel_side_adjustment.plot_left_ratio;
    plot_right += frame.height_pt * excel_side_adjustment.plot_right_ratio;
  } else if style.layout_profile == ChartLayoutProfile::Excel
    && has_side_legend
    && !has_layout_title
    && has_automatic_untitled_layout
    && chart.plot_layout.is_none()
  {
    plot_left += frame.height_pt * excel_untitled_side_adjustment.plot_left_ratio;
  } else if style.layout_profile == ChartLayoutProfile::Excel
    && legend_position.is_none()
    && has_layout_explicit_title
    && chart.plot_layout.is_none()
  {
    plot_left += frame.height_pt * excel_title_only_adjustment.plot_left_ratio;
    plot_right += frame.height_pt * excel_title_only_adjustment.plot_right_ratio;
  }
  plot_left += frame.height_pt * excel_vary_colors_data_table_adjustment.plot_left_ratio;
  plot_right += frame.height_pt * excel_vary_colors_data_table_adjustment.plot_right_ratio;
  plot_left +=
    frame.height_pt * excel_explicit_date_line_top_right_overlay_adjustment.plot_left_ratio;
  plot_right +=
    frame.height_pt * excel_explicit_date_line_top_right_overlay_adjustment.plot_right_ratio;
  plot_left += frame.height_pt * modern_single_series_title_adjustment.plot_left_ratio;
  plot_right += frame.height_pt * modern_single_series_title_adjustment.plot_right_ratio;
  if has_titled_indexed_scatter_layout {
    plot_left += frame.height_pt * profiles::EXCEL_TITLED_INDEXED_SCATTER.plot_left_ratio;
    plot_right += frame.height_pt * profiles::EXCEL_TITLED_INDEXED_SCATTER.plot_right_ratio;
  } else if has_indexed_scatter_automatic_layout {
    plot_left += frame.height_pt * profiles::EXCEL_AUTOMATIC_INDEXED_SCATTER.plot_left_ratio;
    plot_right += frame.height_pt * profiles::EXCEL_AUTOMATIC_INDEXED_SCATTER.plot_right_ratio;
  } else if has_legacy_indexed_scatter_layout {
    plot_right += frame.height_pt * profiles::EXCEL_LEGACY_INDEXED_SCATTER.plot_right_ratio;
  } else if has_legacy_single_series_title_layout {
    plot_left += frame.height_pt * profiles::EXCEL_LEGACY_SINGLE_SERIES_TITLE.plot_left_ratio;
    plot_right += frame.height_pt * profiles::EXCEL_LEGACY_SINGLE_SERIES_TITLE.plot_right_ratio;
  } else if has_untitled_bottom_column_layout {
    plot_left += frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_COLUMN.plot_left_ratio;
    plot_right += frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_COLUMN.plot_right_ratio;
  } else if has_derived_single_series_side_title_layout {
    plot_right +=
      frame.height_pt * profiles::EXCEL_DERIVED_SINGLE_SERIES_SIDE_TITLE.plot_right_ratio;
  } else if has_explicit_single_series_side_title_layout {
    plot_left +=
      frame.height_pt * profiles::EXCEL_EXPLICIT_SINGLE_SERIES_SIDE_TITLE.plot_left_ratio;
    plot_right +=
      frame.height_pt * profiles::EXCEL_EXPLICIT_SINGLE_SERIES_SIDE_TITLE.plot_right_ratio;
  } else if has_untitled_bottom_line_no_marker_layout {
    plot_left += frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_LINE_NO_MARKER.plot_left_ratio;
    plot_right += frame.height_pt * profiles::EXCEL_UNTITLED_BOTTOM_LINE_NO_MARKER.plot_right_ratio;
  } else if has_explicit_bottom_column_layout {
    plot_left += frame.height_pt * profiles::EXCEL_EXPLICIT_BOTTOM_COLUMN.plot_left_ratio;
    plot_right += frame.height_pt * profiles::EXCEL_EXPLICIT_BOTTOM_COLUMN.plot_right_ratio;
  }
  if style.layout_profile == ChartLayoutProfile::Excel
    && has_side_legend
    && !has_layout_title
    && has_automatic_untitled_layout
    && chart.has_explicit_categories
    && chart.plot_layout.is_none()
  {
    // Excel's explicit-category automatic chart profile keeps a slightly
    // larger value-axis inset while extending the right edge of the plot.
    // The ratios come from the Office fixed-output geometry of
    // chart-area-style-border.xlsx and are independent of page coordinates.
    plot_left += frame.height_pt * profiles::EXCEL_EXPLICIT_CATEGORY_AUTOMATIC.plot_left_ratio;
    plot_right += frame.height_pt * profiles::EXCEL_EXPLICIT_CATEGORY_AUTOMATIC.plot_right_ratio;
    plot_top += frame.height_pt * profiles::EXCEL_EXPLICIT_CATEGORY_AUTOMATIC.plot_top_ratio;
    plot_bottom += frame.height_pt * profiles::EXCEL_EXPLICIT_CATEGORY_AUTOMATIC.plot_bottom_ratio;
  }
  if has_shifted_category_empty_side_legend_layout {
    let adjustment = profiles::EXCEL_SHIFTED_CATEGORY_EMPTY_SIDE_LEGEND;
    category_top += frame.height_pt * adjustment.category_top_ratio;
    plot_left += frame.height_pt * adjustment.plot_left_ratio;
    plot_right += frame.height_pt * adjustment.plot_right_ratio;
    plot_top += frame.height_pt * adjustment.plot_top_ratio;
    plot_bottom += frame.height_pt * adjustment.plot_bottom_ratio;
  }
  if has_legacy_styleless_single_series_device_layout {
    // A style-less Excel 12 chart uses a distinct automatic inner-plot
    // rectangle inside the unchanged chart-area frame. Microsoft ChartArea's
    // Position/InnerPlotPosition contract and the archived Chart Controls
    // samples preserve that ownership split. Apply the named fixed-device
    // profile only after automatic semantic bands have been resolved; modern
    // c:style charts and authored manual plot rectangles bypass it.
    let scale = style.stroke_scale;
    category_top += legacy_styleless_device_adjustment.category_top_pt * scale;
    plot_top += legacy_styleless_device_adjustment.plot_top_pt * scale;
    plot_bottom += legacy_styleless_device_adjustment.plot_bottom_pt * scale;
    plot_left += legacy_styleless_device_adjustment.plot_x_pt * scale;
    plot_right += legacy_styleless_device_adjustment.plot_x_pt * scale;
  }
  if horizontal_bar_only {
    let category_labels = category_hierarchy
      .map(|hierarchy| hierarchy.expanded_level(0))
      .unwrap_or_else(|| chart.categories.clone());
    let category_width = category_labels
      .iter()
      .map(|category| metrics.measure_text(category, &style.category_label))
      .fold(0.0_f32, f32::max);
    let hierarchy_width = vertical_category_level_layouts
      .iter()
      .map(|level| level.band_width)
      .sum::<f32>();
    plot_left += category_width
      + style.category_label.font_size_pt
        * if word_marker_legend_frame_width.is_some() {
          WORD_PERCENT_BAR_CATEGORY_LABEL_GAP_EM
        } else {
          0.8
        }
      + hierarchy_width;
    if horizontal_value_tick_labels_visible {
      plot_bottom -= label_line_height
        * if word_marker_legend_frame_width.is_some() {
          1.0
        } else {
          1.35
        };
    }
    if let Some(legend_width) = word_marker_legend_frame_width {
      plot_right = frame.x_pt + frame.width_pt
        - (WORD_PERCENT_BAR_LEGEND_FRAME_RIGHT_INSET_PT + WORD_PERCENT_BAR_LEGEND_PLOT_GAP_PT)
          * style.stroke_scale
        - legend_width;
    }
    if style.layout_profile == ChartLayoutProfile::Word
      && !has_layout_title
      && !has_layout_reserving_legend
      && chart.plot_layout.is_none()
      && chart.view_3d.is_none()
      && category_hierarchy.is_none()
      && chart.category_axis_title.is_none()
      && chart.value_axis_title.is_none()
      && chart.data_table.is_none()
    {
      // Word's PlotArea includes the labels, whereas InsideWidth/Height
      // exclude them. Width/height, independent axis-font, hidden-label and
      // font-face controls retain fixed outer insets. In particular, the
      // final numeric label needs half its width beyond the right endpoint;
      // a frame-height ratio loses that reservation on horizontal bars.
      let device = style.stroke_scale;
      let category_band = metrics
        .vertical_metrics_for_text("Mg", &style.category_label)
        .line_height_pt()
        * profiles::WORD_HORIZONTAL_BAR_AXIS_BAND_LINE_HEIGHTS;
      let value_band = metrics
        .vertical_metrics_for_text("0", &style.value_label)
        .line_height_pt()
        * profiles::WORD_HORIZONTAL_BAR_AXIS_BAND_LINE_HEIGHTS;
      plot_left = frame.x_pt + 6.5 * device + category_width + category_band * 0.5;
      plot_top = frame.y_pt + 11.0 * device;
      let endpoint_width = if horizontal_value_tick_labels_visible {
        tick_labels
          .iter()
          .max_by(|(left, _), (right, _)| left.total_cmp(right))
          .map_or(0.0, |(_, label)| {
            metrics.measure_text(label, &style.value_label)
          })
      } else {
        0.0
      };
      plot_right = frame.x_pt + frame.width_pt - 11.0 * device - endpoint_width * 0.5;
      plot_bottom = frame.y_pt + frame.height_pt
        - if horizontal_value_tick_labels_visible {
          6.5 * device + value_band
        } else {
          11.0 * device
        };
    }
  }
  if word_scatter_layout {
    // COM Inside* excludes axis labels. Width/height and independent-axis-font
    // controls retain 6.5pt leading, an 11pt outer inset, and half the last
    // numeric X label beyond the plot. The upper Y label is also centered
    // on its endpoint and must fit inside the chart area.
    let device = style.stroke_scale;
    tick_left = frame.x_pt + 6.5 * device;
    plot_left = tick_left + maximum_tick_width + tick_gap;
    plot_top = frame.y_pt
      + word_scatter_title_band(chart, style, &mut metrics)
      + (11.0 * device).max(5.0 * device + word_scatter_value_line * 0.5);
    plot_right = frame.x_pt + frame.width_pt
      - word_fixed_line_legend_frame_width
        .or(word_marker_legend_frame_width)
        .map_or_else(
          || {
            if has_side_legend {
              side_legend_width + 17.0 * device
            } else {
              11.0 * device
            }
          },
          |width| width + 17.0 * device,
        )
      - word_scatter_endpoint_width * 0.5;
    plot_bottom = frame.y_pt + frame.height_pt
      - 6.5 * device
      - word_scatter_category_line * profiles::WORD_HORIZONTAL_BAR_AXIS_BAND_LINE_HEIGHTS;
  }
  if word_combination_layout || word_manual_bottom_layout {
    // Both numeric axes own a measured label band, regardless of chart-group
    // order. Word COM width/height/font and no-legend controls preserve the
    // 6.5pt outer label inset; a right legend adds its frame plus 6pt.
    let device = style.stroke_scale;
    tick_left = frame.x_pt + 6.5 * device;
    plot_left = tick_left + left_value_axis_band_width;
    plot_right = frame.x_pt + frame.width_pt
      - right_value_axis_band_width
      - 6.5 * device
      - word_fixed_line_legend_frame_width.map_or(0.0, |width| width + 6.0 * device);
    plot_top = frame.y_pt + (11.0 * device).max(5.0 * device + word_scatter_value_line * 0.5);
    plot_bottom = frame.y_pt + frame.height_pt
      - 6.5 * device
      - word_scatter_category_line * profiles::WORD_HORIZONTAL_BAR_AXIS_BAND_LINE_HEIGHTS;
    category_top = plot_bottom + style.category_label.font_size_pt * 0.7;
  }
  if word_manual_bottom_layout {
    // Manual legend coordinates position the painted legend, not the automatic
    // reservation. Office keeps the reservation when only Left/Top/Width/Height
    // change, and recomputes it when text, font or chart width changes.
    plot_top += word_scatter_title_band(chart, style, &mut metrics);
    if !chart.legend_overlay {
      plot_bottom -= word_bottom_line_legend_reservation(frame, chart, style, scale, &mut metrics);
    }
    category_top = plot_bottom + style.category_label.font_size_pt * 0.7;
    if let Some(title) = chart.value_axis_title.as_deref() {
      let band = word_axis_title_band(
        title,
        &style.value_axis_title,
        style.stroke_scale,
        &mut metrics,
      );
      if primary_value_axis_on_right {
        plot_right -= band;
      } else {
        tick_left += band;
        plot_left += band;
      }
    }
    for (index, title) in chart.additional_axis_titles.iter().enumerate() {
      let title_style = style
        .additional_axis_titles
        .get(index)
        .unwrap_or(&style.label);
      let band = word_axis_title_band(&title.text, title_style, style.stroke_scale, &mut metrics);
      match title.position {
        c::AxisPositionValues::Left => {
          tick_left += band;
          plot_left += band;
        }
        c::AxisPositionValues::Right => plot_right -= band,
        _ => {}
      }
    }
  }
  if chartsheet_category_layout {
    // Native width/height, font-size and no-legend controls retain fixed
    // outer margins. Axis bands grow with font metrics, not chart height.
    let device_scale = style.stroke_scale;
    let value_height = metrics
      .vertical_metrics_for_text("0", &style.value_label)
      .line_height_pt();
    let category_height = metrics
      .vertical_metrics_for_text("Mg", &style.category_label)
      .line_height_pt();
    tick_left = frame.x_pt + 6.5 * device_scale;
    plot_left = tick_left + maximum_tick_width + tick_gap;
    plot_top = frame.y_pt + (11.0 * device_scale).max(5.0 * device_scale + value_height * 0.5);
    plot_right = frame.x_pt + frame.width_pt
      - if has_side_legend {
        side_legend_width + 17.0 * device_scale
      } else {
        11.0 * device_scale
      };
    let leaf_band = if category_label_rotation.abs() <= f32::EPSILON {
      category_height
        * profiles::EXCEL_CHARTSHEET_AXIS_BAND_LINE_HEIGHTS
        * category_label_line_count
    } else {
      category_leaf_label_height + category_height * 0.5
    };
    let parent_bands = hierarchical_category_level_layouts
      .iter()
      .map(|level| {
        category_height
          * profiles::EXCEL_CHARTSHEET_AXIS_BAND_LINE_HEIGHTS
          * level
            .groups
            .iter()
            .map(|group| group.lines.len())
            .max()
            .unwrap_or(1) as f32
      })
      .sum::<f32>();
    plot_bottom = frame.y_pt + frame.height_pt
      - 6.5 * device_scale
      - if category_tick_labels_visible {
        leaf_band + parent_bands
      } else {
        4.5 * device_scale
      };
    category_top = plot_bottom + category_height * 0.5;
  }
  if let Some(layout) = word_data_table_layout {
    // Word's data table owns a separate left series column. Its width is
    // measured before dividing the remaining plot into category columns.
    // The fixed chart viewport inset is visible in both PDF geometry and
    // Word's PlotArea.InsideTop/InsideLeft COM coordinates.
    plot_left = plot_left.max(layout.outer_left + layout.series_column_width);
    plot_top += if word_fixed_line_legend_frame_width.is_some() {
      WORD_DATA_TABLE_LINE_LEGEND_PLOT_TOP_INSET_PT * style.stroke_scale
    } else {
      4.0 * style.stroke_scale
    };
    if let Some(legend_width) = word_fixed_line_legend_frame_width {
      plot_right = frame.x_pt + frame.width_pt
        - (WORD_DATA_TABLE_LINE_LEGEND_FRAME_RIGHT_INSET_PT
          + WORD_DATA_TABLE_LINE_LEGEND_PLOT_GAP_PT)
          * style.stroke_scale
        - legend_width;
    } else {
      plot_right -= 4.0 * style.stroke_scale;
    }
  }
  if has_word_titled_single_line_no_legend {
    // Word COM width/height controls keep these automatic inner-plot bands
    // fixed in points; value-axis font changes only the left measured band,
    // while category font changes only the bottom label band.
    plot_top += WORD_TITLED_SINGLE_LINE_TOP_INSET_PT * style.stroke_scale;
    plot_right =
      frame.x_pt + frame.width_pt - WORD_TITLED_SINGLE_LINE_RIGHT_INSET_PT * style.stroke_scale;
    plot_bottom = frame.y_pt + frame.height_pt
      - WORD_TITLED_SINGLE_LINE_BOTTOM_INSET_PT * style.stroke_scale
      - WORD_TITLED_SINGLE_LINE_CATEGORY_BOTTOM_EM * style.category_label.font_size_pt;
  }
  let parallel_data_table_layout = if word_parallel_layout {
    chart.data_table.map(|table| {
      let mut layout = measure_word_data_table_layout(frame, chart, table, style, &mut metrics);
      let table_line = word_chart_layout_metric(
        metrics
          .vertical_metrics_for_text("Mg", &style.label)
          .line_height_pt(),
      );
      layout.body_row_height = table_line + 3.375 * style.stroke_scale;
      layout.key_width = table_line * 0.45;
      layout.key_height = layout.key_width;
      if data_table_shows_keys(table) {
        // Filled 3-D keys share the square legend key; the 2-D line-key
        // reservation is wider. Native keyed/unkeyed table controls preserve
        // the series-name position and extend only the leading key column.
        let name_width = chart
          .series
          .iter()
          .map(|series| metrics.measure_text(&series.name, &style.label))
          .fold(0.0_f32, f32::max);
        layout.series_column_width = layout.key_width * 1.5
          + 0.75 * style.stroke_scale
          + style.label.font_size_pt * profiles::DEFAULT_HORIZONTAL_CARTESIAN_LEGEND.marker_gap_em
          + name_width
          + 2.6 * style.stroke_scale;
      }
      // Native font and series-count controls separate the table text line,
      // category clearance, and the body rows in the nominal 2-D plot budget.
      layout.header_height = if word_parallel_bar_layout {
        // A horizontal table retains its own category header below the value
        // labels. Native 8/10/12/14/16pt controls reserve one table line and
        // 12pt clearance, independently of the category-axis font.
        layout.outer_left = frame.x_pt + 11.0 * style.stroke_scale;
        table_line + 12.0 * style.stroke_scale
      } else {
        table_line + 0.26 * word_scatter_category_line - 1.5 * style.stroke_scale
      };
      layout
    })
  } else {
    None
  };
  if word_parallel_column_layout {
    // COM Inside* describes the equivalent 2-D plot. Display-unit text owns
    // a separate rotated text box (natural line height + 3pt internal and
    // 6pt external clearance), independently of the numeric tick labels.
    let unit_band = chart
      .value_axis
      .and_then(|axis| value_axis_display_unit_label_text(axis, chart.ui_language.as_deref()))
      .map_or(0.0, |label| {
        let mut unit_style = style.value_label.clone();
        unit_style.bold = true;
        word_chart_layout_metric(
          metrics
            .vertical_metrics_for_text(&label, &unit_style)
            .line_height_pt(),
        ) + 9.0 * style.stroke_scale
      });
    let axis_title_band = chart.value_axis_title.as_deref().map_or(0.0, |title| {
      word_chart_layout_metric(word_axis_title_band(
        title,
        &style.value_axis_title,
        style.stroke_scale,
        &mut metrics,
      ))
    });
    let unit_band = unit_band + axis_title_band;
    tick_left = frame.x_pt
      + 6.5 * style.stroke_scale
      + if primary_value_axis_on_right {
        0.0
      } else {
        unit_band
      };
    plot_left = tick_left + left_value_axis_band_width;
    plot_right = frame.x_pt + frame.width_pt
      - 11.0 * style.stroke_scale
      - right_value_axis_band_width
      - if primary_value_axis_on_right {
        unit_band
      } else {
        0.0
      };
    if has_side_legend {
      // Word's right legend owns its complete frame plus a fixed 6pt gap.
      // Native no-legend/bottom/right and width/font controls preserve the
      // remaining plot bands while changing only this reservation.
      plot_right -= side_legend_width + 6.0 * style.stroke_scale;
    }
    if let Some(layout) = parallel_data_table_layout {
      plot_left = plot_left.max(layout.outer_left + layout.series_column_width);
    }
    plot_top = frame.y_pt
      + word_scatter_title_band(chart, style, &mut metrics)
      + (11.0 * style.stroke_scale).max(5.0 * style.stroke_scale + word_scatter_value_line * 0.5);
    if has_top_legend {
      plot_top += word_bottom_line_legend_reservation(frame, chart, style, scale, &mut metrics);
    }
    // Independent 8/10/14pt category/title/legend controls retain these
    // physical bands when the chart width or height changes. The category
    // title owns its natural line plus 9pt; the legend uses its existing
    // measured row reservation, independently of the title.
    if category_tick_labels_visible && category_label_line_count == 1.0 {
      plot_bottom =
        frame.y_pt + frame.height_pt - 6.5 * style.stroke_scale - word_scatter_category_line * 1.52;
      if let Some(title) = chart.category_axis_title.as_deref() {
        plot_bottom -= word_chart_layout_metric(
          metrics
            .vertical_metrics_for_text(title, &style.category_axis_title)
            .line_height_pt(),
        ) + 9.0 * style.stroke_scale;
      }
      if has_bottom_legend {
        plot_bottom -=
          word_bottom_line_legend_reservation(frame, chart, style, scale, &mut metrics);
      }
      category_top = plot_bottom + style.category_label.font_size_pt * 0.7;
    }
    if let Some(layout) = parallel_data_table_layout {
      plot_bottom =
        frame.y_pt + frame.height_pt - 6.5 * style.stroke_scale - layout.height(chart.series.len());
      if has_bottom_legend {
        plot_bottom -=
          word_bottom_line_legend_reservation(frame, chart, style, scale, &mut metrics);
      }
    }
  }
  if word_parallel_bar_layout {
    let category_width = chart
      .categories
      .iter()
      .map(|text| word_chart_tick_label_width(text, &style.category_label, &mut metrics))
      .fold(0.0_f32, f32::max);
    let category_title_band = chart.category_axis_title.as_deref().map_or(0.0, |title| {
      word_chart_layout_metric(word_axis_title_band(
        title,
        &style.category_axis_title,
        style.stroke_scale,
        &mut metrics,
      ))
    });
    let value_title_band = chart.value_axis_title.as_deref().map_or(0.0, |title| {
      word_chart_layout_metric(
        metrics
          .vertical_metrics_for_text(title, &style.value_axis_title)
          .line_height_pt(),
      ) + 9.0 * style.stroke_scale
    });
    let endpoint_width = tick_labels.last().map_or(0.0, |(_, text)| {
      word_chart_tick_label_width(text, &style.value_label, &mut metrics)
    });
    tick_left = frame.x_pt + 6.5 * style.stroke_scale + category_title_band;
    plot_left = tick_left + category_width + 0.76 * word_scatter_category_line;
    plot_right = frame.x_pt + frame.width_pt
      - 11.0 * style.stroke_scale
      - endpoint_width * 0.5
      - if has_side_legend {
        side_legend_width + 6.0 * style.stroke_scale
      } else {
        0.0
      };
    plot_top =
      frame.y_pt + word_scatter_title_band(chart, style, &mut metrics) + 11.0 * style.stroke_scale;
    plot_bottom = frame.y_pt + frame.height_pt
      - 6.5 * style.stroke_scale
      - 1.52 * word_scatter_value_line
      - value_title_band
      - parallel_data_table_layout.map_or(0.0, |layout| layout.height(chart.series.len()));
    if has_bottom_legend {
      plot_bottom -= word_bottom_line_legend_reservation(frame, chart, style, scale, &mut metrics);
    }
    if has_top_legend {
      plot_top += word_bottom_line_legend_reservation(frame, chart, style, scale, &mut metrics);
    }
    category_top = plot_bottom + 0.7 * style.value_label.font_size_pt;
  }
  if plot_right <= plot_left {
    return Vec::new();
  }
  if let Some(layout) = chart.plot_layout {
    let automatic = PlotRect {
      left: plot_left,
      top: plot_top,
      width: plot_right - plot_left,
      height: plot_bottom - plot_top,
    };
    let manual = apply_manual_layout(frame, automatic, layout);
    plot_left = manual.left;
    plot_top = manual.top;
    plot_right = manual.left + manual.width;
    plot_bottom = manual.top + manual.height;
    if layout.targets_inner_plot {
      // ECMA-376 Part 1 §21.2.2.89 defines the inner target as the
      // rectangle excluding axes and axis labels. Keep the automatic
      // label-to-axis gaps, but anchor those outer bands to the authored
      // inner rectangle instead of leaving them at the automatic plot.
      if !primary_value_axis_on_right {
        tick_left = plot_left - maximum_tick_width - tick_gap;
      }
      category_top = plot_bottom + (category_top - automatic.top - automatic.height);
    }
  }
  let mut projection_3d = None;
  let mut scene_raster_bounds = None;
  if let Some(mut view) = chart.view_3d {
    if word_parallel_layout && !view.height_percent_is_explicit {
      // Word Chart.AutoScaling retains the equivalent 2-D plot aspect before
      // fitting the complete rotated scene. Solving the height from the
      // projected box instead stretches the front plane and its value axis.
      view.height_percent = 100.0 * (plot_bottom - plot_top) / (plot_right - plot_left);
      view.height_percent_is_explicit = true;
    }
    let preferred_model_aspect = if word_parallel_bar_layout {
      (
        word_parallel_bar_model_depth(chart, category_count) * view.height_percent / 100.0,
        false,
      )
    } else {
      cartesian_3d_preferred_model_aspect(chart, category_count)
    };
    let mut scene_plot = PlotRect {
      left: plot_left,
      top: plot_top,
      width: plot_right - plot_left,
      height: plot_bottom - plot_top,
    };
    if !horizontal_bar_only && !word_parallel_column_layout {
      // LibreOffice VDiagram::adjustPosAndSize_3d fits the projected scene
      // while preserving its aspect ratio, then centers that scene in the
      // available rectangle. Axis text is the stable physical scale for the
      // residual 2-D band around that scene.
      // Word's fixed-format layout leaves one value-label em between the
      // automatic outer plot and the fitted 3-D scene. PowerPoint and Excel
      // retain the wider 1.2 em host band. Treating all hosts alike narrows a
      // Word scene symmetrically by 0.4 em, compressing every category slot.
      let horizontal_inset = style.value_label.font_size_pt
        * if style.layout_profile == ChartLayoutProfile::Word {
          1.0
        } else {
          1.2
        };
      let vertical_inset = style.value_label.font_size_pt * 0.25;
      if scene_plot.width > horizontal_inset * 2.0 {
        scene_plot.left += horizontal_inset;
        scene_plot.width -= horizontal_inset * 2.0;
      }
      if scene_plot.height > vertical_inset * 2.0 {
        scene_plot.top += vertical_inset;
        scene_plot.height -= vertical_inset * 2.0;
      }
    }
    if let Some((reserve_on_right, reservation)) = cartesian_3d_series_axis_reservation(
      chart,
      scene_plot,
      view,
      preferred_model_aspect,
      style,
      &mut metrics,
    ) {
      // Office balances the projected scene and the series-axis label band as
      // one automatic-layout unit. The scene retains its physical box and is
      // translated by half the label width; shrinking the projection itself
      // incorrectly compresses the category spacing.
      let direction = if reserve_on_right { -1.0 } else { 1.0 };
      scene_plot.left += direction * reservation * 0.5;
      if style.layout_profile == ChartLayoutProfile::PowerPoint {
        scene_plot.top += frame.height_pt * profiles::POWERPOINT_CARTESIAN_3D_SERIES_AXIS_TOP_RATIO;
      }
    }
    plot_left = scene_plot.left;
    plot_top = scene_plot.top;
    plot_right = scene_plot.left + scene_plot.width;
    plot_bottom = scene_plot.top + scene_plot.height;
    let mut projection = cartesian_3d_projection(
      view,
      scene_plot,
      style.layout_profile,
      preferred_model_aspect.0,
      preferred_model_aspect.1,
    );
    if word_parallel_layout {
      scene_raster_bounds = Some(projection.fit_word_parallel_volume(style.stroke_scale));
    }
    projection_3d = Some(projection);
  }
  if plot_right <= plot_left || plot_bottom <= plot_top {
    return Vec::new();
  }
  let mut plot_width = plot_right - plot_left;
  let plot_height = plot_bottom - plot_top;
  // Axis text shares the same scene-to-screen transform as the grid and
  // markers. Right-angle axes are oblique, not unprojected; bypassing their
  // transform places top value ticks at the scene rectangle rather than on
  // the visible front edge and shifts every category label sideways.
  let axis_text_projection_3d = projection_3d;
  let (mut primary_value_axis_x, primary_value_axis_depth) = projection_3d.map_or(
    (
      if primary_value_axis_on_right {
        plot_right
      } else {
        plot_left
      },
      0.0,
    ),
    |projection| {
      projection.vertical_edge_for_visual_side(
        PlotRect {
          left: plot_left,
          top: plot_top,
          width: plot_width,
          height: plot_height,
        },
        primary_value_axis_on_right,
      )
    },
  );
  let (mut primary_value_label_axis_x, primary_value_label_axis_depth) = axis_text_projection_3d
    .map_or(
      (
        if primary_value_axis_on_right {
          plot_right
        } else {
          plot_left
        },
        0.0,
      ),
      |projection| {
        projection.vertical_edge_for_visual_side(
          PlotRect {
            left: plot_left,
            top: plot_top,
            width: plot_width,
            height: plot_height,
          },
          primary_value_axis_on_right,
        )
      },
    );
  let has_outer_value_label_band = has_legacy_single_series_title_layout
    || has_untitled_bottom_column_layout
    || has_untitled_bottom_line_no_marker_layout
    || has_explicit_bottom_column_layout
    || has_titled_indexed_scatter_layout
    || has_indexed_scatter_automatic_layout
    || has_excel_explicit_title_side_legend_layout
    || has_excel_title_only_layout
    || has_excel_vary_colors_data_table_layout
    || has_word_titled_bottom_device_bands;
  // LibreOffice's TickFactory2D keeps the fixed 1 mm
  // AXIS2D_TICKLABELSPACING separate from the projected tick geometry. The
  // ordinary 2D profiles already absorb that spacing into their calibrated
  // band, but a 3D axis is transformed as a line and needs the fixed distance
  // restored after projection. Otherwise every projected value label sits one
  // millimetre too close to its tick.
  let projected_tick_label_spacing = if axis_text_projection_3d.is_some() {
    CARTESIAN_DATA_LABEL_OFFSET_PT
  } else {
    0.0
  };
  let primary_value_label_gap =
    if word_combination_layout || word_manual_bottom_layout || word_parallel_column_layout {
      tick_gap
    } else if primary_value_axis_on_right {
      tick_gap + frame.height_pt * 0.012_59 + projected_tick_label_spacing
    } else if (has_outer_value_label_band || chartsheet_category_layout)
      && axis_text_projection_3d.is_none()
    {
      // These automatic profiles own an outer value-label band independently
      // of the residual plot inset. Deriving labels from
      // `plot_left` with only the generic gap incorrectly carries that residual
      // into every label. Office fixed output for both `smoothed_series`
      // generations, `tdf115012`, `no_marker`, `chart_title`, the three
      // `testChartTitleProperties*Fill` variants, and `autotitledel_2013`,
      // `dispBlanksAs_2013`, and `ser_labels` instead keep the widest label at
      // `tick_left` while the plot remains at its separately adjusted edge.
      // Word's fixed titled-bottom band has the same ownership split: its
      // 6.6pt label edge is stable while the measured label width still
      // contributes to `plot_left`.
      (plot_left - tick_left - maximum_tick_width).max(0.0)
    } else if word_data_table_layout.is_some() {
      // Word's data-table plot keeps one more generated-axis text inset than
      // the ordinary chart plot. The PDF vector gap is 7.3pt for an 8pt axis
      // face versus 4.1pt for the ordinary numeric-label band. A side line
      // legend instead uses the ordinary measured tick gap (9.25pt here).
      tick_gap
        + if word_fixed_line_legend_frame_width.is_some() {
          0.0
        } else {
          style.value_label.font_size_pt * 0.4
        }
    } else {
      tick_gap + projected_tick_label_spacing
    };
  let word_radar_plot = word_automatic_radar_layout(chart, style)
    .then(|| word_automatic_radar_plot(frame, chart, style, scale, &mut metrics));
  let plot = word_radar_plot.map_or(
    PlotRect {
      left: plot_left,
      top: plot_top,
      width: plot_width,
      height: plot_height,
    },
    |(plot, _)| plot,
  );
  let value_axis_is_horizontal = horizontal_bar_only;
  let available_value_axis_length = if let Some((_, outer_diameter)) = word_radar_plot {
    // Office's automatic polar capacity precedes the category-label inset.
    // Native category-font controls shrink the painted net while retaining
    // the same automatic major unit. Do not budget against that inner net.
    outer_diameter * 0.5
  } else if radar_only {
    // A radar value axis runs from the center to the outer polygon. Its label
    // budget is therefore the radius, not the full plot height used by a
    // cartesian value axis.
    plot_width.min(plot_height) * 0.46
  } else if value_axis_is_horizontal {
    plot_width
  } else if let Some(table_layout) = word_data_table_layout {
    // Word selects an automatic major unit from the vertical capacity before
    // the series rows are reserved. Controlled Word COM height variants keep
    // the same major unit with and without c:dTable: 136pt chooses 50 while
    // 140pt chooses 20, even though the painted table plot is only 29..33pt.
    // The series rows return their height to the budget; the viewport inset
    // remains unavailable to axis labels.
    plot_height + table_layout.body_row_height * chart.series.len() as f32
      - 4.0 * style.stroke_scale
  } else {
    projection_3d.map_or(plot_height, |projection| {
      projection.vertical_axis_length(plot, primary_value_axis_on_right)
    })
  };
  let value_axis_text_properties = chart
    .value_axis
    .and_then(|axis| axis.text_properties.as_deref());
  let value_axis_label_rotation = category_axis_text_rotation_degrees(value_axis_text_properties);
  let value_axis_label_extent = maximum_tick_label_axis_pitch(
    &tick_labels,
    &style.value_label,
    style.layout_profile,
    value_axis_label_rotation,
    value_axis_is_horizontal,
    &mut metrics,
  );
  let maximum_auto_increment_count = suppress_duplicate_formatted_tick_budget(
    maximum_auto_main_increment_count(
      style.layout_profile,
      available_value_axis_length,
      value_axis_label_extent,
    ),
    &tick_labels,
  );
  // Polar radius labels and horizontal bar value labels do not use the same
  // Cartesian vertical-label capacity. LibreOffice gives the polar radius a
  // dedicated estimator; PowerPoint fixed output likewise retains five main
  // radar intervals even when the radius is shorter than five complete text
  // bodies. PowerPoint horizontal bars use the same five-interval automatic
  // scale preference. Word's untitled side-legend horizontal bars instead
  // allow six intervals: this gives both 0..100%/20% and 0..5/1 automatic
  // scales while retaining the 0..6/1 counterexample. Keep these typed axis
  // policies out of titled/bottom-legend Word charts, which may use ten
  // intervals when their generated labels fit.
  let word_untitled_side_horizontal_bar = style.layout_profile == ChartLayoutProfile::Word
    && horizontal_bar_only
    && has_side_legend
    && !has_layout_title
    && chart.plot_layout.is_none();
  let maximum_auto_value_increment_count = cartesian_value_axis_increment_budget(
    style.layout_profile,
    radar_only,
    horizontal_bar_only,
    word_untitled_side_horizontal_bar,
    maximum_auto_increment_count,
  );
  let maximum_auto_horizontal_increment_count = axis_scales
    .first()
    .and_then(|axes| axes.x)
    .map(|horizontal_scale| {
      let labels = scale_tick_labels(
        horizontal_scale.minimum,
        horizontal_scale.maximum,
        horizontal_scale.major_unit,
        horizontal_axis_number_format_code(chart, 0),
        horizontal_scale.logarithmic_base,
        axis_set_horizontal_value_axis(chart, 0).map_or(1.0, value_axis_display_unit),
      );
      let text_properties =
        axis_set_horizontal_value_axis(chart, 0).and_then(|axis| axis.text_properties.as_deref());
      let rotation = category_axis_text_rotation_degrees(text_properties);
      suppress_duplicate_formatted_tick_budget(
        maximum_auto_main_increment_count(
          style.layout_profile,
          plot_width,
          maximum_tick_label_axis_pitch(
            &labels,
            &style.category_label,
            style.layout_profile,
            rotation,
            true,
            &mut metrics,
          ),
        ),
        &labels,
      )
    })
    .unwrap_or(maximum_auto_increment_count);
  let axis_scales = cartesian_axis_scales(
    chart,
    style.layout_profile,
    category_count,
    maximum_auto_value_increment_count,
    maximum_auto_horizontal_increment_count,
    Some((plot_width, plot_height)),
  );
  let Some(scale) = axis_scales.first().map(|axes| axes.y) else {
    return Vec::new();
  };
  if scale.maximum <= scale.minimum {
    return Vec::new();
  }
  let tick_labels = scale_tick_labels(
    scale.minimum,
    scale.maximum,
    scale.major_unit,
    value_number_format,
    scale.logarithmic_base,
    value_display_unit,
  );
  let secondary_value_tick_sets = axis_scales
    .iter()
    .enumerate()
    .skip(1)
    .filter_map(|(axis_set_index, axes)| {
      let axis = axis_set_value_axis(chart, axis_set_index)?;
      if !value_axis_is_visible(axis)
        || axis
          .tick_label_position
          .as_ref()
          .is_some_and(|position| position.val == Some(c::TickLabelPositionValues::None))
        || radar_only
        || horizontal_bar_only
      {
        return None;
      }
      let format_code = vertical_axis_number_format_code(chart, axis_set_index)
        .or_else(|| axis_set_is_percent_stacked(chart, axis_set_index).then_some("0%"));
      let labels = scale_tick_labels(
        axes.y.minimum,
        axes.y.maximum,
        axes.y.major_unit,
        format_code,
        axes.y.logarithmic_base,
        value_axis_display_unit(axis),
      );
      let width = labels
        .iter()
        .map(|(_, label)| metrics.measure_text(label, &style.value_label))
        .fold(0.0_f32, f32::max);
      Some((
        axis_set_index,
        axis,
        axes.y,
        labels,
        width,
        value_axis_is_on_right(axis),
      ))
    })
    .collect::<Vec<_>>();
  if projection_3d.is_none() {
    let final_maximum_tick_width = if value_tick_labels_visible {
      tick_labels
        .iter()
        .map(|(_, label)| metrics.measure_text(label, &style.value_label))
        .fold(0.0_f32, f32::max)
    } else {
      0.0
    };
    let final_secondary_left_value_axis_band_width = secondary_value_tick_sets
      .iter()
      .filter(|(_, _, _, _, _, on_right)| !on_right)
      .map(|(_, _, _, _, width, _)| *width + secondary_axis_tick_gap)
      .sum::<f32>();
    let final_secondary_right_value_axis_band_width = secondary_value_tick_sets
      .iter()
      .filter(|(_, _, _, _, _, on_right)| *on_right)
      .map(|(_, _, _, _, width, _)| *width + secondary_axis_tick_gap)
      .sum::<f32>();
    let final_primary_value_axis_band_width = final_maximum_tick_width + tick_gap;
    let final_left_value_axis_band_width = final_secondary_left_value_axis_band_width
      + if primary_value_axis_on_right {
        0.0
      } else {
        final_primary_value_axis_band_width
      };
    let final_right_value_axis_band_width = final_secondary_right_value_axis_band_width
      + if primary_value_axis_on_right {
        final_primary_value_axis_band_width
      } else {
        0.0
      };
    if chart
      .plot_layout
      .is_some_and(|layout| layout.targets_inner_plot)
    {
      if !primary_value_axis_on_right {
        tick_left = plot_left - final_maximum_tick_width - tick_gap;
      }
    } else {
      // ChartView lays out maximum labels with an initial scale, recalculates
      // the automatic scale for the final axis length, then lets the final
      // label boxes resize the residual plot rectangle. Keep that second
      // horizontal reflow: a change from multi-character half-unit labels to
      // single-character unit labels must move both the plot and its category
      // geometry, not merely replace the painted strings.
      plot_left += final_left_value_axis_band_width - left_value_axis_band_width;
      plot_right -= final_right_value_axis_band_width - right_value_axis_band_width;
      if word_scatter_layout
        && let Some(horizontal_scale) = axis_scales.first().and_then(|axes| axes.x)
      {
        let final_endpoint_width =
          scatter_axis_endpoint_width(chart, horizontal_scale, &style.category_label, &mut metrics);
        plot_right -= (final_endpoint_width - word_scatter_endpoint_width) * 0.5;
      }
    }
    if style.layout_profile == ChartLayoutProfile::Word
      && chart.plot_layout.is_none()
      && chart.data_table.is_none()
      && (chart.category_axis.is_some() || chart.date_axis.is_some())
      && category_hierarchy.is_none()
      && !chart.category_axis_shifted
      && category_tick_labels_visible
      && category_label_lines.len() > 1
      && category_label_rotation.abs() <= f32::EPSILON
      && matches!(
        chart.legend_position,
        None | Some(ChartLegendPosition::Bottom | ChartLegendPosition::Right)
      )
      && chart
        .series
        .iter()
        .all(|series| matches!(series.kind, ChartSeriesKind::Line | ChartSeriesKind::Area))
    {
      // A category centered on an endpoint needs half its label outside the
      // inner plot. Office width/height, font and asymmetric-label controls
      // retain 11pt beyond that extent; between-category axes already have
      // half a category slot and do not need this reservation. Apply after
      // numeric scale reflow without moving the independently centered legend.
      let mut label_width = |lines: Option<&Vec<String>>| {
        lines
          .into_iter()
          .flatten()
          .map(|line| metrics.measure_text(line, &style.category_label))
          .fold(0.0_f32, f32::max)
      };
      let first = label_width(category_label_lines.first());
      let last = label_width(category_label_lines.last());
      // Date ticks are already formatted with the host locale above. Office
      // reserves the first/last *painted* tick widths even when the last major
      // tick falls before the axis maximum. A right legend moves the outer
      // label boundary inward; numeric labels on that side can absorb the
      // overhang before the plot itself needs to shrink.
      let mut label_frame = frame;
      if has_side_legend && legend_position == Some(ChartLegendPosition::Right) {
        label_frame.width_pt = plot_right - frame.x_pt
          + final_right_value_axis_band_width
          + if primary_value_axis_on_right {
            primary_value_axis_title_band_width
          } else {
            0.0
          }
          + 11.0 * style.stroke_scale;
      }
      (plot_left, plot_right) = word_category_endpoint_plot_bounds(
        label_frame,
        (plot_left, plot_right),
        (first, last),
        chart.category_axis_reversed,
        style.stroke_scale,
      );
    }
    if plot_right <= plot_left {
      return Vec::new();
    }
    plot_width = plot_right - plot_left;
    primary_value_axis_x = if primary_value_axis_on_right {
      plot_right
    } else {
      plot_left
    };
    primary_value_label_axis_x = primary_value_axis_x;
  }
  // Keep series, labels and plot paint on the same finalized polar rectangle.
  // The Cartesian endpoint-label pass above does not own radar geometry.
  let (plot_left, plot_top, plot_width, plot_height, plot_right, plot_bottom) = word_radar_plot
    .map_or(
      (
        plot_left,
        plot_top,
        plot_width,
        plot_height,
        plot_right,
        plot_bottom,
      ),
      |(plot, _)| {
        (
          plot.left,
          plot.top,
          plot.width,
          plot.height,
          plot.left + plot.width,
          plot.top + plot.height,
        )
      },
    );
  let painted_category_top = if horizontal_bar_only && chart.data_table.is_some() {
    projection_3d.map_or(category_top, |projection| {
      // A horizontal bar chart swaps the category/value coordinate system.
      // In a 3-D scene Office anchors the bottom value axis and its data
      // table to the projected back edge, not to the unprojected front
      // rectangle. Preserve the automatic 2-D gap between plot and table
      // after moving that edge through the authored view3D transform.
      let (_, projected_bottom) = projection.project(plot_left, plot_bottom, 1.0);
      projected_bottom + (category_top - plot_bottom)
    })
  } else {
    category_top
  };
  let axis_line_width = style
    .axis_line_width_pt
    .unwrap_or_else(|| automatic_axis_line_width_pt(style));
  let value_gridline_width = style.value_gridline_width_pt.unwrap_or(axis_line_width);
  let (axis_line_width, value_gridline_width, gridline_color) = projection_3d.map_or(
    (axis_line_width, value_gridline_width, style.gridline_color),
    |projection| {
      (
        projection.pen_width(axis_line_width, style.stroke_scale),
        projection.pen_width(value_gridline_width, style.stroke_scale),
        projection.unlit_pen_color(style.gridline_color),
      )
    },
  );
  let category_crossing_value =
    if style.layout_profile == ChartLayoutProfile::Word && !horizontal_bar_only && !radar_only {
      word_category_axis_crossing_value(chart.value_axis, scale)
    } else {
      0.0_f64.clamp(scale.minimum, scale.maximum)
    };
  let zero_y = value_y(category_crossing_value, scale, plot_top, plot_height);

  let mut items = Vec::new();
  let chart_area_height = (frame.height_pt
    + legacy_styleless_device_adjustment.chart_area_height_pt * style.stroke_scale)
    .max(0.0);
  push_chart_shape_rect(
    &mut items,
    PlotRect {
      left: frame.x_pt,
      top: frame.y_pt,
      width: frame.width_pt,
      height: chart_area_height,
    },
    ChartShapePaint {
      fill: Some(&style.chart_area_style.fill),
      stroke: None,
      fallback_fill_color: None,
      stroke_width_scale: 1.0,
    },
  );
  let (outline_x, outline_y, outline_width, outline_height) = if style.layout_profile
    == ChartLayoutProfile::Excel
    && has_side_legend
    && !has_layout_title
    && has_automatic_untitled_layout
    && chart.has_explicit_categories
    && chart.plot_layout.is_none()
  {
    (
      frame.x_pt - frame.height_pt * 0.000_85,
      frame.y_pt + frame.height_pt * 0.001_46,
      frame.width_pt - frame.height_pt * 0.004,
      frame.height_pt + frame.height_pt * 0.004_31,
    )
  } else {
    (frame.x_pt, frame.y_pt, frame.width_pt, chart_area_height)
  };
  push_chart_shape_rect(
    &mut items,
    PlotRect {
      left: outline_x,
      top: outline_y,
      width: outline_width,
      height: outline_height,
    },
    ChartShapePaint {
      fill: None,
      stroke: Some(&style.chart_area_style.stroke),
      fallback_fill_color: None,
      stroke_width_scale: 1.0,
    },
  );
  let scene_start = items.len();
  if let Some(projection) = projection_3d {
    lower_cartesian_3d_walls(
      &mut items,
      PlotRect {
        left: plot_left,
        top: plot_top,
        width: plot_width,
        height: plot_height,
      },
      projection,
      style,
    );
  } else {
    push_chart_shape_rect(
      &mut items,
      PlotRect {
        left: plot_left,
        top: plot_top,
        width: plot_width,
        height: plot_height,
      },
      ChartShapePaint {
        fill: Some(&style.plot_area_style.fill),
        stroke: Some(&style.plot_area_style.stroke),
        fallback_fill_color: None,
        stroke_width_scale: 1.0,
      },
    );
  }
  if value_gridlines_visible {
    for (value, _) in &tick_labels {
      if matches!(
        style.layout_profile,
        ChartLayoutProfile::Word | ChartLayoutProfile::PowerPoint
      ) && category_axis_visible
        && value.abs() < f64::EPSILON
      {
        // The category-axis stroke owns the zero line in Office fixed output;
        // painting the coincident major gridline would darken it and duplicate
        // the path in the PDF content stream.
        continue;
      }
      let y = value_y(*value, scale, plot_top, plot_height);
      if let Some(projection) = projection_3d {
        let (front_x, front_y) = projection.project(plot_left, y, 0.0);
        let (back_left_x, back_left_y) = projection.project(plot_left, y, 1.0);
        let (back_right_x, back_right_y) = projection.project(plot_right, y, 1.0);
        items.push(PageItem::Line(LineItem {
          x1_pt: back_left_x,
          y1_pt: back_left_y,
          x2_pt: back_right_x,
          y2_pt: back_right_y,
          width_pt: value_gridline_width,
          color: gridline_color,
          kind: LineItemKind::Stroke,
        }));
        items.push(PageItem::Line(LineItem {
          x1_pt: front_x,
          y1_pt: front_y,
          x2_pt: back_left_x,
          y2_pt: back_left_y,
          width_pt: value_gridline_width,
          color: gridline_color,
          kind: LineItemKind::Stroke,
        }));
      } else {
        items.push(PageItem::Line(LineItem {
          x1_pt: plot_left,
          y1_pt: y,
          x2_pt: plot_right,
          y2_pt: y,
          width_pt: value_gridline_width,
          color: gridline_color,
          kind: LineItemKind::Stroke,
        }));
      }
    }
  }
  let mut back_category_axis = if word_parallel_column_layout
    && category_axis_visible
    && cartesian_axis_outline_visible(
      chart
        .category_axis
        .and_then(|axis| axis.chart_shape_properties.as_deref())
        .or_else(|| {
          chart
            .date_axis
            .and_then(|axis| axis.chart_shape_properties.as_deref())
        }),
    ) {
    projection_3d.map(|projection| {
      let start = projection.project(plot_left, zero_y, 1.0);
      let end = projection.project(plot_right, zero_y, 1.0);
      PageItem::Line(LineItem {
        x1_pt: start.0,
        y1_pt: start.1,
        x2_pt: end.0,
        y2_pt: end.1,
        width_pt: axis_line_width,
        color: gridline_color,
        kind: LineItemKind::Stroke,
      })
    })
  } else {
    None
  };
  // Word's category axis has front and back horizontal edges in a 3-D
  // plot. CrossesAt=.1/.5/1 and hidden-axis controls move both. A thicker
  // coplanar minor ribbon paints in front; equal/thinner pens stay behind
  // (native red .75/2pt controls). Preserve the back axis through dash gaps.
  if projection_3d
    .zip(style.value_minor_gridline.as_ref())
    .is_some_and(|(projection, stroke)| {
      projection.pen_width(stroke.width.0 * style.stroke_scale, style.stroke_scale)
        > axis_line_width
    })
  {
    items.extend(back_category_axis.take());
  }
  if value_axis_visible
    && !radar_only
    && !horizontal_bar_only
    && let Some(minor_stroke) = &style.value_minor_gridline
  {
    let mut minor_stroke = minor_stroke.clone();
    minor_stroke.width.0 *= style.stroke_scale;
    if let Some(projection) = projection_3d {
      minor_stroke.width.0 = projection.pen_width(minor_stroke.width.0, style.stroke_scale);
      let color = projection.unlit_pen_color(RgbColor {
        r: minor_stroke.color.r,
        g: minor_stroke.color.g,
        b: minor_stroke.color.b,
      });
      minor_stroke.color.r = color.r;
      minor_stroke.color.g = color.g;
      minor_stroke.color.b = color.b;
    }
    let stroke = crate::common::ShapeStyleValue::Paint(minor_stroke);
    let minor_unit = chart
      .value_axis
      .and_then(|axis| axis.minor_unit.as_ref())
      .map(|unit| unit.val);
    for value in value_axis_minor_ticks(
      scale,
      minor_unit,
      projection_3d.is_none().then_some(category_crossing_value),
    ) {
      if value_gridlines_visible
        && tick_labels.iter().any(|(major, _)| {
          (value - major).abs()
            <= 1e-9
              * scale
                .major_unit
                .abs()
                .min(value.abs())
                .max(f64::MIN_POSITIVE)
        })
      {
        continue;
      }
      let y = value_y(value, scale, plot_top, plot_height);
      let points = projection_3d.map_or_else(
        || vec![(plot_left, y), (plot_right, y)],
        |projection| {
          vec![
            projection.project(plot_left, y, 0.0),
            projection.project(plot_left, y, 1.0),
            projection.project(plot_right, y, 1.0),
          ]
        },
      );
      push_chart_styled_polyline(
        &mut items,
        &points,
        Some(&stroke),
        gridline_color,
        value_gridline_width,
        1.0,
        false,
      );
    }
  }
  items.extend(back_category_axis);
  for (_, axis, secondary_scale, labels, _, _) in &secondary_value_tick_sets {
    if axis.major_gridlines.is_none() {
      continue;
    }
    for (value, _) in labels {
      let y = value_y(*value, *secondary_scale, plot_top, plot_height);
      if let Some(projection) = projection_3d {
        let (back_left_x, back_left_y) = projection.project(plot_left, y, 1.0);
        let (back_right_x, back_right_y) = projection.project(plot_right, y, 1.0);
        items.push(PageItem::Line(LineItem {
          x1_pt: back_left_x,
          y1_pt: back_left_y,
          x2_pt: back_right_x,
          y2_pt: back_right_y,
          width_pt: value_gridline_width,
          color: gridline_color,
          kind: LineItemKind::Stroke,
        }));
      } else {
        items.push(PageItem::Line(LineItem {
          x1_pt: plot_left,
          y1_pt: y,
          x2_pt: plot_right,
          y2_pt: y,
          width_pt: value_gridline_width,
          color: gridline_color,
          kind: LineItemKind::Stroke,
        }));
      }
    }
  }
  if let Some(ticks) = date_ticks.as_ref() {
    if let Some((color, width_pt)) = style.category_major_gridline {
      for tick in ticks.iter().filter(|tick| {
        tick.gridline_position > f64::EPSILON && tick.gridline_position < 1.0 + f64::EPSILON
      }) {
        let x = plot_left + tick.gridline_position as f32 * plot_width;
        items.push(PageItem::Line(LineItem {
          x1_pt: x,
          y1_pt: plot_top,
          x2_pt: x,
          y2_pt: plot_bottom,
          width_pt,
          color,
          kind: LineItemKind::Stroke,
        }));
      }
    }
    if let Some((color, width_pt)) = style.category_minor_gridline
      && let Some(positions) = date_axis_minor_tick_positions_with_maximum_auto_increment_count(
        chart,
        date_axis_increment_budget,
      )
    {
      for position in positions {
        if position <= f64::EPSILON || position >= 1.0 + f64::EPSILON {
          continue;
        }
        let x = plot_left + position as f32 * plot_width;
        items.push(PageItem::Line(LineItem {
          x1_pt: x,
          y1_pt: plot_top,
          x2_pt: x,
          y2_pt: plot_bottom,
          width_pt,
          color,
          kind: LineItemKind::Stroke,
        }));
      }
    }
  }
  if radar_only && style.layout_profile == ChartLayoutProfile::Word {
    lower_radar_grid(&mut items, chart, plot, scale, style);
  } else if radar_only {
    lower_radar_axes(
      &mut items,
      chart,
      PlotRect {
        left: plot_left,
        top: plot_top,
        width: plot_width,
        height: plot_height,
      },
      scale,
      style,
      &mut metrics,
      has_powerpoint_derived_single_series_title,
    );
  } else if horizontal_bar_only {
    lower_horizontal_bar_axes(
      &mut items,
      chart,
      HorizontalAxisLabels {
        tick_labels: &tick_labels,
        hierarchical_levels: &vertical_category_level_layouts,
        category_count,
      },
      HorizontalAxisGeometry {
        plot: PlotRect {
          left: plot_left,
          top: plot_top,
          width: plot_width,
          height: plot_height,
        },
        scale,
        projection_3d,
        draw_gridlines: true,
        draw_labels: false,
      },
      style,
      &mut metrics,
      has_powerpoint_derived_single_series_title,
    );
  } else if scatter_only && let Some(horizontal_scale) = axis_scales.first().and_then(|axes| axes.x)
  {
    lower_scatter_x_axis(
      &mut items,
      chart,
      ScatterAxisGeometry {
        plot: PlotRect {
          left: plot_left,
          top: plot_top,
          width: plot_width,
          height: plot_height,
        },
        scale: horizontal_scale,
        draw_gridlines: true,
        draw_labels: false,
      },
      style,
      &mut metrics,
    );
  }

  let powerpoint_2d_cartesian_axes = style.layout_profile == ChartLayoutProfile::PowerPoint
    && projection_3d.is_none()
    && !radar_only
    && !horizontal_bar_only;
  if powerpoint_2d_cartesian_axes {
    // PowerPoint's fixed output paints automatic 2-D axes and their ticks
    // after gridlines but before the data series. The axis XML controls the
    // tick direction; c:majorTickMark="none" suppresses ticks without
    // suppressing the main axis line.
    if category_axis_visible {
      items.push(PageItem::Line(LineItem {
        x1_pt: plot_left,
        y1_pt: zero_y,
        x2_pt: plot_right,
        y2_pt: zero_y,
        width_pt: axis_line_width,
        color: gridline_color,
        kind: LineItemKind::Stroke,
      }));
      lower_powerpoint_horizontal_axis_major_ticks(
        &mut items,
        chart,
        PowerPointHorizontalAxisTickContext {
          plot: PlotRect {
            left: plot_left,
            top: plot_top,
            width: plot_width,
            height: plot_height,
          },
          axis_y: zero_y,
          x_scale: axis_scales.first().and_then(|axes| axes.x),
          date_ticks: date_ticks.as_deref(),
          category_count,
          width_pt: axis_line_width,
          color: gridline_color,
          tick_length_pt: profiles::POWERPOINT_AUTOMATIC_MAJOR_TICK_LENGTH_PT,
        },
      );
    }
    if value_axis_visible {
      items.push(PageItem::Line(LineItem {
        x1_pt: primary_value_axis_x,
        y1_pt: plot_top,
        x2_pt: primary_value_axis_x,
        y2_pt: plot_bottom,
        width_pt: axis_line_width,
        color: gridline_color,
        kind: LineItemKind::Stroke,
      }));
      lower_powerpoint_vertical_axis_major_ticks(
        &mut items,
        &tick_labels,
        PowerPointVerticalAxisTickContext {
          axis: chart.value_axis,
          axis_x: primary_value_axis_x,
          axis_on_right: primary_value_axis_on_right,
          scale,
          plot_top,
          plot_height,
          width_pt: axis_line_width,
          color: gridline_color,
        },
      );
    }
  }

  // The back category edge belongs to the wall, behind the data markers.
  // Native opaque cone bases occlude it; drawing it with the front axes
  // cuts a vertical gray line through every curved base.
  if word_parallel_bar_layout && let Some(projection) = projection_3d {
    let plot = PlotRect {
      left: plot_left,
      top: plot_top,
      width: plot_width,
      height: plot_height,
    };
    if category_axis_visible
      && cartesian_axis_outline_visible(
        chart
          .category_axis
          .and_then(|axis| axis.chart_shape_properties.as_deref()),
      )
    {
      let x = value_x(
        word_category_axis_crossing_value(chart.value_axis, scale),
        scale,
        plot,
      );
      let corners = [
        projection.project(x, plot_bottom, 0.0),
        projection.project(x, plot_bottom, 1.0),
        projection.project(x, plot_top, 1.0),
        projection.project(x, plot_top, 0.0),
      ];
      for pair in corners.windows(2) {
        lower_chart_line_segment(
          &mut items,
          pair[0],
          pair[1],
          gridline_color,
          axis_line_width,
        );
      }
    }
  }

  lower_chart_group_decorations(
    &mut items,
    chart,
    PlotRect {
      left: plot_left,
      top: plot_top,
      width: plot_width,
      height: plot_height,
    },
    &axis_scales,
    projection_3d,
    style,
    category_count,
  );
  lower_series_geometry(
    &mut items,
    chart,
    style,
    SeriesPlotGeometry {
      plot: PlotRect {
        left: plot_left,
        top: plot_top,
        width: plot_width,
        height: plot_height,
      },
      axis_scales: &axis_scales,
      bubble_reference_extent,
      category_count,
      projection_3d,
    },
  );
  if let Some(projection) = projection_3d {
    lower_series_axes(
      &mut items,
      chart,
      PlotRect {
        left: plot_left,
        top: plot_top,
        width: plot_width,
        height: plot_height,
      },
      projection,
      style,
      &mut metrics,
    );
  }
  if category_axis_visible
    && !radar_only
    && !horizontal_bar_only
    && !powerpoint_2d_cartesian_axes
    && cartesian_axis_outline_visible(
      chart
        .category_axis
        .and_then(|axis| axis.chart_shape_properties.as_deref())
        .or_else(|| {
          chart
            .date_axis
            .and_then(|axis| axis.chart_shape_properties.as_deref())
        }),
    )
  {
    let (axis_start, axis_end) =
      projection_3d.map_or(((plot_left, zero_y), (plot_right, zero_y)), |projection| {
        (
          projection.project(plot_left, zero_y, 0.0),
          projection.project(plot_right, zero_y, 0.0),
        )
      });
    items.push(PageItem::Line(LineItem {
      x1_pt: axis_start.0,
      y1_pt: axis_start.1,
      x2_pt: axis_end.0,
      y2_pt: axis_end.1,
      width_pt: axis_line_width,
      color: gridline_color,
      kind: LineItemKind::Stroke,
    }));
  }
  if word_parallel_bar_layout && let Some(projection) = projection_3d {
    let plot = PlotRect {
      left: plot_left,
      top: plot_top,
      width: plot_width,
      height: plot_height,
    };
    let mut axes = Vec::new();
    lower_word_horizontal_bar_axis_lines(
      &mut axes,
      chart,
      plot,
      scale,
      &tick_labels,
      category_count,
      AxisStrokeStyle {
        color: gridline_color,
        width_pt: axis_line_width,
        tick_length_pt: 3.5 * style.stroke_scale,
      },
    );
    for item in axes {
      if let PageItem::Line(mut line) = item {
        (line.x1_pt, line.y1_pt) = projection.project(line.x1_pt, line.y1_pt, 0.0);
        (line.x2_pt, line.y2_pt) = projection.project(line.x2_pt, line.y2_pt, 0.0);
        items.push(PageItem::Line(line));
      }
    }
  } else if style.layout_profile == ChartLayoutProfile::Word
    && horizontal_bar_only
    && projection_3d.is_none()
  {
    lower_word_horizontal_bar_axis_lines(
      &mut items,
      chart,
      PlotRect {
        left: plot_left,
        top: plot_top,
        width: plot_width,
        height: plot_height,
      },
      scale,
      &tick_labels,
      category_count,
      AxisStrokeStyle {
        color: gridline_color,
        width_pt: axis_line_width,
        tick_length_pt: 3.5 * style.stroke_scale,
      },
    );
  } else if !radar_only
    && (style.layout_profile == ChartLayoutProfile::Word || chartsheet_category_layout)
  {
    let tick_length = if word_scatter_layout {
      word_scatter_value_line * 0.26
    } else if chartsheet_category_layout {
      metrics
        .vertical_metrics_for_text("0", &style.value_label)
        .line_height_pt()
        * (profiles::EXCEL_CHARTSHEET_AXIS_BAND_LINE_HEIGHTS - 1.0)
        * 0.5
    } else {
      frame.height_pt * 0.012_59
    };
    if value_axis_visible
      && cartesian_axis_outline_visible(
        chart
          .value_axis
          .and_then(|axis| axis.chart_shape_properties.as_deref()),
      )
    {
      let axis_x = primary_value_axis_x;
      let axis_top = projection_3d.map_or((axis_x, plot_top), |projection| {
        projection.project(axis_x, plot_top, primary_value_axis_depth)
      });
      let axis_end_y = if chartsheet_category_layout {
        plot_bottom
      } else {
        zero_y
      };
      let axis_zero = projection_3d.map_or((axis_x, axis_end_y), |projection| {
        projection.project(axis_x, axis_end_y, primary_value_axis_depth)
      });
      items.push(PageItem::Line(LineItem {
        x1_pt: axis_top.0,
        y1_pt: axis_top.1,
        x2_pt: axis_zero.0,
        y2_pt: axis_zero.1,
        width_pt: axis_line_width,
        color: gridline_color,
        kind: LineItemKind::Stroke,
      }));
      if chart.value_axis.is_none_or(value_axis_has_major_ticks) {
        let (tick_start, tick_end) = if chartsheet_category_layout {
          chartsheet_tick_offsets(
            chart
              .value_axis
              .and_then(|axis| axis.major_tick_mark.as_ref())
              .and_then(|tick| tick.val),
            tick_length,
          )
        } else {
          (0.0, tick_length)
        };
        for (value, _) in &tick_labels {
          let y = value_y(*value, scale, plot_top, plot_height);
          let point = projection_3d.map_or((axis_x, y), |projection| {
            projection.project(axis_x, y, primary_value_axis_depth)
          });
          items.push(PageItem::Line(LineItem {
            x1_pt: if primary_value_axis_on_right {
              point.0 + tick_start
            } else {
              point.0 - tick_end
            },
            y1_pt: point.1,
            x2_pt: if primary_value_axis_on_right {
              point.0 + tick_end
            } else {
              point.0 - tick_start
            },
            y2_pt: point.1,
            width_pt: axis_line_width,
            color: gridline_color,
            kind: LineItemKind::Stroke,
          }));
        }
      }
    }
    if scatter_only {
      if chart
        .horizontal_value_axis
        .is_none_or(value_axis_is_visible)
      {
        lower_powerpoint_horizontal_axis_major_ticks(
          &mut items,
          chart,
          PowerPointHorizontalAxisTickContext {
            plot: PlotRect {
              left: plot_left,
              top: plot_top,
              width: plot_width,
              height: plot_height,
            },
            axis_y: zero_y,
            x_scale: axis_scales.first().and_then(|axes| axes.x),
            date_ticks: None,
            category_count,
            width_pt: axis_line_width,
            color: gridline_color,
            tick_length_pt: if word_scatter_layout {
              word_scatter_category_line * 0.26
            } else {
              tick_length
            },
          },
        );
      }
    } else if category_axis_visible
      && chart
        .category_axis
        .map(category_axis_has_major_ticks)
        .or_else(|| chart.date_axis.map(date_axis_has_major_ticks))
        .unwrap_or(true)
    {
      let (tick_start, tick_end) = if chartsheet_category_layout {
        chartsheet_tick_offsets(
          chart
            .category_axis
            .and_then(|axis| axis.major_tick_mark.as_ref())
            .or_else(|| {
              chart
                .date_axis
                .and_then(|axis| axis.major_tick_mark.as_ref())
            })
            .and_then(|tick| tick.val),
          tick_length,
        )
      } else {
        (0.0, tick_length)
      };
      let tick_positions = date_ticks
        .as_ref()
        .map(|ticks| ticks.iter().map(|tick| tick.position).collect::<Vec<_>>())
        .unwrap_or_else(|| {
          (0..=category_count)
            .map(|boundary| boundary as f64 / category_count as f64)
            .collect()
        });
      for position in tick_positions {
        let position = if chart.category_axis_reversed {
          1.0 - position
        } else {
          position
        };
        let x = plot_left + position as f32 * plot_width;
        let point =
          projection_3d.map_or((x, zero_y), |projection| projection.project(x, zero_y, 0.0));
        items.push(PageItem::Line(LineItem {
          x1_pt: point.0,
          y1_pt: point.1 + tick_start,
          x2_pt: point.0,
          y2_pt: point.1 + tick_end,
          width_pt: axis_line_width,
          color: gridline_color,
          kind: LineItemKind::Stroke,
        }));
      }
    }
  }
  let secondary_tick_gap = secondary_axis_tick_gap;
  let mut left_axis_offset = if !primary_value_axis_on_right && value_tick_labels_visible {
    primary_value_axis_band_width
  } else {
    0.0
  };
  let mut right_axis_offset = if primary_value_axis_on_right && value_tick_labels_visible {
    primary_value_axis_band_width
  } else {
    0.0
  };
  for (_, axis, secondary_scale, labels, width, on_right) in &secondary_value_tick_sets {
    let axis_x = if *on_right {
      plot_right + right_axis_offset
    } else {
      plot_left - left_axis_offset
    };
    let paint_axis = cartesian_axis_outline_visible(axis.chart_shape_properties.as_deref());
    if paint_axis {
      items.push(PageItem::Line(LineItem {
        x1_pt: axis_x,
        y1_pt: plot_top,
        x2_pt: axis_x,
        y2_pt: plot_bottom,
        width_pt: axis_line_width,
        color: style.gridline_color,
        kind: LineItemKind::Stroke,
      }));
    }
    if paint_axis && value_axis_has_major_ticks(axis) {
      let tick_length = frame.height_pt * 0.012_59;
      for (value, _) in labels {
        let y = value_y(*value, *secondary_scale, plot_top, plot_height);
        items.push(PageItem::Line(LineItem {
          x1_pt: if *on_right {
            axis_x
          } else {
            axis_x - tick_length
          },
          y1_pt: y,
          x2_pt: if *on_right {
            axis_x + tick_length
          } else {
            axis_x
          },
          y2_pt: y,
          width_pt: axis_line_width,
          color: style.gridline_color,
          kind: LineItemKind::Stroke,
        }));
      }
    }
    if *on_right {
      right_axis_offset += *width + secondary_tick_gap;
    } else {
      left_axis_offset += *width + secondary_tick_gap;
    }
  }

  if radar_only && style.layout_profile == ChartLayoutProfile::Word {
    lower_radar_axes(&mut items, chart, plot, scale, style, &mut metrics, false);
  }

  // Office exports the Cartesian 3-D scene as one 200-DPI surface; its
  // labels remain text. The PDF export policy then owns Print/Screen image
  // reduction, just as it does for the native scene's RGB/alpha pair.
  if style.layout_profile == ChartLayoutProfile::Word
    && projection_3d.is_some()
    && let Some(image) = cartesian_3d_scene_image(
      &items[scene_start..],
      scene_raster_bounds,
      style.fixed_output_raster_dpi,
    )
  {
    items.truncate(scene_start);
    items.push(PageItem::Image(image));
  }

  let defer_data_labels = !scatter_only && !horizontal_bar_only && !radar_only;
  let mut deferred_data_label_items = Vec::new();
  let label_bubble_maxima = bubble_group_maxima(chart);
  for (series_index, series) in chart.series.iter().enumerate() {
    for (label_index, label) in series.data_labels.iter().enumerate() {
      let data_label_style = style
        .data_label_styles
        .get(series_index)
        .and_then(|styles| styles.get(label_index))
        .and_then(Option::as_ref)
        .unwrap_or(&style.data_label);
      let data_label_line_height = line_height(data_label_style);
      let axes = axis_scales
        .get(series.axis_set_index)
        .unwrap_or(&axis_scales[0]);
      let series_zero_y = value_y(
        0.0_f64.clamp(axes.y.minimum, axes.y.maximum),
        axes.y,
        plot_top,
        plot_height,
      );
      let Some(anchor) = data_label_anchor(
        chart,
        series_index,
        label.point_index,
        PlotRect {
          left: plot_left,
          top: plot_top,
          width: plot_width,
          height: plot_height,
        },
        *axes,
        series_zero_y,
        category_count,
      ) else {
        continue;
      };
      let three_dimensional_label_offset =
        if series.is_3d && label.position != c::DataLabelPositionValues::Center {
          BAR_3D_DATA_LABEL_OFFSET_PT
        } else {
          0.0
        };
      let anchor = project_3d_data_label_anchor(chart, series_index, anchor, projection_3d);
      let rich_text_styles = style
        .data_label_rich_text_styles
        .get(series_index)
        .and_then(|styles| styles.get(label_index))
        .map(Vec::as_slice)
        .unwrap_or_default();
      let text_frame = resolved_data_label_text_frame(frame, label);
      let text_box = data_label_text_box(
        &mut metrics,
        label,
        data_label_style,
        rich_text_styles,
        text_frame,
      );
      let (width, data_label_height) = (text_box.width, text_box.height);
      let data_label_insets = chart_data_label_insets(label.text_body_properties);
      let explicit_column_outside_end =
        series.kind == ChartSeriesKind::Column && label.position_explicit;
      let bubble_radius = if series.kind == ChartSeriesKind::Bubble {
        bubble_marker_diameter(
          series,
          label.point_index,
          ScatterGeometry {
            bubble_reference_extent,
            plot: PlotRect {
              left: plot_left,
              top: plot_top,
              width: plot_width,
              height: plot_height,
            },
            scale: axes.y,
            x_scale: axes.x,
            bubble_maximum: series
              .bubble_group_index
              .and_then(|group| label_bubble_maxima.get(group).copied())
              .unwrap_or(0.0),
          },
        )
        .unwrap_or(0.0)
          * 0.5
      } else {
        0.0
      };
      let (x, y) = if series.kind == ChartSeriesKind::Radar
        && label.position == c::DataLabelPositionValues::OutsideEnd
      {
        let (center, radius_x, radius_y) = radar_plot_geometry(chart, style, plot);
        let index = category_display_index(chart, label.point_index, category_count);
        let angle = std::f32::consts::TAU * index as f32 / category_count.max(1) as f32;
        let ratio = series
          .values
          .get(label.point_index)
          .copied()
          .flatten()
          .map_or(0.0, |value| axis_value_ratio(value, axes.y)) as f32;
        // Native Word point/font/size/range controls put the fitted label
        // center .2 diagram radii beyond the data point (MS-OI29500 OutsideEnd).
        (
          center.0 + angle.sin() * radius_x * (ratio + 0.2) - width * 0.5,
          center.1 - angle.cos() * radius_y * (ratio + 0.2) - data_label_height * 0.5,
        )
      } else if series.kind == ChartSeriesKind::Bubble
        && style.layout_profile == ChartLayoutProfile::Word
      {
        // Word COM position controls place the fitted label frame 5.5pt from
        // the bubble outline. The text keeps its own 3pt horizontal inset.
        let gap = 5.5 * style.stroke_scale;
        match label.position {
          c::DataLabelPositionValues::Right => (
            anchor.x + bubble_radius + gap + data_label_insets.left,
            anchor.y - data_label_height * 0.5,
          ),
          c::DataLabelPositionValues::Left => (
            anchor.x - bubble_radius - gap - width - data_label_insets.right,
            anchor.y - data_label_height * 0.5,
          ),
          c::DataLabelPositionValues::Top => (
            anchor.x - width * 0.5,
            anchor.y - bubble_radius - gap - data_label_height - 1.5 * style.stroke_scale,
          ),
          c::DataLabelPositionValues::Bottom => (
            anchor.x - width * 0.5,
            anchor.y + bubble_radius + gap + 1.5 * style.stroke_scale,
          ),
          _ => (anchor.x - width * 0.5, anchor.y - data_label_height * 0.5),
        }
      } else if series.kind == ChartSeriesKind::Bar
        && matches!(
          label.position,
          c::DataLabelPositionValues::Center
            | c::DataLabelPositionValues::InsideBase
            | c::DataLabelPositionValues::InsideEnd
            | c::DataLabelPositionValues::OutsideEnd
            | c::DataLabelPositionValues::BestFit
        )
      {
        horizontal_bar_data_label_origin(
          label.position,
          anchor,
          (width, data_label_height),
          data_label_insets,
          CARTESIAN_DATA_LABEL_OFFSET_PT + three_dimensional_label_offset,
        )
      } else {
        match label.position {
          c::DataLabelPositionValues::Center => (
            (anchor.x + anchor.base_x) * 0.5 - width * 0.5,
            (anchor.y + anchor.base_y) * 0.5 - data_label_height * 0.5,
          ),
          c::DataLabelPositionValues::InsideBase => (
            anchor.base_x - width * 0.5,
            anchor.base_y - data_label_height,
          ),
          c::DataLabelPositionValues::InsideEnd => (anchor.x - width * 0.5, anchor.y),
          c::DataLabelPositionValues::Bottom => (
            anchor.x - width * 0.5,
            anchor.y + data_label_line_height * 0.15,
          ),
          c::DataLabelPositionValues::Left => (
            anchor.x - width - data_label_style.font_size_pt * 0.2,
            anchor.y - data_label_height * 0.5,
          ),
          c::DataLabelPositionValues::Right => (
            anchor.x
              + if has_unshifted_side_line_layout {
                chart_marker_size(
                  &chart.series[series_index],
                  Some(label.point_index),
                  style.automatic_line_width_pt,
                )
                .map(|size| size * style.stroke_scale)
                .unwrap_or(0.0)
              } else {
                0.0
              }
              + data_label_style.font_size_pt * 0.2,
            anchor.y - data_label_height * 0.5,
          ),
          c::DataLabelPositionValues::OutsideEnd | c::DataLabelPositionValues::BestFit => (
            anchor.x - width * 0.5,
            anchor.y
              - data_label_height
              - three_dimensional_label_offset
              // The authored outside-end position retains the same clearance
              // as Word's data-table labels even without a table. An explicit
              // text body's top inset moves its painted glyph upward by that
              // amount in the controlled Word margin matrix. Keep the
              // previously calibrated data-table path separate.
              - if word_data_table_layout.is_some() || explicit_column_outside_end {
                CARTESIAN_DATA_LABEL_OFFSET_PT
              } else {
                0.0
              }
              - if word_data_table_layout.is_none() && explicit_column_outside_end {
                data_label_insets.top
              } else {
                0.0
              }
              - if has_derived_single_series_side_title_layout {
                frame.height_pt * 0.020_82
              } else {
                0.0
              },
          ),
          c::DataLabelPositionValues::Top => {
            let marker_clearance = if matches!(
              chart.series[series_index].kind,
              ChartSeriesKind::Line | ChartSeriesKind::Scatter | ChartSeriesKind::Stock
            ) {
              chart_marker_size(
                &chart.series[series_index],
                Some(label.point_index),
                style.automatic_line_width_pt,
              )
              .map(|size| size * style.stroke_scale * 0.5)
              .unwrap_or(0.0)
                + CARTESIAN_DATA_LABEL_OFFSET_PT
            } else {
              three_dimensional_label_offset
            };
            (
              anchor.x - width * 0.5,
              anchor.y - data_label_height - marker_clearance,
            )
          }
        }
      };
      let (x, y) = label.layout.map_or((x, y), |layout| {
        let bounds = apply_manual_text_layout(
          frame,
          PlotRect {
            left: x,
            top: y,
            width,
            height: data_label_height,
          },
          layout,
        );
        (bounds.left, bounds.top)
      });
      let y = if word_data_table_layout.is_some() && label.layout.is_some() {
        // Word retains the ordinary category/plot clearance as the reference
        // for manually positioned data-label text even after a data table
        // joins the visible plot at that edge. Its DataLabel.Top COM values
        // match this independent text-anchor displacement.
        y + frame.height_pt * word_no_legend_adjustment.plot_bottom_ratio
      } else {
        y
      };
      if let Some(fill_color) = style
        .data_label_fill_colors
        .get(series_index)
        .and_then(|colors| colors.get(label_index))
        .copied()
        .flatten()
      {
        let horizontal_padding = if word_data_table_layout.is_some() {
          AUTOMATIC_DATA_LABEL_HORIZONTAL_INSET_PT * style.stroke_scale
        } else {
          data_label_style.font_size_pt * 0.25
        };
        let vertical_padding = data_label_style.font_size_pt * 0.26;
        let background_height = if word_data_table_layout.is_some() {
          // The Word shape frame keeps about 1.6pt of vertical padding on
          // each side of the measured rich-text line; its top is positioned
          // independently of that fitted height.
          data_label_height + 3.25 * style.stroke_scale
        } else {
          data_label_height + vertical_padding * 2.0
        };
        let fill_opacity = if word_data_table_layout.is_some() {
          direct_chart_data_label_fill_opacity(label).unwrap_or(1.0)
        } else {
          1.0
        };
        let target = if defer_data_labels {
          &mut deferred_data_label_items
        } else {
          &mut items
        };
        target.push(PageItem::Rect(RectItem {
          x_pt: x - horizontal_padding,
          y_pt: y - vertical_padding,
          width_pt: width + horizontal_padding * 2.0,
          height_pt: background_height,
          fill_color: Some(fill_color),
          fill_opacity,
          stroke: None,
          stroke_opacity: 1.0,
        }));
      }
      let target = if defer_data_labels {
        &mut deferred_data_label_items
      } else {
        &mut items
      };
      push_data_label_text_components(
        target,
        &mut metrics,
        DataLabelTextLayout {
          origin: text_box.text_origin((x, y)),
          label,
          style: data_label_style,
          rich_text_styles,
          text_frame,
          align_rich_runs_on_baseline: word_data_table_layout.is_some(),
        },
      );
    }
  }
  if horizontal_bar_only {
    // Horizontal bar data labels are part of the series stream. Office emits
    // the projected value/category axis text after those labels, while the
    // grid geometry remains behind the series.
    lower_horizontal_bar_axes(
      &mut items,
      chart,
      HorizontalAxisLabels {
        tick_labels: &tick_labels,
        hierarchical_levels: &vertical_category_level_layouts,
        category_count,
      },
      HorizontalAxisGeometry {
        plot: PlotRect {
          left: plot_left,
          top: plot_top,
          width: plot_width,
          height: plot_height,
        },
        scale,
        projection_3d: axis_text_projection_3d,
        draw_gridlines: false,
        draw_labels: true,
      },
      style,
      &mut metrics,
      has_powerpoint_derived_single_series_title,
    );
  }

  // Ordinary Office chart streams emit value ticks before categories and
  // legends. Legacy PowerPoint automatic-series-title charts instead retain
  // X/category-axis text before Y/value-axis text, so defer the latter for
  // that structural profile. A chart data table is emitted before the ticks.
  let mut deferred_value_tick_label_items = Vec::new();
  if value_tick_labels_visible && chart.data_table.is_none() {
    let target = if has_powerpoint_derived_single_series_title {
      &mut deferred_value_tick_label_items
    } else {
      &mut items
    };
    lower_cartesian_value_tick_labels(
      target,
      &tick_labels,
      ValueTickLabelContext {
        axis_x: primary_value_label_axis_x,
        labels_on_right: primary_value_axis_on_right,
        label_gap: primary_value_label_gap,
        scale,
        plot_top,
        plot_height,
        axis_depth: primary_value_label_axis_depth,
        value_label_line_height,
        tick_top_offset: frame.height_pt * excel_title_only_adjustment.tick_top_ratio,
        projection_3d: axis_text_projection_3d,
      },
      style,
      &mut metrics,
    );
  }
  if chart.data_table.is_none() {
    let secondary_tick_label_offset = secondary_tick_gap
      + if word_combination_layout || word_manual_bottom_layout {
        0.0
      } else {
        frame.height_pt * 0.012_59
      };
    let mut left_axis_offset = if !primary_value_axis_on_right && value_tick_labels_visible {
      primary_value_axis_band_width
    } else {
      0.0
    };
    let mut right_axis_offset = if primary_value_axis_on_right && value_tick_labels_visible {
      primary_value_axis_band_width
    } else {
      0.0
    };
    for (_, _, secondary_scale, labels, width, on_right) in &secondary_value_tick_sets {
      let axis_x = if *on_right {
        plot_right + right_axis_offset
      } else {
        plot_left - left_axis_offset
      };
      for (value, label) in labels {
        let label_width = metrics.measure_text(label, &style.value_label);
        let target = if has_powerpoint_derived_single_series_title {
          &mut deferred_value_tick_label_items
        } else {
          &mut items
        };
        push_text(
          target,
          if *on_right {
            axis_x + secondary_tick_label_offset
          } else {
            axis_x - secondary_tick_label_offset - label_width
          },
          value_y(*value, *secondary_scale, plot_top, plot_height) - value_label_line_height / 2.0,
          label.clone(),
          style.value_label.clone(),
        );
      }
      if *on_right {
        right_axis_offset += *width + secondary_tick_gap;
      } else {
        left_axis_offset += *width + secondary_tick_gap;
      }
    }
  }
  if scatter_only && let Some(horizontal_scale) = axis_scales.first().and_then(|axes| axes.x) {
    // Excel emits scatter data labels first, followed by value-axis labels
    // and then category-axis labels. Keep the vertical gridline geometry
    // behind the plotted series above, but defer its text to the shared
    // Office chart-text ordering used here.
    lower_scatter_x_axis(
      &mut items,
      chart,
      ScatterAxisGeometry {
        plot: PlotRect {
          left: plot_left,
          top: plot_top,
          width: plot_width,
          height: plot_height,
        },
        scale: horizontal_scale,
        draw_gridlines: false,
        draw_labels: true,
      },
      style,
      &mut metrics,
    );
  }
  let mut painted_category_label_style = style.category_label.clone();
  painted_category_label_style.rotation_deg = category_label_rotation;
  if style.layout_profile == ChartLayoutProfile::Word
    && category_tick_labels_visible
    && let Some(projection) = axis_text_projection_3d
  {
    painted_category_label_style.rotation_deg = chart_3d_category_label_rotation(
      chart,
      &category_label_lines,
      PlotRect {
        left: plot_left,
        top: plot_top,
        width: plot_width,
        height: plot_height,
      },
      zero_y,
      projection,
      &style.category_label,
      &mut metrics,
    );
    if style.layout_profile == ChartLayoutProfile::Word
      && painted_category_label_style.rotation_deg.abs() > f32::EPSILON
    {
      // Word's fixed-format writer emits automatically rotated 3-D tick
      // labels as vector glyph outlines (the visible dates in chart-Area are
      // absent from the PDF text layer). Keep them visible without inventing
      // a searchable semantic overlay.
      painted_category_label_style.pdf_glyph_outlines = true;
      painted_category_label_style.pdf_glyph_outline_options =
        Some(Arc::new(crate::common::PdfGlyphOutlineOptions {
          semantic_text_overlay: false,
          ..crate::common::PdfGlyphOutlineOptions::default()
        }));
    }
  }
  if category_tick_labels_visible {
    if let Some(hierarchy) = category_hierarchy {
      lower_horizontal_category_hierarchy_separators(
        &mut items,
        chart,
        hierarchy,
        &hierarchical_category_level_layouts,
        HorizontalCategoryHierarchyGeometry {
          plot: PlotRect {
            left: plot_left,
            top: plot_top,
            width: plot_width,
            height: plot_height,
          },
          projection: axis_text_projection_3d,
          category_count,
          axis_y: zero_y,
          category_top,
          leaf_height: category_leaf_label_height,
          width_pt: axis_line_width,
          color: style.gridline_color,
        },
      );
    }
    for (category_index, lines) in category_label_lines.iter().enumerate() {
      let center = if let Some(ticks) = date_ticks.as_ref() {
        let position = if chart.category_axis_reversed {
          1.0 - ticks[category_index].position
        } else {
          ticks[category_index].position
        };
        plot_left + position as f32 * plot_width
      } else {
        let display_index = category_display_index(chart, category_index, category_count);
        category_point_x(
          chart,
          display_index,
          category_count,
          PlotRect {
            left: plot_left,
            top: plot_top,
            width: plot_width,
            height: plot_height,
          },
        )
      };
      for (line_index, line) in lines.iter().enumerate() {
        let width = metrics.measure_text(line, &painted_category_label_style);
        let (x, y, rotation_center) = axis_text_projection_3d.map_or_else(
          || {
            if painted_category_label_style.rotation_deg.abs() <= f32::EPSILON {
              return (
                center - width / 2.0,
                category_top + line_index as f32 * category_label_line_height,
                None,
              );
            }
            // DrawingML rotates the complete tick-label rectangle about its
            // center. Anchor the resulting axis-aligned box at category_top;
            // rotating around the text origin instead makes a -90 degree
            // label climb into the plot by roughly its full advance width.
            let angle = painted_category_label_style.rotation_deg.to_radians();
            let rotated_height =
              width * angle.sin().abs() + category_label_line_height * angle.cos().abs();
            let center_y =
              category_top + line_index as f32 * category_label_line_height + rotated_height * 0.5;
            (
              center - width / 2.0,
              center_y - category_label_line_height * 0.5,
              Some((center, center_y)),
            )
          },
          |projection| {
            let point = projection.project(center, zero_y, 0.0);
            let label_gap_em = if style.layout_profile == ChartLayoutProfile::PowerPoint
              && cartesian_3d_series_axis_labels_visible(chart)
            {
              profiles::POWERPOINT_CARTESIAN_3D_CATEGORY_LABEL_GAP_EM
            } else {
              0.45
            };
            // The em term accounts for the projected major-tick reach. Keep
            // LO's independent 1 mm tick-to-text spacing as a physical gap,
            // just as for the projected value axis above.
            let label_gap = painted_category_label_style.font_size_pt * label_gap_em
              + CARTESIAN_DATA_LABEL_OFFSET_PT;
            if painted_category_label_style.rotation_deg.abs() > f32::EPSILON {
              (
                point.0 - painted_category_label_style.font_size_pt * 0.15,
                point.1 + label_gap + line_index as f32 * category_label_line_height,
                None,
              )
            } else {
              (
                point.0 - width / 2.0,
                point.1 + label_gap + line_index as f32 * category_label_line_height,
                None,
              )
            }
          },
        );
        push_text_with_rotation_center(
          &mut items,
          x,
          y,
          line.clone(),
          painted_category_label_style.clone(),
          rotation_center,
        );
      }
    }
    let mut level_top = category_top + category_leaf_label_height;
    for level in &hierarchical_category_level_layouts {
      level_top += level.gap_before;
      for group in &level.groups {
        let center = category_group_center_x(
          chart,
          group.start_index,
          group.span,
          category_count,
          PlotRect {
            left: plot_left,
            top: plot_top,
            width: plot_width,
            height: plot_height,
          },
        );
        for (line_index, line) in group.lines.iter().enumerate() {
          if line.is_empty() {
            continue;
          }
          let width = metrics.measure_text(line, &style.category_label);
          let (x, y) = axis_text_projection_3d.map_or_else(
            || {
              (
                center - width * 0.5,
                level_top + line_index as f32 * category_label_line_height,
              )
            },
            |projection| {
              let point = projection.project(center, zero_y, 0.0);
              (
                point.0 - width * 0.5,
                point.1
                  + CARTESIAN_DATA_LABEL_OFFSET_PT
                  + category_leaf_label_height
                  + (level_top - category_top - category_leaf_label_height)
                  + line_index as f32 * category_label_line_height,
              )
            },
          );
          push_text(&mut items, x, y, line.clone(), style.category_label.clone());
        }
      }
      level_top += level.text_height;
    }
  }
  if let (Some(data_table), Some(word_layout)) = (chart.data_table, word_data_table_layout) {
    // Word serializes its table before the overlaid data labels. Its fixed
    // output text stream then contains table cells, labels, ticks and the
    // axis title in that order; keep the same paint order for overlapping
    // labels as well as PDF text extraction.
    lower_data_table(
      &mut items,
      chart,
      data_table,
      PlotRect {
        left: plot_left,
        top: painted_category_top,
        width: plot_width,
        height: data_table_height,
      },
      style,
      &mut metrics,
      Some(word_layout),
    );
  }
  items.append(&mut deferred_value_tick_label_items);
  items.append(&mut deferred_data_label_items);
  if let Some(axis) = chart.value_axis
    && let Some(label) = value_axis_display_unit_label_text(axis, chart.ui_language.as_deref())
  {
    let mut unit_style = style.value_label.clone();
    // LibreOffice's source-backed OBJECTTYPE_AXISUNIT uses the same automatic
    // text role as an axis title (ObjectFormatter::spAxisTitleTexts), whose
    // default is bold. Office fixed output likewise strokes the synthesized
    // CJK face for an otherwise empty c:dispUnitsLbl.
    unit_style.bold = true;
    unit_style.rotation_deg = -90.0;
    if let Some(projection) = projection_3d {
      let width = metrics.measure_text(&label, &unit_style);
      let point = projection.project(
        primary_value_label_axis_x,
        plot_top,
        primary_value_label_axis_depth,
      );
      let tick_width = tick_labels
        .iter()
        .map(|(_, label)| metrics.measure_text(label, &style.value_label))
        .fold(0.0_f32, f32::max);
      let unit_line = line_height(&unit_style);
      let x = if primary_value_axis_on_right {
        point.0 + primary_value_label_gap + tick_width + 3.0 * style.stroke_scale
      } else {
        point.0 - primary_value_label_gap - tick_width - unit_line - 3.0 * style.stroke_scale
      };
      // Use the text-box origin as rotation center, as for fitted axis
      // titles. The default baseline center would move the label by a font
      // ascent in both directions after a quarter turn.
      let origin = (x, point.1 + width + 3.0 * style.stroke_scale);
      push_text_with_rotation_center(
        &mut items,
        origin.0,
        origin.1,
        label,
        unit_style,
        Some(origin),
      );
    } else {
      push_text(
        &mut items,
        if primary_value_axis_on_right {
          plot_right + tick_gap + unit_style.font_size_pt
        } else {
          plot_left - tick_gap - unit_style.font_size_pt
        },
        value_y(
          (scale.maximum - scale.major_unit).max(scale.minimum),
          scale,
          plot_top,
          plot_height,
        ) - value_label_line_height / 2.0,
        label,
        unit_style,
      );
    }
  }
  let mut left_axis_offset = if !primary_value_axis_on_right && value_tick_labels_visible {
    primary_value_axis_band_width
  } else {
    0.0
  };
  let mut right_axis_offset = if primary_value_axis_on_right && value_tick_labels_visible {
    primary_value_axis_band_width
  } else {
    0.0
  };
  for (_, axis, secondary_scale, _, width, on_right) in &secondary_value_tick_sets {
    let axis_x = if *on_right {
      plot_right + right_axis_offset
    } else {
      plot_left - left_axis_offset
    };
    if let Some(label) = value_axis_display_unit_label_text(axis, chart.ui_language.as_deref()) {
      let mut unit_style = style.value_label.clone();
      unit_style.bold = true;
      unit_style.rotation_deg = -90.0;
      push_text(
        &mut items,
        if *on_right {
          axis_x + secondary_tick_gap + unit_style.font_size_pt
        } else {
          axis_x - secondary_tick_gap - unit_style.font_size_pt
        },
        value_y(
          (secondary_scale.maximum - secondary_scale.major_unit).max(secondary_scale.minimum),
          *secondary_scale,
          plot_top,
          plot_height,
        ) - value_label_line_height / 2.0,
        label,
        unit_style,
      );
    }
    if *on_right {
      right_axis_offset += *width + secondary_tick_gap;
    } else {
      left_axis_offset += *width + secondary_tick_gap;
    }
  }
  if chart.data_table.is_some() && word_data_table_layout.is_none() {
    lower_axis_titles(
      &mut items,
      AxisTitleGeometry {
        frame,
        plot: PlotRect {
          left: plot_left,
          top: plot_top,
          width: plot_width,
          height: plot_height,
        },
        value_label_band_left: tick_left,
        category_band_top: painted_category_top,
        category_label_height,
        data_table_height,
        projection_3d,
      },
      chart,
      style,
      &mut metrics,
    );
  }
  if let Some(data_table) = chart.data_table {
    if word_data_table_layout.is_none() {
      let (table_bounds, table_layout) =
        if word_parallel_bar_layout && let Some(mut layout) = parallel_data_table_layout {
          layout.header_height -= 12.0 * style.stroke_scale;
          let value_title_band = chart.value_axis_title.as_deref().map_or(0.0, |title| {
            word_chart_layout_metric(
              metrics
                .vertical_metrics_for_text(title, &style.value_axis_title)
                .line_height_pt(),
            ) + 9.0 * style.stroke_scale
          });
          let bottom = frame.y_pt + frame.height_pt
            - 11.0 * style.stroke_scale
            - value_title_band
            - if has_bottom_legend {
              word_bottom_line_legend_reservation(frame, chart, style, scale, &mut metrics)
            } else {
              0.0
            };
          let right = frame.x_pt + frame.width_pt
            - 11.0 * style.stroke_scale
            - if has_side_legend {
              side_legend_width + 6.0 * style.stroke_scale
            } else {
              0.0
            };
          let left = layout.outer_left + layout.series_column_width;
          (
            PlotRect {
              left,
              top: bottom - layout.height(chart.series.len()),
              width: right - left,
              height: layout.height(chart.series.len()),
            },
            Some(layout),
          )
        } else if let (Some(mut layout), Some(projection)) =
          (parallel_data_table_layout, projection_3d)
        {
          let left = projection.project(plot_left, plot_bottom, 0.0);
          let right = projection.project(plot_right, plot_bottom, 0.0);
          layout.outer_left = left.0 - layout.series_column_width;
          // The fixed table bottom owns the body rows. Its header spans from
          // the projected front floor edge to those rows, rather than starting
          // below the unprojected plot or stretching all rows equally.
          let table_bottom = frame.y_pt + frame.height_pt
            - 6.5 * style.stroke_scale
            - if has_bottom_legend {
              word_bottom_line_legend_reservation(frame, chart, style, scale, &mut metrics)
            } else {
              0.0
            };
          layout.header_height =
            table_bottom - left.1 - layout.body_row_height * chart.series.len() as f32;
          (
            PlotRect {
              left: left.0,
              top: left.1,
              width: right.0 - left.0,
              height: table_bottom - left.1,
            },
            Some(layout),
          )
        } else {
          (
            PlotRect {
              left: plot_left,
              top: painted_category_top,
              width: plot_width,
              height: data_table_height,
            },
            None,
          )
        };
      lower_data_table(
        &mut items,
        chart,
        data_table,
        table_bounds,
        style,
        &mut metrics,
        table_layout,
      );
    }
    if value_tick_labels_visible {
      lower_cartesian_value_tick_labels(
        &mut items,
        &tick_labels,
        ValueTickLabelContext {
          axis_x: primary_value_label_axis_x,
          labels_on_right: primary_value_axis_on_right,
          label_gap: primary_value_label_gap,
          scale,
          plot_top,
          plot_height,
          axis_depth: primary_value_label_axis_depth,
          value_label_line_height,
          tick_top_offset: frame.height_pt * excel_title_only_adjustment.tick_top_ratio,
          projection_3d: axis_text_projection_3d,
        },
        style,
        &mut metrics,
      );
    }
    let secondary_tick_label_offset = secondary_tick_gap
      + if word_combination_layout || word_manual_bottom_layout {
        0.0
      } else {
        frame.height_pt * 0.012_59
      };
    let mut left_axis_offset = if !primary_value_axis_on_right && value_tick_labels_visible {
      primary_value_axis_band_width
    } else {
      0.0
    };
    let mut right_axis_offset = if primary_value_axis_on_right && value_tick_labels_visible {
      primary_value_axis_band_width
    } else {
      0.0
    };
    for (_, _, secondary_scale, labels, width, on_right) in &secondary_value_tick_sets {
      let axis_x = if *on_right {
        plot_right + right_axis_offset
      } else {
        plot_left - left_axis_offset
      };
      for (value, label) in labels {
        let label_width = metrics.measure_text(label, &style.value_label);
        push_text(
          &mut items,
          if *on_right {
            axis_x + secondary_tick_label_offset
          } else {
            axis_x - secondary_tick_label_offset - label_width
          },
          value_y(*value, *secondary_scale, plot_top, plot_height) - value_label_line_height / 2.0,
          label.clone(),
          style.value_label.clone(),
        );
      }
      if *on_right {
        right_axis_offset += *width + secondary_tick_gap;
      } else {
        left_axis_offset += *width + secondary_tick_gap;
      }
    }
  }
  if chart.data_table.is_none() || word_data_table_layout.is_some() {
    lower_axis_titles(
      &mut items,
      AxisTitleGeometry {
        frame,
        plot: PlotRect {
          left: plot_left,
          top: plot_top,
          width: plot_width,
          height: plot_height,
        },
        value_label_band_left: tick_left,
        category_band_top: painted_category_top,
        category_label_height,
        data_table_height,
        projection_3d,
      },
      chart,
      style,
      &mut metrics,
    );
  }
  if let Some(title) = title_text {
    let automatic_title_top = title_top
      + if has_word_titled_bottom_layout && horizontal_bar_only {
        // Word's title text keeps the physical title band of the 252pt
        // reference chart, while the taller horizontal-bar plot continues to
        // use its frame-height reservation. Office reports the same 2pt title
        // box top for the bar and column charts in the POI two-chart control.
        (profiles::WORD_TITLED_BOTTOM_DEVICE_BAND_HEIGHT_PT - automatic_band_height_pt)
          * host_defaults.title_top_ratio
      } else {
        0.0
      }
      + if style.layout_profile == ChartLayoutProfile::Excel
        && chart.title_vertical_anchor == Some(a::TextAnchoringTypeValues::Bottom)
        && !chart.title_overlay
        && chart.plot_layout.is_none()
      {
        // A rich title anchored to the bottom of Excel's automatic title slot
        // moves within that reserved slot; it does not enlarge the plot's
        // title reservation. Title fill and text move together.
        frame.height_pt * 0.005
      } else {
        0.0
      };
    let mut title_style = style.title.clone();
    title_style.rotation_deg += chart.title_rotation_deg;
    if style.layout_profile == ChartLayoutProfile::Excel
      && chart.title_rotation_deg.abs() > f32::EPSILON
    {
      // Excel's fixed-format writer emits independently rotated chart-title
      // text as glyph outlines, just as it does for rotated worksheet-shape
      // text. Keep the visual title but do not invent extractable PDF text.
      title_style.pdf_glyph_outlines = true;
      let mut options = title_style
        .pdf_glyph_outline_options
        .as_deref()
        .cloned()
        .unwrap_or_default();
      options.semantic_text_overlay = false;
      title_style.pdf_glyph_outline_options = Some(Arc::new(options));
    }
    let width = metrics.measure_text(title, &title_style);
    let automatic_title_x = frame.x_pt + (frame.width_pt - width) / 2.0
      - if has_explicit_single_series_side_title_layout {
        frame.height_pt * 0.004_76
      } else if has_explicit_bottom_column_layout {
        frame.height_pt * 0.003_23
      } else {
        0.0
      };
    let title_bounds = chart.title_layout.map_or(
      PlotRect {
        left: automatic_title_x,
        top: automatic_title_top,
        width,
        height: title_line_height,
      },
      |layout| {
        apply_manual_text_layout(
          frame,
          PlotRect {
            left: automatic_title_x,
            top: automatic_title_top,
            width,
            height: title_line_height,
          },
          layout,
        )
      },
    );
    let title_x = title_bounds.left;
    let painted_title_top = title_bounds.top;
    if let Some(color) = style.title_fill_color {
      let horizontal_padding = title_style.font_size_pt * 0.162;
      let vertical_padding = title_style.font_size_pt * 0.092;
      items.push(PageItem::Rect(RectItem {
        x_pt: title_x - horizontal_padding,
        y_pt: painted_title_top - vertical_padding,
        width_pt: width + horizontal_padding * 2.0,
        height_pt: title_line_height + vertical_padding * 2.0,
        fill_color: Some(color),
        fill_opacity: 1.0,
        stroke: None,
        stroke_opacity: 1.0,
      }));
    }
    push_text(
      &mut items,
      title_x,
      painted_title_top,
      title.to_string(),
      title_style,
    );
  }
  if let Some(layout) = chart.legend_layout {
    lower_manual_legend(&mut items, frame, layout, chart, style, scale);
  } else {
    match legend_position {
      Some(ChartLegendPosition::Bottom) => lower_horizontal_legend(
        &mut items,
        chart,
        style,
        HorizontalLegendGeometry {
          frame,
          available_left: if word_parallel_column_layout {
            frame.x_pt
          } else {
            tick_left
          },
          y: legend_top,
          scale,
        },
        &mut metrics,
      ),
      Some(ChartLegendPosition::Top) => lower_horizontal_legend(
        &mut items,
        chart,
        style,
        HorizontalLegendGeometry {
          frame,
          available_left: frame.x_pt + frame.height_pt * profiles::TOP_LEGEND_LEFT_INSET_RATIO,
          y: if has_layout_title {
            title_top
              + title_line_height
              + frame.height_pt * host_defaults.titled_top_legend_gap_ratio
          } else {
            frame.y_pt + frame.height_pt * profiles::UNTITLED_TOP_LEGEND_TOP_RATIO
          },
          scale,
        },
        &mut metrics,
      ),
      Some(ChartLegendPosition::Left) => lower_vertical_legend(
        &mut items,
        frame.x_pt + side_legend_outer_margin,
        frame,
        false,
        chart,
        style,
        scale,
      ),
      Some(ChartLegendPosition::Right | ChartLegendPosition::TopRight) => lower_vertical_legend(
        &mut items,
        if let Some(legend_width) = word_marker_legend_frame_width {
          frame.x_pt + frame.width_pt
            - WORD_PERCENT_BAR_LEGEND_FRAME_RIGHT_INSET_PT * style.stroke_scale
            - legend_width
            + style.legend.font_size_pt * 0.5
        } else if let Some(legend_width) = word_fixed_line_legend_frame_width {
          frame.x_pt + frame.width_pt
            - WORD_DATA_TABLE_LINE_LEGEND_FRAME_RIGHT_INSET_PT * style.stroke_scale
            - legend_width
            + WORD_DATA_TABLE_LINE_LEGEND_LEFT_PADDING_PT * style.stroke_scale
        } else {
          frame.x_pt + frame.width_pt - side_legend_outer_margin - side_legend_width
            + if style.chartsheet {
              0.0
            } else if has_explicit_single_series_side_title_layout {
              -frame.height_pt * 0.009_84
            } else if has_excel_vary_colors_data_table_layout {
              frame.height_pt * profiles::EXCEL_VARY_COLORS_DATA_TABLE_LEGEND_X_RATIO
            } else if style.layout_profile == ChartLayoutProfile::Excel
              && chart.title.is_none()
              && chart.has_automatic_title_marker
              && chart.has_explicit_categories
              && chart.plot_layout.is_none()
            {
              frame.height_pt * 0.001_42
            } else {
              0.0
            }
        },
        frame,
        legend_position == Some(ChartLegendPosition::TopRight),
        chart,
        style,
        scale,
      ),
      None => {}
    }
  }
  items
}

#[derive(Clone, Copy)]
struct ValueTickLabelContext {
  axis_x: f32,
  labels_on_right: bool,
  label_gap: f32,
  scale: crate::render::chart::LinearAxisScale,
  plot_top: f32,
  plot_height: f32,
  axis_depth: f32,
  value_label_line_height: f32,
  tick_top_offset: f32,
  projection_3d: Option<Chart3DProjection>,
}

fn lower_cartesian_value_tick_labels(
  items: &mut Vec<PageItem>,
  tick_labels: &[(f64, String)],
  context: ValueTickLabelContext,
  style: &ClusteredColumnStyle,
  metrics: &mut TextMetrics,
) {
  for (value, label) in tick_labels {
    let width = metrics.measure_text(label, &style.value_label);
    let model_y = value_y(*value, context.scale, context.plot_top, context.plot_height);
    let (axis_x, axis_y) = context
      .projection_3d
      .map_or((context.axis_x, model_y), |projection| {
        projection.project(context.axis_x, model_y, context.axis_depth)
      });
    push_text(
      items,
      if context.labels_on_right {
        axis_x + context.label_gap
      } else {
        axis_x - context.label_gap - width
      },
      axis_y - context.value_label_line_height / 2.0
        + context.tick_top_offset
        + if context.projection_3d.is_some() {
          // The projected tick is the centre of the font em box. Our chart
          // line box has 1.2 em leading, so centring that whole box biases the
          // glyphs upward by half of the extra 0.2 em. Two-dimensional host
          // profiles already include this in their calibrated axis bands.
          style.value_label.font_size_pt * 0.1
        } else {
          0.0
        },
      label.clone(),
      style.value_label.clone(),
    );
  }
}

fn lower_cartesian_3d_walls(
  items: &mut Vec<PageItem>,
  plot: PlotRect,
  projection: Chart3DProjection,
  style: &ClusteredColumnStyle,
) {
  let first_wall = items.len();
  let front_top_left = projection.project(plot.left, plot.top, 0.0);
  let front_top_right = projection.project(plot.left + plot.width, plot.top, 0.0);
  let front_bottom_left = projection.project(plot.left, plot.top + plot.height, 0.0);
  let front_bottom_right = projection.project(plot.left + plot.width, plot.top + plot.height, 0.0);
  let back_top_left = projection.project(plot.left, plot.top, 1.0);
  let back_top_right = projection.project(plot.left + plot.width, plot.top, 1.0);
  let back_bottom_left = projection.project(plot.left, plot.top + plot.height, 1.0);
  let back_bottom_right = projection.project(plot.left + plot.width, plot.top + plot.height, 1.0);

  let back_color = (style.chart_style_id > 32)
    .then(|| chart_style_fill_fallback_color(&style.plot_area_style))
    .flatten()
    .or((style.chart_style_id > 32).then_some(RgbColor {
      r: 250,
      g: 250,
      b: 247,
    }));
  let (outline_color, outline_width) = chart_style_stroke_fallback(&style.plot_area_style)
    .unwrap_or((style.gridline_color, 0.75 * style.stroke_scale));
  // Word's automatic back/side walls have fill but no resolved outline.
  // The grid and axes own their boundary lines; outlining both wall faces
  // adds a dark vertical seam absent from native 3-D output. Explicit wall
  // spPr/ln still overrides this fallback, and the floor keeps its outline.
  let wall_outline =
    (style.layout_profile != ChartLayoutProfile::Word).then_some((outline_color, outline_width));
  let wall_color = |normal, fallback_shade| {
    back_color.map(|color| {
      if style.layout_profile == ChartLayoutProfile::Word {
        office_parallel_chart_surface_color(color, normal, [0.0, 0.0, 1.0], false)
      } else {
        shade_chart_color(color, fallback_shade)
      }
    })
  };
  push_chart_styled_polygon(
    items,
    &[
      back_top_left,
      back_top_right,
      back_bottom_right,
      back_bottom_left,
    ],
    &style.back_wall_style,
    wall_color([0.0, 0.0, 1.0], 1.0),
    wall_outline,
    style.stroke_scale,
  );

  let (depth_x, _) = projection.depth_vector();
  let (side_front_top, side_front_bottom, side_back_top, side_back_bottom) = if depth_x >= 0.0 {
    (
      front_top_left,
      front_bottom_left,
      back_top_left,
      back_bottom_left,
    )
  } else {
    (
      front_top_right,
      front_bottom_right,
      back_top_right,
      back_bottom_right,
    )
  };
  push_chart_styled_polygon(
    items,
    &[
      side_front_top,
      side_back_top,
      side_back_bottom,
      side_front_bottom,
    ],
    &style.side_wall_style,
    wall_color(
      [1.0, 0.0, 0.0],
      profiles::OFFICE_CARTESIAN_3D_BOX_SIDE_SHADE,
    ),
    wall_outline,
    style.stroke_scale,
  );
  push_chart_styled_polygon(
    items,
    &[
      front_bottom_left,
      back_bottom_left,
      back_bottom_right,
      front_bottom_right,
    ],
    &style.floor_style,
    wall_color([0.0, 1.0, 0.0], profiles::OFFICE_CARTESIAN_3D_BOX_TOP_SHADE),
    Some((outline_color, outline_width)),
    style.stroke_scale,
  );
  for item in &mut items[first_wall..] {
    if let PageItem::Path(path) = item
      && let Some(stroke) = &mut path.stroke
    {
      if style.layout_profile == ChartLayoutProfile::Word {
        // Native floor-outline controls at 1/4/8pt have round corners.
        // A default miter produces spikes outside the projected floor.
        stroke.join.get_or_insert(crate::common::StrokeJoin::Round);
      }
      stroke.width.0 = projection.pen_width(stroke.width.0, style.stroke_scale);
      let color = projection.unlit_pen_color(RgbColor {
        r: stroke.color.r,
        g: stroke.color.g,
        b: stroke.color.b,
      });
      stroke.color.r = color.r;
      stroke.color.g = color.g;
      stroke.color.b = color.b;
    }
  }
}

fn push_chart_styled_polygon(
  items: &mut Vec<PageItem>,
  points: &[(f32, f32)],
  style: &crate::common::ShapeStyle<'static>,
  fallback_fill_color: Option<RgbColor>,
  fallback_stroke: Option<(RgbColor, f32)>,
  stroke_width_scale: f32,
) {
  if points.len() < 3 {
    return;
  }
  let (left, top, right, bottom) = points.iter().fold(
    (
      f32::INFINITY,
      f32::INFINITY,
      f32::NEG_INFINITY,
      f32::NEG_INFINITY,
    ),
    |(left, top, right, bottom), (x, y)| (left.min(*x), top.min(*y), right.max(*x), bottom.max(*y)),
  );
  let bounds = common_rect(left, top, right - left, bottom - top);
  let fill = match &style.fill {
    crate::common::ShapeStyleValue::Paint(fill) => bind_chart_fill_to_bounds(fill, bounds),
    crate::common::ShapeStyleValue::NoPaint => crate::common::Fill::None,
    crate::common::ShapeStyleValue::Unspecified => fallback_fill_color
      .map(|color| crate::common::Fill::Solid(common_rgb(color, 1.0)))
      .unwrap_or(crate::common::Fill::None),
  };
  let stroke = match &style.stroke {
    crate::common::ShapeStyleValue::Paint(stroke) => Some(bind_chart_stroke_to_bounds(
      stroke,
      bounds,
      stroke_width_scale,
    )),
    crate::common::ShapeStyleValue::NoPaint => None,
    crate::common::ShapeStyleValue::Unspecified => {
      fallback_stroke.map(|(color, width_pt)| crate::common::Stroke {
        width: crate::common::Pt(width_pt),
        color: common_rgb(color, 1.0),
        ..Default::default()
      })
    }
  };
  if fill == crate::common::Fill::None && stroke.is_none() {
    return;
  }
  items.push(PageItem::Path(crate::common::PathItem {
    bounds,
    points: points.iter().map(|(x, y)| common_point(*x, *y)).collect(),
    commands: Vec::new(),
    closed: true,
    fill,
    stroke,
  }));
}

fn push_chart_polygon(
  items: &mut Vec<PageItem>,
  points: &[(f32, f32)],
  color: RgbColor,
  stroke: Option<(RgbColor, f32)>,
) {
  if points.len() < 3 {
    return;
  }
  let minimum_x = points
    .iter()
    .map(|point| point.0)
    .fold(f32::INFINITY, f32::min);
  let maximum_x = points
    .iter()
    .map(|point| point.0)
    .fold(f32::NEG_INFINITY, f32::max);
  let minimum_y = points
    .iter()
    .map(|point| point.1)
    .fold(f32::INFINITY, f32::min);
  let maximum_y = points
    .iter()
    .map(|point| point.1)
    .fold(f32::NEG_INFINITY, f32::max);
  items.push(PageItem::Path(crate::common::PathItem {
    bounds: common_rect(
      minimum_x,
      minimum_y,
      maximum_x - minimum_x,
      maximum_y - minimum_y,
    ),
    points: points.iter().map(|(x, y)| common_point(*x, *y)).collect(),
    commands: Vec::new(),
    closed: true,
    fill: crate::common::Fill::Solid(common_rgb(color, 1.0)),
    stroke: stroke.map(|(color, width_pt)| crate::common::Stroke {
      width: crate::common::Pt(width_pt),
      color: common_rgb(color, 1.0),
      dash: None,
      source_style_id: None,
      ..Default::default()
    }),
  }));
}

fn shade_chart_color(color: RgbColor, factor: f32) -> RgbColor {
  let channel = |value: u8| (f32::from(value) * factor).round().clamp(0.0, 255.0) as u8;
  RgbColor {
    r: channel(color.r),
    g: channel(color.g),
    b: channel(color.b),
  }
}

fn tint_chart_color(color: RgbColor, factor: f32) -> RgbColor {
  let channel = |value: u8| {
    (f32::from(value) + (255.0 - f32::from(value)) * factor)
      .round()
      .clamp(0.0, 255.0) as u8
  };
  RgbColor {
    r: channel(color.r),
    g: channel(color.g),
    b: channel(color.b),
  }
}

fn bind_chart_gradient_to_bounds(
  gradient: &crate::common::GradientFill<'static>,
  bounds: crate::common::Rect,
) -> crate::common::GradientFill<'static> {
  let mut gradient = gradient.clone();
  gradient.definition_bounds = Some(bounds);
  if let Some(path) = gradient.path.as_mut() {
    path.transform =
      crate::common::drawingml_gradient::bind_path_transform_to_bounds(path.transform, bounds);
    if path.kind == crate::common::GradientPathKind::Circle {
      path.transform = crate::common::office_circle_gradient_transform(path.transform);
    }
  }
  gradient
}

fn bind_chart_fill_to_bounds(
  fill: &crate::common::Fill<'static>,
  bounds: crate::common::Rect,
) -> crate::common::Fill<'static> {
  match fill {
    crate::common::Fill::Gradient(gradient) => {
      crate::common::Fill::Gradient(bind_chart_gradient_to_bounds(gradient, bounds))
    }
    fill => fill.clone(),
  }
}

fn bind_chart_stroke_to_bounds(
  stroke: &crate::common::Stroke<'static>,
  bounds: crate::common::Rect,
  width_scale: f32,
) -> crate::common::Stroke<'static> {
  let mut stroke = stroke.clone();
  stroke.width.0 *= width_scale;
  if let Some(gradient) = stroke.gradient.as_mut() {
    *gradient = bind_chart_gradient_to_bounds(gradient, bounds);
  }
  stroke
}

fn chart_common_color(color: crate::common::Color) -> RgbColor {
  RgbColor {
    r: color.r,
    g: color.g,
    b: color.b,
  }
}

fn chart_fill_fallback_color(fill: &crate::common::Fill<'_>) -> Option<RgbColor> {
  match fill {
    crate::common::Fill::Solid(color) => Some(chart_common_color(*color)),
    crate::common::Fill::Gradient(gradient) => gradient
      .stops
      .first()
      .map(|stop| chart_common_color(stop.color)),
    crate::common::Fill::Pattern(pattern) => Some(chart_common_color(pattern.foreground)),
    crate::common::Fill::None
    | crate::common::Fill::Theme(_)
    | crate::common::Fill::Image { .. }
    | crate::common::Fill::Texture(_) => None,
  }
}

fn chart_style_fill_fallback_color(style: &crate::common::ShapeStyle<'_>) -> Option<RgbColor> {
  match &style.fill {
    crate::common::ShapeStyleValue::Paint(fill) => chart_fill_fallback_color(fill),
    crate::common::ShapeStyleValue::Unspecified | crate::common::ShapeStyleValue::NoPaint => None,
  }
}

fn chart_style_stroke_fallback(style: &crate::common::ShapeStyle<'_>) -> Option<(RgbColor, f32)> {
  match &style.stroke {
    crate::common::ShapeStyleValue::Paint(stroke) => {
      Some((chart_common_color(stroke.color), stroke.width.0))
    }
    crate::common::ShapeStyleValue::Unspecified | crate::common::ShapeStyleValue::NoPaint => None,
  }
}

#[derive(Clone, Copy)]
struct LegendFrameMetrics {
  horizontal_padding: f32,
  vertical_padding: f32,
  horizontal_entry_offset: f32,
  vertical_entry_offset: f32,
  symbol_to_text: f32,
  symbol_height: f32,
}

fn legend_frame_metrics(font_size_pt: f32) -> LegendFrameMetrics {
  // LibreOffice chart2/source/view/main/VLegend.cxx derives automatic legend
  // geometry from these font-relative values, each with a 1 mm interop floor.
  let millimeter_pt: f32 = 72.0 / 25.4;
  LegendFrameMetrics {
    horizontal_padding: millimeter_pt.max(font_size_pt * 0.33),
    vertical_padding: millimeter_pt.max(font_size_pt * 0.2),
    horizontal_entry_offset: millimeter_pt.max(font_size_pt * 0.66),
    vertical_entry_offset: millimeter_pt.max(font_size_pt * 0.2),
    symbol_to_text: millimeter_pt.max(font_size_pt * 0.22),
    symbol_height: font_size_pt * 0.6,
  }
}

fn legend_frame_has_paint(style: &crate::common::ShapeStyle<'_>) -> bool {
  matches!(style.fill, crate::common::ShapeStyleValue::Paint(_))
    || matches!(style.stroke, crate::common::ShapeStyleValue::Paint(_))
}

fn push_legend_frame(
  items: &mut Vec<PageItem>,
  bounds: PlotRect,
  style: &crate::common::ShapeStyle<'static>,
  stroke_width_scale: f32,
) {
  if !legend_frame_has_paint(style) {
    return;
  }
  push_chart_shape_rect(
    items,
    bounds,
    ChartShapePaint {
      fill: Some(&style.fill),
      stroke: Some(&style.stroke),
      fallback_fill_color: None,
      stroke_width_scale,
    },
  );
}

struct ChartShapePaint<'a> {
  fill: Option<&'a crate::common::ShapeStyleValue<crate::common::Fill<'static>>>,
  stroke: Option<&'a crate::common::ShapeStyleValue<crate::common::Stroke<'static>>>,
  fallback_fill_color: Option<RgbColor>,
  stroke_width_scale: f32,
}

fn resolve_chart_shape_paint(
  bounds: crate::common::Rect,
  paint: ChartShapePaint<'_>,
) -> Option<(
  crate::common::Fill<'static>,
  Option<crate::common::Stroke<'static>>,
)> {
  let fill = match paint.fill {
    Some(crate::common::ShapeStyleValue::Paint(fill)) => bind_chart_fill_to_bounds(fill, bounds),
    Some(crate::common::ShapeStyleValue::NoPaint) => crate::common::Fill::None,
    Some(crate::common::ShapeStyleValue::Unspecified) | None => paint
      .fallback_fill_color
      .map(|color| crate::common::Fill::Solid(common_rgb(color, 1.0)))
      .unwrap_or(crate::common::Fill::None),
  };
  let stroke = match paint.stroke {
    Some(crate::common::ShapeStyleValue::Paint(stroke)) => Some(bind_chart_stroke_to_bounds(
      stroke,
      bounds,
      paint.stroke_width_scale,
    )),
    Some(crate::common::ShapeStyleValue::NoPaint | crate::common::ShapeStyleValue::Unspecified)
    | None => None,
  };
  (fill != crate::common::Fill::None || stroke.is_some()).then_some((fill, stroke))
}

fn push_chart_shape_rect(items: &mut Vec<PageItem>, bounds: PlotRect, paint: ChartShapePaint<'_>) {
  if bounds.width <= 0.0 || bounds.height <= 0.0 {
    return;
  }
  let path_bounds = common_rect(bounds.left, bounds.top, bounds.width, bounds.height);
  let Some((fill, stroke)) = resolve_chart_shape_paint(path_bounds, paint) else {
    return;
  };
  items.push(PageItem::Path(crate::common::PathItem {
    bounds: path_bounds,
    points: vec![
      common_point(bounds.left, bounds.top),
      common_point(bounds.left + bounds.width, bounds.top),
      common_point(bounds.left + bounds.width, bounds.top + bounds.height),
      common_point(bounds.left, bounds.top + bounds.height),
    ],
    commands: Vec::new(),
    closed: true,
    fill,
    stroke,
  }));
}

fn chart_shape_ellipse_path(
  center: (f32, f32),
  dimensions: (f32, f32),
  paint: ChartShapePaint<'_>,
) -> Option<crate::common::PathItem<'static>> {
  let (width, height) = dimensions;
  if width <= 0.0 || height <= 0.0 {
    return None;
  }
  let (center_x_pt, center_y_pt) = center;
  let left = center_x_pt - width * 0.5;
  let top = center_y_pt - height * 0.5;
  let bounds = common_rect(left, top, width, height);
  let (fill, stroke) = resolve_chart_shape_paint(bounds, paint)?;
  const SEGMENT_COUNT: usize = 32;
  let points = (0..SEGMENT_COUNT)
    .map(|index| {
      let angle = std::f32::consts::TAU * index as f32 / SEGMENT_COUNT as f32;
      common_point(
        center_x_pt + width * 0.5 * angle.cos(),
        center_y_pt + height * 0.5 * angle.sin(),
      )
    })
    .collect();
  Some(crate::common::PathItem {
    bounds,
    points,
    commands: Vec::new(),
    closed: true,
    fill,
    stroke,
  })
}

#[derive(Clone, Copy)]
enum ChartStatic3dSurface<'a> {
  DrawingMl {
    scene: &'a a::Scene3DType,
    shape: &'a a::Shape3DType,
  },
  BubbleSphere,
}

#[derive(Clone, Copy)]
struct ResolvedChartShapeEffects<'a> {
  image_effects: Option<&'a crate::common::drawingml_image_effects::ImageEffectContainer>,
  static_3d: Option<ChartStatic3dSurface<'a>>,
  extrusion_color: Option<crate::common::drawingml_3d::Static3dColor>,
  contour_color: Option<crate::common::drawingml_3d::Static3dColor>,
}

#[derive(Clone, Copy)]
enum ChartShapeEffectTarget {
  DataPoint { bubble_3d: bool },
  Marker,
}

#[derive(Clone, Copy)]
struct ChartSeriesPoint {
  series_index: usize,
  point_index: Option<usize>,
}

#[derive(Clone, Copy)]
struct ChartShapeEffectRequest {
  point: ChartSeriesPoint,
  target: ChartShapeEffectTarget,
  include_backdrop: bool,
}

fn resolved_chart_shape_effects(
  style: &ClusteredColumnStyle,
  series_index: usize,
  point_index: Option<usize>,
  target: ChartShapeEffectTarget,
) -> ResolvedChartShapeEffects<'_> {
  let point_marker = if matches!(target, ChartShapeEffectTarget::Marker) {
    point_index.and_then(|point_index| {
      style
        .series_point_marker_effect_styles
        .get(series_index)
        .and_then(|points| points.get(point_index))
        .and_then(Option::as_ref)
    })
  } else {
    None
  };
  let point = point_index
    .and_then(|point_index| {
      style
        .series_point_effect_styles
        .get(series_index)
        .and_then(|points| points.get(point_index))
    })
    .and_then(Option::as_ref);
  let direct = match target {
    ChartShapeEffectTarget::DataPoint { .. } => style.series_effect_styles.get(series_index),
    ChartShapeEffectTarget::Marker => style.series_marker_effect_styles.get(series_index),
  };
  let theme = &style.data_point_effect_style;
  let effect_sources = [point_marker, point, direct, Some(theme)];
  let image_effects = effect_sources
    .into_iter()
    .flatten()
    .find_map(|effects| effects.image_effects.as_ref());

  // Word treats c:bubble3D as an intrinsic sphere. It supersedes every
  // a:scene3d/a:sp3d component (including material) at point, series, and
  // theme scope, while the independently inherited 2-D effect graph above
  // still supplies shadows and other image effects.
  if matches!(
    target,
    ChartShapeEffectTarget::DataPoint { bubble_3d: true }
  ) {
    return ResolvedChartShapeEffects {
      image_effects,
      static_3d: Some(ChartStatic3dSurface::BubbleSphere),
      extrusion_color: None,
      contour_color: None,
    };
  }

  let scene = effect_sources
    .into_iter()
    .flatten()
    .find_map(|effects| effects.scene_3d.as_deref());
  let shape_owner = effect_sources
    .into_iter()
    .flatten()
    .find(|effects| effects.shape_3d.is_some());
  let shape = shape_owner.and_then(|effects| effects.shape_3d.as_deref());
  ResolvedChartShapeEffects {
    image_effects,
    static_3d: scene
      .zip(shape)
      .map(|(scene, shape)| ChartStatic3dSurface::DrawingMl { scene, shape }),
    extrusion_color: shape_owner.and_then(|effects| effects.extrusion_color),
    contour_color: shape_owner.and_then(|effects| effects.contour_color),
  }
}

fn push_chart_shape_ellipse_with_effects(
  items: &mut Vec<PageItem>,
  center: (f32, f32),
  diameter_pt: f32,
  paint: ChartShapePaint<'_>,
  style: &ClusteredColumnStyle,
  request: ChartShapeEffectRequest,
) {
  push_chart_shape_oval_with_effects(
    items,
    center,
    (diameter_pt, diameter_pt),
    paint,
    style,
    request,
  );
}

fn push_chart_shape_oval_with_effects(
  items: &mut Vec<PageItem>,
  center: (f32, f32),
  dimensions: (f32, f32),
  paint: ChartShapePaint<'_>,
  style: &ClusteredColumnStyle,
  request: ChartShapeEffectRequest,
) {
  let Some(path) = chart_shape_ellipse_path(center, dimensions, paint) else {
    return;
  };
  let effects = resolved_chart_shape_effects(
    style,
    request.point.series_index,
    request.point.point_index,
    request.target,
  );
  if !push_chart_shape_effect_raster(
    items,
    &path,
    effects.image_effects,
    effects.static_3d,
    effects.extrusion_color,
    effects.contour_color,
    request.include_backdrop,
  ) {
    items.push(PageItem::Path(path));
  }
}

fn push_chart_shape_effect_raster(
  items: &mut Vec<PageItem>,
  path: &crate::common::PathItem<'static>,
  effects: Option<&crate::common::drawingml_image_effects::ImageEffectContainer>,
  static_3d: Option<ChartStatic3dSurface<'_>>,
  extrusion_color: Option<crate::common::drawingml_3d::Static3dColor>,
  contour_color: Option<crate::common::drawingml_3d::Static3dColor>,
  include_backdrop: bool,
) -> bool {
  use crate::common::drawingml_image_effects::{
    ImageEffectContainer, ImageEffectContainerKind, unchanged_foreground_backdrop,
  };

  let empty_effects = ImageEffectContainer {
    kind: ImageEffectContainerKind::Sibling,
    effects: Vec::new(),
  };
  let effects = effects.unwrap_or(&empty_effects);
  let backdrop = unchanged_foreground_backdrop(effects);
  let has_static_3d = static_3d.is_some();

  if include_backdrop
    && let Some(backdrop) = backdrop.as_ref()
    && let Some(image) = chart_shape_effect_image(path, backdrop, None, None, None, 100.0 / 72.0)
  {
    items.push(PageItem::Image(image));
  }

  if has_static_3d {
    let foreground_effects = if backdrop.is_some() {
      &empty_effects
    } else {
      effects
    };
    let Some(image) = chart_shape_effect_image(
      path,
      foreground_effects,
      static_3d,
      extrusion_color,
      contour_color,
      200.0 / 72.0,
    ) else {
      return false;
    };
    items.push(PageItem::Image(image));
    return true;
  }

  if backdrop.is_some() {
    items.push(PageItem::Path(path.clone()));
    return true;
  }
  if effects.effects.is_empty() {
    return false;
  }
  let Some(image) = chart_shape_effect_image(path, effects, None, None, None, 96.0 / 72.0) else {
    return false;
  };
  items.push(PageItem::Image(image));
  true
}

fn chart_shape_effect_image(
  path: &crate::common::PathItem<'static>,
  effects: &crate::common::drawingml_image_effects::ImageEffectContainer,
  static_3d: Option<ChartStatic3dSurface<'_>>,
  extrusion_color: Option<crate::common::drawingml_3d::Static3dColor>,
  contour_color: Option<crate::common::drawingml_3d::Static3dColor>,
  maximum_pixels_per_point: f32,
) -> Option<ImageItem> {
  let width_pt = path.bounds.size.width.0;
  let height_pt = path.bounds.size.height.0;
  let output_bounds = if effects.effects.is_empty() {
    crate::common::drawingml_image_effects::EffectOutputBounds {
      left_pt: 0.0,
      top_pt: 0.0,
      right_pt: width_pt,
      bottom_pt: height_pt,
    }
  } else {
    crate::common::drawingml_image_effects::container_output_bounds(effects, width_pt, height_pt)?
  };
  let static_padding = static_3d
    .and_then(|surface| match surface {
      ChartStatic3dSurface::DrawingMl { scene, shape } => {
        Some(crate::common::drawingml_3d::output_padding(
          crate::common::drawingml_3d::camera_projection(scene, 0.0),
          shape,
          width_pt,
          height_pt,
        ))
      }
      ChartStatic3dSurface::BubbleSphere => None,
    })
    .unwrap_or_default();
  let relative_left = output_bounds.left_pt.min(0.0) - static_padding.left_pt;
  let relative_top = output_bounds.top_pt.min(0.0) - static_padding.top_pt;
  let relative_right = output_bounds.right_pt.max(width_pt) + static_padding.right_pt;
  let relative_bottom = output_bounds.bottom_pt.max(height_pt) + static_padding.bottom_pt;
  let raster_bounds = crate::common::Rect {
    origin: crate::common::Point {
      x: crate::common::Pt(path.bounds.origin.x.0 + relative_left),
      y: crate::common::Pt(path.bounds.origin.y.0 + relative_top),
    },
    size: crate::common::Size {
      width: crate::common::Pt(relative_right - relative_left),
      height: crate::common::Pt(relative_bottom - relative_top),
    },
  };
  let display_item = crate::common::DisplayItem::Path(path.clone());
  let mut raster =
    crate::common::drawingml_shape_raster::rasterize_vector_items_for_effects_at_bounded_pixels_per_point(
      std::slice::from_ref(&display_item),
      raster_bounds,
      effects,
      maximum_pixels_per_point,
    )?;
  if let Some(static_3d) = static_3d {
    let model_surface = Some(crate::common::drawingml_3d::Static3dSurface {
      left_px: -relative_left * raster.pixels_per_point,
      top_px: -relative_top * raster.pixels_per_point,
      width_px: width_pt * raster.pixels_per_point,
      height_px: height_pt * raster.pixels_per_point,
    });
    match static_3d {
      ChartStatic3dSurface::DrawingMl { scene, shape } => {
        let automatic_extrusion_color =
          crate::common::drawingml_3d::automatic_extrusion_color_from_items(std::slice::from_ref(
            &display_item,
          ));
        crate::common::drawingml_3d::apply_static_3d(
          &mut raster.image,
          scene,
          crate::common::drawingml_3d::camera_projection(scene, 0.0),
          shape,
          crate::common::drawingml_3d::Static3dRenderOptions {
            extrusion_color: extrusion_color.or(automatic_extrusion_color),
            contour_color,
            pixels_per_point: raster.pixels_per_point,
            model_surface,
          },
        );
      }
      ChartStatic3dSurface::BubbleSphere => {
        let scene = &*OFFICE_BUBBLE_3D_SCENE;
        crate::common::drawingml_3d::apply_static_3d_sphere_surface(
          &mut raster.image,
          scene,
          crate::common::drawingml_3d::camera_projection(scene, 0.0),
          None,
          crate::common::drawingml_3d::Static3dRenderOptions {
            extrusion_color: None,
            contour_color: None,
            pixels_per_point: raster.pixels_per_point,
            model_surface,
          },
        );
      }
    }
  }
  if !effects.effects.is_empty() {
    let mut effects = effects.clone();
    crate::common::drawingml_image_effects::scale_container_pixel_lengths(
      &mut effects,
      raster.pixels_per_point / (96.0 / 72.0),
    );
    crate::common::drawingml_image_effects::apply_container_to_padded_image_with_sources(
      &mut raster.image,
      &effects,
      -relative_left * raster.pixels_per_point,
      -relative_top * raster.pixels_per_point,
      width_pt * raster.pixels_per_point,
      height_pt * raster.pixels_per_point,
      crate::common::drawingml_image_effects::ImageEffectSourceImages {
        fill: raster.fill_image.as_ref(),
        line: raster.line_image.as_ref(),
        fill_line: raster.fill_line_image.as_ref(),
        children: raster.children_image.as_ref(),
        effect_mask: None,
        reflection_paint: None,
        bounds: Default::default(),
      },
    );
  }
  chart_raster_image(&raster.image, raster_bounds)
}

fn chartsheet_marker_raster_extent(
  size_pt: f32,
  pen_pt: f32,
  symbol: c::MarkerStyleValues,
  pixels_per_point: f32,
) -> (f32, f32, u32) {
  // Native size/outline controls quantize geometry on the 600-DPI printer
  // grid, then allocate the guarded surface at the nearest 200-DPI pixel.
  // Its actual density follows that integer allocation, not the nominal DPI.
  let dots = f64::from(size_pt) * 600.0 / 72.0;
  let geometry_dots = if symbol == c::MarkerStyleValues::Square {
    dots.round()
  } else {
    (dots * 0.5 + 1e-4).floor() * 2.0
  };
  let canvas_dots = (geometry_dots + f64::from(pen_pt) * 600.0 / 72.0).round() + 2.0;
  let canvas_pt = (canvas_dots * 72.0 / 600.0) as f32;
  let pixels = (canvas_pt * pixels_per_point).round().max(0.0) as u32;
  let source_pixels = (geometry_dots * f64::from(pixels) / canvas_dots) as f32;
  (source_pixels, canvas_pt, pixels)
}

fn chartsheet_marker_source_image(
  path: &crate::common::PathItem<'static>,
  symbol: c::MarkerStyleValues,
  pixels_per_point: f32,
) -> Option<image::RgbaImage> {
  if !matches!(path.fill, crate::common::Fill::Solid(color) if color.a == 255)
    || !matches!(
      symbol,
      c::MarkerStyleValues::Diamond | c::MarkerStyleValues::Triangle | c::MarkerStyleValues::Square
    )
    || path.stroke.as_ref().is_some_and(|stroke| {
      stroke.gradient.is_some()
        || stroke.pattern.is_some()
        || stroke.color.a != 255
        || stroke.resolved_dash().is_some()
        || stroke.alignment == Some(crate::common::StrokeAlignment::Inside)
        || stroke
          .compound
          .is_some_and(|compound| compound != crate::common::StrokeCompound::Single)
    })
  {
    return None;
  }
  let pen = path
    .stroke
    .as_ref()
    .map_or(0.0, |stroke| stroke.width.0.max(0.0));
  let (source_width, canvas_width, width_px) =
    chartsheet_marker_raster_extent(path.bounds.size.width.0, pen, symbol, pixels_per_point);
  let (source_height, _, height_px) =
    chartsheet_marker_raster_extent(path.bounds.size.height.0, pen, symbol, pixels_per_point);
  if width_px == 0 || height_px == 0 || u64::from(width_px) * u64::from(height_px) > 250_000 {
    return None;
  }
  // PixelOffsetModeNone geometry is displaced by half a pixel within the
  // allocated canvas. This also reproduces the native no-outline controls.
  if source_width <= 0.0 || source_height <= 0.0 {
    return None;
  }
  let center_x = (width_px as f32 - 1.0) * 0.5;
  let center_y = (height_px as f32 - 1.0) * 0.5;
  chartsheet_marker_rasterize_source(
    path,
    common_rect(
      center_x - source_width * 0.5,
      center_y - source_height * 0.5,
      source_width,
      source_height,
    ),
    width_px,
    height_px,
    width_px as f32 / canvas_width,
  )
}

fn chartsheet_marker_rasterize_source(
  path: &crate::common::PathItem<'static>,
  source_bounds: crate::common::Rect,
  width_px: u32,
  height_px: u32,
  stroke_scale: f32,
) -> Option<image::RgbaImage> {
  use crate::common::drawingml_shape_raster::{
    PageToRasterMapping, RasterPrimitiveAntialiasing, rasterize_vector_items_at_mapping,
  };
  let mut source = path.clone();
  source.bounds = source_bounds;
  for point in &mut source.points {
    point.x.0 = source.bounds.origin.x.0
      + ((point.x.0 - path.bounds.origin.x.0) / path.bounds.size.width.0 * 2.0).round()
        * source_bounds.size.width.0
        * 0.5;
    point.y.0 = source.bounds.origin.y.0
      + ((point.y.0 - path.bounds.origin.y.0) / path.bounds.size.height.0 * 2.0).round()
        * source_bounds.size.height.0
        * 0.5;
  }
  if let Some(stroke) = source.stroke.as_mut() {
    stroke.width.0 *= stroke_scale;
    stroke.join = stroke.join.or(Some(crate::common::StrokeJoin::Round));
    stroke.drawingml_device = None;
  }
  let mapping = PageToRasterMapping {
    width_px,
    height_px,
    scale_x: 1.0,
    scale_y: 1.0,
    translate_x: 0.0,
    translate_y: 0.0,
    text_hinting: None,
  };
  // GDI+ resolves FillPolygon and DrawPolygon separately before compositing.
  let mut fill = source.clone();
  fill.stroke = None;
  let mut image = rasterize_vector_items_at_mapping(
    &[crate::common::DisplayItem::Path(fill)],
    mapping,
    RasterPrimitiveAntialiasing::OfficeAntiAlias8x4,
  )?;
  let crate::common::Fill::Solid(fill_color) = path.fill else {
    return None;
  };
  chartsheet_marker_premultiply_coverage(&mut image, fill_color);
  if source.stroke.is_some() {
    source.fill = crate::common::Fill::None;
    let stroke = source.stroke.as_ref()?;
    let stroke_color = stroke.color;
    let mut line = if stroke.width.0 * stroke.width.0 < 2.0001 {
      chartsheet_marker_cosmetic_image(&source.points, width_px, height_px, stroke_color)
    } else {
      rasterize_vector_items_at_mapping(
        &[crate::common::DisplayItem::Path(source)],
        mapping,
        RasterPrimitiveAntialiasing::OfficeAntiAlias8x4,
      )?
    };
    chartsheet_marker_premultiply_coverage(&mut line, stroke_color);
    for (destination, source) in image.pixels_mut().zip(line.pixels()) {
      let inverse_alpha = 255 - u32::from(source[3]);
      for channel in 0..4 {
        destination[channel] = (u32::from(source[channel])
          + (u32::from(destination[channel]) * inverse_alpha + 127) / 255)
          .min(255) as u8;
      }
    }
  }
  for pixel in image.pixels_mut() {
    let alpha = u32::from(pixel[3]);
    if alpha == 0 {
      *pixel = image::Rgba([0; 4]);
      continue;
    }
    *pixel = chartsheet_marker_export_pixel(chartsheet_marker_demultiply_pixel(*pixel));
  }
  Some(image)
}

fn chartsheet_marker_cosmetic_image(
  points: &[crate::common::Point],
  width: u32,
  height: u32,
  color: crate::common::Color,
) -> image::RgbaImage {
  // GDI+ cosmetic edges occupy one minor-axis pixel. At a 45-degree tie
  // the vertical axis owns the scan. Cross products preserve exact sample
  // boundaries; widening by a rounded Euclidean normal moves sloped edges.
  let edges = points
    .iter()
    .zip(points.iter().cycle().skip(1))
    .map(|(a, b)| {
      (
        f64::from(a.x.0),
        f64::from(a.y.0),
        f64::from(b.x.0) - f64::from(a.x.0),
        f64::from(b.y.0) - f64::from(a.y.0),
      )
    })
    .collect::<Vec<_>>();
  // Native corner controls retain a subpixel guard; the right arc boundary
  // is excluded by the scanner.
  let corner_radius_squared = 1.0 / 8.0;
  image::RgbaImage::from_fn(width, height, |x, y| {
    let mut covered = 0_u32;
    for sy in 0..4 {
      for sx in 0..8 {
        let px = f64::from(x) + f64::from(sx - 4) / 8.0;
        let py = f64::from(y) + f64::from(sy - 2) / 4.0;
        let inside = edges.iter().any(|&(ax, ay, dx, dy)| {
          let vertical = dy.abs() >= dx.abs();
          let major = if vertical { dy } else { dx };
          if major == 0.0 {
            return false;
          }
          let along = if vertical { py - ay } else { px - ax };
          let cross = if vertical {
            (px - ax) * dy - dx * (py - ay)
          } else {
            (py - ay) * dx - dy * (px - ax)
          } * major.signum();
          let within = if major > 0.0 {
            along >= 0.0 && along < major
          } else {
            along <= 0.0 && along > major
          };
          within && cross >= -major.abs() * 0.5 && cross < major.abs() * 0.5
        }) || points.iter().any(|point| {
          let dx = px - f64::from(point.x.0);
          let dy = py - f64::from(point.y.0);
          let distance = dx * dx + dy * dy;
          distance < corner_radius_squared || distance == corner_radius_squared && dx < 0.0
        });
        covered += u32::from(inside);
      }
    }
    image::Rgba([color.r, color.g, color.b, ((covered * 255 + 16) / 32) as u8])
  })
}

fn chartsheet_marker_demultiply_pixel(mut pixel: image::Rgba<u8>) -> image::Rgba<u8> {
  let alpha = u32::from(pixel[3]);
  if let Some(reciprocal) = (255_u32 << 16).checked_div(alpha) {
    // A truncated reciprocal reproduces the GDI+ primitive color controls.
    // Exact integer division would round some bright edge colors up by one.
    for channel in 0..3 {
      pixel[channel] = ((u32::from(pixel[channel]) * reciprocal) >> 16).min(255) as u8;
    }
  }
  pixel
}

fn chartsheet_marker_premultiply_coverage(
  image: &mut image::RgbaImage,
  color: crate::common::Color,
) {
  // Recover the opaque brush's 32-sample coverage before rounding each
  // premultiplied channel. Using rounded A8 as a fraction loses that boundary.
  for pixel in image.pixels_mut() {
    let samples = (u32::from(pixel[3]) * 32 + 127) / 255;
    for (channel, value) in [color.r, color.g, color.b].into_iter().enumerate() {
      pixel[channel] = ((u32::from(value) * samples + 16) / 32) as u8;
    }
  }
}

fn chartsheet_marker_export_pixel(mut pixel: image::Rgba<u8>) -> image::Rgba<u8> {
  // Native GDI+ color controls reproduce the PDF's RGB/soft-mask pair after
  // this additional truncated premultiply/unpremultiply conversion.
  let alpha = u32::from(pixel[3]);
  for channel in 0..3 {
    let premultiplied = u32::from(pixel[channel]) * alpha / 255;
    if let Some(value) = (premultiplied * 255).checked_div(alpha) {
      pixel[channel] = value as u8;
    }
  }
  pixel
}

struct ChartsheetMarkerShadowAxis {
  near_pt: f32,
  span_pt: f32,
  pixels: u32,
  source_near_px: f32,
  source_span_px: f32,
}

fn chartsheet_marker_shadow_axis(
  size_pt: f32,
  pen_pt: f32,
  symbol: c::MarkerStyleValues,
  offset_pt: f32,
  blur_pt: f32,
  pixels_per_point: f32,
) -> ChartsheetMarkerShadowAxis {
  let dots = f64::from(size_pt) * 600.0 / 72.0;
  let half_dots = (dots * 0.5 + 1e-4).floor();
  let near = -half_dots * 72.0 / 600.0;
  let far = if symbol == c::MarkerStyleValues::Square {
    (dots.round() - half_dots) * 72.0 / 600.0
  } else {
    -near
  };
  let quantize = |value: f64| (value * 600.0 / 72.0).round() * 72.0 / 600.0;
  let offset = f64::from(offset_pt);
  let outset = f64::from(pen_pt) * 0.5 + f64::from(blur_pt);
  // Excel's distance/direction/blur controls quantize the complete translated
  // effect bounds, then add one guard dot. Quantizing the source first loses
  // the change in canvas size and sampling phase at fractional translations.
  let left = quantize(near - outset + offset) - 72.0 / 600.0;
  let right = quantize(far + outset + offset) + 72.0 / 600.0;
  let span = right - left;
  let pixels = (span * f64::from(pixels_per_point)).round().max(0.0) as u32;
  let scale = f64::from(pixels) / span;
  ChartsheetMarkerShadowAxis {
    near_pt: left as f32,
    span_pt: span as f32,
    pixels,
    source_near_px: ((near + offset - left) * scale - 0.5) as f32,
    source_span_px: ((far - near) * scale) as f32,
  }
}

fn push_chartsheet_marker_effect_raster(
  items: &mut Vec<PageItem>,
  marker_backdrops: Option<&mut Vec<PageItem>>,
  path: &crate::common::PathItem<'static>,
  symbol: c::MarkerStyleValues,
  effects: Option<&crate::common::drawingml_image_effects::ImageEffectContainer>,
) -> bool {
  use crate::common::drawingml_image_effects::{
    EffectRasterScale, ImageEffect, ImageEffectSourceGeometry, simple_outer_shadow_translation,
    unchanged_foreground_backdrop,
  };
  let Some(mut backdrop) = effects.and_then(unchanged_foreground_backdrop) else {
    return false;
  };
  let Some(shadow) = simple_outer_shadow_translation(&backdrop) else {
    return false;
  };
  let pixels_per_point = 200.0 / 72.0;
  let Some(source) = chartsheet_marker_source_image(path, symbol, pixels_per_point) else {
    return false;
  };
  let pen = path
    .stroke
    .as_ref()
    .map_or(0.0, |stroke| stroke.width.0.max(0.0));
  let (_, canvas_width, _) =
    chartsheet_marker_raster_extent(path.bounds.size.width.0, pen, symbol, pixels_per_point);
  let (_, canvas_height, _) =
    chartsheet_marker_raster_extent(path.bounds.size.height.0, pen, symbol, pixels_per_point);
  let printer_grid = |value: f32| (f64::from(value) * 600.0 / 72.0).round() as f32 * (72.0 / 600.0);
  // The PDF range ends at the final sample center, half a bitmap pixel short
  // of the allocated surface. Keep this separate from source rasterization.
  // A square allocates an odd printer-dot canvas for its covered outline.
  // Excel anchors that canvas from the snapped marker center using the even
  // inner span; rounding the half-odd canvas origin instead moves some
  // foregrounds one printer dot left of the line and shadow.
  let foreground_x = if symbol == c::MarkerStyleValues::Square {
    printer_grid(path.bounds.origin.x.0 + path.bounds.size.width.0 * 0.5)
      - (canvas_width - 72.0 / 600.0) * 0.5
  } else {
    printer_grid(path.bounds.origin.x.0 + (path.bounds.size.width.0 - canvas_width) * 0.5)
  };
  let foreground_bounds = common_rect(
    foreground_x,
    printer_grid(path.bounds.origin.y.0 + (path.bounds.size.height.0 - canvas_height) * 0.5),
    canvas_width * (1.0 - 0.5 / source.width() as f32),
    canvas_height * (1.0 - 0.5 / source.height() as f32),
  );
  let Some(mut foreground) = chart_raster_image(&source, foreground_bounds) else {
    return false;
  };
  foreground.content_type =
    Some("application/vnd.ooxmlsdk.excel-chartsheet-marker+png".to_string());
  let radius_pt = shadow.blur_radius_px * (72.0 / 96.0);
  let x = chartsheet_marker_shadow_axis(
    path.bounds.size.width.0,
    pen,
    symbol,
    shadow.offset_x_px * (72.0 / 96.0),
    radius_pt,
    pixels_per_point,
  );
  let y = chartsheet_marker_shadow_axis(
    path.bounds.size.height.0,
    pen,
    symbol,
    shadow.offset_y_px * (72.0 / 96.0),
    radius_pt,
    pixels_per_point,
  );
  if x.pixels == 0 || y.pixels == 0 || u64::from(x.pixels) * u64::from(y.pixels) > 250_000 {
    return false;
  }
  let source_bounds = common_rect(
    x.source_near_px,
    y.source_near_px,
    x.source_span_px,
    y.source_span_px,
  );
  let Some(mut image) = chartsheet_marker_rasterize_source(
    path,
    source_bounds,
    x.pixels,
    y.pixels,
    x.pixels as f32 / x.span_pt,
  ) else {
    return false;
  };
  // The shifted shape is sampled directly into its own guarded shadow canvas.
  // Reusing foreground pixels misses the native subpixel phase and density.
  if let [ImageEffect::OuterShadow { distance_px, .. }] = backdrop.effects.as_mut_slice() {
    *distance_px = 0.0;
  }
  let scale = EffectRasterScale {
    x: x.pixels as f32 / x.span_pt / (96.0 / 72.0),
    y: y.pixels as f32 / y.span_pt / (96.0 / 72.0),
  };
  let left = source_bounds.origin.x.0 / scale.x;
  let top = source_bounds.origin.y.0 / scale.y;
  let width = source_bounds.size.width.0 / scale.x;
  let height = source_bounds.size.height.0 / scale.y;
  if crate::common::drawingml_image_effects::apply_container_to_padded_image_with_sources_on_raster(
    &mut image,
    &backdrop,
    ImageEffectSourceGeometry {
      paint_left_px: left,
      paint_top_px: top,
      paint_width_px: width,
      paint_height_px: height,
      shadow_anchor_left_px: left,
      shadow_anchor_top_px: top,
      shadow_anchor_width_px: width,
      shadow_anchor_height_px: height,
      anchor_left_px: left,
      anchor_top_px: top,
      anchor_width_px: width,
      anchor_height_px: height,
      ramp_left_px: left,
      ramp_top_px: top,
      ramp_width_px: width,
      ramp_height_px: height,
    },
    Default::default(),
    scale,
  )
  .is_none()
  {
    return false;
  }
  let shadow_bounds = common_rect(
    printer_grid(path.bounds.origin.x.0 + path.bounds.size.width.0 * 0.5) + x.near_pt,
    printer_grid(path.bounds.origin.y.0 + path.bounds.size.height.0 * 0.5) + y.near_pt,
    x.span_pt * (1.0 - 0.5 / x.pixels as f32),
    y.span_pt * (1.0 - 0.5 / y.pixels as f32),
  );
  let Some(mut shadow) = chart_raster_image(&image, shadow_bounds) else {
    return false;
  };
  shadow.content_type = Some("application/vnd.ooxmlsdk.excel-chartsheet-marker+png".to_string());
  marker_backdrops
    .unwrap_or(items)
    .push(PageItem::Image(shadow));
  items.push(PageItem::Image(foreground));
  true
}

fn chart_raster_image(
  image: &image::RgbaImage,
  raster_bounds: crate::common::Rect,
) -> Option<ImageItem> {
  chart_raster_image_with_target(image, raster_bounds, None, None)
}

fn chart_raster_image_with_target(
  image: &image::RgbaImage,
  raster_bounds: crate::common::Rect,
  target_size: Option<(u32, u32)>,
  logical_canvas: Option<(crate::common::Rect, f32)>,
) -> Option<ImageItem> {
  let mut encoded = Vec::new();
  {
    let mut encoder = png::Encoder::new(&mut encoded, image.width(), image.height());
    encoder.set_color(png::ColorType::Rgba);
    encoder.set_depth(png::BitDepth::Eight);
    let mut writer = encoder.write_header().ok()?;
    writer.write_image_data(image.as_raw()).ok()?;
    if let Some((width, height)) = target_size {
      let mut payload = [0_u8; 8];
      payload[..4].copy_from_slice(&width.to_be_bytes());
      payload[4..].copy_from_slice(&height.to_be_bytes());
      writer
        .write_chunk(png::chunk::ChunkType(*b"oxCg"), &payload)
        .ok()?;
    }
    if let Some((canvas, dpi)) = logical_canvas {
      // Retain the unsnapped viewport relative to this image. Word can move
      // an inline chart later during paragraph alignment; printer-grid
      // enclosure belongs to its final page position, not this early one.
      let values = [
        canvas.origin.x.0 - raster_bounds.origin.x.0,
        canvas.origin.y.0 - raster_bounds.origin.y.0,
        canvas.size.width.0,
        canvas.size.height.0,
        dpi,
      ];
      let payload: Vec<_> = values.into_iter().flat_map(f32::to_be_bytes).collect();
      writer
        .write_chunk(png::chunk::ChunkType(*b"oxCb"), &payload)
        .ok()?;
    }
    writer.finish().ok()?;
  }
  Some(ImageItem {
    x_pt: raster_bounds.origin.x.0,
    y_pt: raster_bounds.origin.y.0,
    width_pt: raster_bounds.size.width.0,
    height_pt: raster_bounds.size.height.0,
    crop: ImageCrop::default(),
    clip_path: Vec::new(),
    rotation_deg: 0.0,
    flip_horizontal: false,
    flip_vertical: false,
    data: Bytes::from(encoded),
    content_type: Some("image/png".to_string()),
    blip_compression_state: crate::common::BlipCompressionState::Unspecified,
    metafile_monochrome_dib_palette_override: None,
    metafile_background_color: None,
    metafile_external_header: None,
    metafile_fixed_output_profile: crate::common::MetafileFixedOutputProfile::Default,
    metafile_semantic_text_includes_raster_backdrop: false,
    alt_text: None,
    hyperlink_url: None,
    floating: false,
    behind_text: false,
  })
}

fn push_chart_styled_line(
  items: &mut Vec<PageItem>,
  start: (f32, f32),
  end: (f32, f32),
  stroke: Option<&crate::common::ShapeStyleValue<crate::common::Stroke<'static>>>,
  fallback_color: RgbColor,
  fallback_width_pt: f32,
  stroke_width_scale: f32,
) {
  let bounds = common_rect(
    start.0.min(end.0),
    start.1.min(end.1),
    (end.0 - start.0).abs(),
    (end.1 - start.1).abs(),
  );
  let stroke = match stroke {
    Some(crate::common::ShapeStyleValue::NoPaint) => return,
    Some(crate::common::ShapeStyleValue::Paint(stroke)) => {
      bind_chart_stroke_to_bounds(stroke, bounds, stroke_width_scale)
    }
    Some(crate::common::ShapeStyleValue::Unspecified) | None => crate::common::Stroke {
      width: crate::common::Pt(fallback_width_pt),
      color: common_rgb(fallback_color, 1.0),
      ..Default::default()
    },
  };
  items.push(PageItem::Path(crate::common::PathItem {
    bounds,
    points: vec![common_point(start.0, start.1), common_point(end.0, end.1)],
    commands: Vec::new(),
    closed: false,
    fill: crate::common::Fill::None,
    stroke: Some(stroke),
  }));
}

fn push_chart_styled_polyline(
  items: &mut Vec<PageItem>,
  points: &[(f32, f32)],
  stroke: Option<&crate::common::ShapeStyleValue<crate::common::Stroke<'static>>>,
  fallback_color: RgbColor,
  fallback_width_pt: f32,
  stroke_width_scale: f32,
  excel_line_series: bool,
) {
  if points.len() < 2 {
    return;
  }
  let (left, top, right, bottom) = points.iter().fold(
    (
      f32::INFINITY,
      f32::INFINITY,
      f32::NEG_INFINITY,
      f32::NEG_INFINITY,
    ),
    |(left, top, right, bottom), (x, y)| (left.min(*x), top.min(*y), right.max(*x), bottom.max(*y)),
  );
  let bounds = common_rect(left, top, right - left, bottom - top);
  let mut stroke = match stroke {
    Some(crate::common::ShapeStyleValue::NoPaint) => return,
    Some(crate::common::ShapeStyleValue::Paint(stroke)) => {
      bind_chart_stroke_to_bounds(stroke, bounds, stroke_width_scale)
    }
    Some(crate::common::ShapeStyleValue::Unspecified) | None => crate::common::Stroke {
      width: crate::common::Pt(fallback_width_pt),
      color: common_rgb(fallback_color, 1.0),
      ..Default::default()
    },
  };
  apply_excel_line_series_stroke_defaults(&mut stroke, excel_line_series);
  items.push(PageItem::Path(crate::common::PathItem {
    bounds,
    points: points.iter().map(|(x, y)| common_point(*x, *y)).collect(),
    commands: Vec::new(),
    closed: false,
    fill: crate::common::Fill::None,
    stroke: Some(stroke),
  }));
}

fn apply_excel_line_series_stroke_defaults(
  stroke: &mut crate::common::Stroke<'_>,
  excel_line_series: bool,
) {
  if excel_line_series {
    // Excel's classic line-chart style supplies round caps and joins even
    // when the theme's a:ln has cap="flat". An authored c:ser/c:spPr/a:ln
    // cap or join overrides its corresponding automatic component.
    stroke.cap.get_or_insert(crate::common::StrokeCap::Round);
    stroke.join.get_or_insert(crate::common::StrokeJoin::Round);
  }
}

/// Clips a chart polyline to the visible plot rectangle using the same
/// Liang-Barsky segment algorithm as LibreOffice chart2 `Clipping.cxx`.
/// Separate visible pieces remain separate paths so a stroke cannot bridge an
/// interval that lies wholly outside the authored axis window.
fn clip_chart_polyline_to_plot(points: &[(f32, f32)], plot: PlotRect) -> Vec<Vec<(f32, f32)>> {
  let mut clipped_runs = Vec::new();
  let mut current = Vec::new();
  for segment in points.windows(2) {
    let Some((start, end)) = clip_chart_line_segment_to_plot(segment[0], segment[1], plot) else {
      if current.len() >= 2 {
        clipped_runs.push(std::mem::take(&mut current));
      } else {
        current.clear();
      }
      continue;
    };
    if start == end {
      continue;
    }
    if current.last().copied() == Some(start) {
      current.push(end);
    } else {
      if current.len() >= 2 {
        clipped_runs.push(std::mem::take(&mut current));
      } else {
        current.clear();
      }
      current.extend([start, end]);
    }
  }
  if current.len() >= 2 {
    clipped_runs.push(current);
  }
  clipped_runs
}

fn clip_chart_line_segment_to_plot(
  start: (f32, f32),
  end: (f32, f32),
  plot: PlotRect,
) -> Option<((f32, f32), (f32, f32))> {
  let direction = (end.0 - start.0, end.1 - start.1);
  if direction.0 == 0.0 && direction.1 == 0.0 {
    return chart_point_inside_plot(start, plot).then_some((start, end));
  }
  let mut enter = 0.0_f32;
  let mut leave = 1.0_f32;
  for (denominator, numerator) in [
    (direction.0, plot.left - start.0),
    (-direction.0, start.0 - (plot.left + plot.width)),
    (direction.1, plot.top - start.1),
    (-direction.1, start.1 - (plot.top + plot.height)),
  ] {
    if denominator > 0.0 {
      let ratio = numerator / denominator;
      if ratio > leave {
        return None;
      }
      enter = enter.max(ratio);
    } else if denominator < 0.0 {
      let ratio = numerator / denominator;
      if ratio < enter {
        return None;
      }
      leave = leave.min(ratio);
    } else if numerator > 0.0 {
      return None;
    }
  }
  Some((
    (start.0 + enter * direction.0, start.1 + enter * direction.1),
    (start.0 + leave * direction.0, start.1 + leave * direction.1),
  ))
}

fn chart_point_inside_plot(point: (f32, f32), plot: PlotRect) -> bool {
  point.0 >= plot.left
    && point.0 <= plot.left + plot.width
    && point.1 >= plot.top
    && point.1 <= plot.top + plot.height
}

fn push_radial_point_with_effects(
  items: &mut Vec<PageItem>,
  backdrops: &mut Vec<PageItem>,
  item: PageItem,
  effects: Option<&crate::common::drawingml_image_effects::ImageEffectContainer>,
) {
  let Some(effects) = effects else {
    items.push(item);
    return;
  };
  let PageItem::Path(path) = item else {
    items.push(item);
    return;
  };
  if let Some(backdrop) =
    crate::common::drawingml_image_effects::unchanged_foreground_backdrop(effects)
    && let Some(image) = chart_shape_effect_image(&path, &backdrop, None, None, None, 100.0 / 72.0)
  {
    backdrops.push(PageItem::Image(image));
  }
  if !push_chart_shape_effect_raster(items, &path, Some(effects), None, None, None, false) {
    items.push(PageItem::Path(path));
  }
}

struct RadialSlice {
  index: usize,
  center: (f32, f32),
  perspective_plane_offset: (f32, f32),
  start_angle: f32,
  sweep: f32,
  explosion: f32,
  color: RgbColor,
}

pub(crate) fn lower_radial_chart(
  frame: ChartFrame,
  chart: &PieChartModel<'_>,
  automatic_title: &str,
  style: &RadialChartStyle,
) -> Vec<PageItem> {
  if frame.width_pt <= 0.0
    || frame.height_pt <= 0.0
    || chart.values.is_empty()
    || style.point_colors.is_empty()
  {
    return Vec::new();
  }
  let total = chart
    .values
    .iter()
    .flatten()
    .filter(|value| value.is_finite() && **value > 0.0)
    .sum::<f64>();
  if total <= f64::EPSILON {
    return Vec::new();
  }

  let mut metrics = TextMetrics::new();
  let title = match chart.title.as_ref() {
    Some(ChartTitleText::Explicit(title)) => Some(title.as_str()),
    Some(ChartTitleText::Automatic) => Some(automatic_title),
    None => None,
  };
  let host_defaults = radial_host_defaults(style.layout_profile);
  let title_height = title.map_or(0.0, |_| {
    line_height(&style.title) * host_defaults.title_height_scale
  });
  let legend = chart.legend_position;
  let side_legend = matches!(
    legend,
    Some(ChartLegendPosition::Left | ChartLegendPosition::Right | ChartLegendPosition::TopRight)
  ) && !chart.legend_overlay;
  let bottom_legend = legend == Some(ChartLegendPosition::Bottom) && !chart.legend_overlay;
  let top_legend = legend == Some(ChartLegendPosition::Top) && !chart.legend_overlay;
  let maximum_side_legend_label_width = if side_legend {
    chart
      .visible_legend_indices
      .iter()
      .filter_map(|index| chart.categories.get(*index))
      .map(|text| metrics.measure_text(text, &style.legend))
      .fold(0.0_f32, f32::max)
  } else {
    0.0
  };
  let legend_width = if side_legend {
    maximum_side_legend_label_width + style.legend.font_size_pt * host_defaults.side_legend_width_em
  } else {
    0.0
  };
  let legend_height = if bottom_legend || top_legend {
    line_height(&style.legend) * 1.8
  } else {
    0.0
  };
  let mut plot = PlotRect {
    left: frame.x_pt
      + if legend == Some(ChartLegendPosition::Left) {
        legend_width
      } else {
        0.0
      },
    top: frame.y_pt + title_height + if top_legend { legend_height } else { 0.0 },
    width: frame.width_pt - if side_legend { legend_width } else { 0.0 },
    height: frame.height_pt - title_height - legend_height,
  };
  let word_pie_3d_layout = word_automatic_pie_3d_layout(chart, style);
  let word_pie_3d_title_band = word_pie_3d_layout.then(|| {
    title.map_or(0.0, |text| {
      word_chart_title_band(text, &style.title, 1.0, &mut metrics)
    })
  });
  if let Some(title_band) = word_pie_3d_title_band {
    // Word's 3-D pie keeps a rectangular viewport. Native angle controls
    // retain this layout; only title, legend and frame dimensions reserve
    // space before the scene is projected.
    let side_band = if side_legend {
      word_filled_legend_metrics(
        chart
          .visible_legend_indices
          .iter()
          .filter_map(|&i| chart.categories.get(i).map(String::as_str)),
        &style.legend,
        1.0,
        &mut metrics,
      )
      .frame_width
        + 6.0
    } else {
      0.0
    };
    plot = PlotRect {
      left: frame.x_pt
        + 11.0
        + if legend == Some(ChartLegendPosition::Left) {
          side_band
        } else {
          0.0
        },
      top: frame.y_pt + 11.0 + title_band,
      width: frame.width_pt - 22.0 - side_band,
      height: frame.height_pt - 22.0 - title_band,
    };
  }
  let word_automatic_radial_plot = style.layout_profile == ChartLayoutProfile::Word
    && matches!(legend, None | Some(ChartLegendPosition::Right))
    && !chart.legend_overlay
    && chart.title_layout.is_none()
    && chart.legend_layout.is_none()
    && chart.plot_layout.is_none()
    && matches!(chart.kind, RadialChartKind::Pie | RadialChartKind::Doughnut);
  if word_automatic_radial_plot {
    let title_band = title.map_or(0.0, |_| {
      profiles::WORD_TITLED_RIGHT_RADIAL_PLOT_TOP_PT
        - profiles::WORD_TITLED_RIGHT_RADIAL_PLOT_BOTTOM_PT
    });
    let available_height = (frame.height_pt - title_band).max(0.0);
    let legend_font_size = style.legend.font_size_pt;
    let legend_frame_padding = if legend_frame_has_paint(&style.legend_frame_style) {
      legend_font_size * profiles::WORD_RIGHT_RADIAL_FRAMED_LEGEND_PADDING_EM
    } else {
      profiles::WORD_RIGHT_RADIAL_UNFRAMED_LEGEND_PADDING_PT
    };
    let legend_reservation = if side_legend {
      maximum_side_legend_label_width
        + legend_font_size
          * (profiles::WORD_RIGHT_RADIAL_LEGEND_MARKER_EM
            + profiles::WORD_RIGHT_RADIAL_LEGEND_MARKER_GAP_EM)
        + 2.0 * legend_frame_padding
        + profiles::WORD_RIGHT_RADIAL_PLOT_CENTER_MARGIN_PT
    } else {
      0.0
    };
    let available_width = (frame.width_pt - legend_reservation).max(0.0);
    let side = (available_width.min(available_height)
      - 2.0 * profiles::WORD_TITLED_RIGHT_RADIAL_PLOT_BOTTOM_PT)
      .max(0.0);
    // Word COM places the plot at the chart's interior center after
    // reserving the actual legend frame and a fixed 6pt side margin.
    // Without a title or legend, the same 11pt inset surrounds the largest
    // square fitting the chart. Word COM reports 58.7pt for an 81.5x80.7pt
    // untitled chart, with its center at the physical frame center.
    plot.left = frame.x_pt + (available_width - side) * 0.5;
    plot.top = frame.y_pt + title_band + (available_height - side) * 0.5;
    plot.width = side;
    plot.height = side;
    if !chart.data_labels.is_empty()
      && matches!(
        chart.data_label_default_position,
        None | Some(c::DataLabelPositionValues::BestFit | c::DataLabelPositionValues::OutsideEnd)
      )
    {
      let below_title_height = side + 2.0 * profiles::WORD_TITLED_RIGHT_RADIAL_PLOT_BOTTOM_PT;
      let label_margin = below_title_height * profiles::WORD_RADIAL_AUTOMATIC_LABEL_MARGIN_RATIO;
      plot.left += label_margin;
      plot.top += label_margin;
      plot.width = (plot.width - label_margin * 2.0).max(0.0);
      plot.height = (plot.height - label_margin * 2.0).max(0.0);
    }
  }
  let has_powerpoint_automatic_radial_plot = style.layout_profile == ChartLayoutProfile::PowerPoint
    && chart.plot_layout.is_none()
    && matches!(chart.kind, RadialChartKind::Pie | RadialChartKind::Doughnut);
  if has_powerpoint_automatic_radial_plot {
    // LibreOffice ChartView gives automatic pie diagrams a fixed 3.5 mm
    // four-sided inset and then reduces the diagram to its preferred 1:1
    // aspect. This is intentionally applied after title/legend bands have
    // claimed their space and never overrides an authored manual layout.
    let inset = profiles::POWERPOINT_AUTOMATIC_PIE_FIXED_INSET_PT;
    plot.left += inset;
    plot.top += inset;
    plot.width = (plot.width - inset * 2.0).max(0.0);
    plot.height = (plot.height - inset * 2.0).max(0.0);
    let side = plot.width.min(plot.height);
    plot.left += (plot.width - side) * 0.5;
    plot.top += (plot.height - side) * 0.5;
    plot.width = side;
    plot.height = side;
  } else if let Some(layout) = chart.plot_layout {
    plot = apply_manual_layout(frame, plot, layout);
  }
  if plot.width <= 0.0 || plot.height <= 0.0 {
    return Vec::new();
  }

  let compact_side_legend_plot =
    style.layout_profile == ChartLayoutProfile::PowerPoint && title.is_some() && side_legend;
  let has_best_fit_data_labels = chart
    .data_labels
    .iter()
    .any(|label| label.position == c::DataLabelPositionValues::BestFit);
  let compact_label_fit_plot = style.layout_profile == ChartLayoutProfile::Excel
    && title.is_some()
    && bottom_legend
    && has_best_fit_data_labels;
  let radius_scale = if word_automatic_radial_plot || has_powerpoint_automatic_radial_plot {
    0.5
  } else if compact_side_legend_plot || compact_label_fit_plot {
    host_defaults.compact_radius_scale
  } else if style.layout_profile == ChartLayoutProfile::Excel && title.is_some() && bottom_legend {
    // Excel's ordinary titled bottom-legend pie keeps the larger automatic
    // plot. The smaller compact profile belongs to visible best-fit labels,
    // whose complete boxes must be rearranged inside the sectors; a c:dLbls
    // container with every show flag disabled does not reserve that region.
    host_defaults.titled_bottom_legend_radius_scale
  } else {
    host_defaults.radius_scale
  };
  let hole_ratio = (chart.hole_size_percent / 100.0).clamp(0.0, 0.9) as f32;
  // Excel keeps a circular 2-D pie inside the plot height. PowerPoint and
  // Word use a 4:3-expanded height basis.
  let radius_basis = plot
    .width
    .min(plot.height * host_defaults.radius_height_basis_scale);
  let powerpoint_pie_3d = (chart.kind == RadialChartKind::Pie3D
    && style.layout_profile == ChartLayoutProfile::PowerPoint)
    .then_some(profiles::POWERPOINT_PIE_3D_PROJECTION);
  let view_3d = chart.view_3d.unwrap_or_default();
  // Automatic pies reserve the same fixed host margin before realizing
  // their 3-D viewport. Unlike a 2-D pie, this viewport need not be square.
  let camera_viewport_height = powerpoint_pie_3d.map(|_| {
    let inset = if chart.plot_layout.is_none() {
      profiles::POWERPOINT_AUTOMATIC_PIE_FIXED_INSET_PT
    } else {
      0.0
    };
    (plot.height - inset * 2.0).max(f32::EPSILON)
  });
  let maximum_explosion = chart
    .point_explosion_percent
    .iter()
    .copied()
    .flatten()
    .fold(chart.series_explosion_percent, f64::max)
    .clamp(0.0, 100.0) as f32
    / 100.0;
  let scene_fit_scale = powerpoint_pie_3d.map_or(1.0, |profile| {
    1.0 / (1.0 + maximum_explosion * profile.explosion_scale)
  });
  let exploded_geometry_scale = powerpoint_pie_3d.map_or(1.0, |profile| {
    if maximum_explosion > f32::EPSILON {
      profile.exploded_geometry_scale
    } else {
      1.0
    }
  });
  let projected_scene_scale = scene_fit_scale * exploded_geometry_scale;
  let unfitted_depth = if let Some(profile) = powerpoint_pie_3d {
    let rotation_scale = (view_3d.rotate_x_deg.to_radians().cos() / 30.0_f32.to_radians().cos())
      .abs()
      .clamp(0.25, 2.0);
    plot.height
      * profile.depth_height_scale
      * (view_3d.height_percent / 100.0).clamp(0.05, 5.0)
      * rotation_scale
  } else if chart.kind == RadialChartKind::Pie3D {
    plot.height * 0.09
  } else {
    0.0
  };
  let fixed_inner_radii = excel_fixed_inner_pie_3d_radii(
    chart.kind,
    style.layout_profile,
    chart.plot_layout,
    plot,
    unfitted_depth,
  );
  let radius_x = if let Some((radius_x, _)) = fixed_inner_radii {
    radius_x
  } else if let Some(profile) = powerpoint_pie_3d {
    radius_basis * profile.radius_x_scale * projected_scene_scale
  } else {
    radius_basis * radius_scale
  };
  let radius_y = if let Some((_, radius_y)) = fixed_inner_radii {
    radius_y
  } else if let Some(profile) = powerpoint_pie_3d {
    radius_x
      * view_3d
        .rotate_x_deg
        .abs()
        .to_radians()
        .sin()
        .clamp(0.05, 1.0)
      * profile.vertical_tilt_scale
  } else if chart.kind == RadialChartKind::Pie3D {
    radius_x * 0.62
  } else {
    radius_x
  };
  let depth = unfitted_depth * projected_scene_scale;
  let center_x = plot.left + plot.width * 0.5;
  let center_y = plot.top
    + (plot.height - unfitted_depth) * 0.5
    + powerpoint_pie_3d.map_or(0.0, |profile| {
      plot.height * profile.center_y_offset_height_ratio
        + if maximum_explosion > f32::EPSILON {
          plot.height * profile.exploded_center_y_offset_height_ratio
        } else {
          0.0
        }
    });
  let word_physical_pie = word_pie_3d_layout
    || (style.layout_profile == ChartLayoutProfile::Word
      && chart.kind == RadialChartKind::Pie3D
      && chart
        .plot_layout
        .is_some_and(|layout| layout.targets_inner_plot));
  let word_pie_projection = word_physical_pie.then(|| {
    if maximum_explosion <= f32::EPSILON {
      word_pie_3d_projection(plot, view_3d)
    } else {
      word_exploded_pie_3d_projection(plot, view_3d, maximum_explosion)
    }
  });
  let (radius_x, radius_y, center_x, center_y) =
    word_pie_projection.map_or((radius_x, radius_y, center_x, center_y), |projection| {
      (
        projection.radii.0,
        projection.radii.1,
        projection.conic_center.0,
        projection.conic_center.1,
      )
    });
  let mut items = Vec::new();
  push_chart_shape_rect(
    &mut items,
    PlotRect {
      left: frame.x_pt,
      top: frame.y_pt,
      width: frame.width_pt,
      height: frame.height_pt,
    },
    ChartShapePaint {
      fill: Some(&style.chart_area_style.fill),
      stroke: Some(&style.chart_area_style.stroke),
      fallback_fill_color: None,
      stroke_width_scale: 1.0,
    },
  );
  push_chart_shape_rect(
    &mut items,
    plot,
    ChartShapePaint {
      fill: Some(&style.plot_area_style.fill),
      stroke: Some(&style.plot_area_style.stroke),
      fallback_fill_color: None,
      stroke_width_scale: 1.0,
    },
  );
  let mut start_angle = chart.first_slice_angle_deg.to_radians() as f32;
  let point_start = items.len();
  let mut point_backdrops = Vec::new();

  if matches!(
    chart.kind,
    RadialChartKind::PieOfPie | RadialChartKind::BarOfPie
  ) && !chart.secondary_indices.is_empty()
  {
    lower_of_pie_geometry(&mut items, &mut point_backdrops, plot, chart, style);
  } else {
    let mut slices = Vec::new();
    for (index, value) in chart.values.iter().enumerate() {
      let Some(value) = value
        .as_ref()
        .copied()
        .filter(|value| value.is_finite() && *value > 0.0)
      else {
        continue;
      };
      let sweep = (value / total * std::f64::consts::TAU) as f32;
      let mid = start_angle + sweep * 0.5;
      let explosion = (chart
        .point_explosion_percent
        .get(index)
        .copied()
        .flatten()
        .unwrap_or(chart.series_explosion_percent)
        / 100.0)
        .clamp(0.0, 1.0) as f32;
      // Excel interprets c:explosion as approximately the percentage of the
      // pie radius. The host profile retains its smaller Word/PowerPoint
      // displacement policy.
      let explosion_scale = if word_physical_pie {
        1.0
      } else {
        powerpoint_pie_3d.map_or(host_defaults.explosion_scale, |profile| {
          profile.explosion_scale
        })
      };
      let perspective_plane_offset = if powerpoint_pie_3d.is_some() || word_physical_pie {
        (
          mid.sin() * explosion * explosion_scale / exploded_geometry_scale,
          -mid.cos() * explosion * explosion_scale / exploded_geometry_scale,
        )
      } else {
        (0.0, 0.0)
      };
      let offset_x = if powerpoint_pie_3d.is_some() || word_physical_pie {
        0.0
      } else {
        mid.sin() * radius_x * explosion * explosion_scale
      };
      let offset_y = if powerpoint_pie_3d.is_some() || word_physical_pie {
        0.0
      } else {
        -mid.cos() * radius_y * explosion * explosion_scale
      };
      let color = style.point_colors[index % style.point_colors.len()];
      slices.push(RadialSlice {
        index,
        center: (center_x + offset_x, center_y + offset_y),
        perspective_plane_offset,
        start_angle,
        sweep,
        explosion,
        color,
      });
      start_angle += sweep;
    }
    let outlined_scene = word_pie_projection
      .and_then(|projection| word_pie_scene::lower(&slices, style, projection, view_3d, plot));
    if let Some(image) = outlined_scene {
      items.push(PageItem::Image(image));
    } else {
      // A 3-D pie is one extruded scene. Paint every side face before any top
      // face; interleaving a translated full sector with its top lets a later
      // sector's side overwrite an earlier top and creates false translucent
      // wedges through the centre. LibreOffice likewise creates independent
      // 3-D extrusions and leaves face visibility to the scene painter.
      if depth > 0.0 {
        let mut word_side_faces = Vec::new();
        for slice in &slices {
          if slice.explosion <= f32::EPSILON {
            continue;
          }
          let side_start = items.len();
          let projection = word_pie_projection
            .map(|projection| projection.with_plane_offset(slice.perspective_plane_offset))
            .unwrap_or_else(|| {
              RadialPerspectiveProjection::new(
                slice.center,
                (radius_x, radius_y),
                view_3d,
                camera_viewport_height,
              )
              .with_plane_offset(slice.perspective_plane_offset)
              .with_extrusion_thickness(
                powerpoint_pie_3d.map_or(0.0, |profile| {
                  profile.thickness_radius_ratio * view_3d.height_percent / 100.0
                }),
                view_3d.rotate_x_deg,
              )
            });
          let word_stroke = word_pie_projection.and_then(|_| {
            word_pie_3d_point_stroke(style.point_styles.get(slice.index), projection)
          });
          // A separated extrusion exposes only the radial cut plane whose
          // outward normal faces the camera. Painting a translated complete
          // sector here would invent a triangular underside beyond the slice
          // hub, most visibly on the back green and purple points.
          if slice.start_angle.sin() < -f32::EPSILON {
            let mut face = radial_3d_cut_face_path(
              projection,
              depth,
              slice.start_angle,
              slice.color,
              word_pie_projection.map(|_| view_3d.rotate_x_deg),
            );
            push_word_pie_cut_face(&mut items, &mut face, word_stroke.clone());
          }
          let end_angle = slice.start_angle + slice.sweep;
          if end_angle.sin() > f32::EPSILON {
            let mut face = radial_3d_cut_face_path(
              projection,
              depth,
              end_angle,
              slice.color,
              word_pie_projection.map(|_| view_3d.rotate_x_deg),
            );
            push_word_pie_cut_face(&mut items, &mut face, word_stroke.clone());
          }
          if word_physical_pie {
            word_side_faces.push((
              -(slice.start_angle + slice.sweep * 0.5).cos(),
              items.split_off(side_start),
            ));
          }
        }
        for slice in &slices {
          let side_start = items.len();
          let projection = word_pie_projection
            .map(|projection| projection.with_plane_offset(slice.perspective_plane_offset))
            .unwrap_or_else(|| {
              RadialPerspectiveProjection::new(
                slice.center,
                (radius_x, radius_y),
                view_3d,
                camera_viewport_height,
              )
              .with_plane_offset(slice.perspective_plane_offset)
              .with_extrusion_thickness(
                powerpoint_pie_3d.map_or(0.0, |profile| {
                  profile.thickness_radius_ratio * view_3d.height_percent / 100.0
                }),
                view_3d.rotate_x_deg,
              )
            });
          items.extend(radial_3d_outer_wall_paths(
            projection,
            depth,
            (slice.start_angle, slice.sweep),
            slice.color,
            projection.horizontal_bounds(),
            RadialWallStyle {
              word_elevation: word_pie_projection.map(|_| view_3d.rotate_x_deg),
              word_stroke: word_pie_projection.and_then(|_| {
                word_pie_3d_point_stroke(style.point_styles.get(slice.index), projection)
              }),
              outlined_cuts: slice.explosion > f32::EPSILON,
            },
          ));
          if word_physical_pie {
            word_side_faces.push((
              -(slice.start_angle + slice.sweep * 0.5).cos(),
              items.split_off(side_start),
            ));
          }
        }
        if word_physical_pie {
          // Separated sectors expose overlapping side faces on both halves
          // of the pie. Source order is angular, not camera depth: on the
          // left half it puts rear yellow/magenta cut planes over the nearer
          // blue/lavender cuts. Resolve complete side faces back to front.
          // All caps share one plane and remain above this side-face pass.
          word_side_faces.sort_by(|a, b| a.0.total_cmp(&b.0));
          for (_, faces) in word_side_faces {
            items.extend(faces);
          }
        }
      }
      for slice in slices {
        // The signed top-plane conic reverses when the eye is below that
        // plane (notably a zero-elevation pie). Its cap is then back-facing.
        if word_pie_projection.is_some_and(|projection| projection.radii.1 <= 0.0) {
          continue;
        }
        let cap_start = items.len();
        push_radial_point_with_effects(
          &mut items,
          &mut point_backdrops,
          light_word_pie_cap(
            radial_segment_path(RadialSegmentSpec {
              center: slice.center,
              radii: (radius_x, radius_y),
              hole_ratio,
              angles: (slice.start_angle, slice.sweep),
              paint: (slice.color, 1.0),
              fallback_stroke: (chart.kind != RadialChartKind::Pie3D).then_some((
                RgbColor {
                  r: 255,
                  g: 255,
                  b: 255,
                },
                0.75,
              )),
              style: style.point_styles.get(slice.index),
              perspective: (chart.kind == RadialChartKind::Pie3D).then(|| {
                word_pie_projection
                  .map(|projection| projection.with_plane_offset(slice.perspective_plane_offset))
                  .unwrap_or_else(|| {
                    RadialPerspectiveProjection::new(
                      slice.center,
                      (radius_x, radius_y),
                      view_3d,
                      camera_viewport_height,
                    )
                    .with_plane_offset(slice.perspective_plane_offset)
                  })
              }),
            }),
            word_pie_projection.map(|_| view_3d.rotate_x_deg),
            word_pie_projection,
          ),
          style
            .point_image_effects
            .get(slice.index)
            .and_then(Option::as_ref),
        );
        if let Some(projection) = word_pie_projection {
          resolve_word_pie_cap_outline_visibility(
            &mut items,
            cap_start,
            (slice.start_angle, slice.sweep),
            projection.with_plane_offset(slice.perspective_plane_offset),
          );
        }
      }
    }
  }

  if word_pie_projection.is_some()
    && let Some(scene) = cartesian_3d_scene_image(
      &items[point_start..],
      Some(common_rect(plot.left, plot.top, plot.width, plot.height)),
      style.fixed_output_raster_dpi,
    )
  {
    // Word's Cartesian and pie controls share the same fixed-output canvas
    // and bitmap allocation. Resolve adjacent faces together, retaining
    // title and legend text as vectors outside the 3-D scene.
    items.truncate(point_start);
    items.push(PageItem::Image(scene));
  } else if powerpoint_pie_3d.is_some()
    && let Some(scene) = radial_3d_scene_image(&items[point_start..])
  {
    items.truncate(point_start);
    items.push(PageItem::Image(scene));
  }

  // Adjacent sectors share their visible foreground. Their shadows belong
  // behind every sector, not between sectors where they darken the next face.
  items.splice(point_start..point_start, point_backdrops);

  for (label_index, label) in chart.data_labels.iter().enumerate() {
    let before = chart
      .values
      .iter()
      .take(label.point_index)
      .flatten()
      .filter(|value| value.is_finite() && **value > 0.0)
      .sum::<f64>();
    let Some(value) = chart
      .values
      .get(label.point_index)
      .copied()
      .flatten()
      .filter(|value| value.is_finite() && *value >= 0.0)
    else {
      continue;
    };
    let angle = chart.first_slice_angle_deg.to_radians() as f32
      + ((before + value * 0.5) / total * std::f64::consts::TAU) as f32;
    let outside = matches!(
      label.position,
      c::DataLabelPositionValues::OutsideEnd
        | c::DataLabelPositionValues::Left
        | c::DataLabelPositionValues::Right
    );
    let data_label_style = style
      .data_label_styles
      .get(label_index)
      .and_then(Option::as_ref)
      .unwrap_or(&style.data_label);
    let rich_text_styles = style
      .data_label_rich_text_styles
      .get(label_index)
      .map(Vec::as_slice)
      .unwrap_or_default();
    let mut text_frame = resolved_radial_data_label_text_frame(frame, label);
    let label_insets = chart_data_label_insets_with_fallback(
      label.text_body_properties,
      chart
        .data_label_text_properties
        .map(|properties| properties.body_properties.as_ref()),
      style.layout_profile == ChartLayoutProfile::Word,
    );
    if style.layout_profile == ChartLayoutProfile::Word
      && (label.layout.is_some()
        || (word_physical_pie && label.position == c::DataLabelPositionValues::OutsideEnd))
      && !label.rich_text_runs.is_empty()
    {
      // Word's custom pie labels use the chart-space width/5 as an OUTER
      // limit. COM controls give 3pt horizontal and 1.5pt vertical padding,
      // even when a:bodyPr is empty. Retain explicit c15 dimensions.
      text_frame.word_line_metrics = true;
      text_frame.insets = label_insets;
      if label.text_body_properties.and_then(|body| body.wrap) != Some(a::TextWrappingValues::None)
        && text_frame.outer_width.is_none()
      {
        text_frame.maximum_inner_width =
          Some((frame.width_pt / 5.0 - label_insets.left - label_insets.right).max(0.0));
      }
      let lines = data_label_rich_text_lines(
        &mut metrics,
        label,
        data_label_style,
        rich_text_styles,
        text_frame,
      );
      let content_width = lines.iter().map(|line| line.width).fold(0.0_f32, f32::max);
      let content_height: f32 = lines.iter().map(|line| line.height).sum();
      text_frame
        .outer_width
        .get_or_insert(content_width + label_insets.left + label_insets.right);
      text_frame
        .outer_height
        .get_or_insert(content_height + label_insets.top + label_insets.bottom);
    }
    let mut text_box = data_label_text_box(
      &mut metrics,
      label,
      data_label_style,
      rich_text_styles,
      text_frame,
    );
    if word_automatic_radial_plot
      && label.position == c::DataLabelPositionValues::Center
      && text_frame.outer_height.is_none()
      && data_label_style.rotation_deg.abs() <= f32::EPSILON
    {
      // The natural Word label line is taller than the generic chart line.
      // Keep the center anchor and the authored c:dLbls insets; only the
      // natural line-box height differs.
      text_box.height += data_label_style.font_size_pt
        * (profiles::WORD_RADIAL_CENTER_LABEL_LINE_HEIGHT_EM - TEXT_LINE_HEIGHT_SCALE);
    }
    let (width, label_height) = (text_box.width, text_box.height);
    let text_body_insets = chart_text_body_insets(label.text_body_properties);
    let mut best_fit_outside = false;
    let label_explosion = (chart
      .point_explosion_percent
      .get(label.point_index)
      .copied()
      .flatten()
      .unwrap_or(chart.series_explosion_percent)
      / 100.0)
      .clamp(0.0, 1.0) as f32;
    let word_outside_projection = word_pie_projection.filter(|_| {
      label.layout.is_some() || label.position == c::DataLabelPositionValues::OutsideEnd
    });
    let (label_x, label_y) = if let Some(projection) = word_outside_projection {
      best_fit_outside = true;
      word_pie_3d_outside_label_position(projection, angle, label_explosion, (width, label_height))
    } else if chart.kind == RadialChartKind::Pie
      && label.position == c::DataLabelPositionValues::BestFit
      && style.layout_profile == ChartLayoutProfile::Excel
    {
      excel_best_fit_pie_label_position(
        (center_x, center_y),
        (radius_x, radius_y),
        (angle, value / total * std::f64::consts::TAU),
        (width, label_height),
      )
    } else if chart.kind == RadialChartKind::Pie
      && label.position == c::DataLabelPositionValues::BestFit
      && style.layout_profile == ChartLayoutProfile::PowerPoint
    {
      let outer_width = if text_frame.is_fully_sized() {
        width
      } else {
        width + text_body_insets.left + text_body_insets.right
      };
      let outer_height = if text_frame.is_fully_sized() {
        label_height
      } else {
        label_height + text_body_insets.top + text_body_insets.bottom
      };
      pie_best_fit_label_position(
        (center_x, center_y),
        (radius_x, radius_y),
        (angle, value / total * std::f64::consts::TAU),
        (outer_width, outer_height),
        !label.rich_text_runs.is_empty()
          || label.text_components.len() > 1
          || text_frame.is_fully_sized(),
        0.975,
      )
      .map(|(x, y)| {
        if text_frame.is_fully_sized() {
          (x, y)
        } else {
          (x + text_body_insets.left, y + text_body_insets.top)
        }
      })
      .unwrap_or_else(|| {
        best_fit_outside = true;
        let outer_origin = outside_radial_label_position(
          (center_x, center_y),
          (radius_x, radius_y),
          angle,
          (outer_width, outer_height),
        );
        if text_frame.is_fully_sized() {
          outer_origin
        } else {
          (
            outer_origin.0 + text_body_insets.left,
            outer_origin.1 + text_body_insets.top,
          )
        }
      })
    } else if chart.kind == RadialChartKind::Pie
      && label.position == c::DataLabelPositionValues::BestFit
      && style.layout_profile == ChartLayoutProfile::Word
      && label.layout.is_none()
    {
      let outer_width = width + label_insets.left + label_insets.right;
      let outer_height = label_height + label_insets.top + label_insets.bottom;
      // Word's automatic best-fit label seeks the sector edge while keeping
      // the complete painted label box inside the slice. Its custom-label
      // rectangle uses the group-level c:dLbls text insets when an individual
      // c:tx/c:rich bodyPr leaves those four attributes unspecified.
      pie_best_fit_label_position(
        (center_x, center_y),
        (radius_x, radius_y),
        (angle, value / total * std::f64::consts::TAU),
        (outer_width, outer_height),
        true,
        f64::from(
          (radius_x.min(radius_y) - profiles::WORD_PIE_BEST_FIT_ARC_INSET_PT)
            / radius_x.min(radius_y),
        ),
      )
      .map(|(x, y)| (x + label_insets.left, y + label_insets.top))
      .unwrap_or_else(|| {
        best_fit_outside = true;
        let (x, y) = outside_radial_label_position(
          (center_x, center_y),
          (radius_x, radius_y),
          angle,
          (outer_width, outer_height),
        );
        (x + label_insets.left, y + label_insets.top)
      })
    } else if label.position == c::DataLabelPositionValues::OutsideEnd {
      outside_radial_label_position(
        (center_x, center_y),
        (radius_x, radius_y),
        angle,
        (width, label_height),
      )
    } else {
      let ring = if outside {
        1.08
      } else {
        (1.0 + hole_ratio) * 0.5
      };
      (
        center_x + angle.sin() * radius_x * ring - width * 0.5,
        center_y - angle.cos() * radius_y * ring - label_height * 0.5,
      )
    };
    let (mut label_x, mut label_y) = label.layout.map_or((label_x, label_y), |layout| {
      let bounds = apply_manual_text_layout(
        frame,
        PlotRect {
          left: label_x,
          top: label_y,
          width,
          height: label_height,
        },
        layout,
      );
      (bounds.left, bounds.top)
    });
    if word_automatic_radial_plot
      && chart.kind == RadialChartKind::Pie
      && label.position == c::DataLabelPositionValues::BestFit
      && label.layout.is_none()
    {
      let grid = profiles::WORD_RADIAL_BEST_FIT_LABEL_GRID_PT;
      // Word's 41-width COM sweep changes this edge-seeking label's 0.75pt
      // column only after one 600-DPI printer dot of horizontal clearance.
      // Keep that dot on the side facing the pie center before grid selection;
      // its vertical placement has an independent grid phase.
      let outer_center_x = label_x + (width + label_insets.right - label_insets.left) * 0.5;
      let guard = crate::units::POINTS_PER_INCH / crate::units::OFFICE_FIXED_OUTPUT_DPI;
      let guarded_x = if outer_center_x >= center_x {
        label_x - guard
      } else {
        label_x + guard
      };
      label_x = ((guarded_x - label_insets.left) / grid).round() * grid + label_insets.left;
      label_y = ((label_y - label_insets.top) / grid).round() * grid + label_insets.top;
    }
    let leader_start = word_outside_projection.map_or_else(
      || {
        (
          center_x + angle.sin() * radius_x,
          center_y - angle.cos() * radius_y,
        )
      },
      |projection| {
        // The connector touches the actual smooth, exploded scene, unlike
        // the legacy integer model used to position the automatic label.
        let (u, cosine) = angle.sin_cos();
        let projection =
          projection.with_plane_offset((u * label_explosion, -cosine * label_explosion));
        if cosine < 0.0 {
          projection.project_bottom_point(u, -cosine, 0.0)
        } else {
          projection.project_plane_point(u, -cosine)
        }
      },
    );
    let word_leader = if word_outside_projection.is_some()
      && !label.rich_text_runs.is_empty()
      && data_label_style.rotation_deg.abs() <= f32::EPSILON
    {
      let lines = data_label_rich_text_lines(
        &mut metrics,
        label,
        data_label_style,
        rich_text_styles,
        text_frame,
      );
      word_pie_rich_label_leader(
        leader_start,
        PlotRect {
          // Native leader attachment geometry retains a 0.75pt chart-edge
          // guard. The text box itself can touch the chart frame. Controls
          // hitting the left/right edge expose this separate clamp.
          left: label_x.clamp(
            frame.x_pt + 0.75,
            (frame.x_pt + frame.width_pt - width - 0.75).max(frame.x_pt + 0.75),
          ),
          top: label_y.clamp(
            frame.y_pt + 0.75,
            (frame.y_pt + frame.height_pt - label_height - 0.75).max(frame.y_pt + 0.75),
          ),
          width,
          height: label_height,
        },
        &lines,
        rich_text_styles,
        data_label_style,
        text_frame.insets,
        &mut metrics,
      )
    } else {
      None
    };
    let leader_end = word_leader.map_or(
      (
        leader_start.0.clamp(label_x, label_x + width),
        leader_start.1.clamp(label_y, label_y + label_height),
      ),
      |points| points[2],
    );
    let leader_edge_distance =
      (leader_start.0 - center_x).powi(2) + (leader_start.1 - center_y).powi(2);
    let leader_label_distance =
      (leader_end.0 - center_x).powi(2) + (leader_end.1 - center_y).powi(2);
    let leader_length = (leader_end.0 - leader_start.0).hypot(leader_end.1 - leader_start.1);
    // LibreOffice PieChart::createTextLabelShape connects the sector edge to
    // the closest point of a custom label rectangle.  It deliberately omits
    // the line when a manual label has been moved inside the pie and when the
    // remaining segment is less than one percent of the chart diagonal.
    let label_is_outside_pie = leader_label_distance > leader_edge_distance + f32::EPSILON;
    let leader_is_visible = leader_length >= frame.width_pt.hypot(frame.height_pt) * 0.01;
    if chart.show_leader_lines
      && label_is_outside_pie
      && leader_is_visible
      && (outside || best_fit_outside || label.layout.is_some())
    {
      if let Some(points) = word_leader {
        push_chart_styled_polyline(
          &mut items,
          &points,
          Some(&style.leader_line_style.stroke),
          style.data_label.color,
          0.75,
          1.0,
          false,
        );
        if let Some(PageItem::Path(path)) = items.last_mut()
          && let Some(stroke) = path.stroke.as_mut()
        {
          stroke.join.get_or_insert(crate::common::StrokeJoin::Round);
        }
      } else {
        push_chart_styled_line(
          &mut items,
          leader_start,
          leader_end,
          Some(&style.leader_line_style.stroke),
          style.data_label.color,
          0.75,
          1.0,
        );
      }
    }
    if let Some(shape_style) = style
      .data_label_shape_styles
      .get(label_index)
      .and_then(Option::as_ref)
    {
      let insets = label_insets;
      let start = items.len();
      push_chart_shape_rect(
        &mut items,
        PlotRect {
          left: label_x - insets.left,
          top: label_y - insets.top,
          width: width + insets.left + insets.right,
          height: label_height + insets.top + insets.bottom,
        },
        ChartShapePaint {
          fill: Some(&shape_style.fill),
          stroke: Some(&shape_style.stroke),
          fallback_fill_color: None,
          stroke_width_scale: 1.0,
        },
      );
      if items.len() > start
        && let Some(PageItem::Path(path)) = items.pop()
        && !push_chart_shape_effect_raster(
          &mut items,
          &path,
          style
            .data_label_image_effects
            .get(label_index)
            .and_then(Option::as_ref),
          None,
          None,
          None,
          true,
        )
      {
        items.push(PageItem::Path(path));
      }
    } else if let Some(fill_color) = style
      .data_label_fill_colors
      .get(label_index)
      .copied()
      .flatten()
    {
      let horizontal_padding = data_label_style.font_size_pt * 0.3;
      let vertical_padding = data_label_style.font_size_pt * 0.4;
      items.push(PageItem::Rect(RectItem {
        x_pt: label_x - horizontal_padding,
        y_pt: label_y - vertical_padding,
        width_pt: width + horizontal_padding * 2.0,
        height_pt: label_height + vertical_padding * 2.0,
        fill_color: Some(fill_color),
        fill_opacity: 1.0,
        stroke: None,
        stroke_opacity: 1.0,
      }));
    }
    let mut text_origin = text_box.text_origin((label_x, label_y));
    if word_automatic_radial_plot {
      text_origin.1 +=
        data_label_style.font_size_pt * profiles::WORD_RADIAL_DATA_LABEL_BASELINE_OFFSET_EM;
    }
    push_data_label_text_components(
      &mut items,
      &mut metrics,
      DataLabelTextLayout {
        origin: text_origin,
        label,
        style: data_label_style,
        rich_text_styles,
        text_frame,
        align_rich_runs_on_baseline: false,
      },
    );
  }

  if let Some(title) = title {
    let mut title_style = style.title.clone();
    title_style.rotation_deg += chart.title_rotation_deg;
    if style.layout_profile == ChartLayoutProfile::Excel
      && chart.title_rotation_deg.abs() > f32::EPSILON
    {
      title_style.pdf_glyph_outlines = true;
      let mut options = title_style
        .pdf_glyph_outline_options
        .as_deref()
        .cloned()
        .unwrap_or_default();
      options.semantic_text_overlay = false;
      title_style.pdf_glyph_outline_options = Some(Arc::new(options));
    }
    let manual_word_title = style.layout_profile == ChartLayoutProfile::Word
      && chart.title_layout.is_some()
      && title_style.rotation_deg.abs() <= f32::EPSILON;
    let title_insets = if manual_word_title {
      chart_data_label_insets_with_fallback(chart.title_text_body_properties, None, true)
    } else {
      ChartTextBodyInsets::default()
    };
    let width = if manual_word_title {
      word_chart_tick_label_width(title, &title_style, &mut metrics)
        + title_insets.left
        + title_insets.right
    } else {
      metrics.measure_text(title, &title_style)
    };
    let automatic = PlotRect {
      left: frame.x_pt + (frame.width_pt - width) * 0.5,
      top: frame.y_pt
        + if (word_automatic_radial_plot || word_pie_3d_layout) && chart.title_layout.is_none() {
          profiles::WORD_TITLED_RIGHT_RADIAL_TITLE_TEXT_TOP_PT
        } else {
          frame.height_pt * profiles::RADIAL_TITLE_TOP_RATIO
        }
        + if style.layout_profile == ChartLayoutProfile::Excel && bottom_legend {
          title_style.font_size_pt * profiles::EXCEL_BOTTOM_LEGEND_TITLE_OFFSET_EM
        } else {
          0.0
        },
      width,
      height: if manual_word_title {
        word_chart_natural_line_height(metrics.vertical_metrics_for_text(title, &title_style))
          + title_insets.top
          + title_insets.bottom
      } else {
        line_height(&title_style)
      },
    };
    let bounds = chart.title_layout.map_or(automatic, |layout| {
      apply_manual_text_layout(frame, automatic, layout)
    });
    let baseline_adjustment = if manual_word_title {
      word_chart_text_baseline_adjustment(&mut metrics, title, &title_style)
    } else {
      0.0
    };
    push_text(
      &mut items,
      bounds.left + title_insets.left,
      bounds.top + title_insets.top + baseline_adjustment,
      title.to_string(),
      title_style,
    );
  }
  lower_radial_legend(
    &mut items,
    frame,
    chart,
    style,
    &mut metrics,
    RadialLegendPlacement {
      side_width: legend_width,
      horizontal_height: legend_height,
      word_auto_side_center_y: word_automatic_radial_plot.then_some(plot.top + plot.height * 0.5),
      word_pie_3d_title_band,
    },
  );
  items
}

fn excel_fixed_inner_pie_3d_radii(
  kind: RadialChartKind,
  profile: ChartLayoutProfile,
  layout: Option<crate::render::chart::ChartManualLayout>,
  plot: PlotRect,
  depth: f32,
) -> Option<(f32, f32)> {
  (kind == RadialChartKind::Pie3D
    && profile == ChartLayoutProfile::Excel
    && layout.is_some_and(|layout| layout.targets_inner_plot))
  .then(|| {
    // ECMA-376 Part 1 section 21.2.2.89 defines an inner layout as the
    // authored plot-area rectangle. LibreOffice's PlotAreaConverter maps it
    // to setDiagramPositionExcludingAxes, and ChartView deliberately skips
    // its automatic minimum-size reduction for fixed inner diagrams. Use the
    // complete rectangle for the 3-D pie body instead of applying the
    // automatic Excel radius profile a second time. The top ellipse occupies
    // height - depth and the side wall completes the authored height.
    (plot.width * 0.5, (plot.height - depth).max(0.0) * 0.5)
  })
}

fn excel_best_fit_pie_label_position(
  center: (f32, f32),
  radii: (f32, f32),
  angles: (f32, f64),
  label_size: (f32, f32),
) -> (f32, f32) {
  let (angle, sweep) = angles;
  let sweep_degrees = sweep.to_degrees() as f32;
  // Excel's best-fit position is not the fixed half-radius "center"
  // position. It moves the complete label box toward the slice boundary and
  // may rotate the anchor away from the bisector so every corner remains in
  // the sector. These three continuous regions correspond to narrow,
  // ordinary, and reflex sectors in the Office fixed-output layout.
  let profile = if sweep_degrees > 180.0 {
    profiles::EXCEL_REFLEX_BEST_FIT_LABEL
  } else if sweep_degrees > 75.0 {
    profiles::EXCEL_ORDINARY_BEST_FIT_LABEL
  } else {
    profiles::EXCEL_NARROW_BEST_FIT_LABEL
  };
  let adjusted_angle = angle + profile.angle_adjustment_degrees.to_radians();
  let (width, height) = label_size;
  (
    center.0 + adjusted_angle.sin() * radii.0 * profile.radius_factor - width * 0.5,
    center.1 - adjusted_angle.cos() * radii.1 * profile.radius_factor - height * 0.5,
  )
}

fn pie_best_fit_label_position(
  center: (f32, f32),
  radii: (f32, f32),
  angles: (f32, f64),
  label_size: (f32, f32),
  seek_outer_edge: bool,
  usable_radius_factor: f64,
) -> Option<(f32, f32)> {
  let (clockwise_from_top, sweep) = angles;
  let radius_x = f64::from(radii.0);
  let radius_y = f64::from(radii.1);
  if label_size.0 <= 0.0
    || label_size.1 <= 0.0
    || radius_x <= 0.0
    || radius_y <= 0.0
    || sweep <= 0.0
  {
    return None;
  }

  let angle = f64::from(clockwise_from_top);
  let initial_center = [angle.sin() * 0.5, angle.cos() * 0.5];
  if sweep > std::f64::consts::PI && !seek_outer_edge {
    return Some((
      center.0 + (initial_center[0] * radius_x) as f32 - label_size.0 * 0.5,
      center.1 - (initial_center[1] * radius_y) as f32 - label_size.1 * 0.5,
    ));
  }

  // `bestFit` starts at PowerPoint's ordinary centered label position. Move
  // that complete rectangle by the minimum Euclidean distance needed to keep
  // every corner inside both radial boundaries and the pie circle. This uses
  // the same rectangle/sector/circle constraints as LibreOffice
  // PieChart::performLabelBestFitInnerPlacement, but not LibreOffice's
  // incompatible choice to push every accepted rectangle all the way to the
  // arc. The immutable percentage-number-formats.pptx Office output is the
  // counterexample: its narrow label remains near the half-radius position.
  #[derive(Clone, Copy)]
  enum Constraint {
    HalfPlane { normal: [f64; 2], minimum: f64 },
    Circle { corner: [f64; 2], radius: f64 },
  }

  let half_width = f64::from(label_size.0) * 0.5 / radius_x;
  let half_height = f64::from(label_size.1) * 0.5 / radius_y;
  if seek_outer_edge
    && f64::from(label_size.0).hypot(f64::from(label_size.1))
      > radius_x.min(radius_y) * usable_radius_factor
  {
    // PieChart::performLabelBestFitInnerPlacement rejects an inner label
    // when its full nearest-to-farthest box diagonal exceeds the usable pie
    // radius. This deliberately conservative test sends the large fixed
    // c15 frames in tdf146487 to the source-defined outside placement.
    return None;
  }
  let corners = [
    [-half_width, -half_height],
    [-half_width, half_height],
    [half_width, -half_height],
    [half_width, half_height],
  ];
  if seek_outer_edge && sweep > std::f64::consts::PI {
    let direction = [angle.sin(), angle.cos()];
    let mut upper = f64::INFINITY;
    for corner in corners {
      let projection = direction[0] * corner[0] + direction[1] * corner[1];
      let discriminant = projection * projection
        - (corner[0] * corner[0] + corner[1] * corner[1] - usable_radius_factor.powi(2));
      if discriminant < 0.0 {
        return None;
      }
      upper = upper.min(-projection + discriminant.sqrt());
    }
    if upper.is_finite() && upper >= 0.0 {
      return Some((
        center.0 + (direction[0] * upper * radius_x) as f32 - label_size.0 * 0.5,
        center.1 - (direction[1] * upper * radius_y) as f32 - label_size.1 * 0.5,
      ));
    }
    return None;
  }
  let alpha = std::f64::consts::FRAC_PI_2 - angle;
  let half_sweep = sweep * 0.5;
  let lower = alpha - half_sweep;
  let upper = alpha + half_sweep;
  let lower_normal = [-lower.sin(), lower.cos()];
  let upper_normal = [upper.sin(), -upper.cos()];
  let mut constraints = Vec::with_capacity(12);
  for corner in corners {
    constraints.push(Constraint::HalfPlane {
      normal: lower_normal,
      minimum: -(lower_normal[0] * corner[0] + lower_normal[1] * corner[1]),
    });
    constraints.push(Constraint::HalfPlane {
      normal: upper_normal,
      minimum: -(upper_normal[0] * corner[0] + upper_normal[1] * corner[1]),
    });
    constraints.push(Constraint::Circle {
      corner,
      // LibreOffice keeps the label rectangle 2.5% inside the arc. Word's
      // fixed output instead uses a fixed 4pt inset across chart sizes; the
      // caller supplies the host's usable radius here.
      radius: usable_radius_factor,
    });
  }

  if seek_outer_edge && sweep <= std::f64::consts::PI {
    // LibreOffice's source-backed inner-placement geometry moves a complete
    // compound label frame as far as possible toward the slice arc. Office
    // fixed output uses that edge-seeking policy for compound/custom labels
    // (tdf125444 and tdf146487), while short scalar labels provide a direct
    // counterexample and use the minimum-displacement branch below.
    let direction = [angle.sin(), angle.cos()];
    let mut lower = 0.0_f64;
    let mut upper = f64::INFINITY;
    for constraint in constraints.iter().copied() {
      match constraint {
        Constraint::HalfPlane { normal, minimum } => {
          let coefficient = normal[0] * direction[0] + normal[1] * direction[1];
          if coefficient > 1.0e-12 {
            lower = lower.max(minimum / coefficient);
          } else if coefficient < -1.0e-12 {
            upper = upper.min(minimum / coefficient);
          } else if minimum > 1.0e-12 {
            return None;
          }
        }
        Constraint::Circle { corner, radius } => {
          let projection = direction[0] * corner[0] + direction[1] * corner[1];
          let discriminant = projection * projection
            - (corner[0] * corner[0] + corner[1] * corner[1] - radius * radius);
          if discriminant < 0.0 {
            return None;
          }
          let root = discriminant.sqrt();
          lower = lower.max(-projection - root);
          upper = upper.min(-projection + root);
        }
      }
    }
    if lower <= upper && upper.is_finite() && upper >= 0.0 {
      let box_center = [direction[0] * upper, direction[1] * upper];
      return Some((
        center.0 + (box_center[0] * radius_x) as f32 - label_size.0 * 0.5,
        center.1 - (box_center[1] * radius_y) as f32 - label_size.1 * 0.5,
      ));
    }
    return None;
  }

  let project = |point: [f64; 2], constraint: Constraint| match constraint {
    Constraint::HalfPlane { normal, minimum } => {
      let value = normal[0] * point[0] + normal[1] * point[1];
      if value >= minimum {
        point
      } else {
        let scale = (minimum - value) / (normal[0] * normal[0] + normal[1] * normal[1]);
        [point[0] + normal[0] * scale, point[1] + normal[1] * scale]
      }
    }
    Constraint::Circle { corner, radius } => {
      let corner_point = [point[0] + corner[0], point[1] + corner[1]];
      let length = corner_point[0].hypot(corner_point[1]);
      if length <= radius || length <= f64::EPSILON {
        point
      } else {
        let scale = radius / length;
        [
          corner_point[0] * scale - corner[0],
          corner_point[1] * scale - corner[1],
        ]
      }
    }
  };

  // Dykstra's cyclic projections return the nearest point in the convex
  // intersection instead of depending on an arbitrary constraint order.
  let mut box_center = initial_center;
  let mut corrections = vec![[0.0_f64; 2]; constraints.len()];
  for _ in 0..96 {
    let mut maximum_step = 0.0_f64;
    for (index, constraint) in constraints.iter().copied().enumerate() {
      let corrected = [
        box_center[0] + corrections[index][0],
        box_center[1] + corrections[index][1],
      ];
      let projected = project(corrected, constraint);
      corrections[index] = [corrected[0] - projected[0], corrected[1] - projected[1]];
      maximum_step =
        maximum_step.max((projected[0] - box_center[0]).hypot(projected[1] - box_center[1]));
      box_center = projected;
    }
    if maximum_step <= 1.0e-10 {
      break;
    }
  }
  let feasible = constraints.iter().all(|constraint| match *constraint {
    Constraint::HalfPlane { normal, minimum } => {
      normal[0] * box_center[0] + normal[1] * box_center[1] >= minimum - 1.0e-7
    }
    Constraint::Circle { corner, radius } => {
      (box_center[0] + corner[0]).hypot(box_center[1] + corner[1]) <= radius + 1.0e-7
    }
  });
  if !feasible {
    return None;
  }
  Some((
    center.0 + (box_center[0] * radius_x) as f32 - label_size.0 * 0.5,
    center.1 - (box_center[1] * radius_y) as f32 - label_size.1 * 0.5,
  ))
}

fn word_pie_rich_label_leader(
  start: (f32, f32),
  bounds: PlotRect,
  lines: &[RichDataLabelLine<'_>],
  rich_styles: &[TextStyle],
  fallback_style: &TextStyle,
  insets: ChartTextBodyInsets,
  metrics: &mut TextMetrics,
) -> Option<[(f32, f32); 3]> {
  // Native connectors target individual text rows. A side connection ends
  // at the authored-font baseline with 1.5pt horizontal clearance; a
  // vertical connection meets the row's top/bottom. The final orthogonal
  // segment is 4.5pt. Using the outer multiline rectangle joins the wrong
  // row and can cut across an adjacent longer line.
  let mut best: Option<(f32, [(f32, f32); 3])> = None;
  let mut top = bounds.top + insets.top;
  for line in lines {
    let baseline = top
      + line
        .fragments
        .iter()
        .map(|fragment| {
          let style = rich_styles
            .get(fragment.run_index)
            .unwrap_or(fallback_style);
          metrics
            .vertical_metrics_for_text(fragment.text, style)
            .directwrite_baseline_offset_pt
        })
        .fold(0.0_f32, f32::max);
    let left =
      bounds.left + insets.left + (bounds.width - insets.left - insets.right - line.width) * 0.5
        - 1.5;
    let right = left + line.width + 3.0;
    let (end, elbow) = if start.0 < left {
      ((left, baseline), (left - 4.5, baseline))
    } else if start.0 > right {
      ((right, baseline), (right + 4.5, baseline))
    } else if start.1 < top {
      ((start.0, top), (start.0, top - 4.5))
    } else if start.1 > baseline {
      ((start.0, baseline), (start.0, baseline + 4.5))
    } else {
      return None;
    };
    let distance = (start.0 - end.0).powi(2) + (start.1 - end.1).powi(2);
    if best
      .as_ref()
      .is_none_or(|(previous, _)| distance < *previous)
    {
      best = Some((distance, [start, elbow, end]));
    }
    top += line.height;
  }
  best.map(|(_, points)| points)
}

fn outside_radial_label_position(
  center: (f32, f32),
  radii: (f32, f32),
  clockwise_from_top: f32,
  label_size: (f32, f32),
) -> (f32, f32) {
  // LibreOffice PolarLabelPositionHelper anchors an outside label at the
  // slice's outer arc, adds the fixed 150 mm100 radial clearance used by
  // PieChart, then places the complete box on the outward side of that
  // anchor. Cardinal directions use centered alignment; diagonal quadrants
  // use the corresponding corner.
  const OUTSIDE_CLEARANCE_PT: f32 = 150.0 * 72.0 / 2540.0;
  let direction = (clockwise_from_top.sin(), -clockwise_from_top.cos());
  let anchor = (
    center.0 + direction.0 * (radii.0 + OUTSIDE_CLEARANCE_PT),
    center.1 + direction.1 * (radii.1 + OUTSIDE_CLEARANCE_PT),
  );
  let office_angle = (90.0 - clockwise_from_top.to_degrees()).rem_euclid(360.0);
  let (width, height) = label_size;
  if office_angle <= 5.0 || office_angle >= 355.0 {
    (anchor.0, anchor.1 - height * 0.5)
  } else if office_angle < 85.0 {
    (anchor.0, anchor.1 - height)
  } else if office_angle <= 95.0 {
    (anchor.0 - width * 0.5, anchor.1 - height)
  } else if office_angle < 175.0 {
    (anchor.0 - width, anchor.1 - height)
  } else if office_angle <= 185.0 {
    (anchor.0 - width, anchor.1 - height * 0.5)
  } else if office_angle < 265.0 {
    (anchor.0 - width, anchor.1)
  } else if office_angle <= 275.0 {
    (anchor.0 - width * 0.5, anchor.1)
  } else {
    (anchor.0, anchor.1)
  }
}

fn word_pie_3d_outside_label_position(
  projection: RadialPerspectiveProjection,
  angle: f32,
  explosion: f32,
  size: (f32, f32),
) -> (f32, f32) {
  // Native Word controls independently varying angle, text width/height,
  // elevation, thickness and explosion expose two legacy model grids.
  // The arc point and the explosion displacement are separately truncated
  // on a radius-100 grid; the alignment vector is rounded at radius 50.
  // Using the smooth painted arc for both loses the authored manual-label
  // origin. A manual bestFit offset is relative to this outside position
  // (also documented by LibreOffice PieChart::createTextLabelShape).
  let (u, cosine) = angle.sin_cos();
  let v = -cosine;
  let direction = ((u * 50.0).round() / 50.0, (v * 50.0).round() / 50.0);
  let anchor = (
    ((u * 100.0).trunc() + (u * explosion * 100.0).trunc()) / 100.0 + 0.0508 * direction.0,
    ((v * 100.0).trunc() + (v * explosion * 100.0).trunc()) / 100.0 + 0.04 * direction.1,
  );
  let project = |u, v| {
    if direction.1 >= 0.0 {
      projection.project_bottom_point(u, v, 0.0)
    } else {
      projection.project_plane_point(u, v)
    }
  };
  let origin = project(0.0, 0.0);
  let endpoint = project(direction.0, direction.1);
  let dx = endpoint.0 - origin.0;
  let dy = endpoint.1 - origin.1;
  // Office's generated alignment frame has a 3:1 horizontal aspect and a
  // one-percent horizontal overhang. Width-only and height-only controls
  // establish these independently; neither depends on the label content.
  let alignment_x = (3.0 * dx / dy.abs().max(f32::EPSILON)).clamp(-1.0, 1.0) * 1.02;
  let alignment_y = (dy / dx.abs().max(f32::EPSILON)).clamp(-1.0, 1.0);
  let anchor = project(anchor.0, anchor.1);
  (
    anchor.0 + size.0 * (alignment_x - 1.0) * 0.5,
    anchor.1 + size.1 * (alignment_y - 1.0) * 0.5,
  )
}

#[derive(Clone, Copy, Debug, Default)]
struct ChartTextBodyInsets {
  left: f32,
  top: f32,
  right: f32,
  bottom: f32,
}

#[derive(Clone, Copy, Debug)]
struct ChartLegendTextBody {
  insets: ChartTextBodyInsets,
  wrap: a::TextWrappingValues,
  vertical_overflow: a::TextVerticalOverflowValues,
  horizontal_overflow: a::TextHorizontalOverflowValues,
  vertical_anchor: a::TextAnchoringTypeValues,
  anchor_center: bool,
}

fn chart_legend_text_body(properties: Option<&a::BodyProperties>) -> ChartLegendTextBody {
  ChartLegendTextBody {
    insets: chart_text_body_insets(properties),
    // ECMA-376 Part 1 §20.1.7.1 assigns these defaults to a:bodyPr. A
    // generated chart legend still uses the same wrapping and overflow
    // defaults when c:txPr is absent, but has no authored body insets.
    wrap: properties
      .and_then(|properties| properties.wrap)
      .unwrap_or(a::TextWrappingValues::Square),
    vertical_overflow: properties
      .and_then(|properties| properties.vertical_overflow)
      .unwrap_or(a::TextVerticalOverflowValues::Overflow),
    horizontal_overflow: properties
      .and_then(|properties| properties.horizontal_overflow)
      .unwrap_or(a::TextHorizontalOverflowValues::Overflow),
    vertical_anchor: properties
      .and_then(|properties| properties.anchor)
      .unwrap_or(a::TextAnchoringTypeValues::Top),
    anchor_center: properties
      .and_then(|properties| properties.anchor_center)
      .is_some_and(|value| value.as_bool()),
  }
}

#[derive(Clone, Copy, Debug, Default)]
struct ResolvedDataLabelTextFrame {
  word_line_metrics: bool,
  outer_width: Option<f32>,
  outer_height: Option<f32>,
  maximum_inner_width: Option<f32>,
  insets: ChartTextBodyInsets,
}

impl ResolvedDataLabelTextFrame {
  fn is_fully_sized(self) -> bool {
    self.outer_width.is_some() && self.outer_height.is_some()
  }

  fn inner_width(self) -> Option<f32> {
    self
      .outer_width
      .map(|width| (width - self.insets.left - self.insets.right).max(0.0))
  }

  fn inner_height(self) -> Option<f32> {
    self
      .outer_height
      .map(|height| (height - self.insets.top - self.insets.bottom).max(0.0))
  }

  fn wrapping_width(self) -> Option<f32> {
    self.inner_width().or(self.maximum_inner_width)
  }
}

fn resolved_radial_data_label_text_frame(
  frame: ChartFrame,
  label: &crate::render::chart::ClusteredColumnDataLabel<'_>,
) -> ResolvedDataLabelTextFrame {
  let mut text_frame = resolved_data_label_text_frame(frame, label);
  text_frame.maximum_inner_width = pie_custom_label_maximum_width(
    frame.width_pt,
    label.layout.is_some(),
    label.rich_text_runs.is_empty(),
    text_frame.outer_width,
  );
  text_frame
}

fn pie_custom_label_maximum_width(
  chart_width: f32,
  has_custom_position: bool,
  has_plain_text: bool,
  explicit_outer_width: Option<f32>,
) -> Option<f32> {
  // LibreOffice PieChart::createTextLabelShape records the Office-compatible
  // rule observed from Microsoft: a custom-position pie label without a
  // custom width wraps at one fifth of the complete chart space. A fixed
  // inner plot still exposes the complete chart frame as its available outer
  // rectangle, so this limit is intentionally based on `ChartFrame`, not the
  // authored pie rectangle. Explicit c15 w/h remains authoritative.
  (has_custom_position
    && has_plain_text
    && explicit_outer_width.is_none()
    && chart_width.is_finite()
    && chart_width > 0.0)
    .then_some(chart_width / 5.0)
}

fn resolved_data_label_text_frame(
  frame: ChartFrame,
  label: &crate::render::chart::ClusteredColumnDataLabel<'_>,
) -> ResolvedDataLabelTextFrame {
  use crate::render::chart::ChartLayoutMode;

  let Some(layout) = label.text_frame_layout else {
    return ResolvedDataLabelTextFrame::default();
  };
  // MS-OI29500 §21.2.3.20 says Office saves wMode/hMode as factor. Do not
  // reinterpret a noncanonical edge value without the final positioned edge;
  // the compatible label then keeps its automatically fitted dimension.
  let scaled = |value: Option<f32>, mode: ChartLayoutMode, extent: f32| {
    (mode == ChartLayoutMode::Factor)
      .then_some(value?)
      .filter(|value| value.is_finite() && *value > 0.0)
      .map(|value| value * extent)
  };
  let outer_width = scaled(layout.width, layout.width_mode, frame.width_pt);
  let outer_height = scaled(layout.height, layout.height_mode, frame.height_pt);
  let insets = if outer_width.is_some() || outer_height.is_some() {
    chart_text_body_insets(label.text_body_properties)
  } else {
    ChartTextBodyInsets::default()
  };
  ResolvedDataLabelTextFrame {
    word_line_metrics: false,
    outer_width,
    outer_height,
    maximum_inner_width: None,
    insets,
  }
}

fn chart_text_body_insets(properties: Option<&a::BodyProperties>) -> ChartTextBodyInsets {
  let Some(properties) = properties else {
    return ChartTextBodyInsets::default();
  };
  // ECMA-376 Part 1 §20.1.7.1 defines the DrawingML text-body defaults as
  // 0.1 in horizontally and 0.05 in vertically. A present empty a:bodyPr is
  // therefore not a zero-inset box.
  let inset = |value: Option<ooxmlsdk::simple_type::Coordinate32Value>, default| {
    crate::units::emu_to_points(value.map_or(default, |value| value.to_emu()))
  };
  ChartTextBodyInsets {
    left: inset(
      properties.left_inset,
      DRAWINGML_DEFAULT_HORIZONTAL_TEXT_BODY_INSET_EMU,
    ),
    top: inset(
      properties.top_inset,
      DRAWINGML_DEFAULT_VERTICAL_TEXT_BODY_INSET_EMU,
    ),
    right: inset(
      properties.right_inset,
      DRAWINGML_DEFAULT_HORIZONTAL_TEXT_BODY_INSET_EMU,
    ),
    bottom: inset(
      properties.bottom_inset,
      DRAWINGML_DEFAULT_VERTICAL_TEXT_BODY_INSET_EMU,
    ),
  }
}

fn chart_data_label_insets(properties: Option<&a::BodyProperties>) -> ChartTextBodyInsets {
  properties.map_or(
    ChartTextBodyInsets {
      left: AUTOMATIC_DATA_LABEL_HORIZONTAL_INSET_PT,
      right: AUTOMATIC_DATA_LABEL_HORIZONTAL_INSET_PT,
      ..ChartTextBodyInsets::default()
    },
    |properties| chart_text_body_insets(Some(properties)),
  )
}

fn chart_data_label_insets_with_fallback(
  properties: Option<&a::BodyProperties>,
  group_properties: Option<&a::BodyProperties>,
  word_defaults: bool,
) -> ChartTextBodyInsets {
  let mut insets = chart_data_label_insets(properties);
  if word_defaults {
    // Word chart labels use 3pt horizontal and 1.5pt vertical text margins,
    // including a present but unqualified a:bodyPr. Chart COM reports the
    // same 18.665x15.205pt box for all four 10pt labels, with/without txPr.
    if properties.and_then(|body| body.left_inset).is_none() {
      insets.left = 3.0;
    }
    if properties.and_then(|body| body.right_inset).is_none() {
      insets.right = 3.0;
    }
    if properties.and_then(|body| body.top_inset).is_none() {
      insets.top = 1.5;
    }
    if properties.and_then(|body| body.bottom_inset).is_none() {
      insets.bottom = 1.5;
    }
  }
  let Some(group) = group_properties else {
    return insets;
  };
  let group_insets = chart_text_body_insets(Some(group));
  if properties.and_then(|body| body.left_inset).is_none() && group.left_inset.is_some() {
    insets.left = group_insets.left;
  }
  if properties.and_then(|body| body.top_inset).is_none() && group.top_inset.is_some() {
    insets.top = group_insets.top;
  }
  if properties.and_then(|body| body.right_inset).is_none() && group.right_inset.is_some() {
    insets.right = group_insets.right;
  }
  if properties.and_then(|body| body.bottom_inset).is_none() && group.bottom_inset.is_some() {
    insets.bottom = group_insets.bottom;
  }
  insets
}

fn generated_chart_text_body_insets(properties: Option<&a::BodyProperties>) -> ChartTextBodyInsets {
  if let Some(properties) = properties {
    return chart_text_body_insets(Some(properties));
  }
  // Axis labels are application-generated text shapes even when neither the
  // axis nor chartSpace authors c:txPr. Their implicit DrawingML text body
  // still owns the same schema defaults as an empty a:bodyPr.
  ChartTextBodyInsets {
    left: crate::units::emu_to_points(DRAWINGML_DEFAULT_HORIZONTAL_TEXT_BODY_INSET_EMU),
    top: crate::units::emu_to_points(DRAWINGML_DEFAULT_VERTICAL_TEXT_BODY_INSET_EMU),
    right: crate::units::emu_to_points(DRAWINGML_DEFAULT_HORIZONTAL_TEXT_BODY_INSET_EMU),
    bottom: crate::units::emu_to_points(DRAWINGML_DEFAULT_VERTICAL_TEXT_BODY_INSET_EMU),
  }
}

fn lower_of_pie_geometry(
  items: &mut Vec<PageItem>,
  backdrops: &mut Vec<PageItem>,
  plot: PlotRect,
  chart: &PieChartModel<'_>,
  style: &RadialChartStyle,
) {
  let secondary = chart
    .secondary_indices
    .iter()
    .filter_map(|index| chart.values.get(*index).copied().flatten())
    .filter(|value| value.is_finite() && *value > 0.0)
    .sum::<f64>();
  let mut primary = chart
    .values
    .iter()
    .enumerate()
    .filter(|(index, _)| !chart.secondary_indices.contains(index))
    .filter_map(|(index, value)| {
      value
        .as_ref()
        .copied()
        .filter(|value| value.is_finite() && *value > 0.0)
        .map(|value| (index, value))
    })
    .collect::<Vec<_>>();
  if secondary > 0.0 {
    // The aggregate "Other" slice inherits the series fill. For varying
    // colors this is the first palette color, not the color of the first
    // point moved into the secondary chart.
    primary.push((0, secondary));
  }
  let primary_total = primary.iter().map(|(_, value)| *value).sum::<f64>();
  if primary_total <= f64::EPSILON {
    return;
  }
  let plot_profile = if style.layout_profile == ChartLayoutProfile::Excel {
    match chart.kind {
      RadialChartKind::PieOfPie => profiles::EXCEL_PIE_OF_PIE_PLOT,
      RadialChartKind::BarOfPie => profiles::EXCEL_BAR_OF_PIE_PLOT,
      _ => profiles::DEFAULT_OF_PIE_PLOT,
    }
  } else {
    profiles::DEFAULT_OF_PIE_PLOT
  };
  let primary_center = (
    plot.left + plot.width * plot_profile.primary_x_ratio,
    plot.top + plot.height * plot_profile.center_y_ratio,
  );
  let primary_radius = plot.width.min(plot.height) * plot_profile.primary_radius_scale;
  let secondary_center = (
    plot.left + plot.width * plot_profile.secondary_x_ratio,
    plot.top + plot.height * plot_profile.center_y_ratio,
  );
  let secondary_radius =
    primary_radius * (chart.secondary_size_percent / 100.0).clamp(0.05, 2.0) as f32;
  // Office rotates an of-pie chart so the aggregate slice is centered on
  // the secondary chart at the right. The aggregate is appended after the
  // original primary points, so the first slice starts half its sweep past
  // the right-facing radial.
  let aggregate_sweep = (secondary / primary_total * std::f64::consts::TAU) as f32;
  let initial_angle = std::f32::consts::FRAC_PI_2 + aggregate_sweep * 0.5;
  let mut angle = initial_angle;
  for (index, value) in primary {
    let sweep = (value / primary_total * std::f64::consts::TAU) as f32;
    push_radial_point_with_effects(
      items,
      backdrops,
      radial_segment_path(RadialSegmentSpec {
        center: primary_center,
        radii: (primary_radius, primary_radius),
        hole_ratio: 0.0,
        angles: (angle, sweep),
        paint: (style.point_colors[index % style.point_colors.len()], 1.0),
        fallback_stroke: (style.layout_profile != ChartLayoutProfile::Excel).then_some((
          RgbColor {
            r: 255,
            g: 255,
            b: 255,
          },
          0.75,
        )),
        style: style.point_styles.get(index),
        perspective: None,
      }),
      style
        .point_image_effects
        .get(index)
        .and_then(Option::as_ref),
    );
    angle += sweep;
  }

  if chart.kind == RadialChartKind::PieOfPie {
    // Excel gives the secondary pie the same starting angle as the primary
    // pie. This keeps the aggregate slice centered toward the secondary plot
    // and preserves the source point order in both pies.
    let mut angle = if style.layout_profile == ChartLayoutProfile::Excel {
      initial_angle
    } else {
      0.0
    };
    for index in chart.secondary_indices.iter().copied() {
      let Some(value) = chart
        .values
        .get(index)
        .copied()
        .flatten()
        .filter(|value| value.is_finite() && *value > 0.0)
      else {
        continue;
      };
      let sweep = (value / secondary * std::f64::consts::TAU) as f32;
      push_radial_point_with_effects(
        items,
        backdrops,
        radial_segment_path(RadialSegmentSpec {
          center: secondary_center,
          radii: (secondary_radius, secondary_radius),
          hole_ratio: 0.0,
          angles: (angle, sweep),
          paint: (style.point_colors[index % style.point_colors.len()], 1.0),
          fallback_stroke: (style.layout_profile != ChartLayoutProfile::Excel).then_some((
            RgbColor {
              r: 255,
              g: 255,
              b: 255,
            },
            0.75,
          )),
          style: style.point_styles.get(index),
          perspective: None,
        }),
        style
          .point_image_effects
          .get(index)
          .and_then(Option::as_ref),
      );
      angle += sweep;
    }
  } else {
    let mut y = secondary_center.1 - secondary_radius;
    for index in chart.secondary_indices.iter().copied() {
      let Some(value) = chart
        .values
        .get(index)
        .copied()
        .flatten()
        .filter(|value| value.is_finite() && *value > 0.0)
      else {
        continue;
      };
      let height = (value / secondary) as f32 * secondary_radius * 2.0;
      let point_style = style.point_styles.get(index);
      let point_start = items.len();
      push_chart_shape_rect(
        items,
        PlotRect {
          left: secondary_center.0 - secondary_radius * 0.45,
          top: y,
          width: secondary_radius,
          height,
        },
        ChartShapePaint {
          fill: point_style.map(|style| &style.fill),
          stroke: point_style.map(|style| &style.stroke),
          fallback_fill_color: Some(style.point_colors[index % style.point_colors.len()]),
          stroke_width_scale: 1.0,
        },
      );
      let point_items = items.drain(point_start..).collect::<Vec<_>>();
      for item in point_items {
        push_radial_point_with_effects(
          items,
          backdrops,
          item,
          style
            .point_image_effects
            .get(index)
            .and_then(Option::as_ref),
        );
      }
      y += height;
    }
  }
  // c:serLines is optional. Preserve the historical connector fallback for
  // Word and PowerPoint, but do not invent connector lines for Excel
  // of-pie charts when the source does not provide them.
  if style.layout_profile != ChartLayoutProfile::Excel {
    for direction in [-1.0_f32, 1.0] {
      items.push(PageItem::Line(LineItem {
        x1_pt: primary_center.0 + primary_radius * 0.75,
        y1_pt: primary_center.1 + direction * primary_radius * 0.45,
        x2_pt: secondary_center.0 - secondary_radius,
        y2_pt: secondary_center.1 + direction * secondary_radius * 0.7,
        width_pt: 0.75,
        color: RgbColor {
          r: 128,
          g: 128,
          b: 128,
        },
        kind: LineItemKind::Stroke,
      }));
    }
  }
}

#[derive(Clone, Copy)]
struct RadialExtrusionProjection {
  denominator: f32,
  numerator: f32,
}

#[derive(Clone, Copy)]
struct RadialPerspectiveProjection {
  conic_center: (f32, f32),
  radii: (f32, f32),
  strength: f32,
  plane_offset: (f32, f32),
  extrusion: Option<RadialExtrusionProjection>,
}

fn word_pie_3d_projection(plot: PlotRect, view: Chart3DView) -> RadialPerspectiveProjection {
  word_exploded_pie_3d_projection(plot, view, 0.0)
}

fn word_exploded_pie_3d_projection(
  plot: PlotRect,
  view: Chart3DView,
  explosion: f32,
) -> RadialPerspectiveProjection {
  // Word controls varying elevation, perspective, frame aspect and hPercent
  // retain a circular cylinder. MS-OI29500 defines hPercent as a multiplier
  // of its default thickness, and perspective as twice the vertical FOV.
  let tilt = view.rotate_x_deg.clamp(0.0, 90.0).to_radians();
  let (s, c) = tilt.sin_cos();
  let thickness = 0.24 * (view.height_percent / 100.0).clamp(0.05, 5.0);
  // Explosion translates each sector in its source plane. Fit the enlarged
  // circular envelope before projecting; its thickness remains unchanged.
  // Independent native 0/25/50% and hPercent 50/100/200 controls retain the
  // same viewport, including a manually authored inner plot rectangle.
  let radius = 1.0 + explosion.clamp(0.0, 1.0);
  // Native near-parallel controls at three thicknesses, and independent
  // height/width controls, establish the padded model envelope. This is a
  // host scene-fit margin, not a correction to the authored view angle.
  let envelope = 1.028;
  if view.right_angle_axes {
    let scale = (plot.width / (2.0 * radius * envelope))
      .min(plot.height / ((2.0 * radius * s + thickness * c) * envelope).max(f32::EPSILON));
    return RadialPerspectiveProjection {
      conic_center: (
        plot.left + plot.width * 0.5,
        plot.top + plot.height * 0.5 - thickness * c * scale * 0.5,
      ),
      radii: (scale, scale * s),
      strength: 0.0,
      plane_offset: (0.0, 0.0),
      extrusion: Some(RadialExtrusionProjection {
        denominator: 0.0,
        numerator: thickness * c * scale,
      }),
    };
  }
  let fov = if view.perspective_half_degrees <= f32::EPSILON {
    0.1
  } else {
    view.perspective_half_degrees * 0.5
  };
  let tangent = (fov * 0.5).to_radians().tan();
  let focal = plot.height / (2.0 * tangent);
  let half_thickness = thickness * 0.5;
  // Fit the near and far planes in the vertical frustum first. A narrow
  // viewport increases camera distance without recentering the projected
  // silhouette: the native narrow/tall controls preserve this eye offset.
  let eye_y = if view.rotate_x_deg <= 0.0 {
    half_thickness
  } else if view.rotate_x_deg >= 90.0 {
    0.0
  } else {
    half_thickness * c - tangent * (radius * c - half_thickness * s)
  };
  let distance = ((radius * s + half_thickness * c) * envelope / tangent + half_thickness * s).max(
    ((2.0 * focal * envelope * radius / plot.width).powi(2) + (radius * c).powi(2)).sqrt()
      + thickness * s,
  );
  let top_distance = distance - thickness * s;
  let top_y = eye_y - thickness * c;
  let strength = c / top_distance;
  let conic_denominator = top_distance * top_distance - c * c;
  let radius_x = focal / conic_denominator.sqrt();
  let radius_y = focal * (s * top_distance + top_y * c) / conic_denominator;
  let hub_offset = focal * top_y / top_distance;
  let depth_denominator = thickness * s / top_distance;
  RadialPerspectiveProjection {
    conic_center: (
      plot.left + plot.width * 0.5,
      plot.top + plot.height * 0.5 + hub_offset + radius_y * strength,
    ),
    radii: (radius_x, radius_y),
    strength,
    plane_offset: (0.0, 0.0),
    extrusion: Some(RadialExtrusionProjection {
      denominator: depth_denominator,
      numerator: focal * thickness * c / top_distance - hub_offset * depth_denominator,
    }),
  }
}

impl RadialPerspectiveProjection {
  fn new(
    center: (f32, f32),
    radii: (f32, f32),
    view: crate::render::chart::Chart3DView,
    viewport_height: Option<f32>,
  ) -> Self {
    let strength = if view.right_angle_axes {
      0.0
    } else if let Some(viewport_height) = viewport_height {
      // MS-OI29500 §21.2.2.136: val is twice the field of view; val=0
      // means 0.1 degrees. For focal length f and projected ellipse radius
      // rx, rx=f*R/sqrt(D²-R²*cos(a)²). Solve this for k=R*cos(a)/D.
      // The fitted radius already includes explosion scaling; do not scale
      // k a second time or approximate its nonlinear dependence on rx.
      let fov = if view.perspective_half_degrees <= f32::EPSILON {
        0.1
      } else {
        view.perspective_half_degrees * 0.5
      };
      let focal_length = viewport_height / (2.0 * (fov.clamp(0.1, 100.0) * 0.5).to_radians().tan());
      let ratio = radii.0 * view.rotate_x_deg.to_radians().cos().abs() / focal_length;
      ratio / (1.0 + ratio * ratio).sqrt()
    } else {
      // Other host layouts do not yet expose their physical 3-D viewport.
      (view.perspective_half_degrees / 200.0).clamp(0.0, 0.9)
    };
    Self {
      conic_center: center,
      radii,
      strength,
      plane_offset: (0.0, 0.0),
      extrusion: None,
    }
  }

  fn hub(self) -> (f32, f32) {
    self.project_plane_point(0.0, 0.0)
  }

  fn with_plane_offset(mut self, offset: (f32, f32)) -> Self {
    self.plane_offset = offset;
    self
  }

  fn with_extrusion_thickness(mut self, thickness_radius_ratio: f32, tilt_deg: f32) -> Self {
    // For a circle seen at elevation a, k = R*cos(a)/D. Extruding H away
    // from its top plane adds H*sin(a)/D to the homogeneous denominator.
    // Explosion scales k and the scene together, retaining H/R.
    let tilt = tilt_deg.to_radians();
    if thickness_radius_ratio > 0.0 && tilt.cos().abs() > f32::EPSILON {
      let horizontal_scale = self.radii.0 * (1.0 - self.strength * self.strength).sqrt();
      let vertical_scale = self.radii.1 * (1.0 - self.strength * self.strength);
      // The conic is expressed relative to its projected hub, not the
      // camera's principal point. Its vertical numerator V therefore equals
      // f*sin(a) + hub_offset*k. Subtract that offset's q contribution when
      // projecting an extrusion: d = H/R * (f/cos(a) - V*tan(a)). This keeps
      // both coordinates in the same pinhole camera; a measured screen
      // depth cannot be used as the homogeneous numerator.
      let numerator = if self.strength > f32::EPSILON {
        thickness_radius_ratio * (horizontal_scale / tilt.cos() - vertical_scale * tilt.tan())
      } else {
        thickness_radius_ratio * horizontal_scale * tilt.cos()
      };
      self.extrusion = Some(RadialExtrusionProjection {
        denominator: (self.strength * thickness_radius_ratio * tilt.tan()).max(0.0),
        numerator,
      });
    }
    self
  }

  fn point(self, angle: f32) -> (f32, f32) {
    self.project_plane_point(angle.sin(), -angle.cos())
  }

  fn project_plane_point(self, horizontal: f32, vertical: f32) -> (f32, f32) {
    self.project_point(horizontal, vertical, 0.0, 0.0)
  }

  fn project_bottom_point(self, horizontal: f32, vertical: f32, fallback_depth: f32) -> (f32, f32) {
    if let Some(extrusion) = self.extrusion {
      self.project_point(
        horizontal,
        vertical,
        extrusion.denominator,
        extrusion.numerator,
      )
    } else {
      // Other host profiles still describe a screen-space extrusion.
      let top = self.project_plane_point(horizontal, vertical);
      (top.0, top.1 + fallback_depth)
    }
  }

  fn project_point(
    self,
    horizontal: f32,
    vertical: f32,
    depth_denominator: f32,
    depth_numerator: f32,
  ) -> (f32, f32) {
    let horizontal = horizontal + self.plane_offset.0;
    let vertical = vertical + self.plane_offset.1;
    let denominator = (1.0 - self.strength * vertical + depth_denominator).max(0.05);
    let one_minus_squared = 1.0 - self.strength * self.strength;
    let base_hub_y = self.conic_center.1 - self.radii.1 * self.strength;
    let vertical_scale = self.radii.1 * one_minus_squared;
    (
      self.conic_center.0 + self.radii.0 * one_minus_squared.sqrt() * horizontal / denominator,
      base_hub_y + (vertical_scale * vertical + depth_numerator) / denominator,
    )
  }

  fn visible_wall_interval(self) -> (f32, f32) {
    if self.extrusion.is_none() {
      return (
        std::f32::consts::FRAC_PI_2,
        3.0 * std::f32::consts::FRAC_PI_2,
      );
    }
    // A cylindrical wall faces the eye iff N dot (eye - surface) > 0.
    // Unlike a parallel view, its silhouette is not at +/- 90 degrees.
    let eye_u = -self.strength * self.plane_offset.0;
    let eye_v = 1.0 - self.strength * self.plane_offset.1;
    let distance = eye_u.hypot(eye_v);
    let center = eye_u.atan2(-eye_v).rem_euclid(std::f32::consts::TAU);
    let half_angle = (self.strength / distance.max(f32::EPSILON))
      .clamp(-1.0, 1.0)
      .acos();
    (center - half_angle, center + half_angle)
  }

  fn horizontal_bounds(self) -> (f32, f32) {
    (0..=180).fold((f32::INFINITY, f32::NEG_INFINITY), |(left, right), step| {
      let point = self.point(step as f32 * std::f32::consts::TAU / 180.0);
      (left.min(point.0), right.max(point.0))
    })
  }
}

struct RadialSegmentSpec<'a> {
  center: (f32, f32),
  radii: (f32, f32),
  hole_ratio: f32,
  angles: (f32, f32),
  paint: (RgbColor, f32),
  fallback_stroke: Option<(RgbColor, f32)>,
  style: Option<&'a crate::common::ShapeStyle<'static>>,
  perspective: Option<RadialPerspectiveProjection>,
}

fn radial_segment_path(spec: RadialSegmentSpec<'_>) -> PageItem {
  let RadialSegmentSpec {
    center,
    radii,
    hole_ratio,
    angles,
    paint,
    fallback_stroke,
    style,
    perspective,
  } = spec;
  let (center_x, center_y) = center;
  let (radius_x, radius_y) = radii;
  let (start_angle, sweep) = angles;
  let (color, opacity) = paint;
  let segment_count = ((sweep.to_degrees().abs() / 2.0).ceil() as usize).max(2);
  let mut points = Vec::with_capacity(segment_count * 2 + 3);
  if hole_ratio <= f32::EPSILON {
    let hub = perspective.map_or((center_x, center_y), RadialPerspectiveProjection::hub);
    points.push(common_point(hub.0, hub.1));
  }
  for segment in 0..=segment_count {
    let angle = start_angle + sweep * segment as f32 / segment_count as f32;
    let point = perspective.map_or_else(
      || {
        (
          center_x + angle.sin() * radius_x,
          center_y - angle.cos() * radius_y,
        )
      },
      |projection| projection.point(angle),
    );
    points.push(common_point(point.0, point.1));
  }
  if hole_ratio > f32::EPSILON {
    for segment in (0..=segment_count).rev() {
      let angle = start_angle + sweep * segment as f32 / segment_count as f32;
      points.push(common_point(
        center_x + angle.sin() * radius_x * hole_ratio,
        center_y - angle.cos() * radius_y * hole_ratio,
      ));
    }
  }
  // DrawingML binds a gradient to the bounding box of the painted shape,
  // not to the complete source ellipse from which a pie sector was cut.
  // This distinction is visible for every non-reflex sector: PowerPoint's
  // fixed output uses the sector's centre/radial/arc bounds independently
  // for each c:dPt.  Keep the display-list bounds aligned with the actual
  // polygon so gradient coordinates, effects, and pattern paint share that
  // authored shape box.
  let (left, top, right, bottom) = points.iter().fold(
    (
      f32::INFINITY,
      f32::INFINITY,
      f32::NEG_INFINITY,
      f32::NEG_INFINITY,
    ),
    |(left, top, right, bottom), point| {
      (
        left.min(point.x.0),
        top.min(point.y.0),
        right.max(point.x.0),
        bottom.max(point.y.0),
      )
    },
  );
  let bounds = common_rect(left, top, right - left, bottom - top);
  let fill = match style.map(|style| &style.fill) {
    Some(crate::common::ShapeStyleValue::Paint(fill)) => bind_chart_fill_to_bounds(fill, bounds),
    Some(crate::common::ShapeStyleValue::NoPaint) => crate::common::Fill::None,
    Some(crate::common::ShapeStyleValue::Unspecified) | None => {
      crate::common::Fill::Solid(common_rgb(color, opacity))
    }
  };
  let stroke = match style.map(|style| &style.stroke) {
    Some(crate::common::ShapeStyleValue::Paint(stroke)) => {
      Some(bind_chart_stroke_to_bounds(stroke, bounds, 1.0))
    }
    Some(crate::common::ShapeStyleValue::NoPaint) => None,
    Some(crate::common::ShapeStyleValue::Unspecified) | None => {
      fallback_stroke.map(|(stroke_color, stroke_width_pt)| crate::common::Stroke {
        width: crate::common::Pt(stroke_width_pt),
        color: common_rgb(stroke_color, opacity),
        ..Default::default()
      })
    }
  };
  PageItem::Path(crate::common::PathItem {
    bounds,
    points,
    commands: Vec::new(),
    closed: true,
    fill,
    stroke,
  })
}

/// Builds one non-perspective radial segment while preserving the complete
/// resolved DrawingML point style. Word's specialized automatic-layout path
/// uses this entry point so it shares fill/stroke inheritance and paint
/// binding with PowerPoint, Excel, and the general Word radial lowerer.
pub(crate) fn radial_2d_segment_path(
  center: (f32, f32),
  radii: (f32, f32),
  hole_ratio: f32,
  angles: (f32, f32),
  fallback_color: RgbColor,
  fallback_stroke: Option<(RgbColor, f32)>,
  style: Option<&crate::common::ShapeStyle<'static>>,
) -> PageItem {
  radial_segment_path(RadialSegmentSpec {
    center,
    radii,
    hole_ratio,
    angles,
    paint: (fallback_color, 1.0),
    fallback_stroke,
    style,
    perspective: None,
  })
}

pub(crate) fn word_chart_3d_final_canvas(
  data: &[u8],
  bounds: crate::common::Rect,
) -> Option<crate::common::Rect> {
  if !data.starts_with(b"\x89PNG\r\n\x1a\n") {
    return None;
  }
  let mut offset = 8usize;
  while let Some(header) = data.get(offset..offset.checked_add(8)?) {
    let length = u32::from_be_bytes(header[..4].try_into().ok()?) as usize;
    let end = offset.checked_add(8)?.checked_add(length)?;
    if &header[4..] == b"oxCb" {
      let payload = data.get(offset + 8..end)?;
      let values: Vec<_> = payload
        .as_chunks::<4>()
        .0
        .iter()
        .map(|chunk| f32::from_be_bytes(*chunk))
        .collect();
      if payload.len() != 20
        || values.iter().any(|v| !v.is_finite())
        || values[2] <= 0.0
        || values[3] <= 0.0
        || values[4] <= 0.0
      {
        return None;
      }
      let left = f64::from(bounds.origin.x.0 + values[0]);
      let top = f64::from(bounds.origin.y.0 + values[1]);
      let grid = f64::from(WORD_FIXED_CHART_DATA_EDGE_GRID_PT);
      let x = (left / grid).floor() * grid;
      let y = (top / grid).floor() * grid;
      let right = ((left + f64::from(values[2])) / grid).ceil() * grid;
      let bottom = ((top + f64::from(values[3])) / grid).ceil() * grid;
      let half_sample = 0.5 * f64::from(crate::units::POINTS_PER_INCH / values[4]);
      return Some(common_rect(
        x as f32,
        y as f32,
        (right - x - half_sample) as f32,
        (bottom - y - half_sample) as f32,
      ));
    }
    offset = end.checked_add(4)?;
  }
  None
}

fn cartesian_3d_scene_image(
  items: &[PageItem],
  viewport: Option<crate::common::Rect>,
  raster_dpi: f32,
) -> Option<ImageItem> {
  chart_3d_scene_image(items, viewport, raster_dpi, None)
}

fn chart_3d_scene_image(
  items: &[PageItem],
  viewport: Option<crate::common::Rect>,
  raster_dpi: f32,
  mesh: Option<&word_pie_scene::Scene>,
) -> Option<ImageItem> {
  use crate::common::drawingml_shape_raster::{
    PageToRasterMapping, rasterize_vector_scene_at_mapping,
  };
  use crate::common::{DisplayItem, Pt, Stroke};
  let mut display = Vec::with_capacity(items.len());
  let mut left = f32::INFINITY;
  let mut top = f32::INFINITY;
  let mut right = f32::NEG_INFINITY;
  let mut bottom = f32::NEG_INFINITY;
  for item in items {
    let (bounds, outset, item) = match item {
      PageItem::Path(path) => (
        path.bounds,
        path
          .stroke
          .as_ref()
          .map_or(0.0, |stroke| stroke.width.0 * 0.5),
        DisplayItem::Path(path.clone()),
      ),
      PageItem::Line(line) => (
        common_rect(
          line.x1_pt.min(line.x2_pt),
          line.y1_pt.min(line.y2_pt),
          (line.x2_pt - line.x1_pt).abs(),
          (line.y2_pt - line.y1_pt).abs(),
        ),
        line.width_pt * 0.5,
        DisplayItem::Line(crate::common::LineItem {
          start: common_point(line.x1_pt, line.y1_pt),
          end: common_point(line.x2_pt, line.y2_pt),
          stroke: Stroke {
            width: Pt(line.width_pt),
            color: common_rgb(line.color, 1.0),
            ..Default::default()
          },
          kind: crate::common::LineKind::Stroke,
        }),
      ),
      // Keep authored text and unsupported paint on their existing path.
      _ => return None,
    };
    left = left.min(bounds.origin.x.0 - outset);
    top = top.min(bounds.origin.y.0 - outset);
    right = right.max(bounds.origin.x.0 + bounds.size.width.0 + outset);
    bottom = bottom.max(bounds.origin.y.0 + bounds.size.height.0 + outset);
    display.push(item);
  }
  if display.is_empty() && mesh.is_none() {
    return None;
  }
  if let Some(stroke_bounds) =
    crate::common::drawingml_stroke::display_items_stroke_bounds(&display)
  {
    left = left.min(stroke_bounds.origin.x.0);
    top = top.min(stroke_bounds.origin.y.0);
    right = right.max(stroke_bounds.origin.x.0 + stroke_bounds.size.width.0);
    bottom = bottom.max(stroke_bounds.origin.y.0 + stroke_bounds.size.height.0);
  }
  let ppp = crate::units::OFFICE_FIXED_OUTPUT_RASTER_DPI / crate::units::POINTS_PER_INCH;
  let mut target_size = None;
  let mut raster_scale = (ppp, ppp);
  let (raster_bounds, left_px, top_px, width, height) = if let Some(viewport) = viewport {
    // The native chart canvas belongs to the 600-DPI printer grid, whereas
    // its bitmap encloses that canvas on the global 200-DPI lattice. These
    // origins need not coincide. PDF placement ends half a sample before
    // the canvas edge, as with Office's chart marker source surfaces.
    let grid = f64::from(WORD_FIXED_CHART_DATA_EDGE_GRID_PT);
    let snap_down = |v: f32| (f64::from(v) / grid).floor() * grid;
    let snap_up = |v: f32| (f64::from(v) / grid).ceil() * grid;
    let x = snap_down(viewport.origin.x.0);
    let y = snap_down(viewport.origin.y.0);
    // Enclose both page-space endpoints, not the extent alone. Native
    // Print/Screen controls translated across a printer-dot boundary lose
    // one dot of canvas width/height while retaining their logical viewport.
    let w = snap_up(viewport.origin.x.0 + viewport.size.width.0) - x;
    let h = snap_up(viewport.origin.y.0 + viewport.size.height.0) - y;
    let density = f64::from(raster_dpi) / f64::from(crate::units::POINTS_PER_INCH);
    // Bitmap allocation encloses the logical viewport on its own lattice,
    // independently of the printer-dot PDF canvas. A translated native
    // Screen control has 288 rows; enclosing the expanded canvas yields 289.
    let allocation = |density: f64| {
      let left = f64::from(viewport.origin.x.0) * density;
      let top = f64::from(viewport.origin.y.0) * density;
      let right = left + f64::from(viewport.size.width.0) * density;
      let bottom = top + f64::from(viewport.size.height.0) * density;
      (
        ((right - 1e-5).ceil() - (left + 1e-5).floor()) as u32,
        ((bottom - 1e-5).ceil() - (top + 1e-5).floor()) as u32,
      )
    };
    target_size = Some(allocation(density));
    let (width, height) = allocation(
      f64::from(crate::units::OFFICE_FIXED_OUTPUT_RASTER_DPI)
        / f64::from(crate::units::POINTS_PER_INCH),
    );
    raster_scale = (
      width as f32 / viewport.size.width.0,
      height as f32 / viewport.size.height.0,
    );
    (
      common_rect(
        x as f32,
        y as f32,
        (w - 0.5 / density) as f32,
        (h - 0.5 / density) as f32,
      ),
      // Native independent document translations change the integer bitmap
      // allocation and stretch the same logical viewport across that surface.
      // Keep its unsnapped origin, with independent X/Y device scale factors.
      viewport.origin.x.0 * raster_scale.0,
      viewport.origin.y.0 * raster_scale.1,
      width,
      height,
    )
  } else {
    let left = (left * ppp).floor() / ppp;
    let top = (top * ppp).floor() / ppp;
    let width = ((right - left) * ppp).ceil() as u32;
    let height = ((bottom - top) * ppp).ceil() as u32;
    (
      common_rect(left, top, width as f32 / ppp, height as f32 / ppp),
      left * ppp,
      top * ppp,
      width,
      height,
    )
  };
  if u64::from(width) * u64::from(height) > 16_000_000 {
    return None;
  }
  let mapping = PageToRasterMapping {
    width_px: width,
    height_px: height,
    scale_x: raster_scale.0,
    scale_y: raster_scale.1,
    // The logical viewport already maps its edges to the native surface.
    // Independent unoutlined wall controls at different sizes/translations
    // retain this origin; adding a half-pixel would shift every gridline.
    translate_x: -left_px,
    translate_y: -top_px,
    text_hinting: None,
  };
  let image = if let Some(mesh) = mesh {
    mesh.rasterize(mapping)?
  } else {
    rasterize_vector_scene_at_mapping(&display, mapping)?
  };
  let mut image = chart_raster_image_with_target(
    &image,
    raster_bounds,
    target_size,
    viewport.map(|canvas| (canvas, raster_dpi)),
  )?;
  if viewport.is_some() {
    image.content_type = Some("application/vnd.ooxmlsdk.wordprocessing-chart-3d+png".to_owned());
  }
  Some(image)
}

fn radial_3d_scene_image(items: &[PageItem]) -> Option<ImageItem> {
  use crate::common::drawingml_shape_raster::{
    PageToRasterMapping, rasterize_vector_scene_at_mapping,
  };
  let paths = items
    .iter()
    .map(|item| match item {
      PageItem::Path(path) => Some(path.clone()),
      _ => None,
    })
    .collect::<Option<Vec<_>>>()?;
  let first = paths.first()?;
  let mut bounds = first.bounds;
  for path in &paths[1..] {
    let left = bounds.origin.x.0.min(path.bounds.origin.x.0);
    let top = bounds.origin.y.0.min(path.bounds.origin.y.0);
    let right = (bounds.origin.x.0 + bounds.size.width.0)
      .max(path.bounds.origin.x.0 + path.bounds.size.width.0);
    let bottom = (bounds.origin.y.0 + bounds.size.height.0)
      .max(path.bounds.origin.y.0 + path.bounds.size.height.0);
    bounds = common_rect(left, top, right - left, bottom - top);
  }
  // Stroke/effect paint owns additional extent beyond this geometric scene.
  // Keep its existing path until that extent is explicitly represented here.
  if paths.iter().any(|path| path.stroke.is_some()) {
    return None;
  }
  let ppp = crate::units::OFFICE_FIXED_OUTPUT_RASTER_DPI / crate::units::POINTS_PER_INCH;
  let left = (bounds.origin.x.0 * ppp).floor() / ppp;
  let top = (bounds.origin.y.0 * ppp).floor() / ppp;
  let width = ((bounds.origin.x.0 + bounds.size.width.0 - left) * ppp).ceil() as u32;
  let height = ((bounds.origin.y.0 + bounds.size.height.0 - top) * ppp).ceil() as u32;
  if u64::from(width) * u64::from(height) > 16_000_000 {
    return None;
  }
  let display = paths
    .into_iter()
    .map(crate::common::DisplayItem::Path)
    .collect::<Vec<_>>();
  let image = rasterize_vector_scene_at_mapping(
    &display,
    PageToRasterMapping {
      width_px: width,
      height_px: height,
      scale_x: ppp,
      scale_y: ppp,
      translate_x: -left * ppp,
      translate_y: -top * ppp,
      text_hinting: None,
    },
  )?;
  chart_raster_image(
    &image,
    common_rect(left, top, width as f32 / ppp, height as f32 / ppp),
  )
}

fn office_perspective_chart_diffuse_color(color: RgbColor, normal: [f32; 3]) -> RgbColor {
  // Native pie caps at 15/30/40/90 degrees pin the camera-space diagonal
  // light independently of the series color. Ambient .4, directional .75
  // and the existing 1/128 D3D vertex lattice reproduce their RGB values.
  // Side-wall samples independently verify the X component of this light.
  let diffuse = 0.4 + 0.75 / 3.0_f32.sqrt() * (-normal.iter().sum::<f32>()).max(0.0);
  let channel = |value| {
    crate::common::drawingml_3d::quantize_gouraud_channel(f32::from(value) / 255.0 * diffuse)
  };
  RgbColor {
    r: channel(color.r),
    g: channel(color.g),
    b: channel(color.b),
  }
}

fn word_pie_3d_pen_width(width: f32, projection: RadialPerspectiveProjection) -> f32 {
  // Native 0/.5/1/2/4/8pt controls use a model-space pen, with a one-sample
  // hairline floor. Independent elevation, thickness and explosion controls
  // scale its width with the projected model radius (1/250 per point), not
  // with the flattened 2-D ellipse's minor axis or the text/chart frame.
  (width * projection.radii.0 / 250.0)
    .max(crate::units::POINTS_PER_INCH / crate::units::OFFICE_FIXED_OUTPUT_RASTER_DPI)
}

fn resolve_word_pie_cap_outline_visibility(
  items: &mut Vec<PageItem>,
  start: usize,
  angles: (f32, f32),
  projection: RadialPerspectiveProjection,
) {
  let [PageItem::Path(cap)] = &items[start..] else {
    return;
  };
  let Some(stroke) = &cap.stroke else {
    return;
  };
  if cap.points.len() < 4 || stroke.dash.is_some() || stroke.pattern.is_some() {
    return;
  }
  // As for Word's parallel cylinders, the far rim is behind its cap plane.
  // Native filled/wire controls at four elevations expose the inner half
  // of this rim only after removing the fill. Radial cuts and the near rim
  // remain visible across the adjoining cap/side faces.
  let count = cap.points.len();
  let eye = (
    -projection.strength * projection.plane_offset.0,
    1.0 - projection.strength * projection.plane_offset.1,
  );
  let front = (0..count)
    .map(|edge| {
      if edge == 0 || edge == count - 1 {
        return true;
      }
      let angle = angles.0 + angles.1 * (edge as f32 - 0.5) / (count - 2) as f32;
      angle.sin() * eye.0 - angle.cos() * eye.1 >= projection.strength
    })
    .collect::<Vec<_>>();
  let Some(boundary) = (0..count).find(|&edge| front[edge] != front[(edge + count - 1) % count])
  else {
    return;
  };
  let mut before = Vec::new();
  let mut after = Vec::new();
  let mut consumed = 0;
  while consumed < count {
    let first = (boundary + consumed) % count;
    let visible = front[first];
    let mut points = vec![cap.points[first]];
    loop {
      consumed += 1;
      let next = (boundary + consumed) % count;
      points.push(cap.points[next]);
      if consumed == count || front[next] != visible {
        break;
      }
    }
    let mut outline = cap.clone();
    outline.points = points;
    outline.closed = false;
    outline.fill = crate::common::Fill::None;
    if visible {
      after.push(PageItem::Path(outline));
    } else {
      before.push(PageItem::Path(outline));
    }
  }
  let mut fill = cap.clone();
  fill.stroke = None;
  items.truncate(start);
  items.extend(before);
  items.push(PageItem::Path(fill));
  items.extend(after);
}

fn word_pie_3d_point_stroke(
  style: Option<&crate::common::ShapeStyle<'static>>,
  projection: RadialPerspectiveProjection,
) -> Option<crate::common::Stroke<'static>> {
  let crate::common::ShapeStyleValue::Paint(stroke) = &style?.stroke else {
    return None;
  };
  let mut stroke = stroke.clone();
  stroke.width.0 = word_pie_3d_pen_width(stroke.width.0, projection);
  Some(stroke)
}

fn light_word_pie_cap(
  mut item: PageItem,
  elevation: Option<f32>,
  projection: Option<RadialPerspectiveProjection>,
) -> PageItem {
  if let Some(projection) = projection
    && let PageItem::Path(path) = &mut item
    && let Some(stroke) = path.stroke.as_mut()
  {
    stroke.width.0 = word_pie_3d_pen_width(stroke.width.0, projection);
  }
  if let Some(elevation) = elevation
    && let PageItem::Path(path) = &mut item
    && let crate::common::Fill::Solid(color) = &mut path.fill
  {
    let (s, c) = elevation.to_radians().sin_cos();
    let lit = office_perspective_chart_diffuse_color(
      RgbColor {
        r: color.r,
        g: color.g,
        b: color.b,
      },
      [0.0, -c, -s],
    );
    color.r = lit.r;
    color.g = lit.g;
    color.b = lit.b;
  }
  item
}

struct RadialWallStyle {
  word_elevation: Option<f32>,
  word_stroke: Option<crate::common::Stroke<'static>>,
  outlined_cuts: bool,
}

fn radial_3d_outer_wall_paths(
  projection: RadialPerspectiveProjection,
  depth: f32,
  angles: (f32, f32),
  color: RgbColor,
  horizontal_light_bounds: (f32, f32),
  wall_style: RadialWallStyle,
) -> Vec<PageItem> {
  let RadialWallStyle {
    word_elevation,
    word_stroke,
    outlined_cuts,
  } = wall_style;
  let (start_angle, sweep) = angles;
  let end_angle = start_angle + sweep;
  let (first_front_start, first_front_end) = projection.visible_wall_interval();
  let mut front_start = first_front_start
    + ((start_angle - first_front_start) / std::f32::consts::TAU).floor() * std::f32::consts::TAU;
  let mut items = Vec::new();
  while front_start < end_angle {
    let front_end = front_start + first_front_end - first_front_start;
    let visible_start = start_angle.max(front_start);
    let visible_end = end_angle.min(front_end);
    if visible_end > visible_start + f32::EPSILON {
      let visible_sweep = visible_end - visible_start;
      let segment_count = ((visible_sweep.to_degrees().abs() / 2.0).ceil() as usize).max(2);
      if let Some(elevation) = word_elevation {
        let (s, c) = elevation.to_radians().sin_cos();
        let surface = |angle: f32| {
          let u = angle.sin();
          let v = -angle.cos();
          office_perspective_chart_diffuse_color(color, [u, s * v, -c * v])
        };
        for segment in 0..segment_count {
          let a = visible_start + visible_sweep * segment as f32 / segment_count as f32;
          let b = visible_start + visible_sweep * (segment + 1) as f32 / segment_count as f32;
          let top_a = projection.point(a);
          let top_b = projection.point(b);
          let bottom_a = projection.project_bottom_point(a.sin(), -a.cos(), depth);
          let bottom_b = projection.project_bottom_point(b.sin(), -b.cos(), depth);
          let color_a = surface(a);
          let color_b = surface(b);
          push_chart_two_color_triangle(&mut items, [top_a, bottom_a, top_b], color_a, color_b);
          push_chart_two_color_triangle(&mut items, [top_b, bottom_b, bottom_a], color_b, color_a);
        }
        if let Some(stroke) = &word_stroke {
          let bottom = (0..=segment_count).map(|index| {
            let angle = visible_start + visible_sweep * index as f32 / segment_count as f32;
            projection.project_bottom_point(angle.sin(), -angle.cos(), depth)
          });
          // Each physical mesh edge owns one pen. The cap paints the top
          // arc; a visible radial cut paints its shared vertical edge.
          // Stroking both adjacent faces doubles partially covered pixels.
          let mut outline = Vec::new();
          if !(outlined_cuts && visible_start == start_angle && start_angle.sin() < 0.0) {
            outline.push(projection.point(visible_start));
          }
          outline.extend(bottom);
          if !(outlined_cuts && visible_end == end_angle && end_angle.sin() > 0.0) {
            outline.push(projection.point(visible_end));
          }
          push_chart_styled_polyline(
            &mut items,
            &outline,
            Some(&crate::common::ShapeStyleValue::Paint(stroke.clone())),
            color,
            0.0,
            1.0,
            false,
          );
        }
        front_start += std::f32::consts::TAU;
        continue;
      }
      let mut points = Vec::with_capacity((segment_count + 1) * 2);
      for segment in 0..=segment_count {
        let angle = visible_start + visible_sweep * segment as f32 / segment_count as f32;
        let point = projection.point(angle);
        points.push(common_point(point.0, point.1));
      }
      for segment in (0..=segment_count).rev() {
        let angle = visible_start + visible_sweep * segment as f32 / segment_count as f32;
        let point = projection.project_bottom_point(angle.sin(), -angle.cos(), depth);
        points.push(common_point(point.0, point.1));
      }
      let (left, top, right, bottom) = points.iter().fold(
        (
          f32::INFINITY,
          f32::INFINITY,
          f32::NEG_INFINITY,
          f32::NEG_INFINITY,
        ),
        |(left, top, right, bottom), point| {
          (
            left.min(point.x.0),
            top.min(point.y.0),
            right.max(point.x.0),
            bottom.max(point.y.0),
          )
        },
      );
      let gradient_y = projection.conic_center.1 + depth * 0.5;
      items.push(PageItem::Path(crate::common::PathItem {
        bounds: common_rect(left, top, right - left, bottom - top),
        points,
        commands: Vec::new(),
        closed: true,
        fill: crate::common::Fill::Gradient(crate::common::GradientFill {
          stops: vec![
            crate::common::GradientStop {
              position: 0.0,
              color: common_rgb(shade_chart_color(color, 0.86), 1.0),
              scheme: None,
            },
            crate::common::GradientStop {
              position: 0.2,
              color: common_rgb(shade_chart_color(color, 0.76), 1.0),
              scheme: None,
            },
            crate::common::GradientStop {
              position: 0.4,
              color: common_rgb(shade_chart_color(color, 0.63), 1.0),
              scheme: None,
            },
            crate::common::GradientStop {
              position: 0.7,
              color: common_rgb(shade_chart_color(color, 0.38), 1.0),
              scheme: None,
            },
            crate::common::GradientStop {
              position: 1.0,
              color: common_rgb(shade_chart_color(color, 0.38), 1.0),
              scheme: None,
            },
          ],
          angle_degrees: None,
          definition_bounds: None,
          line: Some((
            common_point(horizontal_light_bounds.0, gradient_y),
            common_point(horizontal_light_bounds.1, gradient_y),
          )),
          interpolation: crate::common::GradientInterpolation::LinearSrgb,
          scaled: false,
          rotate_with_shape: None,
          path: None,
        }),
        stroke: None,
      }));
    }
    front_start += std::f32::consts::TAU;
  }
  items
}

fn push_word_pie_cut_face(
  items: &mut Vec<PageItem>,
  face: &mut PageItem,
  stroke: Option<crate::common::Stroke<'static>>,
) {
  items.push(face.clone());
  if let (PageItem::Path(path), Some(stroke)) = (face, stroke) {
    // The top radial edge belongs to the cap. Retain the other three
    // visible edges as one open contour instead of stroking this quad twice.
    let mut outline = path.clone();
    outline.points.rotate_left(1);
    outline.closed = false;
    outline.fill = crate::common::Fill::None;
    outline.stroke = Some(stroke);
    items.push(PageItem::Path(outline));
  }
}

fn radial_3d_cut_face_path(
  projection: RadialPerspectiveProjection,
  depth: f32,
  angle: f32,
  color: RgbColor,
  word_elevation: Option<f32>,
) -> PageItem {
  let hub = projection.hub();
  let outer = projection.point(angle);
  let bottom_hub = projection.project_bottom_point(0.0, 0.0, depth);
  let bottom_outer = projection.project_bottom_point(angle.sin(), -angle.cos(), depth);
  let points = vec![
    common_point(hub.0, hub.1),
    common_point(outer.0, outer.1),
    common_point(bottom_outer.0, bottom_outer.1),
    common_point(bottom_hub.0, bottom_hub.1),
  ];
  let left = hub.0.min(outer.0).min(bottom_hub.0).min(bottom_outer.0);
  let top = hub.1.min(outer.1).min(bottom_hub.1).min(bottom_outer.1);
  let right = hub.0.max(outer.0).max(bottom_hub.0).max(bottom_outer.0);
  let bottom = hub.1.max(outer.1).max(bottom_hub.1).max(bottom_outer.1);
  // Office's fixed upper-left chart light leaves a 40% ambient face and
  // adds diffuse light only while the radial plane points toward the lower
  // left. This reconstructs the dark green/purple cuts and the brighter red
  // cut from the same surface-normal rule, without series-color exceptions.
  let shade = 0.4 + 0.33 * (-angle.cos()).max(0.0);
  let color = word_elevation.map_or_else(
    || shade_chart_color(color, shade),
    |elevation| word_pie_cut_face_color(color, angle, elevation),
  );
  PageItem::Path(crate::common::PathItem {
    bounds: common_rect(left, top, right - left, bottom - top),
    points,
    commands: Vec::new(),
    closed: true,
    fill: crate::common::Fill::Solid(common_rgb(color, 1.0)),
    stroke: None,
  })
}

fn word_pie_cut_face_color(color: RgbColor, angle: f32, elevation: f32) -> RgbColor {
  let (s, c) = elevation.to_radians().sin_cos();
  // Office lights the cut mesh with its inward winding normal, reversing
  // it between the start and end planes. Native twelve-sector controls
  // independently reproduce all eleven visible cut colors with this same
  // camera-space diffuse rule (including both lit and ambient-only faces).
  let direction = if angle.sin() > 0.0 { -1.0 } else { 1.0 };
  let normal = (direction * angle.cos(), direction * angle.sin());
  office_perspective_chart_diffuse_color(color, [normal.0, s * normal.1, -c * normal.1])
}

fn word_automatic_pie_3d_layout(chart: &PieChartModel<'_>, style: &RadialChartStyle) -> bool {
  style.layout_profile == ChartLayoutProfile::Word
    && chart.kind == RadialChartKind::Pie3D
    && matches!(
      chart.legend_position,
      None | Some(ChartLegendPosition::Left | ChartLegendPosition::Right)
    )
    && !chart.legend_overlay
    && chart.legend_layout.is_none()
    && chart.title_layout.is_none()
    && chart.plot_layout.is_none()
}

struct RadialLegendPlacement {
  side_width: f32,
  horizontal_height: f32,
  word_auto_side_center_y: Option<f32>,
  word_pie_3d_title_band: Option<f32>,
}

fn lower_radial_legend(
  items: &mut Vec<PageItem>,
  frame: ChartFrame,
  chart: &PieChartModel<'_>,
  style: &RadialChartStyle,
  metrics: &mut TextMetrics,
  placement: RadialLegendPlacement,
) {
  let RadialLegendPlacement {
    side_width,
    horizontal_height,
    word_auto_side_center_y,
    word_pie_3d_title_band,
  } = placement;
  let Some(position) = chart.legend_position else {
    return;
  };
  if let Some(title_band) = word_pie_3d_title_band {
    // The native pie controls use the same natural-line row and filled key
    // slots as Word's Cartesian 3-D legend (8/10/14pt and left/right).
    let legend = word_filled_legend_metrics(
      chart
        .visible_legend_indices
        .iter()
        .filter_map(|&i| chart.categories.get(i).map(String::as_str)),
      &style.legend,
      1.0,
      metrics,
    );
    let height = chart.visible_legend_indices.len() as f32 * legend.row_height;
    let bounds = PlotRect {
      left: if position == ChartLegendPosition::Left {
        frame.x_pt + 6.0
      } else {
        frame.x_pt + frame.width_pt - 6.0 - legend.frame_width
      },
      top: frame.y_pt + (frame.height_pt - height + title_band) * 0.5,
      width: legend.frame_width,
      height,
    };
    push_legend_frame(items, bounds, &style.legend_frame_style, 1.0);
    let key_x = bounds.left + 2.25 + legend.key_width * 0.5;
    for (row, &index) in chart.visible_legend_indices.iter().enumerate() {
      let Some(label) = chart.categories.get(index) else {
        continue;
      };
      let center_y = bounds.top + (row as f32 + 0.5) * legend.row_height;
      push_radial_legend_key(
        items,
        key_x,
        center_y - legend.key_width * 0.5,
        legend.key_width,
        index,
        style,
      );
      push_text(
        items,
        key_x
          + legend.key_width
          + style.legend.font_size_pt * profiles::DEFAULT_HORIZONTAL_CARTESIAN_LEGEND.marker_gap_em,
        center_y - line_height(&style.legend) * 0.5,
        label.clone(),
        style.legend.clone(),
      );
    }
    return;
  }
  let host_defaults = radial_host_defaults(style.layout_profile);
  let framed = legend_frame_has_paint(&style.legend_frame_style);
  let mut frame_metrics = legend_frame_metrics(style.legend.font_size_pt);
  if word_auto_side_center_y.is_some() && framed {
    // Word centers the visible key/text span in a framed legend. The 9pt
    // four-entry COM control has a 20.45pt frame around an 11.72pt span.
    frame_metrics.horizontal_padding =
      style.legend.font_size_pt * profiles::WORD_RIGHT_RADIAL_FRAMED_LEGEND_PADDING_EM;
  }
  let marker = if framed && word_auto_side_center_y.is_none() {
    frame_metrics.symbol_height
  } else if word_auto_side_center_y.is_some() {
    style.legend.font_size_pt * profiles::WORD_RIGHT_RADIAL_LEGEND_MARKER_EM
  } else {
    style.legend.font_size_pt * host_defaults.legend_marker_em
  };
  let gap = if word_auto_side_center_y.is_some() {
    style.legend.font_size_pt * profiles::WORD_RIGHT_RADIAL_LEGEND_MARKER_GAP_EM
  } else if framed {
    frame_metrics.symbol_to_text
  } else {
    style.legend.font_size_pt * host_defaults.legend_marker_gap_em
  };
  if let Some(layout) = chart.legend_layout {
    let automatic = PlotRect {
      left: if position == ChartLegendPosition::Left {
        frame.x_pt
      } else {
        frame.x_pt + frame.width_pt * 0.8
      },
      top: frame.y_pt + frame.height_pt * 0.1,
      width: frame.width_pt * 0.2,
      height: frame.height_pt * 0.8,
    };
    let bounds = apply_manual_layout(frame, automatic, layout);
    if bounds.width <= 0.0 || bounds.height <= 0.0 {
      return;
    }

    if layout.width.is_some() && layout.height.is_some() {
      push_legend_frame(items, bounds, &style.legend_frame_style, 1.0);
      let bounds = if framed {
        PlotRect {
          left: bounds.left + frame_metrics.horizontal_padding,
          top: bounds.top + frame_metrics.vertical_padding,
          width: (bounds.width - frame_metrics.horizontal_padding * 2.0).max(0.0),
          height: (bounds.height - frame_metrics.vertical_padding * 2.0).max(0.0),
        }
      } else {
        bounds
      };
      // LibreOffice VLegend::lcl_placeLegendEntries treats an authored-size
      // legend as a custom grid: the legend text owns a maximum frame width,
      // words wrap inside its DrawingML body insets, overflowing rows are
      // removed, and the remaining rows share the complete custom height.
      // Retaining those four stages is important: a narrow legend can wrap
      // its first entry and therefore expose fewer later entries even though
      // the unwrapped strings would fit vertically.
      let text_body = chart_legend_text_body(chart.legend_text_body_properties);
      let insets = text_body.insets;
      let millimeter_pt: f32 = 72.0 / 25.4;
      let marker_gap = millimeter_pt.max(style.legend.font_size_pt * 0.22);
      let maximum_text_width =
        (bounds.width - marker - marker_gap - insets.left - insets.right).max(0.0);
      let legend_line_height = line_height(&style.legend);
      let minimum_row_gap = millimeter_pt.max(style.legend.font_size_pt * 0.2);
      let mut entries = Vec::new();
      let mut occupied_height = 0.0_f32;
      for index in chart.visible_legend_indices.iter().copied() {
        let Some(text) = chart.categories.get(index) else {
          continue;
        };
        let lines = wrap_chart_legend_label(
          text,
          maximum_text_width,
          text_body.wrap,
          &style.legend,
          metrics,
        );
        let outer_height = lines.len() as f32 * legend_line_height + insets.top + insets.bottom;
        let next_count = entries.len() + 1;
        let required_height =
          occupied_height + outer_height + minimum_row_gap * (next_count + 1) as f32;
        // VLegend accepts a one-millimetre OOXML interop tolerance, but it
        // does not paint entries whose normal row spacing still exceeds it.
        if !entries.is_empty() && required_height > bounds.height + millimeter_pt {
          break;
        }
        occupied_height += outer_height;
        entries.push((index, lines));
      }
      if entries.is_empty() {
        return;
      }

      let cell_height = bounds.height / entries.len() as f32;
      let inner_height = (cell_height - insets.top - insets.bottom).max(0.0);
      for (_, lines) in &mut entries {
        apply_chart_legend_vertical_overflow(
          lines,
          inner_height,
          legend_line_height,
          text_body.vertical_overflow,
          maximum_text_width,
          &style.legend,
          metrics,
        );
      }
      let maximum_line_width = entries
        .iter()
        .flat_map(|(_, lines)| lines)
        .map(|line| metrics.measure_text(line, &style.legend))
        .fold(0.0_f32, f32::max);
      let anchored_text_width = if text_body.anchor_center {
        maximum_text_width
      } else {
        maximum_line_width
      };
      let column_width = marker + marker_gap + insets.left + anchored_text_width + insets.right;
      let x = bounds.left + (bounds.width - column_width).max(0.0) * 0.5;
      let text_x = x
        + marker
        + marker_gap
        + insets.left
        + if text_body.anchor_center {
          (maximum_text_width - maximum_line_width).max(0.0) * 0.5
        } else {
          0.0
        };
      for (row, (index, lines)) in entries.into_iter().enumerate() {
        let cell_bounds = PlotRect {
          left: bounds.left,
          top: bounds.top + row as f32 * cell_height,
          width: bounds.width,
          height: cell_height,
        };
        let (vertical_offset, line_step) = chart_legend_vertical_line_layout(
          text_body.vertical_anchor,
          inner_height,
          lines.len(),
          legend_line_height,
        );
        let y = cell_bounds.top + insets.top + vertical_offset;
        push_radial_legend_key(
          items,
          x,
          if lines.is_empty() {
            cell_bounds.top + (cell_height - marker).max(0.0) * 0.5
          } else {
            y + (legend_line_height - marker) * 0.5
          },
          marker,
          index,
          style,
        );
        let paint_clip = chart_legend_text_paint_clip(frame, cell_bounds, text_body);
        for (line_index, line) in lines.into_iter().enumerate() {
          push_text_with_paint_clip(
            items,
            text_x,
            y + line_index as f32 * line_step,
            line,
            style.legend.clone(),
            paint_clip,
          );
        }
      }
      return;
    }

    let visible_entries = chart
      .visible_legend_indices
      .iter()
      .filter_map(|index| chart.categories.get(*index))
      .collect::<Vec<_>>();
    let automatic_width = visible_entries
      .iter()
      .map(|text| marker + gap + metrics.measure_text(text, &style.legend))
      .fold(0.0_f32, f32::max);
    let automatic_height = line_height(&style.legend) * visible_entries.len() as f32
      + frame_metrics.vertical_entry_offset * visible_entries.len().saturating_sub(1) as f32;
    let frame_bounds = PlotRect {
      left: bounds.left,
      top: bounds.top,
      width: layout.width.map_or(
        automatic_width + frame_metrics.horizontal_padding * 2.0,
        |_| bounds.width,
      ),
      height: layout.height.map_or(
        automatic_height + frame_metrics.vertical_padding * 2.0,
        |_| bounds.height,
      ),
    };
    push_legend_frame(items, frame_bounds, &style.legend_frame_style, 1.0);
    let content_left = frame_bounds.left
      + if framed {
        frame_metrics.horizontal_padding
      } else {
        0.0
      };
    let mut y = frame_bounds.top
      + if framed {
        frame_metrics.vertical_padding
      } else {
        0.0
      };
    for index in chart.visible_legend_indices.iter().copied() {
      let Some(text) = chart.categories.get(index) else {
        continue;
      };
      push_radial_legend_key(items, content_left, y, marker, index, style);
      push_text(
        items,
        content_left + marker + gap,
        y - (line_height(&style.legend) - marker) * 0.5,
        text.clone(),
        style.legend.clone(),
      );
      y += if framed {
        line_height(&style.legend) + frame_metrics.vertical_entry_offset
      } else {
        line_height(&style.legend) * 1.25
      };
    }
    return;
  }
  if matches!(
    position,
    ChartLegendPosition::Bottom | ChartLegendPosition::Top
  ) {
    // A pie legend represents data points rather than series. Excel's
    // automatic horizontal row uses a compact point-entry gap; keeping the
    // cartesian one-em gap makes the first/last entries fan out around the
    // correct center.
    let entry_gap = style.legend.font_size_pt * host_defaults.horizontal_legend_entry_gap_em;
    let widths = chart
      .visible_legend_indices
      .iter()
      .filter_map(|index| chart.categories.get(*index))
      .map(|text| marker + gap + metrics.measure_text(text, &style.legend))
      .collect::<Vec<_>>();
    let total = widths.iter().sum::<f32>() + entry_gap * widths.len().saturating_sub(1) as f32;
    let mut x = frame.x_pt + (frame.width_pt - total) * 0.5;
    x += style.legend.font_size_pt * host_defaults.horizontal_legend_center_offset_em;
    let legend_line_height = line_height(&style.legend);
    let legend_top = if position == ChartLegendPosition::Top {
      frame.y_pt + horizontal_height * 0.2
    } else if style.layout_profile == ChartLayoutProfile::Excel {
      let profiled_text_top = frame.y_pt + frame.height_pt
        - horizontal_height
          * if chart.title.is_some() {
            profiles::EXCEL_TITLED_BOTTOM_LEGEND_HEIGHT_SCALE
          } else {
            profiles::EXCEL_UNTITLED_BOTTOM_LEGEND_HEIGHT_SCALE
          };
      if chart.title.is_some() {
        // The established titled Excel profile was measured from a centered
        // legend text line. Normalize it back to the container top before
        // applying the authored DrawingML anchor below.
        profiled_text_top
          - single_line_vertical_anchor_offset(
            Some(a::TextAnchoringTypeValues::Center),
            horizontal_height,
            legend_line_height,
          )
      } else {
        profiled_text_top
      }
    } else {
      frame.y_pt + frame.height_pt - horizontal_height * 0.8
    };
    let y = legend_top
      + single_line_vertical_anchor_offset(
        chart.legend_vertical_anchor,
        horizontal_height,
        legend_line_height,
      );
    push_legend_frame(
      items,
      PlotRect {
        left: x - frame_metrics.horizontal_padding,
        top: y - frame_metrics.vertical_padding,
        width: total + frame_metrics.horizontal_padding * 2.0,
        height: legend_line_height + frame_metrics.vertical_padding * 2.0,
      },
      &style.legend_frame_style,
      1.0,
    );
    for ((index, text), width) in chart
      .visible_legend_indices
      .iter()
      .filter_map(|index| chart.categories.get(*index).map(|text| (*index, text)))
      .zip(widths)
    {
      push_radial_legend_key(
        items,
        x,
        y + (line_height(&style.legend) - marker) * 0.5,
        marker,
        index,
        style,
      );
      push_text(
        items,
        x + marker + gap,
        y,
        text.clone(),
        style.legend.clone(),
      );
      x += width + entry_gap;
    }
  } else {
    let side_inset = style.legend.font_size_pt
      * if word_auto_side_center_y.is_some() && framed {
        profiles::WORD_RIGHT_RADIAL_FRAMED_SIDE_INSET_EM
      } else {
        0.4
      };
    let x = if position == ChartLegendPosition::Left {
      frame.x_pt + side_inset
    } else {
      frame.x_pt + frame.width_pt - side_width + side_inset
    };
    let entry_height = word_auto_side_center_y.map_or(line_height(&style.legend), |_| {
      style.legend.font_size_pt * profiles::WORD_RIGHT_RADIAL_LEGEND_ENTRY_HEIGHT_EM
    });
    let entry_step = word_auto_side_center_y.map_or(
      line_height(&style.legend) * host_defaults.side_legend_entry_step,
      |_| entry_height + profiles::WORD_RIGHT_RADIAL_LEGEND_ROW_GAP_PT,
    );
    let entry_count = chart.visible_legend_indices.len();
    let total_height = entry_height + entry_step * entry_count.saturating_sub(1) as f32;
    let center_y = word_auto_side_center_y.unwrap_or({
      frame.y_pt
        + frame.height_pt * 0.5
        + style.legend.font_size_pt * host_defaults.side_legend_center_offset_em
    });
    let mut y = center_y - total_height * 0.5;
    let maximum_width = chart
      .visible_legend_indices
      .iter()
      .filter_map(|index| chart.categories.get(*index))
      .map(|text| marker + gap + metrics.measure_text(text, &style.legend))
      .fold(0.0_f32, f32::max);
    push_legend_frame(
      items,
      PlotRect {
        left: x - frame_metrics.horizontal_padding,
        top: y - frame_metrics.vertical_padding,
        width: maximum_width + frame_metrics.horizontal_padding * 2.0,
        height: total_height + frame_metrics.vertical_padding * 2.0,
      },
      &style.legend_frame_style,
      1.0,
    );
    for index in chart.visible_legend_indices.iter().copied() {
      let Some(text) = chart.categories.get(index) else {
        continue;
      };
      push_radial_legend_key(
        items,
        x,
        y + (entry_height - marker) * 0.5,
        marker,
        index,
        style,
      );
      push_text(
        items,
        x + marker + gap,
        y,
        text.clone(),
        style.legend.clone(),
      );
      y += entry_step;
    }
  }
}

fn push_radial_legend_key(
  items: &mut Vec<PageItem>,
  x_pt: f32,
  y_pt: f32,
  size_pt: f32,
  point_index: usize,
  style: &RadialChartStyle,
) {
  let point_style = style.point_styles.get(point_index);
  push_chart_shape_rect(
    items,
    PlotRect {
      left: x_pt,
      top: y_pt,
      width: size_pt,
      height: size_pt,
    },
    ChartShapePaint {
      fill: point_style.map(|style| &style.fill),
      stroke: point_style.map(|style| &style.stroke),
      fallback_fill_color: Some(style.point_colors[point_index % style.point_colors.len()]),
      stroke_width_scale: 1.0,
    },
  );
}

fn single_line_vertical_anchor_offset(
  anchor: Option<a::TextAnchoringTypeValues>,
  container_height: f32,
  line_height: f32,
) -> f32 {
  let available_height = (container_height - line_height).max(0.0);
  // ECMA-376 Part 1 §20.1.10.60 makes the one-line cases explicit:
  // distributed anchors in the middle, while justified anchors at the top.
  match anchor.unwrap_or(a::TextAnchoringTypeValues::Top) {
    a::TextAnchoringTypeValues::Center | a::TextAnchoringTypeValues::Distributed => {
      available_height * 0.5
    }
    a::TextAnchoringTypeValues::Bottom => available_height,
    a::TextAnchoringTypeValues::Top | a::TextAnchoringTypeValues::Justified => 0.0,
  }
}

