#[derive(Clone, Copy, Debug)]
struct Chart3DProjection {
  input: PlotRect,
  rotate_x_rad: f32,
  rotate_y_rad: f32,
  right_angle_axes: bool,
  model_width: f32,
  model_height: f32,
  model_depth: f32,
  camera_distance: Option<f32>,
  raw_center_x: f32,
  raw_center_y: f32,
  scale: f32,
  screen_center_x: f32,
  screen_center_y: f32,
  screen_matrix: [f32; 4],
  model_pen_scale: Option<f32>,
}

impl Chart3DProjection {
  fn fit_word_parallel_volume(&mut self, stroke_scale: f32) -> crate::common::Rect {
    // Independent Word COM controls (manual/automatic plot rectangles, both
    // fitting axes, view angles and chart sizes) reserve the margin in model
    // space BEFORE fitting the projection. A 2-D inset cannot represent its
    // oblique depth contribution. Native point boxes also establish the small
    // asymmetric plane guard and the additional back-wall depth guard.
    let plane_guard = 0.00007 * self.model_width;
    let margin = 2.0 * stroke_scale * self.model_width / self.input.width;
    let planar_span = 2.0 * (margin + plane_guard);
    let depth_span = planar_span + 0.002 * self.model_width;
    let sin_x = self.rotate_x_rad.sin();
    let sin_y = self.rotate_y_rad.sin();
    let width = self.model_width + planar_span + sin_y.abs() * (self.model_depth + depth_span);
    let height = self.model_height + planar_span + sin_x.abs() * (self.model_depth + depth_span);
    self.scale = (self.input.width / width).min(self.input.height / height);
    let viewport = common_rect(
      self.input.left + (self.input.width - width * self.scale) * 0.5,
      self.input.top + (self.input.height - height * self.scale) * 0.5,
      width * self.scale,
      height * self.scale,
    );
    self.screen_center_x = self.input.left
      + self.input.width * 0.5
      + (plane_guard - sin_y * depth_span * 0.5) * self.scale;
    self.screen_center_y = self.input.top
      + self.input.height * 0.5
      + (-plane_guard + sin_x * depth_span * 0.5) * self.scale;
    self.model_pen_scale = Some(self.scale * self.model_width / self.input.width);
    viewport
  }

  fn pen_width(self, width: f32, minimum: f32) -> f32 {
    self
      .model_pen_scale
      .map_or(width, |scale| width.max(minimum) * scale)
  }

  fn unlit_pen_color(self, color: RgbColor) -> RgbColor {
    if self.model_pen_scale.is_none() {
      return color;
    }
    let channel =
      |value| crate::common::drawingml_3d::quantize_gouraud_channel(f32::from(value) / 255.0);
    RgbColor {
      r: channel(color.r),
      g: channel(color.g),
      b: channel(color.b),
    }
  }

  fn project(self, x: f32, y: f32, depth_ratio: f32) -> (f32, f32) {
    let model_x = if self.input.width > f32::EPSILON {
      ((x - self.input.left) / self.input.width - 0.5) * self.model_width
    } else {
      0.0
    };
    let model_y = if self.input.height > f32::EPSILON {
      ((y - self.input.top) / self.input.height - 0.5) * self.model_height
    } else {
      0.0
    };
    let model_z = (depth_ratio - 0.5) * self.model_depth;
    let (raw_x, raw_y) = project_chart_model_point(
      self.rotate_x_rad,
      self.rotate_y_rad,
      self.right_angle_axes,
      self.camera_distance,
      model_x,
      model_y,
      model_z,
    );
    let screen_x = (raw_x - self.raw_center_x) * self.scale;
    let screen_y = (raw_y - self.raw_center_y) * self.scale;
    (
      self.screen_center_x + self.screen_matrix[0] * screen_x + self.screen_matrix[1] * screen_y,
      self.screen_center_y + self.screen_matrix[2] * screen_x + self.screen_matrix[3] * screen_y,
    )
  }

  fn x_for_visual_side(self, plot: PlotRect, visual_right: bool, y: f32, depth_ratio: f32) -> f32 {
    let left_screen_x = self.project(plot.left, y, depth_ratio).0;
    let right_screen_x = self.project(plot.left + plot.width, y, depth_ratio).0;
    if (right_screen_x >= left_screen_x) == visual_right {
      plot.left + plot.width
    } else {
      plot.left
    }
  }

  fn vertical_edge_for_visual_side(self, plot: PlotRect, visual_right: bool) -> (f32, f32) {
    let y = plot.top + plot.height * 0.5;
    let mut selected = (plot.left, 0.0_f32);
    let mut selected_x = self.project(selected.0, y, selected.1).0;
    for x in [plot.left, plot.left + plot.width] {
      for depth in [0.0_f32, 1.0] {
        let screen_x = self.project(x, y, depth).0;
        if (visual_right && screen_x > selected_x) || (!visual_right && screen_x < selected_x) {
          selected = (x, depth);
          selected_x = screen_x;
        }
      }
    }
    selected
  }

  fn vertical_axis_length(self, plot: PlotRect, visual_right: bool) -> f32 {
    let (x, depth) = self.vertical_edge_for_visual_side(plot, visual_right);
    let top = self.project(x, plot.top, depth);
    let bottom = self.project(x, plot.top + plot.height, depth);
    (bottom.0 - top.0).hypot(bottom.1 - top.1)
  }

  fn depth_vector(self) -> (f32, f32) {
    let x = self.input.left + self.input.width * 0.5;
    let y = self.input.top + self.input.height * 0.5;
    let front = self.project(x, y, 0.0);
    let back = self.project(x, y, 1.0);
    (back.0 - front.0, back.1 - front.1)
  }
}

