  #[test]
  fn word_radar_category_labels_face_away_from_the_net() {
    // Native default five-spoke date-label PDF origins, independent of the
    // source lowerer's plot fitting; tolerance covers fixed-output snapping.
    for (index, expected_x) in [
      (0, 241.7),
      (1, 364.51),
      (2, 324.89),
      (3, 158.5),
      (4, 118.87),
    ] {
      let (x, _) = super::word_radar_category_label_origin(
        (260.72516, 198.0),
        (104.87165, 104.87165),
        std::f32::consts::TAU * index as f32 / 5.0,
        (38.2, 12.205),
      );
      assert!((x - expected_x).abs() < 0.12, "index={index}, x={x}");
    }
  }

  #[test]
  fn word_radar_outer_capacity_is_independent_of_category_font_insets() {
    let frame = super::ChartFrame {
      x_pt: 108.0,
      y_pt: 72.0,
      width_pt: 432.0,
      height_pt: 252.0,
    };
    // Office automatic-layout controls: title + top legend, with only the
    // category font varied. Natural Calibri lines and inner diameters are
    // measured independently through COM; vertices confirm the same center.
    for (category_line, expected_diameter) in [
      (7.325, 173.07488),
      (10.985, 163.85157),
      (12.205, 160.77819),
      (14.65, 154.61803),
    ] {
      let (plot, outer) =
        super::word_radar_plot_from_bands(frame, [0.0, 48.965_12, 0.0, 0.0], category_line, 1.0);
      assert!((plot.width - expected_diameter).abs() < 0.006);
      assert!((plot.left + plot.width * 0.5 - 324.0).abs() < 0.001);
      assert!((plot.top + plot.height * 0.5 - 222.48256).abs() < 0.001);
      assert!((outer - 181.03488).abs() < 0.001);
      assert_eq!(
        maximum_auto_main_increment_count(ChartLayoutProfile::Word, outer * 0.5, 10.985,),
        7
      );
    }
    // The independent untitled, filled-radar side-legend control.
    let (plot, outer) =
      super::word_radar_plot_from_bands(frame, [0.0, 0.0, 54.549685, 0.0], 12.205, 1.0);
    assert!((outer - 230.0).abs() < 0.001);
    assert!((plot.width - 209.74331).abs() < 0.002);
    assert!((plot.left + plot.width * 0.5 - 296.72516).abs() < 0.001);
    assert!((plot.top + plot.height * 0.5 - 198.0).abs() < 0.001);
  }

  #[test]
  fn word_radar_keeps_the_available_value_axis_capacity() {
    // Native Word base, wide/tall and 6/8pt controls all retain seven or more
    // radar intervals. The PowerPoint five-interval preference is not shared.
    assert_eq!(
      cartesian_value_axis_increment_budget(ChartLayoutProfile::Word, true, false, false, 7),
      7
    );
    assert_eq!(
      cartesian_value_axis_increment_budget(ChartLayoutProfile::Word, true, false, false, 10),
      10
    );
    assert_eq!(
      cartesian_value_axis_increment_budget(ChartLayoutProfile::Word, true, false, false, 2),
      2
    );
    assert_eq!(
      cartesian_value_axis_increment_budget(ChartLayoutProfile::PowerPoint, true, false, false, 10),
      5
    );
  }

  #[test]
  fn bubble_legend_line_column_depends_on_visible_trendlines() {
    for (trendline, deleted, has_line) in [
      ("", "", false),
      (
        r#"<c:trendline><c:trendlineType val="power"/></c:trendline>"#,
        "",
        true,
      ),
      (
        r#"<c:trendline><c:trendlineType val="power"/></c:trendline>"#,
        r#"<c:legendEntry><c:idx val="1"/><c:delete val="1"/></c:legendEntry>"#,
        false,
      ),
    ] {
      let xml = format!(
        r#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart><c:plotArea><c:bubbleChart><c:ser><c:idx val="0"/><c:order val="0"/>{trendline}<c:yVal><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:yVal></c:ser><c:axId val="1"/><c:axId val="2"/></c:bubbleChart></c:plotArea><c:legend><c:legendPos val="r"/>{deleted}</c:legend></c:chart></c:chartSpace>"#
      );
      let space = c::ChartSpace::from_bytes(xml.as_bytes()).unwrap();
      let chart = crate::render::chart::cartesian_chart_for_ui_language(&space, None).unwrap();
      assert_eq!(super::chart_has_visible_line_legend_entry(&chart), has_line);
    }
  }

