  #[test]
  fn excel_line_series_inherits_round_pen_without_overriding_direct_outline() {
    let mut automatic = Stroke::default();
    super::apply_excel_line_series_stroke_defaults(&mut automatic, true);
    assert_eq!(automatic.cap, Some(StrokeCap::Round));
    assert_eq!(automatic.join, Some(StrokeJoin::Round));

    let mut authored = Stroke {
      cap: Some(StrokeCap::Flat),
      join: Some(StrokeJoin::Bevel),
      ..Stroke::default()
    };
    super::apply_excel_line_series_stroke_defaults(&mut authored, true);
    assert_eq!(authored.cap, Some(StrokeCap::Flat));
    assert_eq!(authored.join, Some(StrokeJoin::Bevel));

    let mut other_host = Stroke::default();
    super::apply_excel_line_series_stroke_defaults(&mut other_host, false);
    assert_eq!(other_host.cap, None);
    assert_eq!(other_host.join, None);
  }

  #[test]
  fn numeric_scatter_x_cache_preserves_blank_point_slots() {
    let chart_space = c::ChartSpace::from_bytes(
      br#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
        <c:chart><c:plotArea><c:scatterChart><c:scatterStyle val="lineMarker"/>
          <c:ser><c:idx val="0"/><c:order val="0"/>
            <c:xVal><c:numRef><c:f>Sheet1!$A$1:$A$5</c:f><c:numCache>
              <c:formatCode>General</c:formatCode><c:ptCount val="5"/>
              <c:pt idx="0"><c:v>0.04</c:v></c:pt>
              <c:pt idx="2"><c:v>0.16</c:v></c:pt>
              <c:pt idx="3"><c:v>0.11</c:v></c:pt>
            </c:numCache></c:numRef></c:xVal>
            <c:yVal><c:numLit><c:ptCount val="5"/>
              <c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt>
              <c:pt idx="2"><c:v>3</c:v></c:pt><c:pt idx="3"><c:v>4</c:v></c:pt>
              <c:pt idx="4"><c:v>5</c:v></c:pt>
            </c:numLit></c:yVal>
          </c:ser><c:axId val="1"/><c:axId val="2"/>
        </c:scatterChart></c:plotArea></c:chart>
      </c:chartSpace>"#,
    )
    .expect("scatter chart");
    let chart = crate::render::chart::cartesian_chart_for_ui_language(&chart_space, None)
      .expect("cartesian chart");
    let series = &chart.series[0];

    assert!(series.x_values_preserve_missing);
    assert_eq!(
      series.x_values,
      [Some(0.04), None, Some(0.16), Some(0.11), None]
    );
    assert_eq!(super::scatter_x_value(series, 1), None);
    assert_eq!(super::scatter_x_axis_values(&chart, 0), [0.04, 0.16, 0.11]);
  }

  #[test]
  fn stock_series_uses_shifted_date_axis_category_centers() {
    let chart_space = c::ChartSpace::from_bytes(
      br#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
        <c:chart><c:plotArea><c:stockChart>
          <c:ser><c:idx val="0"/><c:order val="0"/>
            <c:cat><c:numLit><c:formatCode>m/d/yyyy</c:formatCode><c:ptCount val="2"/>
              <c:pt idx="0"><c:v>37261</c:v></c:pt><c:pt idx="1"><c:v>37262</c:v></c:pt>
            </c:numLit></c:cat>
            <c:val><c:numLit><c:ptCount val="2"/>
              <c:pt idx="0"><c:v>10</c:v></c:pt><c:pt idx="1"><c:v>20</c:v></c:pt>
            </c:numLit></c:val>
          </c:ser><c:axId val="1"/><c:axId val="2"/>
        </c:stockChart>
        <c:dateAx><c:axId val="1"/><c:scaling/><c:axPos val="b"/><c:crossAx val="2"/></c:dateAx>
        <c:valAx><c:axId val="2"/><c:scaling/><c:axPos val="l"/>
          <c:crossAx val="1"/><c:crossBetween val="between"/>
        </c:valAx></c:plotArea></c:chart>
      </c:chartSpace>"#,
    )
    .expect("stock chart");
    let chart = crate::render::chart::cartesian_chart_for_ui_language(&chart_space, None)
      .expect("cartesian stock chart");
    let plot = PlotRect {
      left: 0.0,
      top: 0.0,
      width: 100.0,
      height: 100.0,
    };

    assert!(chart.category_axis_shifted);
    assert_eq!(chart.series[0].kind, ChartSeriesKind::Stock);
    assert_eq!(
      super::series_category_point_x(&chart, ChartSeriesKind::Stock, 0, 2, plot),
      25.0
    );
    assert_eq!(
      super::series_category_point_x(&chart, ChartSeriesKind::Stock, 1, 2, plot),
      75.0
    );
    assert_eq!(super::category_point_x(&chart, 0, 2, plot), 0.0);
    assert_eq!(super::category_point_x(&chart, 1, 2, plot), 50.0);
  }

  #[test]
  fn word_text_scatter_positions_allow_fractional_numeric_ticks() {
    let source = c::ChartSpace::from_bytes(
      br#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
      <c:chart><c:plotArea><c:scatterChart><c:scatterStyle val="lineMarker"/>
        <c:ser><c:idx val="0"/><c:order val="0"/>
          <c:xVal><c:strRef><c:f>Sheet1!A1:A4</c:f><c:strCache><c:ptCount val="4"/>
            <c:pt idx="0"><c:v>A</c:v></c:pt><c:pt idx="1"><c:v>B</c:v></c:pt>
            <c:pt idx="2"><c:v>C</c:v></c:pt><c:pt idx="3"><c:v>D</c:v></c:pt>
          </c:strCache></c:strRef></c:xVal>
          <c:yVal><c:numLit><c:ptCount val="4"/>
            <c:pt idx="0"><c:v>1</c:v></c:pt><c:pt idx="1"><c:v>2</c:v></c:pt>
            <c:pt idx="2"><c:v>3</c:v></c:pt><c:pt idx="3"><c:v>4</c:v></c:pt>
          </c:numLit></c:yVal>
        </c:ser><c:axId val="1"/><c:axId val="2"/>
      </c:scatterChart>
      <c:valAx><c:axId val="1"/><c:scaling/><c:axPos val="b"/>
        <c:majorTickMark val="out"/><c:crossAx val="2"/></c:valAx>
      <c:valAx><c:axId val="2"/><c:scaling/><c:axPos val="l"/>
        <c:crossAx val="1"/></c:valAx>
      </c:plotArea></c:chart></c:chartSpace>"#,
    )
    .unwrap();
    let chart = crate::render::chart::cartesian_chart_for_ui_language(&source, None).unwrap();
    assert_eq!(
      super::scatter_x_axis_values(&chart, 0),
      [1.0, 2.0, 3.0, 4.0]
    );
    let wide = super::cartesian_axis_scales(&chart, ChartLayoutProfile::Word, 4, 10, 10, None)[0]
      .x
      .unwrap();
    assert_eq!(
      (wide.minimum, wide.maximum, wide.major_unit),
      (0.0, 4.5, 0.5)
    );
    let narrow = super::cartesian_axis_scales(&chart, ChartLayoutProfile::Word, 4, 10, 6, None)[0]
      .x
      .unwrap();
    assert_eq!(
      (narrow.minimum, narrow.maximum, narrow.major_unit),
      (0.0, 5.0, 1.0)
    );
    let mut items = Vec::new();
    super::lower_powerpoint_horizontal_axis_major_ticks(
      &mut items,
      &chart,
      super::PowerPointHorizontalAxisTickContext {
        plot: PlotRect {
          left: 10.0,
          top: 0.0,
          width: 100.0,
          height: 80.0,
        },
        axis_y: 80.0,
        x_scale: Some(narrow),
        date_ticks: None,
        category_count: 4,
        width_pt: 0.75,
        color: RgbColor::default(),
        tick_length_pt: 3.0,
      },
    );
    assert_eq!(
      items.len(),
      6,
      "numeric ticks are independent of four data positions"
    );
    for (i, item) in items.iter().enumerate() {
      let PageItem::Line(line) = item else {
        panic!("axis tick")
      };
      assert_eq!(line.x1_pt, 10.0 + i as f32 * 20.0);
      assert!((line.y2_pt - line.y1_pt - 3.0).abs() < 0.00001);
    }
  }

  #[test]
  fn deleted_line_legend_entry_leaves_column_keys_square() {
    let source = c::ChartSpace::from_bytes(br#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
      <c:chart><c:plotArea>
      <c:barChart><c:barDir val="col"/><c:ser><c:idx val="0"/><c:order val="0"/></c:ser><c:axId val="1"/><c:axId val="2"/></c:barChart>
      <c:lineChart><c:ser><c:idx val="1"/><c:order val="1"/></c:ser><c:axId val="1"/><c:axId val="2"/></c:lineChart>
      </c:plotArea><c:legend><c:legendPos val="b"/></c:legend></c:chart></c:chartSpace>"#).unwrap();
    let mut chart = crate::render::chart::cartesian_chart_for_ui_language(&source, None).unwrap();
    assert!(super::chart_has_visible_line_legend_entry(&chart));
    chart.deleted_legend_entry_indices = vec![1];
    assert!(!super::chart_has_visible_line_legend_entry(&chart));
    chart.deleted_legend_entry_indices = vec![0];
    assert!(super::chart_has_visible_line_legend_entry(&chart));
  }

  #[test]
  fn word_horizontal_legend_matches_native_entry_count_and_unequal_width_controls() {
    let frame = super::ChartFrame {
      x_pt: 0.0,
      y_pt: 0.0,
      width_pt: 432.0,
      height_pt: 252.0,
    };
    // COM Legend.Left is relative to ChartArea.Left=4pt in these controls.
    for (slots, left, width, gap) in [
      (vec![60.634646; 3], 106.85677, 218.28638, 9.09543),
      (vec![60.634646; 2], 143.23787, 145.52425, 8.08488),
      (vec![60.634646], 179.618_9, 72.76213, 6.06370),
      (
        vec![29.209528, 60.634646, 60.634646],
        125.71189,
        180.57622,
        7.52417,
      ),
    ] {
      let observed = super::word_horizontal_line_legend_band(frame, &slots);
      assert!((observed.0 - left).abs() < 0.002);
      assert!((observed.1 - width).abs() < 0.002);
      assert!((observed.2 - gap).abs() < 0.002);
    }
  }

  #[test]
  fn word_filled_legend_matches_native_count_font_and_frame_controls() {
    // Native Office LegendEntry widths and exported PDF key coordinates.
    for (count, natural_line, slot_width, frame_x, frame_width, expected_x, expected_y) in [
      (3, 12.204961, 42.549213, 73.5, 432.0, 222.79, 306.2077),
      (1, 12.204961, 42.549213, 73.5, 432.0, 271.72, 306.2077),
      (2, 12.204961, 42.549213, 73.5, 432.0, 247.61, 306.2077),
      (3, 12.204961, 16.769055, 73.5, 432.0, 265.33, 306.2077),
      (3, 9.764961, 34.043_15, 73.5, 432.0, 236.28, 307.9657),
      (3, 17.089922, 59.575_75, 73.5, 432.0, 195.79, 302.6995),
      (3, 12.204961, 42.549213, 72.0, 550.0, 280.29, 306.2077),
    ] {
      let frame = super::ChartFrame {
        x_pt: frame_x,
        y_pt: 72.0,
        width_pt: frame_width,
        height_pt: 252.0,
      };
      let labels = vec![slot_width - natural_line * 0.9; count];
      let (bounds, key_width, key_x, _) =
        super::word_bottom_filled_legend_geometry(frame, &labels, natural_line, 1.0);
      assert!((key_x - expected_x).abs() < 0.01, "{key_x} != {expected_x}");
      let key_y = bounds.top + (bounds.height - key_width) * 0.5;
      assert!((key_y - expected_y).abs() < 0.01, "{key_y} != {expected_y}");
    }
  }

  #[test]
  fn word_perspective_pie_light_matches_native_caps_and_side_normals() {
    let material = RgbColor {
      r: 79,
      g: 129,
      b: 189,
    };
    for (elevation, rgb) in [
      (15.0_f32, [72, 120, 175]),
      (30.0, [78, 128, 187]),
      (40.0, [80, 129, 189]),
      (90.0, [66, 106, 157]),
    ] {
      let (s, c) = elevation.to_radians().sin_cos();
      let color = super::office_perspective_chart_diffuse_color(material, [0.0, -c, -s]);
      assert_eq!([color.r, color.g, color.b], rgb);
    }
    let (s, c) = 40.0_f32.to_radians().sin_cos();
    for (angle, rgb) in [
      (120.0_f32, [30, 50, 74]),
      (160.0, [30, 50, 74]),
      (180.0, [35, 57, 85]),
      (200.0, [46, 77, 112]),
      (220.0, [55, 91, 135]),
      (240.0, [62, 103, 151]),
    ] {
      let (u, cos_angle) = angle.to_radians().sin_cos();
      let color =
        super::office_perspective_chart_diffuse_color(material, [u, -s * cos_angle, c * cos_angle]);
      for (actual, expected) in [color.r, color.g, color.b].into_iter().zip(rgb) {
        // Native samples interpolate quantized mesh vertices.
        assert!((i32::from(actual) - expected).abs() <= 2);
      }
    }
  }

