  #[test]
  fn word_chart_canvas_encloses_the_final_inline_position() {
    let logical = common_rect(180.15314, 227.45903, 215.96039, 83.67449);
    let early = common_rect(180.12, 227.4, 215.82, 83.58);
    let image = super::chart_raster_image_with_target(
      &image::RgbaImage::new(1, 1),
      early,
      Some((601, 234)),
      Some((logical, 200.0)),
    )
    .unwrap();
    let original = super::word_chart_3d_final_canvas(&image.data, early).unwrap();
    assert!((original.size.width.0 - 215.82).abs() < 0.002);
    let centered =
      super::word_chart_3d_final_canvas(&image.data, common_rect(186.87, 227.4, 215.82, 83.58))
        .unwrap();
    // Native Word's final page-space PDF matrix. Both physical endpoints
    // cross the printer grid after paragraph centering by 6.75pt.
    assert!((centered.origin.x.0 - 186.84).abs() < 0.002);
    assert!((centered.origin.y.0 - 227.4).abs() < 0.002);
    assert!((centered.size.width.0 - 215.94).abs() < 0.002);
    assert!((centered.size.height.0 - 83.58).abs() < 0.002);
  }

  #[test]
  fn word_pie_outline_matches_native_model_pen_and_hairline_controls() {
    // Measured black/alpha coverage of a straight radial edge in Office's
    // 200-DPI scene; native raster coverage is quantized to eighth samples.
    for (width, tilt, height, explosion, pixels) in [
      (0.0, 15.0, 100.0, 0.25, 1.0),
      (0.5, 15.0, 100.0, 0.25, 1.0),
      (1.0, 15.0, 100.0, 0.25, 1.0),
      (2.0, 15.0, 100.0, 0.25, 1.875),
      (4.0, 15.0, 100.0, 0.25, 3.75),
      (8.0, 15.0, 100.0, 0.25, 7.5),
      (4.0, 15.0, 100.0, 0.0, 4.625),
      (4.0, 30.0, 100.0, 0.25, 2.5),
      (4.0, 15.0, 200.0, 0.25, 3.25),
    ] {
      let projection = super::word_exploded_pie_3d_projection(
        PlotRect {
          left: 0.0,
          top: 0.0,
          width: 215.960_39,
          height: 83.674_49,
        },
        Chart3DView {
          rotate_x_deg: tilt,
          height_percent: height,
          perspective_half_degrees: 0.0,
          right_angle_axes: false,
          ..Default::default()
        },
        explosion,
      );
      let actual = super::word_pie_3d_pen_width(width, projection) * 200.0 / 72.0;
      assert!(
        (actual - pixels).abs() < 0.15,
        "pen {width}, view {tilt}/{height}/{explosion}: {actual} != {pixels}"
      );
    }
  }

