  #[test]
  fn word_pie_camera_matches_independent_view_frame_and_thickness_controls() {
    // Native lossless-image conics in logical PlotArea coordinates. Their
    // half-arc coverage fits have subpixel uncertainty; they independently
    // constrain the camera, not the end-to-end PDF acceptance threshold.
    for (width, height, tilt, perspective, thickness, rx, ry, hub_y) in [
      (
        355.6104, 199.025, 40.0, 30.0, 100.0, 134.786, 84.159, 75.1274,
      ),
      (
        355.6104, 199.025, 30.0, 30.0, 100.0, 165.280, 77.663, 65.416,
      ),
      (
        355.6104, 199.025, 40.0, 60.0, 100.0, 141.073, 83.159, 62.0545,
      ),
      (
        139.6104, 199.025, 40.0, 30.0, 100.0, 67.802, 42.785, 87.1512,
      ),
      (
        355.6104, 297.025, 40.0, 30.0, 100.0, 173.170, 108.522, 117.1137,
      ),
      (355.6104, 199.025, 40.0, 30.0, 50.0, 142.992, 89.980, 0.0),
      (355.6104, 199.025, 40.0, 30.0, 200.0, 120.866, 74.422, 0.0),
    ] {
      let projection = super::word_pie_3d_projection(
        super::PlotRect {
          left: 0.0,
          top: 0.0,
          width,
          height,
        },
        Chart3DView {
          rotate_x_deg: tilt,
          perspective_half_degrees: perspective,
          right_angle_axes: false,
          height_percent: thickness,
          ..Chart3DView::default()
        },
      );
      assert!((projection.radii.0 - rx).abs() < 0.4);
      assert!((projection.radii.1 - ry).abs() < 0.4);
      if hub_y > 0.0 {
        assert!((projection.hub().1 - hub_y).abs() < 0.4);
      }
    }
  }

  #[test]
  fn word_filled_side_legend_matches_independent_pie_font_and_name_controls() {
    let labels = ["1st Qtr", "2nd Qtr", "3rd Qtr", "4th Qtr"];
    let mut metrics = TextMetrics::new();
    for (font_size, width, row, key) in [
      (8.0, 39.91866, 15.66732, 4.39425),
      (10.0, 48.38961, 18.08291, 5.49228),
      (14.0, 65.341_1, 22.91898, 7.69047),
    ] {
      let style = TextStyle {
        font_family: Some("Calibri".into()),
        font_size_pt: font_size,
        ..TextStyle::default()
      };
      let observed =
        super::word_filled_legend_metrics(labels.into_iter(), &style, 1.0, &mut metrics);
      assert!(
        (observed.frame_width - width).abs() < 0.01,
        "{} != {width}",
        observed.frame_width
      );
      assert!((observed.row_height - row).abs() < 0.001);
      assert!((observed.key_width - key).abs() < 0.001);
    }
    let style = TextStyle {
      font_family: Some("Calibri".into()),
      font_size_pt: 10.0,
      ..TextStyle::default()
    };
    let observed = super::word_filled_legend_metrics(
      ["A", "Wide Label", "Third", "Last"].into_iter(),
      &style,
      1.0,
      &mut metrics,
    );
    assert!((observed.frame_width - 62.1848).abs() < 0.01);
    let title = TextStyle {
      font_size_pt: 18.0,
      bold: true,
      ..style
    };
    assert!(
      (super::word_chart_title_band("Sales", &title, 1.0, &mut metrics) - 30.975).abs() < 0.001
    );
  }

  #[test]
  fn word_bottom_legend_rows_match_native_count_and_font_controls() {
    // Office legend bounding heights + its independent 6pt plot clearance.
    // Inputs are native natural font lines, not renderer outputs.
    for (rows, lines, natural_line, expected) in [
      (1, 1, 10.985, 22.875118),
      (1, 2, 10.985, 33.750236),
      (2, 2, 10.985, 49.125354),
      (3, 2, 10.985, 76.875_59),
      (4, 2, 10.985, 104.625827),
      (4, 1, 10.985, 72.000_47),
      (4, 1, 9.765, 67.169_29),
      (4, 2, 12.205, 113.080_39),
      (4, 2, 14.65, 130.024_8),
      (4, 2, 17.09, 146.932_83),
    ] {
      let measured =
        super::word_bottom_legend_row_reservation(rows, lines, natural_line * 0.99, 1.0);
      assert!(
        (measured - expected).abs() < 0.003,
        "{rows} rows/{lines} lines: {measured} vs {expected}"
      );
    }
  }

  #[test]
  fn axis_no_fill_pen_is_independent_of_shape_fill_and_labels() {
    let mut axis = c::ValueAxis::from_bytes(br#"<c:valAx xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><c:axId val="1"/><c:scaling/><c:axPos val="l"/><c:spPr><a:noFill/><a:ln><a:noFill/></a:ln></c:spPr><c:crossAx val="2"/></c:valAx>"#).unwrap();
    assert!(super::value_axis_is_visible(&axis));
    assert!(!super::cartesian_axis_outline_visible(
      axis.chart_shape_properties.as_deref()
    ));
    axis.chart_shape_properties.as_mut().unwrap().outline = None;
    assert!(super::cartesian_axis_outline_visible(
      axis.chart_shape_properties.as_deref()
    ));
    assert!(super::cartesian_axis_outline_visible(None));
  }

  #[test]
  fn manual_legend_omits_zero_length_series_but_keeps_declared_blank_slots() {
    let chart_space = c::ChartSpace::from_bytes(
      br#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
        <c:chart><c:plotArea><c:lineChart>
          <c:ser><c:idx val="0"/><c:order val="0"/><c:tx><c:v>No cache</c:v></c:tx>
            <c:val><c:numRef><c:f>Sheet1!$A$1:$A$2</c:f></c:numRef></c:val>
          </c:ser>
          <c:ser><c:idx val="1"/><c:order val="1"/><c:tx><c:v>Blank slots</c:v></c:tx>
            <c:val><c:numLit><c:ptCount val="2"/></c:numLit></c:val>
          </c:ser>
          <c:ser><c:idx val="2"/><c:order val="2"/><c:tx><c:v>Value</c:v></c:tx>
            <c:val><c:numLit><c:ptCount val="1"/><c:pt idx="0"><c:v>4</c:v></c:pt></c:numLit></c:val>
          </c:ser>
          <c:axId val="1"/><c:axId val="2"/>
        </c:lineChart></c:plotArea><c:legend><c:layout><c:manualLayout/></c:layout></c:legend>
        </c:chart></c:chartSpace>"#,
    )
    .expect("chart space");
    let chart = crate::render::chart::cartesian_chart_for_ui_language(&chart_space, None)
      .expect("cartesian chart");

    assert!(chart.series[0].values.is_empty());
    assert_eq!(chart.series[1].values, [None, None]);
    assert_eq!(chart.series[2].values, [Some(4.0)]);
    assert!(!super::cartesian_series_has_data_points(&chart.series[0]));
    assert!(super::cartesian_series_has_data_points(&chart.series[1]));
    assert!(super::cartesian_series_has_data_points(&chart.series[2]));
  }

  #[test]
  fn chartsheet_legend_marker_matches_native_font_size_controls() {
    // Office exports: an 8pt automatic plot marker is capped independently
    // by each legend font. A smaller authored marker remains smaller.
    for (font_size, expected) in [(8.0, 4.0), (10.0, 6.0), (12.0, 7.0), (20.0, 8.0)] {
      assert_eq!(
        super::chartsheet_legend_marker_size_pt(8.0, font_size),
        expected
      );
    }
    assert_eq!(super::chartsheet_legend_marker_size_pt(3.0, 12.0), 3.0);
  }

  #[test]
  fn chartsheet_marker_raster_matches_native_polygon_coverage() {
    // Alpha masses from configured Office output, independently reproduced
    // by GDI+ FillPolygon/DrawPolygon with AntiAlias8x4 and PixelOffsetModeNone.
    for (symbol, size, pen, pixels, expected) in [
      (c::MarkerStyleValues::Diamond, 8.0, 0.5, 24, 67_448_i64),
      (c::MarkerStyleValues::Triangle, 8.0, 0.5, 24, 69_584),
      (c::MarkerStyleValues::Square, 8.0, 0.5, 24, 137_542),
      (c::MarkerStyleValues::Diamond, 8.0, 0.0, 23, 63_836),
      (c::MarkerStyleValues::Triangle, 8.0, 0.0, 23, 63_116),
      (c::MarkerStyleValues::Square, 8.0, 0.0, 23, 126_943),
      (c::MarkerStyleValues::Diamond, 12.0, 0.5, 35, 148_626),
      (c::MarkerStyleValues::Triangle, 12.0, 0.5, 35, 153_216),
      (c::MarkerStyleValues::Square, 12.0, 0.5, 35, 298_791),
      (c::MarkerStyleValues::Diamond, 12.0, 0.0, 34, 142_040),
      (c::MarkerStyleValues::Triangle, 12.0, 0.0, 34, 140_952),
      (c::MarkerStyleValues::Square, 12.0, 0.0, 34, 282_967),
    ] {
      let geometry = super::chart_marker_geometry(symbol, 141.56569, 150.65988, size, true);
      let path = crate::common::PathItem {
        bounds: geometry.bounds,
        points: geometry.points,
        commands: geometry.commands,
        closed: geometry.closed,
        fill: Fill::Solid(Color {
          a: 255,
          ..Color::default()
        }),
        stroke: (pen > 0.0).then_some(Stroke {
          width: Pt(pen),
          color: Color {
            a: 255,
            ..Color::default()
          },
          ..Stroke::default()
        }),
      };
      let image = super::chartsheet_marker_source_image(&path, symbol, 200.0 / 72.0).unwrap();
      assert_eq!(image.dimensions(), (pixels, pixels));
      let mass: i64 = image.pixels().map(|pixel| i64::from(pixel[3])).sum();
      assert!(
        (mass - expected).abs() <= expected / 100,
        "{symbol:?}, size {size}, pen {pen}: alpha mass {mass}, native {expected}"
      );
    }
  }

  #[test]
  fn chartsheet_shadow_canvas_matches_native_distance_and_blur_controls() {
    // Office zero/1/2/3pt, reverse direction, 45-degree and 3pt blur exports.
    // Square's odd printer-dot width is retained independently of polygons.
    for (offset, blur, near, polygon_span, square_span, pixels) in [
      (0.0, 5.0, -9.36, 18.72, 18.84, 52),
      (1.0, 5.0, -8.28, 18.60, 18.72, 52),
      (2.0, 5.0, -7.32, 18.60, 18.72, 52),
      (3.0, 5.0, -6.36, 18.72, 18.84, 52),
      (-2.0, 5.0, -11.28, 18.60, 18.72, 52),
      (std::f32::consts::SQRT_2, 5.0, -7.92, 18.72, 18.84, 52),
      (2.0, 3.0, -5.28, 14.64, 14.76, 41),
    ] {
      for (symbol, span) in [
        (c::MarkerStyleValues::Diamond, polygon_span),
        (c::MarkerStyleValues::Triangle, polygon_span),
        (c::MarkerStyleValues::Square, square_span),
      ] {
        let axis =
          super::chartsheet_marker_shadow_axis(8.0, 0.5, symbol, offset, blur, 200.0 / 72.0);
        assert!(
          (axis.near_pt - near).abs() < 0.0001,
          "{symbol:?}, offset {offset}"
        );
        assert!(
          (axis.span_pt - span).abs() < 0.0001,
          "{symbol:?}, offset {offset}"
        );
        assert_eq!(axis.pixels, pixels);
      }
    }
  }

