  #[test]
  fn radial_effect_backdrops_do_not_replace_or_interleave_foreground_sectors() {
    use crate::common::drawingml_image_effects::{
      ImageEffect, ImageEffectContainer, ImageEffectContainerKind,
    };
    let effects = ImageEffectContainer {
      kind: ImageEffectContainerKind::Sibling,
      effects: vec![
        ImageEffect::Container(ImageEffectContainer {
          kind: ImageEffectContainerKind::Tree,
          effects: vec![ImageEffect::Blur {
            radius_px: 2.0,
            grow_bounds: true,
          }],
        }),
        ImageEffect::Identity,
      ],
    };
    let path = || {
      radial_2d_segment_path(
        (40.0, 40.0),
        (20.0, 20.0),
        0.0,
        (0.0, std::f32::consts::PI),
        RgbColor {
          r: 80,
          g: 120,
          b: 160,
        },
        None,
        None,
      )
    };
    let mut items = Vec::new();
    let mut backdrops = Vec::new();
    super::push_radial_point_with_effects(&mut items, &mut backdrops, path(), None);
    assert!(backdrops.is_empty());
    let empty = ImageEffectContainer {
      kind: ImageEffectContainerKind::Sibling,
      effects: vec![],
    };
    super::push_radial_point_with_effects(&mut items, &mut backdrops, path(), Some(&empty));
    assert!(backdrops.is_empty());
    for _ in 0..2 {
      super::push_radial_point_with_effects(&mut items, &mut backdrops, path(), Some(&effects));
    }
    assert_eq!(backdrops.len(), 2);
    assert!(
      backdrops
        .iter()
        .all(|item| matches!(item, PageItem::Image(_)))
    );
    assert_eq!(items.len(), 4);
    assert!(items.iter().all(|item| matches!(item, PageItem::Path(_))));
  }

  #[test]
  fn chart_fill_precedence_keeps_explicit_no_fill_and_vary_color_order() {
    let unspecified = ShapeStyleValue::Unspecified;
    let no_fill = ShapeStyleValue::NoPaint;
    let point_marker = ShapeStyleValue::Paint(Fill::Solid(Color {
      r: 0,
      g: 1,
      b: 2,
      a: u8::MAX,
    }));
    let series = ShapeStyleValue::Paint(Fill::Solid(Color {
      r: 1,
      g: 2,
      b: 3,
      a: u8::MAX,
    }));
    let automatic_point = ShapeStyleValue::Paint(Fill::Solid(Color {
      r: 4,
      g: 5,
      b: 6,
      a: u8::MAX,
    }));
    let automatic_series = ShapeStyleValue::Paint(Fill::Solid(Color {
      r: 7,
      g: 8,
      b: 9,
      a: u8::MAX,
    }));

    assert_eq!(
      super::chart_fill_style_from_precedence(
        Some(&point_marker),
        Some(&no_fill),
        Some(&series),
        Some(&automatic_point),
        Some(&automatic_series),
      ),
      Some(&point_marker),
    );
    assert_eq!(
      super::chart_fill_style_from_precedence(
        None,
        Some(&no_fill),
        Some(&series),
        Some(&automatic_point),
        Some(&automatic_series),
      ),
      Some(&no_fill),
    );
    assert_eq!(
      super::chart_fill_style_from_precedence(
        None,
        Some(&unspecified),
        Some(&series),
        Some(&automatic_point),
        Some(&automatic_series),
      ),
      Some(&series),
    );
    assert_eq!(
      super::chart_fill_style_from_precedence(
        None,
        Some(&unspecified),
        Some(&unspecified),
        Some(&automatic_point),
        Some(&automatic_series),
      ),
      Some(&automatic_point),
    );
    assert_eq!(
      super::chart_fill_style_from_precedence(None, None, None, None, Some(&automatic_series),),
      Some(&automatic_series),
    );
  }

