  #[test]
  fn word_endpoint_category_labels_reserve_independent_measured_overhangs() {
    let frame = super::ChartFrame {
      x_pt: 0.0,
      y_pt: 0.0,
      width_pt: 432.0,
      height_pt: 252.0,
    };
    // Office controls: original, smaller/larger category font, short labels,
    // then independently lengthened first and last categories.
    for (labels, expected) in [
      ((41.57024, 41.57024), (31.78512, 400.21488)),
      ((27.71024, 27.71024), (24.85512, 407.14488)),
      ((64.67024, 64.67024), (43.33512, 388.664_9)),
      ((5.2, 5.53496), (19.40913, 418.232_5)),
      ((81.00048, 5.53496), (51.50024, 418.232_5)),
      ((5.2, 82.43056), (19.40913, 379.78472)),
    ] {
      let actual =
        super::word_category_endpoint_plot_bounds(frame, (19.40913, 421.0), labels, false, 1.0);
      assert!((actual.0 - expected.0).abs() < 0.002);
      assert!((actual.1 - expected.1).abs() < 0.002);
    }
    let reversed = super::word_category_endpoint_plot_bounds(
      frame,
      (19.40913, 421.0),
      (81.00048, 5.53496),
      true,
      1.0,
    );
    assert!((reversed.0 - 19.40913).abs() < 0.002);
    assert!((reversed.1 - 380.49976).abs() < 0.002);
  }

  #[test]
  fn word_date_endpoints_reserve_space_before_the_right_legend() {
    // Office controls: date font6/10/14, short/long date formats and an
    // extended maximum. The native legend boundary stays fixed; a final
    // major tick on January8 needs less room than one on January10.
    let frame = super::ChartFrame {
      x_pt: 0.0,
      y_pt: 0.0,
      width_pt: 377.450_32,
      height_pt: 252.0,
    };
    for (width, expected_right) in [
      (38.14, 347.380_3),
      (22.87008, 355.015_3),
      (53.38032, 339.760_16),
      (5.07008, 363.915_28),
      (48.28, 342.310_3),
      (43.20992, 344.845_37),
    ] {
      let actual = super::word_category_endpoint_plot_bounds(
        frame,
        (38.135827, 366.450_32),
        (width, width),
        false,
        1.0,
      );
      assert!((actual.0 - 38.135827).abs() < 0.002);
      assert!((actual.1 - expected_right).abs() < 0.002);
    }
    // An already reserved right numeric band is shared with the end label.
    let actual = super::word_category_endpoint_plot_bounds(
      frame,
      (38.135827, 330.0),
      (38.14, 38.14),
      false,
      1.0,
    );
    assert_eq!(actual.1, 330.0);
  }

