  #[test]
  fn word_horizontal_bar_axes_use_numeric_ticks_and_category_boundaries() {
    let source = c::ChartSpace::from_bytes(
      br#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart">
      <c:chart><c:plotArea><c:barChart><c:barDir val="bar"/>
        <c:ser><c:idx val="0"/><c:order val="0"/><c:val><c:numLit>
          <c:ptCount val="1"/><c:pt idx="0"><c:v>1</c:v></c:pt>
        </c:numLit></c:val></c:ser><c:axId val="1"/><c:axId val="2"/>
      </c:barChart>
      <c:catAx><c:axId val="1"/><c:scaling/><c:axPos val="l"/>
        <c:majorTickMark val="out"/><c:crossAx val="2"/></c:catAx>
      <c:valAx><c:axId val="2"/><c:scaling/><c:axPos val="b"/>
        <c:majorTickMark val="in"/><c:crossAx val="1"/></c:valAx>
      </c:plotArea></c:chart></c:chartSpace>"#,
    )
    .unwrap();
    let chart = crate::render::chart::cartesian_chart_for_ui_language(&source, None).unwrap();
    let mut items = Vec::new();
    super::lower_word_horizontal_bar_axis_lines(
      &mut items,
      &chart,
      PlotRect {
        left: 10.0,
        top: 20.0,
        width: 100.0,
        height: 80.0,
      },
      crate::render::chart::LinearAxisScale {
        minimum: 0.0,
        maximum: 25.0,
        major_unit: 5.0,
        logarithmic_base: None,
        reversed: false,
      },
      &(0..=5)
        .map(|i| (f64::from(i) * 5.0, String::new()))
        .collect::<Vec<_>>(),
      8,
      super::AxisStrokeStyle {
        color: RgbColor::default(),
        width_pt: 0.75,
        tick_length_pt: 3.5,
      },
    );
    let lines = items
      .iter()
      .map(|item| match item {
        PageItem::Line(line) => (line.x1_pt, line.y1_pt, line.x2_pt, line.y2_pt),
        _ => panic!("axis stroke"),
      })
      .collect::<Vec<_>>();
    assert_eq!(lines[0], (10.0, 100.0, 110.0, 100.0));
    for (i, line) in lines[1..7].iter().enumerate() {
      let x = 10.0 + i as f32 * 20.0;
      assert_eq!(*line, (x, 96.5, x, 100.0));
    }
    assert_eq!(lines[7], (10.0, 20.0, 10.0, 100.0));
    for (i, line) in lines[8..].iter().enumerate() {
      let y = 20.0 + i as f32 * 10.0;
      assert_eq!(*line, (10.0, y, 6.5, y));
    }
    assert_eq!(lines.len(), 17);
  }

