  #[test]
  fn horizontal_bar_labels_follow_marker_base_and_end() {
    let rightward = ChartPointAnchor {
      x: 100.0,
      y: 50.0,
      base_x: 20.0,
      base_y: 50.0,
    };
    let leftward = ChartPointAnchor {
      x: 20.0,
      y: 50.0,
      base_x: 100.0,
      base_y: 50.0,
    };
    let insets = ChartTextBodyInsets {
      left: 3.0,
      top: 1.5,
      right: 3.0,
      bottom: 1.5,
    };
    let origin = |position, anchor| {
      horizontal_bar_data_label_origin(position, anchor, (20.0, 10.0), insets, 2.8)
    };

    assert_eq!(
      origin(c::DataLabelPositionValues::Center, rightward),
      (50.0, 46.5)
    );
    assert_eq!(
      origin(c::DataLabelPositionValues::InsideBase, rightward),
      (25.8, 46.5)
    );
    assert_eq!(
      origin(c::DataLabelPositionValues::InsideEnd, rightward),
      (74.2, 46.5)
    );
    assert_eq!(
      origin(c::DataLabelPositionValues::OutsideEnd, rightward),
      (105.8, 46.5)
    );
    assert_eq!(
      origin(c::DataLabelPositionValues::InsideBase, leftward),
      (74.2, 46.5)
    );
    assert_eq!(
      origin(c::DataLabelPositionValues::InsideEnd, leftward),
      (25.8, 46.5)
    );
    assert_eq!(
      origin(c::DataLabelPositionValues::OutsideEnd, leftward),
      (-5.8, 46.5)
    );
  }

