  #[test]
  fn word_horizontal_parallel_volume_matches_native_size_font_and_slot_controls() {
    // Native COM median point pitch across independent width/height, angle,
    // data-table font, series count, GapWidth and GapDepth controls.
    for (width, height, elevation, rotation, series_count, gap_width, gap_depth, native_pitch) in [
      (283.169_28, 176.678_5, 15.0, 20.0, 3, 300, 150, 41.804646),
      (351.169_28, 176.678_5, 15.0, 20.0, 3, 300, 150, 41.794094),
      (283.169_28, 181.678_5, 15.0, 20.0, 3, 300, 150, 43.020945),
      (283.169_28, 176.678_5, 0.0, 0.0, 3, 300, 150, 43.182_28),
      (283.169_28, 157.138_66, 15.0, 20.0, 3, 300, 150, 37.052126),
      (283.169_28, 176.678_5, 15.0, 20.0, 3, 0, 150, 40.764_49),
      (283.169_28, 176.678_5, 15.0, 20.0, 3, 150, 150, 41.452047),
      (283.169_28, 176.678_5, 15.0, 20.0, 3, 300, 0, 42.454646),
      (283.169_28, 176.678_5, 15.0, 20.0, 3, 300, 300, 41.174_25),
      (283.169_28, 207.838_35, 15.0, 20.0, 1, 300, 150, 48.760315),
    ] {
      let series = (0..series_count).map(|i| format!(r#"<c:ser><c:idx val="{i}"/><c:order val="{i}"/><c:val><c:numLit><c:pt idx="0"><c:v>5</c:v></c:pt></c:numLit></c:val></c:ser>"#)).collect::<String>();
      let xml = format!(
        r#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart><c:view3D><c:rAngAx val="1"/></c:view3D><c:plotArea><c:bar3DChart><c:barDir val="bar"/><c:grouping val="clustered"/>{series}<c:gapWidth val="{gap_width}"/><c:gapDepth val="{gap_depth}"/></c:bar3DChart></c:plotArea></c:chart></c:chartSpace>"#
      );
      let source = c::ChartSpace::from_bytes(xml.as_bytes()).unwrap();
      let chart = crate::render::chart::cartesian_chart_for_ui_language(&source, None).unwrap();
      let mut projection = cartesian_3d_projection(
        Chart3DView {
          rotate_x_deg: elevation,
          rotate_y_deg: rotation,
          right_angle_axes: true,
          height_percent: 100.0 * height / width,
          height_percent_is_explicit: true,
          ..Chart3DView::default()
        },
        PlotRect {
          left: 0.0,
          top: 0.0,
          width,
          height,
        },
        ChartLayoutProfile::Word,
        super::word_parallel_bar_model_depth(&chart, 4) * height / width,
        false,
      );
      projection.fit_word_parallel_volume(1.0);
      let first = projection.project(0.0, height * 0.125, 0.0).1;
      let second = projection.project(0.0, height * 0.375, 0.0).1;
      assert!(
        (second - first - native_pitch).abs() < 0.0002,
        "{width}/{height}/{gap_width}/{gap_depth}: {} vs {native_pitch}",
        second - first
      );
    }
  }

  #[test]
  fn stacked_3d_scene_depth_uses_both_logical_slot_gaps() {
    for (categories, gap_width, gap_depth, expected) in [
      (4, 75, 150, 2.5 / 7.0),
      (4, 0, 150, 2.5 / 4.0),
      (4, 150, 150, 0.25),
      (4, 75, 0, 1.0 / 7.0),
      (4, 75, 300, 4.0 / 7.0),
      (8, 75, 150, 2.5 / 14.0),
    ] {
      let xml = format!(
        r#"<c:chartSpace xmlns:c="http://schemas.openxmlformats.org/drawingml/2006/chart"><c:chart><c:view3D><c:rAngAx val="1"/></c:view3D><c:plotArea><c:bar3DChart><c:barDir val="col"/><c:grouping val="stacked"/><c:ser><c:idx val="0"/><c:order val="0"/><c:val><c:numLit><c:pt idx="0"><c:v>1</c:v></c:pt></c:numLit></c:val></c:ser><c:gapWidth val="{gap_width}"/><c:gapDepth val="{gap_depth}"/></c:bar3DChart></c:plotArea></c:chart></c:chartSpace>"#
      );
      let space = c::ChartSpace::from_bytes(xml.as_bytes()).expect("chart space");
      let chart =
        crate::render::chart::cartesian_chart_for_ui_language(&space, None).expect("chart");
      let (depth, _) = super::cartesian_3d_preferred_model_aspect(&chart, categories);
      assert!(
        (depth - expected).abs() < 1e-6,
        "{categories}/{gap_width}/{gap_depth}: {depth}"
      );
    }
  }

  #[test]
  fn native_chart_light_separates_gray_diffuse_and_black_specular() {
    let view = [20_f32.to_radians().sin(), 15_f32.to_radians().sin(), 1.0];
    for (normal, expected) in [
      ([1.0, 0.0, 0.0], 82),
      ([0.0, 1.0, 0.0], 98),
      ([0.0, 0.0, 1.0], 128),
    ] {
      let gray = super::office_parallel_chart_surface_color(
        RgbColor {
          r: 128,
          g: 128,
          b: 128,
        },
        normal,
        view,
        false,
      );
      assert_eq!(
        gray,
        RgbColor {
          r: expected,
          g: expected,
          b: expected
        }
      );
    }
    // Samples at independently measured model normals in Office's 200dpi
    // native image; tolerance covers native vertex color quantization.
    for (pixel, gray192, black) in [
      (111.0, 160, 0),
      (131.0, 189, 0),
      (151.0, 201, 4),
      (171.0, 198, 1),
      (191.0, 179, 0),
    ] {
      let angle = 20_f32.to_radians().sin().atan() - ((pixel - 154.0_f32) / 61.0).acos();
      let normal = [angle.cos(), 0.0, -angle.sin()];
      let diffuse = super::office_parallel_chart_surface_color(
        RgbColor {
          r: 192,
          g: 192,
          b: 192,
        },
        normal,
        view,
        false,
      );
      let specular = super::office_parallel_chart_surface_color(
        RgbColor { r: 0, g: 0, b: 0 },
        normal,
        view,
        true,
      );
      assert!((i32::from(diffuse.r) - gray192).abs() <= 2);
      assert!((i32::from(specular.r) - black).abs() <= 1);
    }
  }

  #[test]
  fn native_chart_sub_lattice_highlight_does_not_change_diffuse_color() {
    // Office single-cylinder controls, rotation20/elevation30: the black
    // material has no highlight anywhere on the front arc. Gray64/128/192
    // retain the diffuse ramp, including the brightest interpolated region.
    let view = [20_f32.to_radians().sin(), 0.5, 1.0];
    for i in 0..52 {
      let angle = std::f32::consts::TAU * i as f32 / 52.0;
      let normal = [angle.cos(), 0.0, -angle.sin()];
      for value in [0, 64, 128, 192] {
        let color = RgbColor {
          r: value,
          g: value,
          b: value,
        };
        assert_eq!(
          super::office_parallel_chart_surface_color(color, normal, view, true),
          super::office_parallel_chart_surface_color(color, normal, view, false),
        );
      }
    }
  }

  #[test]
  fn word_chart_tick_width_matches_native_literal_label_controls() {
    let mut metrics = crate::text_metrics::TextMetrics::new();
    for (size, digit, em, exponential, repeated) in [
      (8.0, 4.055, 6.84, 24.595, 28.385),
      (10.0, 5.07, 8.55, 30.75, 35.49),
      (14.0, 7.095, 11.97, 43.035, 49.665),
    ] {
      let style = crate::model::TextStyle {
        font_family: Some("Calibri".into()),
        font_size_pt: size,
        ..Default::default()
      };
      // Differences between native InsideLeft values cancel all fixed bands.
      // One versus seven zeros isolates the independently rounded advance;
      // exponential labels also detect unwanted kerning between digits/dot.
      for (text, expected) in [
        ("0", digit),
        ("M", em),
        ("1.4E-08", exponential),
        ("0000000", repeated),
      ] {
        let actual = super::word_chart_tick_label_width(text, &style, &mut metrics);
        assert!(
          (actual - expected).abs() < 0.001,
          "{size} {text}: {actual} != {expected}"
        );
      }
    }
  }

