  #[test]
  fn word_cartesian_scene_keeps_print_samples_and_screen_canvas_allocation() {
    let viewport = super::common_rect(153.3643, 83.1035, 328.9521, 170.5498);
    let mut items = Vec::new();
    super::push_chart_polygon(
      &mut items,
      &[(160.0, 90.0), (480.0, 90.0), (480.0, 250.0), (160.0, 250.0)],
      RgbColor {
        r: 127,
        g: 154,
        b: 72,
      },
      None,
    );
    for (dpi, width_pt, height_pt, target) in [
      (96.0, 328.665, 170.265, (440_u32, 229_u32)),
      (200.0, 328.86, 170.46, (914, 475)),
    ] {
      let image = super::cartesian_3d_scene_image(&items, Some(viewport), dpi).unwrap();
      let decoded = image::load_from_memory(&image.data).unwrap();
      assert_eq!((decoded.width(), decoded.height()), (914, 475));
      assert!((image.x_pt - 153.36).abs() < 1e-4);
      assert!((image.y_pt - 83.04).abs() < 1e-4);
      assert!((image.width_pt - width_pt).abs() < 1e-4);
      assert!((image.height_pt - height_pt).abs() < 1e-4);
      let offset = image.data.windows(4).position(|v| v == b"oxCg").unwrap();
      assert_eq!(&image.data[offset + 4..offset + 8], &target.0.to_be_bytes());
      assert_eq!(
        &image.data[offset + 8..offset + 12],
        &target.1.to_be_bytes()
      );
    }
  }

